// Compare place names ignoring case and diacritics. The world-atlas geometry can
// carry accented names (e.g. "São Tomé and Principe") while our data keys / quiz
// lists are plain ASCII ("Sao Tome and Principe"); this bridges the two.
function normalizeName(s) {
    return (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
}
function namesMatch(a, b) {
    return normalizeName(a) === normalizeName(b);
}
// Look up a data-object entry tolerant of diacritic/case differences.
function lookupDataEntry(name, dataObj) {
    if (!dataObj) return null;
    if (dataObj[name]) return dataObj[name];
    const norm = normalizeName(name);
    const key = Object.keys(dataObj).find(k => normalizeName(k) === norm);
    return key ? dataObj[key] : null;
}

// Helper function to get flag URL for a country
function getFlagUrl(itemName) {
    const data = gameState.currentDataObj[itemName];
    if (!data) {
        console.warn(`No data found for item: ${itemName}`);
        return null;
    }
    // No per-lookup log: the flag-heavy modes call this once per country per redraw.
    return `https://flagcdn.com/${data.code}.svg`;
}

// Helper function to get capital for a country/state
function getCapital(itemName) {
    const data = gameState.currentDataObj[itemName];
    return data ? data.capital : null;
}

// Generate multiple choice options with tricky distractors
function generateMultipleChoiceOptions(correctAnswer, answerType = 'item') {
    const options = [correctAnswer];
    const data = gameState.currentDataObj[correctAnswer];
    const currentList = gameState.currentQuizList;

    // Get similar items for tricky distractors
    let similarItems = [];
    if (data && data.similar) {
        similarItems = data.similar.filter(item => {
            // Ensure the similar item is in our quiz list
            return currentList.includes(item);
        });
    }

    // Add at least one similar item if available
    if (similarItems.length > 0) {
        const randomSimilar = similarItems[Math.floor(Math.random() * similarItems.length)];
        options.push(randomSimilar);
    }

    // Fill remaining options with random items
    while (options.length < 4) {
        const randomItem = currentList[Math.floor(Math.random() * currentList.length)];
        if (!options.includes(randomItem)) {
            options.push(randomItem);
        }
    }

    // For capital questions, answer with the capitals instead of the item names. Shuffled
    // AFTER the mapping: this branch used to return early, before the shuffle below, so the
    // correct capital was always the first option (Capitals ▸ Multiple Choice gave itself away).
    if (answerType === 'capital') {
        return shuffleArray(options.map(item => getCapital(item)).filter(cap => cap !== null));
    }

    // Shuffle the options
    return shuffleArray(options);
}

// Helper function to shuffle an array
function shuffleArray(array) {
    const shuffled = [...array];
    for (let i = shuffled.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    return shuffled;
}

// Render multiple choice options
function renderMultipleChoice(options, correctAnswer) {
    const container = document.getElementById('options-grid');
    if (!container) return;
    container.innerHTML = '';
    container.className = 'options-grid'; // Ensure correct class for button layout

    options.forEach(option => {
        const button = document.createElement('button');
        button.className = 'option-btn';
        button.textContent = option;
        button.onclick = () => handleMultipleChoiceAnswer(option, correctAnswer, button);
        container.appendChild(button);
    });

    // Show multiple choice container
    document.getElementById('multiple-choice-container').classList.remove('hidden');
}

// Handle multiple choice answer
function handleMultipleChoiceAnswer(selectedAnswer, correctAnswer, button) {
    if (gameState.answeredCorrectly) return;

    const isCorrect = selectedAnswer === correctAnswer;

    // Odd One Out withholds the trait until the round is decided — that IS the question — so
    // this is where it gets said, right or wrong, and recorded for the end-of-game review.
    if (gameState.questionType === 'odd-one-out') recordOddAnswer(selectedAnswer, isCorrect);
    // Same idea for the sandbox quizzes: the reason IS the payoff, so it is said either way.
    if (gameState.questionType === 'sandbox-fact') recordSandboxAnswer(selectedAnswer, isCorrect);

    // Visual feedback — except on a round that has asked to hold its verdict, where the only
    // thing a click may say is "this is the one you chose". `.selected` is the accent colour and
    // reads as approval, so a deferred round gets a plain grey instead, right or wrong.
    const deferring = !!(gameState.sbQuestion && gameState.sbQuestion.deferMark);
    button.classList.add(deferring ? 'sb-picked-wait' : 'selected');

    if (isCorrect) {
        // A round whose reveal is an argument marks its own buttons, at the end of it — see
        // `deferMark`. Turning this one green on the click states the conclusion before the
        // animation has made the case, which on Mercator Lies is the whole round.
        if (!deferring) button.classList.add('correct');
        handleCorrectAnswer(button);
        // Highlight correct country on globe if applicable
        if (gameState.questionType === 'identify') {
            highlightCountryOnGlobe(gameState.targetCountry);
        }
    } else if (deferring) {
        // Nothing but "you picked this" until the reveal has finished. Red on the click says the
        // answer is no before the picture has said anything at all, and on Mercator Lies the
        // picture is the argument. `sbMarkCorrectOption` paints it red at the end.
        button.classList.add('sb-picked-wait');
    } else {
        button.classList.add('incorrect');
        handleIncorrectAnswer(button);
        scheduleWrongThenCorrect(() => {
            let correctButton = null;
            document.querySelectorAll('.option-btn').forEach(btn => {
                // `data-answer` when a renderer has one, because a tile need not WEAR its answer:
                // Upside Down withholds the country names until the round is decided, and its
                // buttons are blank while it matters.
                if ((btn.dataset.answer || btn.textContent) === correctAnswer) {
                    btn.classList.add('correct');
                    correctButton = btn;
                }
            });
            return correctButton;
        });
    }
}

// Store the spinning animation interval for identify mode
let globeSpinInterval = null;

// Stop globe spinning animation
function stopGlobeSpin() {
    if (globeSpinInterval) {
        clearInterval(globeSpinInterval);
        globeSpinInterval = null;
    }
}

// Start slow eastward globe spin (for identify mode)
function startGlobeSpin(speed = 0.2) {
    if (!isGlobeView()) return; // Spinning only applies to the orthographic globe
    stopGlobeSpin(); // Clear any existing spin

    const spinStep = () => {
        // The interval outlives the mode that started it by up to 50 ms, and the next mode may
        // be on a projection with no rotation at all — `d3.geoAlbersUsa` is a composite and has
        // no `.rotate`. One tick landing in that gap threw, which is how the puzzle managed to
        // report a rotation error about a board that never rotates.
        if (!projection || typeof projection.rotate !== 'function') { stopGlobeSpin(); return; }
        const [lon, lat, roll] = projection.rotate();
        // Increment longitude to spin east (right)
        projection.rotate([lon + speed, lat, roll || 0]);
        countriesGroup.selectAll('path').attr('d', path);
        updateIslandMarkers(); // keep dots + lakes rotating with the land
    };

    // Spin every 50ms for smooth animation
    globeSpinInterval = setInterval(spinStep, 50);
}

// True when a feature IS `countryName` or is one of its overseas territories, so
// naming/finding a parent fills the parent and all its dependencies together.
function featureBelongsTo(d, countryName) {
    return !!(d && d.properties &&
        (d.properties.name === countryName || d.properties.parent === countryName));
}

// Raise highlighted paths so their outline paints ON TOP of neighbouring
// countries — otherwise a later-drawn neighbour clips the highlight's border.
function raiseHighlight(selection) {
    if (selection && !selection.empty()) selection.raise();
}

// Highlight country on globe (plus any of its overseas territories).
function highlightCountryOnGlobe(countryName) {
    const paths = countriesGroup.selectAll('path')
        .filter(d => featureBelongsTo(d, countryName))
        .classed('target', true);
    raiseHighlight(paths);

    // Island nations are dots, not polygons — highlight the marker too.
    if (islandMarkersGroup) {
        const dots = islandMarkersGroup.selectAll('circle')
            .filter(d => featureBelongsTo(d, countryName))
            .classed('target', true);
        raiseHighlight(dots);
    }
}

// Paint a country's shape(s) with its own flag (used once its flag sub-question has been
// asked). An objectBoundingBox pattern maps the flag into each feature's bounding box, so
// the fill automatically follows the country as the globe rotates/zooms. Parent + overseas
// territories all get the parent's flag.
// Paint a country's shape with its own flag.
//
// The pattern is `userSpaceOnUse`, sized and positioned from the country's CURRENT projected
// bounding box, with the image set to `slice` — so the flag covers the shape completely at
// its true aspect ratio (overflow is cropped by the country outline) instead of being
// squashed to fit. An `objectBoundingBox` pattern, which is what this used to be, normalises
// the coordinate space to the bbox and therefore stretches every flag by that bbox's aspect.
//
// On the globe the pattern is also ROTATED to local north (`patternTransform`) and rebuilt on
// every redraw by updateFlagFills(), so the flag turns and rescales with the country as the
// globe spins — it reads as painted onto the surface rather than as a window cut through it.
// PER FEATURE, not per country. Sizing one pattern to the union of a country and all its
// overseas territories spans most of the map — France plus French Guiana plus New Caledonia
// is a box 470 units wide — and `slice` then crops a single flat band of the flag into each
// shape: mainland France lands in the white stripe and reads as EMPTY. Rotating the globe
// until the territories clip away shrinks the box back and it works again, which is exactly
// the "empty unless the globe is rotated just so" symptom. One box per drawn shape instead.
function flagPatternGeometry(feature) {
    if (!feature) return null;
    // The framing core, not the whole feature: at 110m "France" is one MultiPolygon that
    // includes French Guiana, so its raw bbox is 470 units wide and `slice` crops a single
    // flat band into the mainland. Sized to the core the mainland gets a whole flag, and the
    // pattern simply TILES across the remote parts at the same scale — which is what you want.
    const core = shapeFramingCore(feature) || feature;
    const b = path.bounds(core);
    if (!isFinite(b[0][0])) return null;
    const x0 = b[0][0], y0 = b[0][1], x1 = b[1][0], y1 = b[1][1];
    if (x1 <= x0 || y1 <= y0) return null;

    // Local north at the shape's centre, in screen terms: project a point slightly north
    // and measure the bearing. On a flat map this is 0; on the globe it tilts toward the pole.
    let angle = 0;
    const c = d3.geoCentroid(core);
    if (c && isFinite(c[0])) {
        const p0 = projection(c);
        const p1 = projection([c[0], Math.min(89, c[1] + 2)]);
        if (p0 && p1 && isFinite(p0[0]) && isFinite(p1[0])) {
            angle = Math.atan2(p1[0] - p0[0], p0[1] - p1[1]) * 180 / Math.PI;
            if (!isFinite(angle)) angle = 0;
        }
    }
    // Rotating the pattern about the centre leaves corners uncovered, so oversize it by the
    // diagonal ratio — `slice` crops the excess anyway.
    const w = x1 - x0, h = y1 - y0;
    const grow = Math.abs(Math.sin(angle * Math.PI / 180)) * (Math.max(w, h) / Math.min(w, h) - 1) + 1;
    const pw = w * grow, ph = h * grow;
    return { x: x0 - (pw - w) / 2, y: y0 - (ph - h) / 2, w: pw, h: ph,
             cx: (x0 + x1) / 2, cy: (y0 + y1) / 2, angle };
}

// A stable per-shape pattern id: the flag code plus whatever identifies this one feature.
function flagPatternId(code, feature) {
    const key = (feature && (feature.id != null ? feature.id : feature.properties && feature.properties.name)) || 'x';
    return 'flagfill-' + code + '-' + String(key).replace(/[^A-Za-z0-9_-]/g, '');
}

// Create or re-derive the pattern for one drawn shape. Returns the fill, or null if the
// shape has no projected extent right now (fully clipped by the globe's limb, say).
function syncFlagPattern(defs, code, feature) {
    const geo = flagPatternGeometry(feature);
    if (!geo) return null;
    const patId = flagPatternId(code, feature);
    const url = `https://flagcdn.com/${code}.svg`;
    let pat = defs.select('#' + patId);
    if (pat.empty()) {
        pat = defs.append('pattern')
            .attr('id', patId)
            .attr('patternUnits', 'userSpaceOnUse');
        pat.append('image')
            .attr('href', url).attr('xlink:href', url)   // href + legacy xlink:href for older renderers
            .attr('preserveAspectRatio', 'xMidYMid slice');
    }
    pat.attr('x', geo.x).attr('y', geo.y).attr('width', geo.w).attr('height', geo.h)
       .attr('patternTransform', `rotate(${geo.angle.toFixed(2)} ${geo.cx.toFixed(2)} ${geo.cy.toFixed(2)})`);
    pat.select('image').attr('x', geo.x).attr('y', geo.y)
       .attr('width', geo.w).attr('height', geo.h);
    return `url(#${patId})`;
}

// Dots are a few pixels across, so orientation is meaningless and a bounding-box pattern is
// both simpler and immune to the projection: one per flag, reused by every marker.
function dotFlagFill(defs, code) {
    const patId = 'flagfill-dot-' + code;
    if (defs.select('#' + patId).empty()) {
        const url = `https://flagcdn.com/${code}.svg`;
        const pat = defs.append('pattern')
            .attr('id', patId)
            .attr('patternUnits', 'objectBoundingBox')
            .attr('patternContentUnits', 'objectBoundingBox')
            .attr('width', 1).attr('height', 1);
        pat.append('image')
            .attr('href', url).attr('xlink:href', url)
            .attr('width', 1).attr('height', 1)
            .attr('preserveAspectRatio', 'xMidYMid slice');
    }
    return `url(#${patId})`;
}

function fillCountryWithFlag(countryName) {
    if (!svg || !countriesGroup) return;
    const data = gameState.currentDataObj && gameState.currentDataObj[countryName];
    if (!data || !data.code) return;

    let defs = svg.select('defs');
    if (defs.empty()) defs = svg.append('defs');

    // One pattern per drawn shape, so a country and each of its territories each get a whole
    // flag scaled to themselves.
    countriesGroup.selectAll('path')
        .filter(d => featureBelongsTo(d, countryName))
        .each(function (d) {
            const fill = syncFlagPattern(defs, data.code, d);
            if (fill) d3.select(this).style('fill', fill).classed('flag-filled', true);
        });
    if (islandMarkersGroup) {
        const dotFill = dotFlagFill(defs, data.code);
        islandMarkersGroup.selectAll('circle')
            .filter(d => featureBelongsTo(d, countryName))
            .style('fill', dotFill)
            .classed('flag-filled', true);
    }
    // Remember it so a redraw can re-derive the patterns for the new projection.
    if (!gameState.flagFilledNames) gameState.flagFilledNames = new Set();
    gameState.flagFilledNames.add(countryName);
}

// Re-derive every live flag pattern for the current projection. Called wherever the map is
// re-pathed (globe drag, zoom, pinch), so the flags stay glued to their countries.
function updateFlagFills() {
    const names = gameState.flagFilledNames;
    if (!names || !names.size || !svg || !path || !countriesGroup) return;
    const defs = svg.select('defs');
    if (defs.empty()) return;
    names.forEach(name => {
        const data = gameState.currentDataObj && gameState.currentDataObj[name];
        if (!data || !data.code) return;
        countriesGroup.selectAll('path')
            .filter(d => featureBelongsTo(d, name))
            .each(function (d) {
                const fill = syncFlagPattern(defs, data.code, d);
                if (fill) d3.select(this).style('fill', fill).classed('flag-filled', true);
            });
    });
}

// Clear multiple choice UI
// Every one of these is a fixed element of the page rather than something a mode creates, so a
// missing one is somebody else's bug — but it must not be allowed to become THIS function's
// crash. Thrown from inside the map load's callback it surfaces as "Error loading map data", which
// sends anybody debugging it to the network tab to look at a file that downloaded perfectly.
function clearMultipleChoice() {
    const grid = document.getElementById('options-grid');
    if (grid) {
        grid.innerHTML = '';
        grid.className = 'options-grid'; // Reset to default class
    }
    const mcBox = document.getElementById('multiple-choice-container');
    if (mcBox) mcBox.classList.add('hidden');
    const flagBox = document.getElementById('flag-display');
    if (flagBox) flagBox.style.display = 'none';
    const skyline = document.getElementById('skyline-display');
    if (skyline) skyline.style.display = 'none';
}

// Initialize the game
async function initGame() {
    loadCoreOverrides();
    // Load and validate all game data first
    const dataLoaded = await initializeGameData();
    if (!dataLoaded) return;

    setupEventListeners();

    // Deep-link support: if the URL names a mode (from a shared/challenge link), open it.
    routeFromUrl();
}

// Start game with selected mode
function startGameWithMode(mode) {
    // Reset all game state
    stopNameAllTimer(); // cancel any running name-all countdown before resetting state
    removeSpaceshipInset(); // clear the spaceship guess inset from any prior game
    disposeOrbital();       // tear down any prior orbital WebGL canvas
    const modeConfig = QUIZ_MODES[mode];
    // Mark the spaceship view so the mobile layout can split into earth + guess map.
    document.body.classList.toggle('spaceship-active', !!modeConfig.spaceshipMode);
    // Mark the puzzle so its board can claim a minimum height (and, on a phone, let the
    // page scroll) rather than being crushed by the piece tray below it.
    document.body.classList.toggle('state-puzzle-active', !!modeConfig.statePuzzleMode);
    // The tile-only and slider sandbox rounds stack a prompt, four big tiles (or an arc plus a
    // globe) and the controls into one column. On a phone that is taller than the viewport, and
    // `body { height: 100vh; overflow: hidden }` would cut the controls off — leaving no way to
    // submit. Same exception the puzzle board takes, scoped the same way.
    // The panels that are taller than a phone viewport get the app-wide `height: 100vh;
    // overflow: hidden` lifted, or their controls are simply cut off with no way to reach them.
    document.body.classList.toggle('sb-tall-active',
        !!((modeConfig.sbQuizMode && modeConfig.sbNoMap) || modeConfig.projectionLabMode));
    document.body.classList.toggle('sb-wide-panel',
        !!(modeConfig.sbQuizMode && modeConfig.sbEngine === 'estimate'));
    // And hand the map box back, for the same reason `sbTeardown` does: the tile-only rounds
    // hide it inline, an inline style outlives the mode that wrote it, and every mode after one
    // of those would otherwise draw into a box measuring 0x0. The sandbox rounds set it both
    // ways per round, so clearing it here cannot fight them.
    const mapBox0 = document.getElementById('map-container');
    if (mapBox0) mapBox0.style.display = '';
    // Globe modes (but not spaceship, which has its own bespoke inset layout) get the
    // map/globe maximised with question/flag/multiple-choice in a narrow side panel —
    // see .globe-layout/.globe-side-panel in style.css. Places-been uses the same side
    // layout (its category lists live in that panel) even for the flat US map.
    // Free Explore goes a step further: the globe takes the FULL width and the same panel
    // floats over its (otherwise unused) top-right corner — see explore-overlay-layout.
    // The States Puzzle uses the same side layout for its piece tray (as Places-been does
    // for its category lists) even though its AlbersUSA map isn't a globe: the board is
    // height-constrained, so spending width on the tray costs the map nothing.
    // useWorldQuizLayout modes are excluded because they render in #world-quiz-layout and hide
    // #map-container/#question-container outright — the side layout would then make the now-empty
    // #globe-layout a `flex: 1` row, and it claimed 310px of blank space above the real content.
    // sbNoMap covers the sandbox rounds whose question is entirely in the answer tiles (four
    // silhouettes, four flags) plus the ordering one: they all still LOAD the map — for areas,
    // centroids and shape geometry — but never show it, so a 300px column beside a hidden map
    // would just squeeze the tiles that are the whole round.
    document.querySelector('.container').classList.toggle(
        'globe-side-layout', (!!modeConfig.useGlobe || !!modeConfig.placesMode ||
        !!modeConfig.flagPlaceMode || !!modeConfig.sandboxMode || !!modeConfig.statePuzzleMode) &&
        !modeConfig.spaceshipMode && !modeConfig.freeExploreMode && !modeConfig.useWorldQuizLayout &&
        modeConfig.sbEngine !== 'order' && !modeConfig.sbNoMap && !modeConfig.sbFullMap);
    document.querySelector('.container').classList.toggle('explore-overlay-layout', !!modeConfig.freeExploreMode);
    // Map edge to edge, everything else floating on it. Same trick as Free Explore's overlay
    // layout, and for the same reason: there is not enough furniture to justify a column.
    document.querySelector('.container').classList.toggle('sb-full-map', !!modeConfig.sbFullMap);
    // Widens the side panel for the piece/flag tray (and only there) on top of globe-side-layout.
    document.querySelector('.container').classList.toggle('state-puzzle-layout',
        !!modeConfig.flagPlaceMode || !!modeConfig.statePuzzleMode);

    // Drop any leftover Places panel when switching to a different mode.
    const stalePlacesPanel = document.getElementById('places-panel');
    if (stalePlacesPanel && !modeConfig.placesMode) stalePlacesPanel.remove();
    // Always clear the puzzle tray (and its timer/drag/resize listener) — renderStatePuzzle
    // rebuilds it from scratch, and any other mode must not inherit it.
    removePuzzleTray();
    removeFlagTray();
    removeSandboxPanel();
    removeMissingSandbox();
    removeFramingSandbox();
    removeProjectionLab();
    removeSunMoonPanel();
    removeSunPathMode();
    drawBorderState = null;
    // Free Explore's country popup is not tied to the map, so nothing else takes it down on
    // a mode switch — without this it stays on screen over whatever loads next.
    closeCountryPopup();
    gameState = {
        score: 0,
        currentQuestion: 1,
        totalQuestions: modeConfig.totalQuestions,
        targetCountry: null,
        countries: [],
        answeredCorrectly: false,
        usedCountries: new Set(),
        questionType: null,
        currentAnswer: null,
        multipleChoiceOptions: [],
        subQuestionIndex: 0,
        maxSubQuestions: 3,
        mode: mode,
        currentDataObj: null,
        currentQuizList: null,
        foundCountries: new Set(),
        nameAllStartTime: null,
        nameAllGaveUp: false,
        placesSelections: {},   // Places-been: { placeName: 'visited'|'lived'|'passed' }
        placesMessage: '',
        ended: false
    };

    // Set current data sources
    // A sandbox/link seed is handed over exactly once, into the fresh gameState.
    gameState.spaceshipSeed = pendingSpaceshipSeed;
    if (pendingSpaceshipSeed) {
        gameState.totalQuestions = pendingSpaceshipSeed.length;
        document.getElementById('total-questions').textContent = String(gameState.totalQuestions);
    }
    pendingSpaceshipSeed = null;

    gameState.currentDataObj = window[modeConfig.dataObjKey] || {};
    gameState.currentQuizList = modeConfig.quizList;
    console.log(`Mode: ${mode}, DataObj keys: ${Object.keys(gameState.currentDataObj).length}, Sample keys: ${Object.keys(gameState.currentDataObj).slice(0, 5)}`);

    // Clear any previous game state messages
    const feedback = document.getElementById('feedback');
    feedback.textContent = '';
    feedback.className = 'feedback';
    document.getElementById('question-text').innerHTML = '';

    // Clear dynamically appended content from question-container
    const orderingContainer = document.getElementById('ordering-container');
    if (orderingContainer) orderingContainer.remove();
    const nameAllInputContainer = document.getElementById('name-all-input-container');
    if (nameAllInputContainer) nameAllInputContainer.remove();
    const capitalsRaceInputContainer = document.getElementById('capitals-race-input-container');
    if (capitalsRaceInputContainer) capitalsRaceInputContainer.remove();
    const wsPanel = document.getElementById('ws-panel');
    if (wsPanel) wsPanel.remove();

    // Clear world quiz feedback
    const flagFeedback = document.getElementById('flag-feedback');
    if (flagFeedback) {
        flagFeedback.textContent = '';
        flagFeedback.className = 'feedback';
    }
    const capitalFeedback = document.getElementById('capital-feedback');
    if (capitalFeedback) {
        capitalFeedback.textContent = '';
        capitalFeedback.className = 'feedback';
    }

    // Update score display
    document.getElementById('score').textContent = '0'; syncScoreDisplay();
    document.getElementById('current-question').textContent = '1';

    // Hide mode selector and show game elements with top bar
    document.getElementById('mode-selector').classList.add('hidden');
    document.getElementById('states-selector').classList.add('hidden');
    document.getElementById('landing-header').style.display = 'none';
    document.getElementById('top-bar').style.display = '';
    document.getElementById('controls').classList.remove('hidden');
    syncScoreDisplay();

    // Show gamma lock toggle only for the orthographic globe view (not the fixed spaceship view)
    const gammaToggle = document.getElementById('gamma-lock-toggle');
    // Named explicitly rather than left to isGlobeView(): `flatGlobeView` is not set for the new
    // mode until further down this same function, so this test still sees the PREVIOUS mode's
    // answer and a flat board can inherit a tilt button from whatever came before it.
    gammaToggle.style.display = (isGlobeView() && !modeConfig.spaceshipMode &&
        !modeConfig.projectionLabMode && !modeConfig.framingSandboxMode &&
        !modeConfig.missingSandboxMode && !modeConfig.sbQuizMode) ? '' : 'none';
    gammaToggle.textContent = gammaLocked ? 'Tilt: Locked' : 'Tilt: Free';

    // Detail toggle: only for world (countries) maps that follow the global detail level —
    // not the spaceship close-up, the sandbox that models it, or the shape silhouette, all
    // of which pin their own resolution.
    const detailToggle = document.getElementById('detail-toggle');
    if (detailToggle) {
        detailToggle.style.display = (modeConfig.mapObject === 'countries' && !modeConfig.spaceshipMode &&
            !modeConfig.sandboxMode && !modeConfig.countryShapeIdMode &&
            !modeConfig.projectionLabMode && !modeConfig.sbQuizMode) ? '' : 'none';
        detailToggle.textContent = 'Detail: ' + mapDetail.charAt(0).toUpperCase() + mapDetail.slice(1);
    }

    // Orbital tuning (altitude + scoring weights): only for the orbital view.
    const spaceshipTuning = document.getElementById('spaceship-tuning');
    if (spaceshipTuning) spaceshipTuning.style.display = modeConfig.spaceshipMode ? '' : 'none';

    // Country-outline hint button: shown only in the spaceship view; label reflects state.
    const hintBtn = document.getElementById('hint-outlines-toggle');
    if (hintBtn) {
        hintBtn.style.display = modeConfig.spaceshipMode ? '' : 'none';
        hintBtn.textContent = 'Outlines: ' + (orbitalHintOn ? 'On' : 'Off');
    }

    // Five-colour map: offered where adjacency is the thing being looked at.
    const colourBtn = document.getElementById('map-colour-toggle');
    if (colourBtn) {
        const wants = gameState.mode === 'sb-missing' || !!modeConfig.missingSandboxMode;
        colourBtn.style.display = wants ? '' : 'none';
        if (!wants && mapColourOn) { mapColourOn = false; }
        mapColourCache = null;
        colourBtn.textContent = 'Colours: ' + (mapColourOn ? 'On' : 'Off');
    }

    // Show the projection (globe/flat) toggle only for globe-capable modes
    const projToggle = document.getElementById('projection-toggle');
    if (projToggle) {
        // The quick quizzes each present themselves one way on purpose — a lone silhouette,
        // a flat pair, a coastline-only world — and none of them is answerable any better on
        // the other projection, so the toggle is only a way to break the framing.
        // In the Explore pair the button is not a projection toggle at all: it is the door
        // between the two halves of the folder. Free Explore has one view (a globe you turn) and
        // the lab has fourteen, so "flat or round" was never the question there — the question is
        // which of the two you want to be in.
        const explorePair = modeConfig.freeExploreMode || modeConfig.projectionLabMode;
        projToggle.style.display = (explorePair ||
            (modeConfig.useGlobe && !modeConfig.spaceshipMode && !modeConfig.sbQuizMode)) ? '' : 'none';
        projToggle.textContent = explorePair
            ? (modeConfig.projectionLabMode ? 'View: Globe' : 'View: Projections')
            : (flatGlobeView ? 'View: Map' : 'View: Globe');
    }

    // Reset the debug overlay for each new game
    debugValidityOn = false;
    const debugToggle = document.getElementById('debug-validity-toggle');
    if (debugToggle) debugToggle.textContent = 'Debug: Off';

    // Show appropriate layout based on mode
    if (modeConfig.useWorldQuizLayout) {
        // Use World Quiz Layout (globe left 2/3, questions right 1/3)
        document.getElementById('world-quiz-layout').classList.remove('hidden');
        document.getElementById('world-quiz-question-bar').classList.remove('hidden');
        document.getElementById('question-container').classList.add('hidden');
        document.getElementById('multiple-choice-container').classList.add('hidden');
        document.getElementById('map-container').classList.add('hidden');

    } else {
        // Use standard layout
        document.getElementById('question-container').classList.remove('hidden');
        document.getElementById('map-container').classList.remove('hidden');

        document.getElementById('world-quiz-layout').classList.add('hidden');
        document.getElementById('world-quiz-question-bar').classList.add('hidden');
    }

    // Reflect the current mode in the URL so a plain "copy link" shares this mode. Places
    // mode manages its own richer URL (region + selections + message) in updatePlacesUrl.
    if (!modeConfig.placesMode && !gameState.spaceshipSeed && !modeConfig.sandboxMode) syncModeUrl(mode);

    // Setup visualization based on mode
    // Skip map loading for the map-less modes (ordering, skyline photos, Sun Path's canvases)
    if (modeConfig.orderingMode || modeConfig.skylineIdMode || modeConfig.sunPathMode ||
        modeConfig.flagWorkshopMode) {
        startNewQuestion();
    } else {
        if (modeConfig.spaceshipMode) flatGlobeView = false; // always orthographic for the LEO view
        if (modeConfig.sbQuizMode) flatGlobeView = !!modeConfig.sbFlat;  // see sbFlat
        // The surgery is a world-scale thing to look at, and an orthographic globe can only
        // ever show half of it.
        if (modeConfig.missingSandboxMode) flatGlobeView = true;
        // A framing question is a Mercator question — that is the projection every mode that
        // uses shapeFramingCore fits into.
        if (modeConfig.framingSandboxMode) flatGlobeView = true;
        // The lab supplies its own projection every frame; the globe/flat switch would only
        // fight it.
        if (modeConfig.projectionLabMode) flatGlobeView = true;
        setupGlobe();
        loadMapData();
    }
}

// Custom AlbersUSA composite projection that includes a Puerto Rico inset.
// Based on https://observablehq.com/@d3/u-s-map-with-puerto-rico
function geoAlbersUsaPr() {
    const ε = 1e-6;

    const lower48   = d3.geoAlbers();
    const alaska    = d3.geoConicEqualArea().rotate([154, 0]).center([-2,   58.5]).parallels([55, 65]);
    const hawaii    = d3.geoConicEqualArea().rotate([157, 0]).center([-3,   19.9]).parallels([ 8, 18]);
    const puertoRico= d3.geoConicEqualArea().rotate([ 66, 0]).center([ 0,   18  ]).parallels([ 8, 18]);

    // pointStream pattern: calling a sub-projection's stream with this sink lets us
    // test whether a lat/lon falls inside that sub-projection's clipExtent.
    let point;
    const pointStream = { point(x, y) { point = [x, y]; } };
    let lower48Point, alaskaPoint, hawaiiPoint, puertoRicoPoint;

    let cache, cacheStream;

    function multiplex(streams) {
        const n = streams.length;
        return {
            point(x, y)     { for (let i = 0; i < n; i++) streams[i].point(x, y); },
            sphere()         { for (let i = 0; i < n; i++) streams[i].sphere(); },
            lineStart()      { for (let i = 0; i < n; i++) streams[i].lineStart(); },
            lineEnd()        { for (let i = 0; i < n; i++) streams[i].lineEnd(); },
            polygonStart()   { for (let i = 0; i < n; i++) streams[i].polygonStart(); },
            polygonEnd()     { for (let i = 0; i < n; i++) streams[i].polygonEnd(); }
        };
    }

    function reset() { cache = cacheStream = null; return albersUsaPr; }

    // The projection callable: routes a [lon,lat] to the correct inset.
    function albersUsaPr(coordinates) {
        const x = coordinates[0], y = coordinates[1];
        return (point = null,
            (lower48Point.point(x, y),    point) ||
            (alaskaPoint.point(x, y),     point) ||
            (hawaiiPoint.point(x, y),     point) ||
            (puertoRicoPoint.point(x, y), point));
    }

    albersUsaPr.invert = function(coordinates) {
        const k = lower48.scale();
        const t = lower48.translate();
        const x = (coordinates[0] - t[0]) / k;
        const y = (coordinates[1] - t[1]) / k;
        return (y >= 0.120 && y < 0.234 && x >= -0.425 && x < -0.214 ? alaska
              : y >= 0.166 && y < 0.234 && x >= -0.214 && x < -0.115 ? hawaii
              : y >= 0.166 && y < 0.234 && x >=  0.320 && x <  0.380 ? puertoRico
              : lower48).invert(coordinates);
    };

    albersUsaPr.stream = function(output) {
        if (cache && cacheStream === output) return cache;
        cache = multiplex([
            lower48.stream(output),
            alaska.stream(output),
            hawaii.stream(output),
            puertoRico.stream(output)
        ]);
        cacheStream = output;
        return cache;
    };

    albersUsaPr.precision = function(_) {
        if (!arguments.length) return lower48.precision();
        lower48.precision(_); alaska.precision(_); hawaii.precision(_); puertoRico.precision(_);
        return reset();
    };

    albersUsaPr.scale = function(_) {
        if (!arguments.length) return lower48.scale();
        const k = +_;
        lower48.scale(k);
        alaska.scale(k * 0.35);
        hawaii.scale(k);
        puertoRico.scale(k * 1.5);
        return albersUsaPr.translate(lower48.translate());
    };

    albersUsaPr.translate = function(_) {
        if (!arguments.length) return lower48.translate();
        const k = lower48.scale();
        const x = +_[0], y = +_[1];

        lower48Point = lower48
            .translate([x, y])
            .clipExtent([[x - 0.455*k + ε, y - 0.238*k + ε], [x + 0.455*k - ε, y + 0.238*k - ε]])
            .stream(pointStream);

        alaskaPoint = alaska
            .translate([x - 0.307*k, y + 0.201*k])
            .clipExtent([[x - 0.425*k + ε, y + 0.120*k + ε], [x - 0.214*k - ε, y + 0.234*k - ε]])
            .stream(pointStream);

        hawaiiPoint = hawaii
            .translate([x - 0.205*k, y + 0.212*k])
            .clipExtent([[x - 0.214*k + ε, y + 0.166*k + ε], [x - 0.115*k - ε, y + 0.234*k - ε]])
            .stream(pointStream);

        puertoRicoPoint = puertoRico
            .translate([x + 0.350*k, y + 0.212*k])
            .clipExtent([[x + 0.320*k + ε, y + 0.166*k + ε], [x + 0.380*k - ε, y + 0.234*k - ε]])
            .stream(pointStream);

        return reset();
    };

    albersUsaPr.fitExtent = function(extent, object) {
        const w = extent[1][0] - extent[0][0];
        const h = extent[1][1] - extent[0][1];

        // Reset to reference scale/translate so sub-projection clipExtents are well-defined
        albersUsaPr.scale(150).translate([0, 0]);

        // Compute the bounding box of all projected features
        let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
        d3.geoStream(object, albersUsaPr.stream({
            point(x, y) {
                if (x < x0) x0 = x; if (x > x1) x1 = x;
                if (y < y0) y0 = y; if (y > y1) y1 = y;
            },
            lineStart(){}, lineEnd(){}, polygonStart(){}, polygonEnd(){}, sphere(){}
        }));

        if (x1 < x0) return albersUsaPr; // nothing projected

        const k = 0.95 * Math.min(w / (x1 - x0), h / (y1 - y0));
        const tx = +extent[0][0] + (w - k * (x1 + x0)) / 2;
        const ty = +extent[0][1] + (h - k * (y1 + y0)) / 2;
        return albersUsaPr.scale(k * 150).translate([tx, ty]);
    };

    albersUsaPr.fitSize = function(size, object) {
        return albersUsaPr.fitExtent([[0, 0], size], object);
    };

    // Initialise at default scale with a placeholder translate so pointStreams are created
    return albersUsaPr.scale(1070).translate([480, 300]);
}

// ==================== FLAT WORLD (wrapping Mercator) ====================
// The flat view of the world crops to a band that barely contains Greenland to
// the north and the southern tip of Chile to the south, fills the container, and
// wraps continuously east-west (horizontal panning rotates the projection's
// longitude rather than translating, so countries re-enter on the far edge).
const FLAT_WORLD_NORTH = 84;
const FLAT_WORLD_SOUTH = -56;

function mercatorY(latDeg) {
    return Math.log(Math.tan(Math.PI / 4 + (latDeg * Math.PI / 180) / 2));
}

// True when showing the wrapping flat world (a globe mode, in map view, world geometry).
function isFlatWorldView() {
    const mc = QUIZ_MODES[gameState.mode];
    return !!(mc && mc.useGlobe && flatGlobeView && mc.mapObject === 'countries');
}

// Scale that fills the container for the crop band (also the zoom-out floor).
function flatWorldFitScale() {
    const band = mercatorY(FLAT_WORLD_NORTH) - mercatorY(FLAT_WORLD_SOUTH);
    return Math.max(width / (2 * Math.PI), height / band);
}

// Keep the crop band covering the viewport vertically (no blank above/below).
function clampFlatWorldVertical() {
    const s = projection.scale();
    const t = projection.translate();
    const a = s * mercatorY(FLAT_WORLD_NORTH);          // translate[1] that puts North at y=0
    const b = height + s * mercatorY(FLAT_WORLD_SOUTH); // translate[1] that puts South at y=height
    const ty = Math.max(Math.min(a, b), Math.min(Math.max(a, b), t[1]));
    if (ty !== t[1]) projection.translate([t[0], ty]);
}

// The sandbox needs the Antarctic coast on screen (it is shoreline like any other), so it
// fits the taller −82..84 band instead of the Greenland–Chile crop the guessing maps use.
// Mercator runs to infinity at the pole; −82 is as far as is worth showing and still clears
// the Ross ice shelf edge at −78.5. The fit is height-limited, so the world ends up narrower
// than the container — centred, which is what the extra width is for.
const FLAT_SANDBOX_SOUTH = -82;
function fitSandboxWorld(proj) {
    const north = mercatorY(FLAT_WORLD_NORTH), south = mercatorY(FLAT_SANDBOX_SOUTH);
    const scale = Math.min(width / (2 * Math.PI), height / (north - south));
    proj.center([0, 0]);
    proj.rotate([0, 0, 0]);
    proj.scale(scale);
    proj.translate([width / 2, height / 2 + scale * (north + south) / 2]);
}

// Fit the whole world into the container width (all longitudes visible) for the
// Find-the-Capital guessing map — a static, non-wrapping Mercator.
function fitCapitalWorld(proj) {
    const yMid = (mercatorY(FLAT_WORLD_NORTH) + mercatorY(FLAT_WORLD_SOUTH)) / 2;
    const scale = width / (2 * Math.PI);
    proj.center([0, 0]);
    proj.rotate([0, 0, 0]);
    proj.scale(scale);
    proj.translate([width / 2, height / 2 + scale * yMid]);
}

// Configure the projection to fill the container for the crop band, centered.
function fitFlatWorld(proj) {
    const yMid = (mercatorY(FLAT_WORLD_NORTH) + mercatorY(FLAT_WORLD_SOUTH)) / 2;
    const scale = flatWorldFitScale();
    proj.center([0, 0]);
    proj.rotate([0, 0, 0]);
    proj.scale(scale);
    proj.translate([width / 2, height / 2 + scale * yMid]);
}

// Set up the globe SVG and projection
// Modes whose map must not pan or zoom. Find-the-Capital and Place-the-Countries store
// guess markers as pixel coordinates; the puzzle board has to keep matching its pieces;
// and Country Shape ID fits the projection to one country per question, so any pan drags
// the silhouette straight off the viewport (which reads as the country vanishing).
// A click that MOVED is not a click. Browsers still fire one at the end of a drag, and on the
// static boards there is no d3.drag installed to swallow it (d3-drag suppresses the click itself
// once the pointer passes `clickDistance`) — so a stray swipe re-pinned a guess somewhere the
// player never aimed, or spent a detail step. Which is the most likely accident there is on a
// board that does not pan: the map does not move, so a drag feels like nothing happened.
// The threshold matches the 8 px the touch handlers already use to tell a tap from a drag.
const SVG_CLICK_SLOP = 8;
let svgPointerFrom = null;
function svgClickDragged(event) {
    const from = svgPointerFrom;
    svgPointerFrom = null;
    if (!from || typeof svg === 'undefined' || !svg) return false;
    const p = d3.pointer(event, svg.node());
    return Math.hypot(p[0] - from[0], p[1] - from[1]) > SVG_CLICK_SLOP;
}

function isStaticMapMode(mc) {
    // A sandbox round showing ONE shape is framed to that shape and nothing else, so a wheel
    // or a drag has nowhere to go but off the edge — scrolling on Every Neighbour simply made
    // the country disappear. It unlocks the moment the reveal hands the board back (which
    // clears `solo`), because zooming into the answer is the whole point of that map.
    if (mc && mc.sbQuizMode && gameState.sbQuestion && gameState.sbQuestion.solo) return true;
    // A reveal may lock the board back down. Near to Far's is an argument about distances made by
    // a particular projection centred on a particular place: dragging it re-centres nothing (the
    // rotation comes from the anchor) and only slides the argument off the edge.
    if (mc && mc.sbQuizMode && gameState.sbQuestion && gameState.sbQuestion.lockMap) return true;
    if (mc && mc.framingSandboxMode) return true;
    // The lab's drag is its own — it turns the WORLD under the projection rather than panning
    // the picture — so the shared pan and wheel must keep off it.
    if (mc && mc.projectionLabMode) return true;
    return !!(mc && (mc.findCapitalMode || mc.statePuzzleMode || mc.countryShapeIdMode ||
                     mc.sandboxMode || mc.drawBorderMode));
}

function setupGlobe() {
    const modeConfig = QUIZ_MODES[gameState.mode];

    // Leaving the orbital ("spaceship") view: tear down its WebGL canvas/context.
    if (!modeConfig.spaceshipMode) disposeOrbital();

    // Select the appropriate SVG element based on layout
    const svgId = modeConfig.useWorldQuizLayout ? '#globe-world' : '#globe';

    // Clear any existing content in the SVG
    d3.select(svgId).selectAll('*').remove();

    svg = d3.select(svgId)
        .attr('viewBox', `0 0 ${width} ${height}`)
        .attr('preserveAspectRatio', 'xMidYMid meet')
        .style('width', '100%')
        .style('height', '100%')
        .style('display', '')          // undo any prior spaceship-mode hide
        .style('touch-action', 'none');

    const globeView = modeConfig.useGlobe && !flatGlobeView;
    const spaceship = modeConfig.spaceshipMode;
    svg.classed('spaceship-view', !!spaceship);

    if (spaceship) {
        // The orbital view is drawn by three.js on its own WebGL canvas. This
        // projection is only scaffolding so the shared globe setup below (and the
        // now-hidden SVG) has a valid projection to path against.
        projection = d3.geoOrthographic()
            .translate([width / 2, height / 2])
            .clipAngle(90);
    } else if (globeView) {
        // Orthographic projection for globe view
        projection = d3.geoOrthographic()
            .scale(Math.min(width, height) / 2 - 10)
            .translate([width / 2, height / 2])
            .clipAngle(90);
    } else if (modeConfig.useAlbersUsa) {
        // Albers USA composite projection — AK and HI insets are built in
        projection = d3.geoAlbersUsa();
    } else {
        // Mercator projection for regional maps (India, Germany, etc.) and the flat world view.
        // precision(0) disables D3's adaptive great-circle resampling, which would otherwise
        // bow straight parallels (e.g. the 49th-parallel US–Canada border) into visible curves.
        projection = d3.geoMercator()
            .center([0, 0])
            .scale(1)
            .translate([width / 2, height / 2])
            .precision(0);
    }

    path = d3.geoPath().projection(projection);

    // Add gradient for ocean
    // Pull the muted ocean tones from the active theme's CSS variables
    const rootStyle = getComputedStyle(document.documentElement);
    const ocean1 = (rootStyle.getPropertyValue('--ocean-1').trim()) || '#aebfca';
    const ocean2 = (rootStyle.getPropertyValue('--ocean-2').trim()) || '#647d8d';

    const defs = svg.append('defs');
    // userSpaceOnUse so the ocean circle/sphere AND carved-out lakes all sample the
    // same globe-centered gradient (kept in sync by syncOceanGradient on every redraw).
    const gradient = defs.append('radialGradient')
        .attr('id', 'ocean-gradient')
        .attr('gradientUnits', 'userSpaceOnUse')
        .attr('cx', width / 2).attr('cy', height / 2).attr('r', projection.scale() || Math.min(width, height) / 2);

    gradient.append('stop')
        .attr('offset', '0%')
        .attr('stop-color', ocean1);

    gradient.append('stop')
        .attr('offset', '100%')
        .attr('stop-color', ocean2);

    // Create main group
    g = svg.append('g');

    if (spaceship) {
        // The photographic orbital view renders on a three.js WebGL canvas overlaid on
        // the map container (created lazily in ensureOrbital); hide the SVG globe.
        svg.style('display', 'none');
    } else if (globeView) {
        // Draw ocean for globe view
        g.append('circle')
            .attr('cx', width / 2)
            .attr('cy', height / 2)
            .attr('r', projection.scale())
            .attr('fill', 'url(#ocean-gradient)')
            .attr('stroke', ocean2)
            .attr('stroke-width', 1.5);
    }

    // Group for countries
    countriesGroup = g.append('g');

    // Add drag behavior: quaternion rotation for the globe, simple panning for flat maps
    // (the orbital view has its own pointer handlers on the WebGL canvas).
    // Static-map modes get NO map drag at all: the puzzle stores its pieces in projected
    // board coordinates and the guess/silhouette modes pin their markers the same way, so a
    // pan or a rotate would slide the map out from under them.
    //
    // The test is made AT DRAG TIME, not here. setupGlobe runs when the map loads, which for a
    // sandbox round is before the round exists — so `gameState.sbQuestion` was undefined,
    // isStaticMapMode said no, and every solo board (Pin the Capital, Every Neighbour, Name the
    // Lake) got a live pan handler attached for good. The board is fitted to one shape, so a
    // drag slid that shape straight off the edge and the round looked like it had vanished. The
    // wheel and touch handlers always tested live; only the drag was decided up front.
    svg.on('dragstart', (event) => event.preventDefault());
    svg.style('user-select', 'none');
    svg.on('pointerdown.clickslop', (event) => { svgPointerFrom = d3.pointer(event, svg.node()); });
    const staticNow = () => isStaticMapMode(QUIZ_MODES[gameState.mode]);
    if (globeView && !spaceship) {
        const drag = d3.drag()
            .on('start', (...a) => { if (!staticNow()) dragStart(...a); })
            .on('drag', (...a) => { if (!staticNow()) dragging(...a); })
            .on('end', (...a) => { if (!staticNow()) dragEnd(...a); });

        svg.call(drag);
    } else if (modeConfig.useGlobe) {
        // Flat (Mercator) view of a globe mode: drag to pan
        let panLast = null;
        const flatDrag = d3.drag()
            .on('start', (event) => { panLast = staticNow() ? null : [event.x, event.y]; })
            .on('drag', (event) => {
                if (gameState.scrollLocked || !panLast || staticNow()) return;
                const dx = event.x - panLast[0];
                const dy = event.y - panLast[1];
                if (isFlatWorldView()) {
                    // Horizontal pan rotates the projection's longitude → seamless wrap.
                    const dLon = dx * 360 / (2 * Math.PI * projection.scale());
                    const r = projection.rotate();
                    projection.rotate([r[0] + dLon, r[1], r[2]]);
                    const t = projection.translate();
                    projection.translate([t[0], t[1] + dy]);
                    clampFlatWorldVertical();
                } else {
                    const t = projection.translate();
                    projection.translate([t[0] + dx, t[1] + dy]);
                }
                panLast = [event.x, event.y];
                countriesGroup.selectAll('path').attr('d', path);
                updateIslandMarkers();
            });
        svg.call(flatDrag);
    }

    // Find-the-Capital / Place-the-Countries: clicking the static map drops/moves a guess marker.
    if (modeConfig.findCapitalMode) {
        svg.on('click', handleCapitalGuessClick);
    }

    // Add zoom behavior with scroll wheel (Jason Davies style)
    svg.on('wheel', function(event) {
        // Don't allow scrolling if locked
        if (gameState.scrollLocked) {
            event.preventDefault();
            return;
        }

        event.preventDefault();

        // Draw the Border is otherwise static, but a bounded zoom is genuinely useful there.
        if (QUIZ_MODES[gameState.mode] && QUIZ_MODES[gameState.mode].drawBorderMode) {
            zoomDrawBorder(event);
            return;
        }
        if (isStaticMapMode(QUIZ_MODES[gameState.mode])) return;

        const delta = -event.deltaY * (event.deltaMode === 1 ? 0.05 : event.deltaMode ? 1 : 0.002);
        const scale = projection.scale();
        const k = Math.pow(2, delta);
        const newScale = scale * k;

        // Set min and max scale limits (don't zoom out beyond starting view)
        const minScale = gameState.initialScale || 100;
        const maxScale = 2000;

        if (newScale >= minScale && newScale <= maxScale) {
            const modeConfig = QUIZ_MODES[gameState.mode];

            if (isFlatWorldView()) {
                // Flat world: zoom about the cursor — longitude via rotation
                // (keeps the wrap), latitude via translate.
                const mouse = d3.pointer(event, svg.node());
                const geo = projection.invert(mouse);
                projection.scale(newScale);
                if (geo) {
                    const after = projection(geo);
                    if (after) {
                        const dLon = (mouse[0] - after[0]) * 360 / (2 * Math.PI * newScale);
                        const r = projection.rotate();
                        projection.rotate([r[0] + dLon, r[1], r[2]]);
                        const after2 = projection(geo);
                        if (after2) {
                            const t = projection.translate();
                            projection.translate([t[0], t[1] + (mouse[1] - after2[1])]);
                        }
                    }
                }
                clampFlatWorldVertical();
            } else if (isGlobeView()) {
                // Globe mode: zoom towards mouse position using rotation
                const mouse = d3.pointer(event, svg.node());
                const mouseGeo = projection.invert(mouse);

                projection.scale(newScale);

                // Adjust rotation to zoom towards mouse position
                if (mouseGeo && !isNaN(mouseGeo[0]) && !isNaN(mouseGeo[1])) {
                    const mousePx = projection(mouseGeo);
                    if (mousePx) {
                        const dx = mousePx[0] - mouse[0];
                        const dy = mousePx[1] - mouse[1];
                        const rotation = projection.rotate();
                        const k = 75 / scale;
                        projection.rotate([rotation[0] + dx * k, rotation[1] - dy * k, rotation[2]]);
                        r_unconstrained = projection.rotate().slice();
                    }
                }

                // Update ocean circle for globe view
                g.select('circle').attr('r', newScale);
            } else {
                // States mode: zoom centered on closest state to cursor
                const mouse = d3.pointer(event, svg.node());
                const mouseGeo = projection.invert(mouse);

                // Find the state under the cursor or closest to it
                let targetState = null;
                if (mouseGeo && !isNaN(mouseGeo[0]) && !isNaN(mouseGeo[1]) && gameState.countries) {
                    // First, try to find a state that contains the mouse point
                    for (const state of gameState.countries) {
                        if (d3.geoContains(state, mouseGeo)) {
                            targetState = state;
                            break;
                        }
                    }

                    // If no state contains the mouse (outside bounds), find the closest state
                    if (!targetState && gameState.countries.length > 0) {
                        let minDist = Infinity;
                        for (const state of gameState.countries) {
                            const centroid = d3.geoCentroid(state);
                            const dist = Math.sqrt(
                                Math.pow(centroid[0] - mouseGeo[0], 2) +
                                Math.pow(centroid[1] - mouseGeo[1], 2)
                            );
                            if (dist < minDist) {
                                minDist = dist;
                                targetState = state;
                            }
                        }
                    }
                }

                // Zoom centered on the target state's centroid
                if (targetState) {
                    const centroid = d3.geoCentroid(targetState);
                    const centroidPx = projection(centroid);

                    projection.scale(newScale);

                    // Adjust translate to keep centroid at the same screen position
                    const newCentroidPx = projection(centroid);
                    if (centroidPx && newCentroidPx) {
                        const translate = projection.translate();
                        projection.translate([
                            translate[0] + (centroidPx[0] - newCentroidPx[0]),
                            translate[1] + (centroidPx[1] - newCentroidPx[1])
                        ]);
                    }
                } else {
                    // Fallback: just scale without repositioning
                    projection.scale(newScale);
                }
            }

            countriesGroup.selectAll('path').attr('d', path);
            updateIslandMarkers();
        }
    });

    // Touch support: pinch-to-zoom and single-finger drag
    let touchState = { lastDist: null, lastCenter: null, dragging: false, moved: false, startPos: null, wasPinch: false };

    function touchDist(touches) {
        const dx = touches[0].clientX - touches[1].clientX;
        const dy = touches[0].clientY - touches[1].clientY;
        return Math.sqrt(dx * dx + dy * dy);
    }

    function svgPoint(touch) {
        const rect = svg.node().getBoundingClientRect();
        const scaleX = width / rect.width;
        const scaleY = height / rect.height;
        return [(touch.clientX - rect.left) * scaleX, (touch.clientY - rect.top) * scaleY];
    }

    svg.node().addEventListener('touchstart', function(e) {
        if (gameState.scrollLocked) return;
        if (isStaticMapMode(QUIZ_MODES[gameState.mode])) return;
        if (e.touches.length === 2) {
            e.preventDefault();
            touchState.lastDist = touchDist(e.touches);
            touchState.dragging = false;
            touchState.wasPinch = true;
        } else if (e.touches.length === 1 && !touchState.wasPinch) {
            touchState.dragging = true;
            touchState.moved = false;
            touchState.lastCenter = null;
            touchState.startPos = { x: e.touches[0].clientX, y: e.touches[0].clientY };
            const p = svgPoint(e.touches[0]);
            r0 = projection.rotate();
            v0 = versor.cartesian(projection.invert(p));
            q0 = versor(r_unconstrained || r0);
        }
    }, { passive: false });

    svg.node().addEventListener('touchmove', function(e) {
        if (gameState.scrollLocked) return;
        if (isStaticMapMode(QUIZ_MODES[gameState.mode])) return;
        e.preventDefault();
        if (e.touches.length === 2) {
            // Pinch zoom
            const dist = touchDist(e.touches);
            if (touchState.lastDist) {
                const k = dist / touchState.lastDist;
                const scale = projection.scale();
                const newScale = scale * k;
                const minScale = gameState.initialScale || 100;
                const maxScale = 2000;
                if (newScale >= minScale && newScale <= maxScale) {
                    projection.scale(newScale);
                    if (isGlobeView()) {
                        g.select('circle').attr('r', newScale);
                    }
                    countriesGroup.selectAll('path').attr('d', path);
                    updateIslandMarkers();
                }
            }
            touchState.lastDist = dist;
        } else if (e.touches.length === 1 && touchState.dragging) {
            // Check if finger has moved enough to count as a drag (not a tap)
            if (touchState.startPos) {
                const dx = e.touches[0].clientX - touchState.startPos.x;
                const dy = e.touches[0].clientY - touchState.startPos.y;
                if (Math.sqrt(dx * dx + dy * dy) > 8) touchState.moved = true;
            }
            if (!touchState.moved) return;

            const p = svgPoint(e.touches[0]);
            if (isGlobeView()) {
                projection.rotate(r0);
                const v1 = versor.cartesian(projection.invert(p));
                const q1 = versor.multiply(q0, versor.delta(v0, v1));
                const r1 = versor.rotation(q1);
                if (gammaLocked) {
                    const constrainedLat = Math.max(-85, Math.min(85, r1[1]));
                    const locked = [r1[0], constrainedLat, 0];
                    projection.rotate(locked);
                    r_unconstrained = locked;
                } else {
                    projection.rotate(r1);
                    r_unconstrained = r1;
                }
            } else {
                // Flat map pan
                if (touchState.lastCenter) {
                    const pdx = p[0] - touchState.lastCenter[0];
                    const pdy = p[1] - touchState.lastCenter[1];
                    if (isFlatWorldView()) {
                        const dLon = pdx * 360 / (2 * Math.PI * projection.scale());
                        const r = projection.rotate();
                        projection.rotate([r[0] + dLon, r[1], r[2]]);
                        const t = projection.translate();
                        projection.translate([t[0], t[1] + pdy]);
                        clampFlatWorldVertical();
                    } else if (!(QUIZ_MODES[gameState.mode] && QUIZ_MODES[gameState.mode].findCapitalMode)) {
                        const t = projection.translate();
                        projection.translate([t[0] + pdx, t[1] + pdy]);
                    }
                }
            }
            touchState.lastCenter = p;
            countriesGroup.selectAll('path').attr('d', path);
            updateIslandMarkers();
        }
    }, { passive: false });

    svg.node().addEventListener('touchend', function(e) {
        if (e.touches.length < 2) touchState.lastDist = null;
        if (e.touches.length === 0) {
            // If it was a clean single-finger tap (no drag, no pinch), simulate a click
            if (!touchState.moved && !touchState.wasPinch && touchState.startPos) {
                const target = document.elementFromPoint(touchState.startPos.x, touchState.startPos.y);
                if (target) target.dispatchEvent(new MouseEvent('click', { bubbles: true }));
            }
            touchState.dragging = false;
            touchState.moved = false;
            touchState.wasPinch = false;
            touchState.lastCenter = null;
            touchState.startPos = null;
        }
    });
}

// Some hi-res world features render as the whole globe: either wound backwards
// (cleanly inverted → reverse the rings) or genuinely broken (e.g. Maldives in the
// 10m data, whose geoArea is nonsensically huge → drop it; it falls back to an
// island dot). A real country never exceeds ~half a steradian, so anything over a
// hemisphere is bad geometry.
function reverseRings(g) {
    if (!g) return;
    if (g.type === 'Polygon') g.coordinates.forEach(r => r.reverse());
    else if (g.type === 'MultiPolygon') g.coordinates.forEach(p => p.forEach(r => r.reverse()));
}

function fixCountryWinding(features) {
    for (let i = features.length - 1; i >= 0; i--) {
        const f = features[i];
        if (!f.geometry) continue;
        if (d3.geoArea(f) > 2 * Math.PI) {
            reverseRings(f.geometry);          // try to fix a clean inversion
            if (d3.geoArea(f) > 2 * Math.PI) {
                features.splice(i, 1);         // still broken → drop so it can't cover the map
            }
        }
    }
}

// Load map data based on current mode
function loadMapData() {
    const modeConfig = QUIZ_MODES[gameState.mode];

    // World modes pick their resolution from the detail toggle; others use their fixed URL.
    const mapUrl = (modeConfig.mapObject === 'countries') ? worldCountriesUrl() : modeConfig.mapUrl;
    const loader = (modeConfig.mapObject === 'countries') ? fetchWorldTopo(mapUrl) : d3.json(mapUrl);
    loader
        .then(data => {
            // Check mapObject to determine how to process the data
            gameState.mapTopology = (data && data.objects) ? data : null;   // kept for Draw the Border's arc filter
            if (modeConfig.mapObject === 'countries') {
                gameState.countries = worldFeaturesFromTopology(data);

                // Add country names. Some features (disputed territories) have no
                // numeric id; keep their original map name instead of a placeholder.
                gameState.countries.forEach(country => {
                    const mapped = getCountryName(country.id);
                    if (!/^Country /.test(mapped)) {
                        country.properties.name = mapped;
                    }
                });
                // Tag overseas territories with their sovereign parent so they fill
                // with (and count as) the parent, while staying separate features.
                splitDisputedGlacier(gameState.countries);
                tagTerritories(gameState.countries);
                fixCountryWinding(gameState.countries);

                // Flat (Mercator) view of the world: crop to the Greenland–Chile
                // band, fill the container, and enable east-west wrapping.
                // The orthographic globe keeps its fixed scale instead.
                if (modeConfig.sandboxMode) {
                    fitSandboxWorld(projection);  // taller crop: the Antarctic coast is in play
                } else if (modeConfig.findCapitalMode || modeConfig.statePuzzleMode || modeConfig.drawBorderMode) {
                    // Static full-width world. The puzzle needs this too: without a fit, a
                    // non-globe `countries` map keeps Mercator's default scale of 1 and the
                    // whole board collapses to a dot.
                    fitCapitalWorld(projection); // static full-width world for guessing
                } else if (flatGlobeView) {
                    fitFlatWorld(projection);
                }
            } else if (modeConfig.mapObject === 'states') {
                gameState.countries = topojson.feature(data, data.objects.states).features;
                gameState.countries.forEach(state => {
                    state.properties.name = getStateName(state.id);
                });
                // geoAlbersUsa handles AK/HI insets; fitSize scales the whole composite
                projection.fitSize([width, height], {
                    type: 'FeatureCollection',
                    features: gameState.countries
                });
            } else if (modeConfig.mapObject === null) {
                // For maps with null mapObject (like Indian states), data is already in GeoJSON format
                if (data.features) {
                    gameState.countries = data.features;
                } else {
                    gameState.countries = data;
                }

                // Map state names from properties
                gameState.countries.forEach(state => {
                    if (state.properties.st_nm) {
                        state.properties.name = state.properties.st_nm;
                    } else if (state.properties.NAME_1) {
                        state.properties.name = state.properties.NAME_1;
                    } else if (state.properties.CTRY21NM) {
                        state.properties.name = state.properties.CTRY21NM;
                    }
                });

                // Fit projection to data
                projection.fitSize([width, height], {
                    type: 'FeatureCollection',
                    features: gameState.countries
                });
            }

            shapeDescriptorCache = null; // rebuild shape descriptors for the new geometry
            drawCountries();
            gameState.initialScale = projection.scale();
            startNewQuestion();
        })
        .catch(error => {
            console.error('Error loading map data:', error);
            document.getElementById('question-text').textContent = 'Error loading map data';
        });
}

// Snapshot the per-feature marks a redraw would otherwise wipe: the class attribute
// (target / found / places categories) AND any inline fill (the flag pattern painted by
// fillCountryWithFlag). Covers the country paths and the island dots alike — dots are
// rebuilt from scratch by drawIslandMarkers, so unlike the paths they lose *everything*.
function captureFeatureMarks() {
    const marks = { paths: [], dots: [] };
    const grab = (bucket, baseClass) => function (d) {
        const cls = this.getAttribute('class') || '';
        const fill = this.style.fill || '';
        const stroke = this.style.stroke || '';
        if (cls === baseClass && !fill && !stroke) return;   // untouched feature: nothing to restore
        const name = d && d.properties && d.properties.name;
        if (name) bucket.push({ name, cls, fill, stroke });
    };
    if (countriesGroup) countriesGroup.selectAll('path').each(grab(marks.paths, 'country'));
    if (islandMarkersGroup) islandMarkersGroup.selectAll('circle').each(grab(marks.dots, 'country island-marker'));
    return marks;
}

// Re-apply a captureFeatureMarks() snapshot after the geometry has been redrawn.
function restoreFeatureMarks(marks) {
    if (!marks) return;
    const apply = (sel, list) => list.forEach(m => {
        const hit = sel.filter(d => d && d.properties && d.properties.name === m.name);
        hit.attr('class', m.cls);
        if (m.fill) hit.style('fill', m.fill);
        if (m.stroke) hit.style('stroke', m.stroke);
    });
    if (countriesGroup) apply(countriesGroup.selectAll('path'), marks.paths);
    if (islandMarkersGroup) apply(islandMarkersGroup.selectAll('circle'), marks.dots);
}

// Reload the world geometry at the current detail level WITHOUT starting a new
// question — preserves rotation/scale and any in-progress highlight.
function reloadWorldDetail() {
    const modeConfig = QUIZ_MODES[gameState.mode];
    if (!countriesGroup || !modeConfig || modeConfig.mapObject !== 'countries') return;

    // Capture highlight classes + flag fills (paths AND dots) to restore after the redraw.
    const marks = captureFeatureMarks();

    const rot = projection.rotate(), sc = projection.scale(), tr = projection.translate();
    fetchWorldTopo(worldCountriesUrl()).then(data => {
        gameState.countries = worldFeaturesFromTopology(data);
        gameState.countries.forEach(c => {
            const m = getCountryName(c.id);
            if (!/^Country /.test(m)) c.properties.name = m;
        });
        splitDisputedGlacier(gameState.countries);
        fixCountryWinding(gameState.countries);
        projection.rotate(rot).scale(sc).translate(tr);
        countriesGroup.selectAll('*').remove();
        drawCountries(); // redraws land + lakes + island dots
        restoreFeatureMarks(marks);
        updateIslandMarkers();
    }).catch(err => console.error('Detail reload failed:', err));
}

// Load world map data (legacy function for backwards compatibility)
function loadWorldData() {
    loadMapData();
}

// ==================== OVERSEAS TERRITORIES ====================
// Overseas dependencies that appear as their OWN feature in the world-atlas but
// belong to a sovereign parent. Keyed by ISO 3166-1 numeric id (= the atlas
// feature id). Marking these lets us: (a) fill them green when the parent is
// named/clicked, (b) count a click on the territory as finding the parent, and
// (c) label/flag them by the parent — e.g. "Puerto Rico (USA)". Because they stay
// SEPARATE features with their own names, the parent's shape/centroid/bounding box
// (used for zoom and Shape-ID) naturally excludes them, as requested.
// `code` is the territory's own ISO 3166-1 alpha-2 (for its flag on flagcdn and for the
// Places-been share URL), distinct from its sovereign parent's.
const TERRITORY_BY_ID = {
    // United Kingdom
    60:  { name: 'Bermuda',                     parent: 'United Kingdom', code: 'bm' },
    92:  { name: 'British Virgin Islands',      parent: 'United Kingdom', code: 'vg' },
    136: { name: 'Cayman Islands',              parent: 'United Kingdom', code: 'ky' },
    238: { name: 'Falkland Islands',            parent: 'United Kingdom', code: 'fk' },
    292: { name: 'Gibraltar',                   parent: 'United Kingdom', code: 'gi' },
    500: { name: 'Montserrat',                  parent: 'United Kingdom', code: 'ms' },
    654: { name: 'Saint Helena',                parent: 'United Kingdom', code: 'sh' },
    660: { name: 'Anguilla',                    parent: 'United Kingdom', code: 'ai' },
    796: { name: 'Turks and Caicos Islands',    parent: 'United Kingdom', code: 'tc' },
    831: { name: 'Guernsey',                    parent: 'United Kingdom', code: 'gg' },
    832: { name: 'Jersey',                      parent: 'United Kingdom', code: 'je' },
    833: { name: 'Isle of Man',                 parent: 'United Kingdom', code: 'im' },
    // United States
    16:  { name: 'American Samoa',              parent: 'United States of America', code: 'as' },
    316: { name: 'Guam',                        parent: 'United States of America', code: 'gu' },
    580: { name: 'Northern Mariana Islands',    parent: 'United States of America', code: 'mp' },
    630: { name: 'Puerto Rico',                 parent: 'United States of America', code: 'pr' },
    850: { name: 'United States Virgin Islands', parent: 'United States of America', code: 'vi' },
    // France
    258: { name: 'French Polynesia',            parent: 'France', code: 'pf' },
    260: { name: 'French Southern Territories', parent: 'France', code: 'tf' },
    540: { name: 'New Caledonia',               parent: 'France', code: 'nc' },
    663: { name: 'Saint Martin',                parent: 'France', code: 'mf' },
    666: { name: 'Saint Pierre and Miquelon',   parent: 'France', code: 'pm' },
    876: { name: 'Wallis and Futuna',           parent: 'France', code: 'wf' },
    // Denmark
    234: { name: 'Faroe Islands',               parent: 'Denmark', code: 'fo' },
    304: { name: 'Greenland',                   parent: 'Denmark', code: 'gl' },
    // Netherlands
    531: { name: 'Curaçao',                     parent: 'Netherlands', code: 'cw' },
    533: { name: 'Aruba',                       parent: 'Netherlands', code: 'aw' },
    534: { name: 'Sint Maarten',                parent: 'Netherlands', code: 'sx' },
    // New Zealand
    184: { name: 'Cook Islands',                parent: 'New Zealand', code: 'ck' },
    570: { name: 'Niue',                        parent: 'New Zealand', code: 'nu' },
    // Australia
    162: { name: 'Christmas Island',            parent: 'Australia', code: 'cx' },
    166: { name: 'Cocos Islands',               parent: 'Australia', code: 'cc' },
    574: { name: 'Norfolk Island',              parent: 'Australia', code: 'nf' },
};

// Short parenthetical shown after a territory's name, e.g. "Puerto Rico (USA)".
const PARENT_ABBREV = {
    'United States of America': 'USA',
    'United Kingdom': 'UK',
    'New Zealand': 'NZ',
};

// Reverse map (territory name -> parent name), built once from TERRITORY_BY_ID.
const TERRITORY_PARENT_BY_NAME = {};
Object.values(TERRITORY_BY_ID).forEach(t => { TERRITORY_PARENT_BY_NAME[t.name] = t.parent; });

// Territory name <-> own ISO code maps (for Places-been flags and share URLs).
const TERRITORY_CODE_BY_NAME = {};
const TERRITORY_NAME_BY_CODE = {};
Object.values(TERRITORY_BY_ID).forEach(t => {
    if (!t.code) return;
    TERRITORY_CODE_BY_NAME[t.name] = t.code;
    TERRITORY_NAME_BY_CODE[t.code] = t.name;
});

// Parent country name for a territory, or null if `name` isn't a territory.
function parentOfTerritory(name) {
    return TERRITORY_PARENT_BY_NAME[name] || null;
}

// The name to use for data lookups (flag / capital / population): a territory
// resolves to its sovereign parent, everything else is itself.
function effectiveDataName(name) {
    return parentOfTerritory(name) || name;
}

// Display label for a feature/name — "Puerto Rico (USA)" for territories.
function displayLabelForName(name) {
    const parent = parentOfTerritory(name);
    if (!parent) return name;
    return `${name} (${PARENT_ABBREV[parent] || parent})`;
}

// Attach territory metadata (parent, isTerritory, displayName) to world features.
// ==================== THE DISPUTED GLACIER ====================
// Natural Earth ships the Siachen Glacier as its own admin-0 unit — it is claimed by both India
// and Pakistan and administered by neither exclusively, so the atlas declines to award it. That
// is the honest cartographic choice and the wrong one for this app: it leaves a 2,200 km² hole
// in the map belonging to no country in the quiz list, which shows up as an unclickable blank in
// every Find round, an unnamed shape in Name All, and a stray neighbour in the border graph.
//
// It is split down the middle and given to both. West to Pakistan, east to India, which is the
// side each actually holds — the Actual Ground Position Line runs roughly north–south along the
// Saltoro Ridge with Indian positions to its east. A meridian through the glacier's own centroid
// is a rough stand-in for that ridge, and rough is the right precision here: the point is that
// the map has no holes in it, not that a quiz adjudicates a border dispute.
const GLACIER_NAME = 'Siachen Glacier';
const GLACIER_WEST = 'Pakistan';
const GLACIER_EAST = 'India';

// Sutherland–Hodgman against a meridian. Clipping a ring against a half-plane is the whole of
// it: walk the edges, keep the vertices on the wanted side, and emit the crossing point
// wherever an edge changes side.
function clipRingByMeridian(ring, lon, keepWest) {
    const inside = pt => (keepWest ? pt[0] <= lon : pt[0] >= lon);
    const out = [];
    for (let i = 0; i < ring.length - 1; i++) {
        const a = ring[i], b = ring[i + 1];
        const ai = inside(a), bi = inside(b);
        if (ai) out.push(a);
        if (ai !== bi) {
            const t = (lon - a[0]) / (b[0] - a[0]);
            out.push([lon, a[1] + (b[1] - a[1]) * t]);
        }
    }
    if (out.length < 3) return null;
    if (out[0][0] !== out[out.length - 1][0] || out[0][1] !== out[out.length - 1][1]) out.push(out[0]);
    return out;
}

function splitDisputedGlacier(features) {
    if (!features) return features;
    const gi = features.findIndex(f => f && f.properties && namesMatch(f.properties.name || '', GLACIER_NAME));
    if (gi < 0) return features;
    const glacier = features[gi];
    const west = features.find(f => f && f.properties && namesMatch(f.properties.name || '', GLACIER_WEST));
    const east = features.find(f => f && f.properties && namesMatch(f.properties.name || '', GLACIER_EAST));
    // If either neighbour is missing (a resolution that ships one and not the other), leave the
    // glacier alone rather than deleting land from the map.
    if (!west || !east) return features;

    const cut = d3.geoCentroid(glacier)[0];
    const halves = { west: [], east: [] };
    featureParts(glacier).forEach(poly => {
        // Outer ring only. The glacier has no holes, and a hole clipped independently of its
        // shell is a shape with no defined inside.
        const w = clipRingByMeridian(poly[0], cut, true);
        const e = clipRingByMeridian(poly[0], cut, false);
        if (w) halves.west.push([w]);
        if (e) halves.east.push([e]);
    });
    if (!halves.west.length || !halves.east.length) return features;

    const give = (target, polys) => {
        const geom = target.geometry;
        const own = geom.type === 'Polygon' ? [geom.coordinates] : geom.coordinates;
        target.geometry = { type: 'MultiPolygon', coordinates: own.concat(polys) };
    };
    give(west, halves.west);
    give(east, halves.east);
    features.splice(gi, 1);
    return features;
}

function tagTerritories(features) {
    features.forEach(f => {
        const terr = TERRITORY_BY_ID[parseInt(f.id, 10)];
        if (!terr) return;
        f.properties.name = terr.name;
        f.properties.parent = terr.parent;
        f.properties.isTerritory = true;
        f.properties.displayName = displayLabelForName(terr.name);
    });
}

