// Country dots: a feature whose largest polygon is too small to see on screen (and
// any world micro-state with no polygon at all) is drawn as a clickable circle
// instead of an invisible sliver. Dot-vs-outline is decided per redraw from the
// on-screen pixel size, so it updates live as you zoom.
let islandMarkersGroup = null;
const ISLAND_MARKER_RADIUS = 4;
let DOT_PIXEL_THRESHOLD = 5;       // largest-polygon pixel size below which a dot is shown (slider-tunable)
const DOT_CANDIDATE_AREA = 0.05;   // steradians; bigger features are always outlines (skip the pixel check)
let DOT_SPACING = 5;               // min centre-to-centre px between dots; closer ones are nudged apart (slider-tunable)
const MIN_LAKE_DIAM_KM = 32;       // lakes whose largest inscribed circle is narrower than this (km) are hidden; ~just under Great Salt Lake. Locked.
// The Lake Winnipeg system is several separate Natural Earth features; treat them as
// one for the size filter so they appear/disappear together instead of fragmenting.
const WINNIPEG_GROUP = new Set(['Lake Winnipeg', 'Cedar Lake', 'Lake Manitoba', 'Lake Winnipegosis']);
let lakesGroup = null;     // major-lakes overlay (Great Lakes, Victoria, Baikal, …)
// Natural Earth lakes at two resolutions so the overlay tracks the map's detail level:
// 110m is bundled locally; 50m is fetched from jsdelivr and cached, with the local 110m
// file as a fallback. Keyed by resolution → features array.
const lakesCache = {};

// medium maps to 110m, NOT 50m: country coastlines at 'medium' are the 50m source
// client-side-simplified down to MEDIUM_SIMPLIFY_RETAIN (20%) via worldFeaturesFromTopology,
// but lake polygons have no equivalent simplification pass — fetching raw 50m lakes for
// 'medium' rendered them sharper than the coastline they sit inside. 110m lakes are close
// in coarseness to a 20%-simplified 50m coastline, and (being the bundled local file) need
// no network fetch, so 'medium' now locks to the same source as 'low'.
function lakesResForDetail() {
    const mc = QUIZ_MODES[gameState.mode];
    if (mc && mc.spaceshipMode) return '110m';                 // moot — lakes are suppressed in the orbital view
    if (mc && mc.sbHiRes) return '10m';                        // Name the Lake is judged on the outline
    return ({ low: '110m', medium: '110m', high: '50m' })[mapDetail] || '110m';
}
function lakesUrlForRes(res) {
    return res === '110m'
        ? 'data/lakes.geo.json'
        : `https://cdn.jsdelivr.net/gh/martynafford/natural-earth-geojson@master/${res}/physical/ne_${res}_lakes.json`;
}

// Draw countries on the globe
function drawCountries() {
    const mc = QUIZ_MODES[gameState.mode];
    // The States Puzzle draws empty slots (or a bare silhouette) plus a layer for placed
    // pieces — nothing clickable, and no lakes or island dots.
    if (mc && mc.statePuzzleMode) { drawPuzzleBoard(); return; }
    // Country Shape ID draws only the current target (in renderCountryShapeIdQuestion);
    // adding the whole 10m world here would be far too heavy for a one-country view.
    if (mc && mc.drawBorderMode) { drawBorderBoard(); return; }

    // Some sandbox rounds show ONE shape and nothing else — the surrounding map is the answer
    // in those (Every Neighbour would just point at its own neighbours; Pin the Capital was
    // reading as broken because the country sat in a world it did not need).
    if (mc && mc.sbQuizMode && sbCustomBoard()) return;

    // The framing sandbox owns its board too, and it has to be redrawn from state rather than
    // merely drawn once: a resize, a projection change or any other caller reaching
    // drawCountries would otherwise replace the parts with the ordinary world map and the
    // country would simply vanish.
    if (mc && mc.framingSandboxMode) { if (framingState && framingState.feature) framingDraw(); return; }

    // Same reason as the framing sandbox: the lab owns its board and has to rebuild it from
    // state, or any caller reaching drawCountries replaces it with the ordinary world map.
    if (mc && mc.projectionLabMode) { if (labState) labDraw(); return; }

    // Coming Into Focus draws one growing outline into countriesGroup and nothing else. The
    // shape-id branch below skips the join, so the path survives — but only if it is still
    // attached; if something emptied the group, put it back at the detail it had reached.
    if (mc && mc.countryShapeIdMode && shapeUnfold) {
        const node = shapeUnfold.layer.node();
        if (!node || !node.isConnected) {
            shapeUnfold.layer = countriesGroup.append('path').attr('class', 'country shape-target shape-unfold');
            drawShapeUnfold(shapeUnfold.points);
        }
    }

    if (!(mc && mc.countryShapeIdMode)) {
        // A FULL join — enter, update and exit. It used to be enter-only, which is invisible
        // while the group starts empty (the normal case) and silently wrong the moment
        // drawCountries runs twice against a changed feature list: `enter()` is empty, so the
        // existing paths keep their old `d` and the new geometry is never drawn at all. That is
        // what left Who's Missing showing the *previous* round's map, with one orphaned path
        // per removed country and no round independent of the one before it.
        const sel = countriesGroup.selectAll('path.country').data(gameState.countries);
        sel.exit().remove();
        sel.enter()
            .append('path')
            .attr('class', 'country')
            .on('click', handleCountryClick)
            .merge(sel)
            .attr('d', path);
    }

    drawLakes();          // water on top of land, below the clickable dots
    drawIslandMarkers();

    // A sandbox reveal that hands the board back to the ordinary drawing path still needs its
    // countries picked out, and this is the one place every redraw goes through.
    if (mc && mc.sbQuizMode) sbApplyBoardMarks();
    if (mapColourOn) applyMapColouring();

    // Re-apply the debug validity overlay if it is currently on
    if (debugValidityOn) applyDebugValidity();
}

// ---- Largest-inscribed-circle ("fatness") metric for lakes ----
// Even-odd point-in-polygon test against a set of rings ([[x,y],...] each).
function pointInPolygon(x, y, rings) {
    let inside = false;
    for (const ring of rings) {
        for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
            const xi = ring[i][0], yi = ring[i][1], xj = ring[j][0], yj = ring[j][1];
            if (((yi > y) !== (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) inside = !inside;
        }
    }
    return inside;
}

function pointToSegmentDist(px, py, a, b) {
    const dx = b[0] - a[0], dy = b[1] - a[1];
    let t = 0;
    const len2 = dx * dx + dy * dy;
    if (len2 > 0) t = Math.max(0, Math.min(1, ((px - a[0]) * dx + (py - a[1]) * dy) / len2));
    return Math.hypot(px - (a[0] + t * dx), py - (a[1] + t * dy));
}

function distToRings(x, y, rings) {
    let m = Infinity;
    for (const ring of rings) {
        for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
            m = Math.min(m, pointToSegmentDist(x, y, ring[j], ring[i]));
        }
    }
    return m;
}

// Compact polylabel: coarse bbox grid → best interior cell → one local refine pass.
// Returns the radius; largestInscribedCircle returns the POINT as well, which Who's Missing
// needs — it partitions a country by pulling every neighbour's border in to that point.
function largestInscribedRadius(rings) {
    return largestInscribedCircle(rings).radius;
}

function largestInscribedCircle(rings) {
    let minx = Infinity, miny = Infinity, maxx = -Infinity, maxy = -Infinity;
    for (const r of rings) for (const p of r) {
        if (p[0] < minx) minx = p[0]; if (p[0] > maxx) maxx = p[0];
        if (p[1] < miny) miny = p[1]; if (p[1] > maxy) maxy = p[1];
    }
    const search = (x0, y0, x1, y1, steps) => {
        let best = 0, bx = (x0 + x1) / 2, by = (y0 + y1) / 2;
        for (let i = 0; i <= steps; i++) for (let j = 0; j <= steps; j++) {
            const x = x0 + (x1 - x0) * i / steps, y = y0 + (y1 - y0) * j / steps;
            if (!pointInPolygon(x, y, rings)) continue;
            const d = distToRings(x, y, rings);
            if (d > best) { best = d; bx = x; by = y; }
        }
        return { best, bx, by };
    };
    const coarse = search(minx, miny, maxx, maxy, 40);
    const cw = (maxx - minx) / 40, ch = (maxy - miny) / 40;
    const fine = search(coarse.bx - cw, coarse.by - ch, coarse.bx + cw, coarse.by + ch, 20);
    const win = fine.best >= coarse.best ? fine : coarse;
    return { radius: win.best, x: win.bx, y: win.by };
}

// Diameter (km) of the largest circle that fits inside a lake feature's polygon.
// Cached on the feature object — drawLakes runs on every redraw, and at 50m there
// are many lakes, so this must not recompute per-redraw.
function lakeInscribedDiamKm(f) {
    if (f._lakeDiamKm != null) return f._lakeDiamKm;
    const geom = f.geometry;
    const polys = geom.type === 'Polygon' ? [geom.coordinates] : geom.coordinates;
    const [[w, s], [e, n]] = d3.geoBounds(f);
    const lat0 = (s + n) / 2;
    const kx = 111.320 * Math.cos(lat0 * Math.PI / 180), ky = 110.574; // deg → km at this latitude
    let best = 0;
    for (const poly of polys) {
        const rings = poly.map(r => r.map(p => [p[0] * kx, p[1] * ky]));
        best = Math.max(best, largestInscribedRadius(rings));
    }
    return (f._lakeDiamKm = 2 * best);
}

// Draw the major-lakes overlay (water-colored, non-interactive) on world maps,
// at the resolution matching the current map detail level.
function drawLakes() {
    if (lakesGroup) { lakesGroup.remove(); lakesGroup = null; }
    // A board-replacing sandbox round shows one shape, or coastlines and nothing else. The
    // lake overlay is a SIBLING of countriesGroup, so emptying that leaves it behind and the
    // world's lakes float over a lone silhouette — and any later redraw puts them back, which
    // is why the board itself removing the group once was not enough.
    {
        const q = gameState.sbQuestion;
        if (q && (q.solo || q.coastOnly)) return;
    }
    const lakesMode = QUIZ_MODES[gameState.mode];
    if (!g || !lakesMode || lakesMode.mapObject !== 'countries' || lakesMode.countryShapeIdMode) return;
    if (lakesMode.spaceshipMode) return; // lakes project to infinity under the tilt camera

    const res = lakesResForDetail();
    const feats = lakesCache[res];
    if (feats === undefined) {
        lakesCache[res] = null; // mark in-flight to avoid duplicate fetches
        d3.json(lakesUrlForRes(res))
            .then(data => { lakesCache[res] = (data && data.features) || []; drawLakes(); updateIslandMarkers(); })
            .catch(() => {
                // Fall back to the bundled 110m file so lakes still render.
                d3.json('data/lakes.geo.json')
                    .then(d => { lakesCache[res] = (d && d.features) || []; drawLakes(); updateIslandMarkers(); })
                    .catch(() => { lakesCache[res] = []; });
            });
        return;
    }
    if (feats === null) return; // still loading this resolution

    // Filter by the diameter of the largest circle that fits inside each lake (its
    // "fatness"), so long-thin lakes read as small. The Winnipeg system shares one
    // metric (its largest member) so its parts pass/fail together.
    const nameOf = f => f && f.properties && f.properties.name;
    const groupDiam = feats
        .filter(f => WINNIPEG_GROUP.has(nameOf(f)))
        .reduce((m, f) => Math.max(m, lakeInscribedDiamKm(f)), 0);
    const visibleFeats = feats.filter(f => {
        const d = WINNIPEG_GROUP.has(nameOf(f)) ? groupDiam : lakeInscribedDiamKm(f);
        return d >= MIN_LAKE_DIAM_KM;
    });

    // Match the surrounding ocean: the shaded gradient on the globe/orbit views,
    // the flat-map surface colour on Mercator (where the card backdrop is the ocean).
    const oceanFill = isGlobeView() ? 'url(#ocean-gradient)' : 'var(--surface)';
    lakesGroup = g.append('g').attr('class', 'lakes');
    lakesGroup.selectAll('path')
        .data(visibleFeats)
        .enter()
        .append('path')
        .attr('class', 'lake')
        .attr('d', path)
        .style('fill', oceanFill);
}

// Split a Polygon/MultiPolygon feature's geometry into one ring-set per polygon PART. A
// feature with several islands scattered across many degrees has one combined bounding box
// spanning the whole spread — measuring THAT (rather than each part on its own) is what let
// a 10-island nation register as "big" even when no single island is more than a pixel.
function featureParts(feature) {
    // Accepts a Feature or a bare geometry. shapeFramingCore RETURNS a bare MultiPolygon, so
    // anything that wants to look at the parts of a core it just computed was silently getting
    // an empty list — which read as "this country has no parts at all".
    const geom = (feature && feature.geometry) || feature;
    if (!geom || !geom.type) return [];
    if (geom.type === 'Polygon') return [geom.coordinates];
    if (geom.type === 'MultiPolygon') return geom.coordinates;
    return [];
}

// Longitude span of a set of degrees, correctly handling antimeridian wraparound: the true
// extent going around the circle is 360° minus the single largest gap between consecutive
// (sorted) longitudes. d3.geoBounds gets this right when it has a whole feature's worth of
// points to find the gap in, but on an ISOLATED ring of just a few points that happens to
// sit right at ±180° (e.g. a sliver of Fiji), it can't tell which side is "outside" and
// reports the full 360° — this computes it directly from the ring's own points instead.
function lonSpanDeg(lons) {
    if (lons.length < 2) return 0;
    const sorted = lons.slice().sort((a, b) => a - b);
    let maxGap = 360 - (sorted[sorted.length - 1] - sorted[0]); // wrap-around gap: last → first
    for (let i = 1; i < sorted.length; i++) maxGap = Math.max(maxGap, sorted[i] - sorted[i - 1]);
    return 360 - maxGap;
}

// A feature's largest angular extent among its individual polygon PARTS, in radians
// (rotation-independent) — not the combined bounding box of every part. Multiplying by the
// orthographic scale gives the pixel size the LARGEST part would have at the centre of the
// globe — so the dot/outline decision doesn't change as a country rotates toward the limb
// (where perspective foreshortening would otherwise shrink it into a dot).
function angularDimOfBounds(b) {
    let dLon = b[1][0] - b[0][0];
    if (dLon < 0) dLon += 360; // antimeridian-wrap safety (rare for dot candidates)
    const dLat = b[1][1] - b[0][1];
    const midLat = (b[0][1] + b[1][1]) / 2 * Math.PI / 180;
    const angW = dLon * Math.PI / 180 * Math.cos(midLat); // shrink longitude span toward the poles
    const angH = dLat * Math.PI / 180;
    const m = Math.max(Math.abs(angW), Math.abs(angH));
    return isFinite(m) ? m : 0;
}
// Per-part angular extent computed directly from the part's own raw points (via lonSpanDeg)
// rather than through d3.geoBounds, since a single small part is exactly the case where
// d3.geoBounds's antimeridian heuristic can misfire (see lonSpanDeg).
function angularDimOfPart(coords) {
    let minLat = Infinity, maxLat = -Infinity;
    const lons = [];
    coords.forEach(ring => ring.forEach(p => {
        lons.push(p[0]);
        if (p[1] < minLat) minLat = p[1];
        if (p[1] > maxLat) maxLat = p[1];
    }));
    if (!lons.length) return 0;
    const dLon = lonSpanDeg(lons);
    const dLat = maxLat - minLat;
    const midLat = (minLat + maxLat) / 2 * Math.PI / 180;
    const angW = dLon * Math.PI / 180 * Math.cos(midLat);
    const angH = dLat * Math.PI / 180;
    const m = Math.max(Math.abs(angW), Math.abs(angH));
    return isFinite(m) ? m : 0;
}
function featureAngularDim(f) {
    const parts = featureParts(f);
    if (!parts.length) return angularDimOfBounds(d3.geoBounds(f)); // unexpected geometry type: fall back whole
    let maxDim = 0;
    for (const coords of parts) {
        maxDim = Math.max(maxDim, angularDimOfPart(coords));
    }
    return maxDim;
}

// The flat-map analogue of featureAngularDim: largest on-screen pixel dimension among a
// feature's individual polygon parts, under the CURRENT projection — not path.bounds() on
// the whole feature, which unions every part into one bbox.
function pixelDimOfBounds(b) {
    if (!isFinite(b[0][0]) || !isFinite(b[0][1]) || !isFinite(b[1][0]) || !isFinite(b[1][1])) return 0;
    return Math.max(b[1][0] - b[0][0], b[1][1] - b[0][1]);
}
function featureMaxPartPixelDim(feature) {
    const parts = featureParts(feature);
    if (!parts.length) return pixelDimOfBounds(path.bounds(feature)); // unexpected geometry type: fall back whole
    let maxDim = 0;
    for (const coords of parts) {
        maxDim = Math.max(maxDim, pixelDimOfBounds(path.bounds({ type: 'Polygon', coordinates: coords })));
    }
    return maxDim;
}

// Build the candidate dot set: quiz items with no polygon (world micro-states) or a
// small enough polygon that they might need a dot at some zoom. Each dot carries its
// feature (for the live pixel-size check) and a [lon,lat] anchor.
function drawIslandMarkers() {
    if (islandMarkersGroup) { islandMarkersGroup.remove(); islandMarkersGroup = null; }

    const mc = QUIZ_MODES[gameState.mode];
    if (!g || !mc || mc.spaceshipMode || mc.countryShapeIdMode) return; // no dots in spaceship / shape silhouette

    const dataObj = gameState.currentDataObj || {};
    const quizList = gameState.currentQuizList || [];
    const featureByName = new Map();
    // Some atlas resolutions split a country into several features sharing a name
    // (e.g. a real Australia MultiPolygon plus a stray micro-polygon). Keep the
    // LARGEST one so the dot/outline decision uses the country's true size.
    (gameState.countries || []).forEach(f => {
        const n = f && f.properties && f.properties.name;
        if (!n) return;
        const prev = featureByName.get(n);
        if (!prev || d3.geoArea(f) > d3.geoArea(prev)) featureByName.set(n, f);
    });

    // A country Who's Missing has eaten is absent from the features but still in the quiz list,
    // so the no-polygon fallback below would plant a dot exactly where it used to be — and name
    // the answer. It is the one name that must produce no marker at all.
    const eaten = (gameState.sbQuestion && gameState.sbQuestion.surgery)
        ? gameState.sbQuestion.surgery.gone : null;

    const dots = [];
    for (const name of quizList) {
        if (eaten && namesMatch(name, eaten)) continue;
        const f = featureByName.get(name);
        if (f) {
            if (d3.geoArea(f) > DOT_CANDIDATE_AREA) continue; // big feature: always an outline
            dots.push({ properties: { name }, feature: f, lonlat: d3.geoCentroid(f), angDim: featureAngularDim(f) });
        } else {
            const d = dataObj[name];
            if (d && Array.isArray(d.capitalCoords)) {
                dots.push({ properties: { name }, feature: null, lonlat: [d.capitalCoords[1], d.capitalCoords[0]] });
            }
        }
    }
    if (!dots.length) return;

    // Draw on top of the country paths so the dots stay clickable.
    islandMarkersGroup = g.append('g').attr('class', 'island-markers');
    islandMarkersGroup.selectAll('circle')
        .data(dots)
        .enter()
        .append('circle')
        .attr('class', 'country island-marker')
        .attr('r', ISLAND_MARKER_RADIUS)
        .on('click', handleCountryClick);

    updateIslandMarkers();

    // Re-apply Places-been fills — a full marker rebuild (detail change etc.) drops the
    // category classes; country paths keep theirs, so this only really re-colours the dots.
    if (QUIZ_MODES[gameState.mode] && QUIZ_MODES[gameState.mode].placesMode) applyPlacesFills();
}

// Keep the ocean gradient centered/sized on the globe so the ocean and the carved
// lakes share identical shading at any zoom.
function syncOceanGradient() {
    if (!svg) return;
    const grad = svg.select('#ocean-gradient');
    if (grad.empty() || !isGlobeView()) return;
    grad.attr('cx', width / 2).attr('cy', height / 2).attr('r', projection.scale());
}

// Per redraw: keep the ocean gradient + lakes in sync, then decide for each
// candidate whether to show a dot or its polygon outline based on pixel size,
// hiding the polygon underneath when a dot is shown.
function updateIslandMarkers() {
    syncOceanGradient();
    if (lakesGroup) lakesGroup.selectAll('path').attr('d', path);
    // Flag fills are derived from the CURRENT projection, so they refresh wherever the map
    // is re-pathed. Hooked here (above the marker guard) because every such path already
    // calls this, and a map with no island dots still has flags to keep glued down.
    updateFlagFills();
    // Same reasoning for the overlays the Sandbox modes hang off the projection (the
    // day/night terminator, the chain, the drawn border): this is the one function every
    // re-path already calls, so hooking here covers drag, wheel, pinch and animation alike.
    updateModeOverlays();
    if (!islandMarkersGroup) return;

    const globe = isGlobeView();
    // Only the orthographic globe has .rotate() and a far side to hide.
    const center = globe ? (() => { const r = projection.rotate(); return [-r[0], -r[1]]; })() : null;
    const dotted = new Set();
    const shown = [];      // visible dots, collected so overlapping ones can be spread apart
    const obstacles = [];  // small outline polygons a dot should not cover

    islandMarkersGroup.selectAll('circle').each(function (d) {
        const sel = d3.select(this);
        const xy = projection(d.lonlat);
        const offGlobe = globe && d3.geoDistance(d.lonlat, center) > Math.PI / 2;
        const valid = xy && !isNaN(xy[0]) && !offGlobe;
        let showDot = true;
        if (d.feature) {
            // On the globe, size the feature as if it were at the centre of view (angular
            // extent × scale) so it doesn't flip to a dot merely by rotating toward the
            // limb. Flat maps have no such foreshortening, so measure the on-screen bbox.
            // Both measure the LARGEST INDIVIDUAL polygon part, not every part combined.
            const maxDim = globe
                ? projection.scale() * (d.angDim || 0)
                : featureMaxPartPixelDim(d.feature);
            showDot = isFinite(maxDim) && maxDim < DOT_PIXEL_THRESHOLD;
        }
        if (!valid || !showDot) {
            sel.style('display', 'none');
            // A small feature shown as an outline (not a dot) is an obstacle the
            // surrounding dots should avoid covering.
            if (valid && !showDot && d.feature) obstacles.push({ x: xy[0], y: xy[1] });
        } else {
            sel.style('display', null);
            shown.push({ sel, x: xy[0], y: xy[1] });
            dotted.add(d.properties.name);
        }
    });

    // Nudge overlapping/too-close dots apart (and off small outline polygons) so each
    // stays individually visible — e.g. the dense Caribbean / Pacific clusters.
    relaxDots(shown, obstacles);
    shown.forEach(s => s.sel.attr('cx', s.x).attr('cy', s.y));

    // Hide the polygon outline for any country currently represented by a dot.
    countriesGroup.selectAll('path').each(function (d) {
        if (d && d.properties) this.style.display = dotted.has(d.properties.name) ? 'none' : null;
    });
}

// Simple iterative relaxation: push any pair of dots closer than DOT_SPACING apart
// (and push dots off fixed obstacle points the same distance). O(n²) but n is small.
function relaxDots(dots, obstacles) {
    const minD = DOT_SPACING;
    if (minD <= 0 || !dots.length) return;
    for (let iter = 0; iter < 12; iter++) {
        let moved = false;
        // Dot ↔ dot: split the overlap between the two.
        for (let i = 0; i < dots.length; i++) {
            for (let j = i + 1; j < dots.length; j++) {
                const a = dots[i], b = dots[j];
                let dx = b.x - a.x, dy = b.y - a.y;
                let dist = Math.hypot(dx, dy);
                if (dist >= minD) continue;
                if (dist < 1e-6) { dx = Math.random() - 0.5; dy = Math.random() - 0.5; dist = Math.hypot(dx, dy) || 1; }
                const push = (minD - dist) / 2;
                const ux = dx / dist, uy = dy / dist;
                a.x -= ux * push; a.y -= uy * push;
                b.x += ux * push; b.y += uy * push;
                moved = true;
            }
        }
        // Dot ↔ obstacle: only the dot moves (the polygon stays put).
        if (obstacles && obstacles.length) {
            for (const a of dots) {
                for (const o of obstacles) {
                    let dx = a.x - o.x, dy = a.y - o.y;
                    let dist = Math.hypot(dx, dy);
                    if (dist >= minD) continue;
                    if (dist < 1e-6) { dx = Math.random() - 0.5; dy = Math.random() - 0.5; dist = Math.hypot(dx, dy) || 1; }
                    const push = (minD - dist);
                    a.x += dx / dist * push; a.y += dy / dist * push;
                    moved = true;
                }
            }
        }
        if (!moved) break;
    }
}

// ==================== DEBUG: VALIDITY OVERLAY ====================
// Color-codes every map feature green (has matching quiz data) or red (no data),
// so it's easy to see which countries/states are actually playable.
let debugValidityOn = false;

function toggleDebugValidity() {
    // Only meaningful once a map is drawn
    if (typeof countriesGroup === 'undefined' || !countriesGroup) return;
    debugValidityOn = !debugValidityOn;
    applyDebugValidity();
    if (!debugValidityOn) clearDebugBoundingBoxes();
    const btn = document.getElementById('debug-validity-toggle');
    if (btn) btn.textContent = debugValidityOn ? 'Debug: On' : 'Debug: Off';
}

function applyDebugValidity() {
    if (!countriesGroup) return;
    const dataObj = gameState.currentDataObj || {};
    countriesGroup.selectAll('path').each(function (d) {
        const sel = d3.select(this);
        if (!debugValidityOn) {
            // Revert to stylesheet-driven colors
            sel.style('fill', null).style('stroke', null);
            return;
        }
        const name = d && d.properties && d.properties.name;
        const valid = name && Object.prototype.hasOwnProperty.call(dataObj, name);
        sel.style('fill', valid ? '#22c55e' : '#ef4444')
           .style('stroke', valid ? '#15803d' : '#991b1b');
    });
}

let debugBboxGroup = null;

function clearDebugBoundingBoxes() {
    if (debugBboxGroup) { debugBboxGroup.remove(); debugBboxGroup = null; }
}

// While the debug overlay is on, clicking/selecting a country draws its two pixel
// bounding boxes: the country's OWN feature (orange — what Shape-ID/zoom use, territories
// excluded) and the union INCLUDING its overseas territories (cyan). Static under the
// current projection (redraw by re-selecting); cleared on the next click / question.
function drawDebugBoundingBoxes(d) {
    clearDebugBoundingBoxes();
    if (!debugValidityOn || !g || !d || !d.properties) return;

    const name = d.properties.parent || d.properties.name;
    const members = (gameState.countries || []).filter(f => featureBelongsTo(f, name));
    const own = members.find(f => f.properties && f.properties.name === name && !f.properties.isTerritory)
        || (d.geometry ? d : (d.feature || null)); // fall back to the clicked feature itself

    debugBboxGroup = g.append('g').attr('class', 'debug-bbox-group').attr('pointer-events', 'none');

    const drawRect = (bounds, color, label) => {
        if (!bounds || !isFinite(bounds[0][0]) || !isFinite(bounds[1][0])) return;
        const x = bounds[0][0], y = bounds[0][1];
        const w = bounds[1][0] - bounds[0][0], h = bounds[1][1] - bounds[0][1];
        debugBboxGroup.append('rect')
            .attr('x', x).attr('y', y).attr('width', w).attr('height', h)
            .attr('fill', 'none').attr('stroke', color).attr('stroke-width', 1.5)
            .attr('stroke-dasharray', '5,3');
        debugBboxGroup.append('text')
            .attr('x', x + 2).attr('y', Math.max(y - 3, 10))
            .attr('fill', color).attr('font-size', '11px').attr('font-family', 'monospace')
            .text(label);
    };

    // With territories: union of every member feature's pixel bbox.
    let ub = null;
    members.forEach(f => {
        const b = path.bounds(f);
        if (!isFinite(b[0][0])) return;
        if (!ub) ub = [[b[0][0], b[0][1]], [b[1][0], b[1][1]]];
        else {
            ub[0][0] = Math.min(ub[0][0], b[0][0]); ub[0][1] = Math.min(ub[0][1], b[0][1]);
            ub[1][0] = Math.max(ub[1][0], b[1][0]); ub[1][1] = Math.max(ub[1][1], b[1][1]);
        }
    });
    drawRect(ub, '#22d3ee', name + ' +territories');            // cyan, drawn first (underneath)
    if (own && own.geometry) drawRect(path.bounds(own), '#f97316', name); // orange, on top
}

// ==================== PROJECTION TOGGLE (Globe <-> Mercator) ====================

// Switch the current globe mode between the orthographic globe and a flat Mercator
// map, preserving the in-progress question.
function toggleFlatGlobe() {
    const mc = QUIZ_MODES[gameState.mode];
    // In the Explore folder this button is the door between its two halves rather than a
    // projection switch: Free Explore has one view and the lab has fourteen, so "flat or round"
    // is not the question there. Which of the two you want to be in is.
    if (mc && mc.freeExploreMode) { startGameWithMode('projection-lab'); return; }
    if (mc && mc.projectionLabMode) { startGameWithMode('free-explore'); return; }
    if (!mc || !mc.useGlobe) return; // Only globe-capable modes can switch projection
    flatGlobeView = !flatGlobeView;
    reprojectMap();

    const btn = document.getElementById('projection-toggle');
    if (btn) btn.textContent = flatGlobeView ? 'View: Map' : 'View: Globe';
    const gammaToggle = document.getElementById('gamma-lock-toggle');
    if (gammaToggle) gammaToggle.style.display = isGlobeView() ? '' : 'none';
}

// Rebuild the map for the current projection without changing the question.
function reprojectMap() {
    if (!countriesGroup || !gameState.countries) return;

    // Capture current per-feature highlight state so it can be restored after redraw.
    // Includes the island dots, which setupGlobe/drawCountries rebuild from scratch.
    const marks = captureFeatureMarks();

    stopGlobeSpin();
    setupGlobe();

    // Flat world view: crop/fill/wrap; the globe keeps its fixed scale.
    if (flatGlobeView && QUIZ_MODES[gameState.mode].mapObject === 'countries') {
        fitFlatWorld(projection);
    }

    drawCountries();
    gameState.initialScale = projection.scale();

    // Restore highlights (the debug overlay is re-applied by drawCountries).
    if (!debugValidityOn) restoreFeatureMarks(marks);

    // In the globe view, re-center on the target for auto-rotate modes.
    if (isGlobeView() && QUIZ_MODES[gameState.mode].autoRotate && gameState.targetCountry) {
        rotateToCountry(gameState.targetCountry);
    }
}

// (drawUSStatesWithInlays removed — replaced by d3.geoAlbersUsa composite projection)
function drawUSStatesWithInlays_UNUSED() {
    // Draw contiguous states
    countriesGroup.selectAll('path.contiguous')
        .data(gameState.contiguousStates)
        .enter()
        .append('path')
        .attr('class', 'country contiguous')
        .attr('d', path)
        .on('click', handleCountryClick);

    // DEBUG: red border around contiguous 48 bounds
    const cb = path.bounds({ type: 'FeatureCollection', features: gameState.contiguousStates });
    g.append('rect')
        .attr('x', cb[0][0]).attr('y', cb[0][1])
        .attr('width', cb[1][0] - cb[0][0]).attr('height', cb[1][1] - cb[0][1])
        .attr('fill', 'none').attr('stroke', 'red').attr('stroke-width', 3)
        .attr('stroke-dasharray', '6,3').attr('class', 'debug-box');

    // Create inlay boxes in the reserved bottom strip (100px)
    const inlayWidth = 120;
    const inlayHeight = 80;
    const inlayPadding = 10;
    const inlayY = height - 100 + (100 - inlayHeight) / 2; // centered in the 100px strip

    // Alaska inlay (bottom-left)
    if (gameState.alaskaState.length > 0) {
        const alaskaGroup = g.append('g')
            .attr('class', 'inlay-group alaska-inlay')
            .attr('transform', `translate(${inlayPadding}, ${inlayY})`);

        // Inlay box background
        alaskaGroup.append('rect')
            .attr('width', inlayWidth)
            .attr('height', inlayHeight)
            .attr('fill', '#f0f0f0')
            .attr('stroke', 'blue')
            .attr('stroke-width', 3)
            .attr('rx', 5);

        // Create projection for Alaska.
        // Alaska's Aleutians cross the antimeridian, so Mercator fitSize produces a
        // world-spanning bounding box. Use a rotated conic projection centered on Alaska
        // and fitExtent to the known geographic bounds instead.
        // Bbox (user-supplied): -179.136,51.229 → 179.774,71.352
        const akBboxPoly = {
            type: 'Feature',
            geometry: {
                type: 'Polygon',
                coordinates: [[
                    [-179.13657211802118, 51.229087747767466],
                    [ 179.77488070600702, 51.229087747767466],
                    [ 179.77488070600702, 71.352561],
                    [-179.13657211802118, 71.352561],
                    [-179.13657211802118, 51.229087747767466]
                ]]
            }
        };
        const alaskaProjection = d3.geoConicEqualArea()
            .parallels([55, 65])
            .rotate([154, 0])
            .fitExtent([[5, 15], [inlayWidth - 5, inlayHeight - 5]], akBboxPoly);
        const alaskaPath = d3.geoPath().projection(alaskaProjection);

        // Draw Alaska
        alaskaGroup.selectAll('path.alaska')
            .data(gameState.alaskaState)
            .enter()
            .append('path')
            .attr('class', 'country alaska')
            .attr('d', d => alaskaPath(d))
            .attr('transform', 'translate(5, 15)')
            .on('click', handleCountryClick);

        // Label
        alaskaGroup.append('text')
            .attr('x', inlayWidth / 2)
            .attr('y', 12)
            .attr('text-anchor', 'middle')
            .attr('font-size', '10px')
            .attr('font-weight', 'bold')
            .attr('fill', '#333')
            .text('AK');
    }

    // Hawaii inlay (bottom-center)
    if (gameState.hawaiiState.length > 0) {
        const hawaiiX = (width - inlayWidth) / 2;
        const hawaiiGroup = g.append('g')
            .attr('class', 'inlay-group hawaii-inlay')
            .attr('transform', `translate(${hawaiiX}, ${inlayY})`);

        // Inlay box background
        hawaiiGroup.append('rect')
            .attr('width', inlayWidth)
            .attr('height', inlayHeight)
            .attr('fill', '#f0f0f0')
            .attr('stroke', 'green')
            .attr('stroke-width', 3)
            .attr('rx', 5);

        // Create projection for Hawaii
        const hawaiiProjection = d3.geoMercator()
            .fitSize([inlayWidth - 10, inlayHeight - 20], {
                type: 'FeatureCollection',
                features: gameState.hawaiiState
            });
        const hawaiiPath = d3.geoPath().projection(hawaiiProjection);

        // Draw Hawaii
        hawaiiGroup.selectAll('path.hawaii')
            .data(gameState.hawaiiState)
            .enter()
            .append('path')
            .attr('class', 'country hawaii')
            .attr('d', d => hawaiiPath(d))
            .attr('transform', 'translate(5, 15)')
            .on('click', handleCountryClick);

        // Label
        hawaiiGroup.append('text')
            .attr('x', inlayWidth / 2)
            .attr('y', 12)
            .attr('text-anchor', 'middle')
            .attr('font-size', '10px')
            .attr('font-weight', 'bold')
            .attr('fill', '#333')
            .text('HI');
    }

    // Puerto Rico inlay (bottom-right)
    if (gameState.puertoRicoState.length > 0) {
        const prX = width - inlayWidth - inlayPadding;
        const prGroup = g.append('g')
            .attr('class', 'inlay-group pr-inlay')
            .attr('transform', `translate(${prX}, ${inlayY})`);

        // Inlay box background
        prGroup.append('rect')
            .attr('width', inlayWidth)
            .attr('height', inlayHeight)
            .attr('fill', '#f0f0f0')
            .attr('stroke', 'magenta')
            .attr('stroke-width', 3)
            .attr('rx', 5);

        // Create projection for Puerto Rico
        const prProjection = d3.geoMercator()
            .fitSize([inlayWidth - 10, inlayHeight - 20], {
                type: 'FeatureCollection',
                features: gameState.puertoRicoState
            });
        const prPath = d3.geoPath().projection(prProjection);

        // Draw Puerto Rico
        prGroup.selectAll('path.pr')
            .data(gameState.puertoRicoState)
            .enter()
            .append('path')
            .attr('class', 'country pr')
            .attr('d', d => prPath(d))
            .attr('transform', 'translate(5, 15)')
            .on('click', handleCountryClick);

        // Label
        prGroup.append('text')
            .attr('x', inlayWidth / 2)
            .attr('y', 12)
            .attr('text-anchor', 'middle')
            .attr('font-size', '10px')
            .attr('font-weight', 'bold')
            .attr('fill', '#333')
            .text('PR');
    }
}

// Handle country click
function handleCountryClick(event, d) {
    // Debug: draw the clicked country's bounding boxes (own + with-territories) before
    // any mode-specific early-returns, so it works no matter what question is active.
    if (debugValidityOn) drawDebugBoundingBoxes(d);

    if (gameState.questionType === 'missing-sandbox') {
        msHandleClick(d.properties.parent || d.properties.name);
        return;
    }

    // Handle free explore mode clicks
    if (gameState.questionType === 'free-explore') {
        const countryName = d.properties.name;
        showCountryPopup(countryName);
        return;
    }

    // Places-been: cycle the clicked feature's own category. Unlike the quizzes, each
    // territory is independent of its parent here — clicking Denmark doesn't fill Greenland.
    if (gameState.questionType === 'places-been') {
        cyclePlace(d.properties.name);
        return;
    }

    // Only allow clicking countries during location or mystery-flag questions
    if (gameState.questionType !== 'location' && gameState.questionType !== 'mystery-flag') return;
    if (gameState.answeredCorrectly) return;

    // Only allow ONE click per question
    if (gameState.guessedThisQuestion) return;

    gameState.guessedThisQuestion = true;
    gameState.scrollLocked = true; // Lock scrolling during animation

    const modeConfig = QUIZ_MODES[gameState.mode];
    // A click on an overseas territory counts as finding its sovereign parent.
    const clickedCountry = d.properties.parent || d.properties.name;
    const isCorrect = clickedCountry === gameState.targetCountry;

    if (isCorrect) {
        if (modeConfig.useWorldQuizLayout) {
            // For World Quiz Layout, color correct country bright green and zoom to it.
            // Fill the parent AND any overseas territories, not just the clicked feature.
            highlightCountryOnGlobe(gameState.targetCountry);
            gameState.answeredCorrectly = true;
            gameState.score++;
            document.getElementById('score').textContent = gameState.score; syncScoreDisplay();

            // Zoom to correct country, then advance
            zoomAndRotateToCountry(gameState.targetCountry, 800).then(() => {
                // Keep scrolling locked until next question
                clearAutoAdvance();
                autoAdvanceTimer = setTimeout(() => {
                    autoAdvanceTimer = null;
                    gameState.subQuestionIndex++;
                    startNewQuestion();
                }, ANSWER_PAUSE_MS);
            });
        } else {
            handleCorrectAnswer(event.target);
            // Fill parent + territories (clicking any part of a country reveals the whole).
            highlightCountryOnGlobe(gameState.targetCountry);
            gameState.scrollLocked = false;
        }
    } else {
        if (modeConfig.useWorldQuizLayout) {
            // For World Quiz Layout, color incorrect country red instantly
            const incorrectElement = d3.select(event.target);
            incorrectElement.classed('incorrect', true);
            raiseHighlight(incorrectElement);

            // Zoom to incorrect country and pause before revealing the correct one
            zoomAndRotateToCountry(clickedCountry, 600).then(() => {
                return new Promise(resolve => setTimeout(resolve, ANSWER_PAUSE_MS));
            }).then(() => {
                // Find and highlight the correct country in green (covers island dots too).
                // The wrong country stays red (never cleared) so both are visible together.
                highlightCountryOnGlobe(gameState.targetCountry);

                // Zoom to correct country
                return zoomAndRotateToCountry(gameState.targetCountry, 800);
            }).then(() => {
                // Advance to next sub-question after showing the correct answer
                clearAutoAdvance();
                autoAdvanceTimer = setTimeout(() => {
                    autoAdvanceTimer = null;
                    gameState.subQuestionIndex++;
                    startNewQuestion();
                }, ANSWER_PAUSE_MS);
            });
        } else {
            handleIncorrectAnswer(event.target);

            // Highlight the correct answer in green — the wrong one (marked above) is
            // never cleared, so both stay visible together.
            highlightCountryOnGlobe(gameState.targetCountry);

            // Auto-advance to next sub-question even on incorrect answer
            const maxSub = maxSubForMode(modeConfig);

            if (gameState.subQuestionIndex < maxSub - 1) {
                // Show correct (green) and incorrect (red), pause, then advance
                clearAutoAdvance();
                autoAdvanceTimer = setTimeout(() => {
                    autoAdvanceTimer = null;
                    gameState.subQuestionIndex++;
                    gameState.scrollLocked = false;
                    startNewQuestion();
                }, ANSWER_PAUSE_MS);
            } else {
                // All sub-questions complete — enable Next as a manual skip, and auto-advance.
                gameState.scrollLocked = false;
                document.getElementById('next-btn').disabled = false;

                // For mystery-flag mode, rotate the correct country into view (it's already
                // highlighted, but may be off-screen/unrotated-to).
                if (modeConfig.mysteryFlagMode) rotateToCountry(gameState.targetCountry);

                scheduleAutoAdvance();
            }
        }
    }
}

// Number of sub-questions (score-able steps) per target for a mode. Single-question
// modes score 1 point per target; find modes score per sub-question (location, +flag,
// +capital). Kept in ONE place so the per-answer and end-of-game maths never diverge
// (a mismatch is what made Shape-ID cap at 50% even on a perfect run).
function maxSubForMode(mc) {
    if (!mc) return 1;
    if (mc.identifyOnly || mc.mysteryFlagMode || mc.capitalsRaceMode || mc.countryShapeIdMode ||
        mc.skylineIdMode || mc.statePuzzleMode || mc.capitalsChoiceMode || mc.flagPlaceMode ||
        mc.oddOneOutMode || mc.drawBorderMode || mc.sbQuizMode ||
        mc.findOnly) {
        return 1;
    }
    return mc.hasFlags ? 3 : 2;
}

// ---- Shared answer pacing -------------------------------------------------------------
// One knob controls every quiz mode's reveal/advance pacing (Settings ▸ Gameplay). A
// CORRECT answer: pause, then advance. A WRONG answer: pause, THEN reveal the correct
// answer alongside it (the wrong highlight is never cleared, so the two stay visible
// together — see handleIncorrectAnswer), pause again, then advance. Distance/score-based
// modes (find-capital, spaceship, ordering) have no "wrong" to reveal against, so they use
// a single pause after the result is shown, same shape as a correct answer.
let ANSWER_PAUSE_MS = 1200;
let autoAdvanceTimer = null;

function clearAutoAdvance() {
    if (autoAdvanceTimer) {
        clearTimeout(autoAdvanceTimer);
        autoAdvanceTimer = null;
    }
}

function scheduleAutoAdvance(delay = ANSWER_PAUSE_MS) {
    clearAutoAdvance();
    autoAdvanceTimer = setTimeout(goToNextQuestion, delay);
}

function goToNextQuestion() {
    clearAutoAdvance();
    gameState.subQuestionIndex = 0;
    gameState.currentQuestion++;
    if (gameState.currentQuestion <= gameState.totalQuestions) {
        gameState.answeredCorrectly = false;
        startNewQuestion();
    } else {
        endGame();
    }
}

// Handle correct answer. `award` is false when this is only being used to reveal the answer
// and drive the advance after the player already got it WRONG — that path must not score.
function handleCorrectAnswer(element, award = true) {
    gameState.answeredCorrectly = true;
    if (award) gameState.score++;

    // Always confirm a correct answer with a green highlight (path, dot, or button) — except
    // where the round's reveal is an argument and marks its own buttons at the end of it
    // (`deferMark`, and `sbMarkCorrectOption` does the marking). Stating the conclusion on the
    // click and then playing the case for it is the wrong way round.
    const defer = element && !element.ownerSVGElement &&
                  gameState.sbQuestion && gameState.sbQuestion.deferMark;
    if (element && !defer) {
        const sel = d3.select(element).classed('selected', false).classed('target', true).classed('correct', true);
        // Raise map highlights so their outline isn't clipped by neighbouring shapes.
        if (element.ownerSVGElement) raiseHighlight(sel);
    }
    document.getElementById('score').textContent = gameState.score; syncScoreDisplay();

    // The round is decided (this also runs for the auto-reveal after a wrong answer), so the
    // photo credit can finally be shown without its title spoiling the city.
    if (gameState.questionType === 'skyline-id') revealSkylineCredit();
    // Same idea for Shape ID's harder tiers: the silhouette turns back upright and fills in.
    if (gameState.questionType === 'country-shape-id') revealShapeIdTruth();

    // Determine max sub-questions based on mode
    const modeConfig = QUIZ_MODES[gameState.mode];
    const maxSub = maxSubForMode(modeConfig);

    // Pause briefly on the green confirmation before advancing — never instant.
    if (gameState.subQuestionIndex < maxSub - 1) {
        clearAutoAdvance();
        autoAdvanceTimer = setTimeout(() => {
            autoAdvanceTimer = null;
            gameState.subQuestionIndex++;
            startNewQuestion();
        }, ANSWER_PAUSE_MS);
    } else {
        // All sub-questions complete: enable Next as a manual skip and auto-advance.
        document.getElementById('next-btn').disabled = false;
        scheduleAutoAdvance();
    }
}

// Handle incorrect answer. Unlike a stale "self-clearing" flash, this highlight is left in
// place deliberately — the caller pauses, then reveals the correct answer ALONGSIDE it (see
// scheduleWrongThenCorrect) so the two can be compared, and the whole button/shape grid is
// rebuilt fresh for the next question anyway (clearMultipleChoice/startNewQuestion), so
// nothing needs to explicitly clear this class later.
function handleIncorrectAnswer(element) {
    const sel = d3.select(element).classed('selected', false).classed('incorrect', true);
    // Raise map highlights so the red outline isn't clipped by neighbouring shapes.
    if (element && element.ownerSVGElement) raiseHighlight(sel);
}

// The standard two-phase wrong-answer sequence used by every discrete right/wrong question
// type: pause, call `revealCorrect` (marks the correct answer — must NOT clear the existing
// wrong highlight), pause again, then advance (via handleCorrectAnswer, unscored).
function scheduleWrongThenCorrect(revealCorrect) {
    clearAutoAdvance();
    autoAdvanceTimer = setTimeout(() => {
        autoAdvanceTimer = null;
        const correctElement = revealCorrect();
        if (correctElement && !gameState.answeredCorrectly) handleCorrectAnswer(correctElement, false);
    }, ANSWER_PAUSE_MS);
}

// Handle give up - reveal answer without awarding points
function giveUp() {
    // Special handling for name-all mode
    const modeConfig = QUIZ_MODES[gameState.mode];
    if (modeConfig.nameAllMode) {
        handleNameAllGiveUp();
        return;
    }

    if (modeConfig.findCapitalMode) {
        skipCapitalGuess();
        return;
    }

    // Sandbox quizzes: reveal the answer with its reason (unscored) and advance.
    if (modeConfig.sbQuizMode) {
        if (modeConfig.sbEngine === 'pinpoint') { sbSubmitPinpoint(); return; }
        if (modeConfig.sbEngine === 'multi') { sbSubmitMulti(); return; }
        if (modeConfig.sbEngine === 'estimate') { sbSubmitEstimate(); return; }
        if (modeConfig.sbEngine === 'picker') { sbSubmitPicker(); return; }
        if (modeConfig.sbEngine === 'connect') { sbFinishConnect(gameState.sbQuestion, false); return; }
        const q = gameState.sbQuestion;
        gameState.sbAnswered = true;
        const feedback = document.getElementById('feedback');
        feedback.innerHTML = q ? `The answer was <strong>${q.correct}</strong>. ${q.explain || ''}` : '';
        feedback.className = 'feedback incorrect';
        document.getElementById('give-up-btn').style.display = 'none';
        sbPlayRevealAnimation();
        scheduleAutoAdvance();
        return;
    }

    if (modeConfig.flagPlaceMode) { finishFlagPlace(); return; }

    // The puzzle's "Give Up" is "Solve It": fill the remaining slots in, unscored.
    if (modeConfig.statePuzzleMode) {
        solveStatePuzzle();
        return;
    }

    if (modeConfig.spaceshipMode) {
        skipSpaceshipGuess();
        return;
    }

    // Odd One Out: mark the outlier on the buttons and say what the other three shared.
    if (modeConfig.oddOneOutMode) {
        if (gameState.answeredCorrectly || !gameState.oddPuzzle) return;
        gameState.answeredCorrectly = true;
        document.querySelectorAll('.option-btn').forEach(btn => {
            if (btn.textContent === gameState.oddPuzzle.odd) btn.classList.add('correct');
        });
        const feedback = document.getElementById('feedback');
        feedback.innerHTML = `<strong>${gameState.oddPuzzle.odd}</strong> — the others are ` +
            `${gameState.oddPuzzle.why}.`;
        feedback.className = 'feedback partial';
        scheduleAutoAdvance();
        return;
    }

    // Draw the Border: show the real outline (and score whatever was drawn).
    if (modeConfig.drawBorderMode) {
        revealDrawnBorder();
        return;
    }

    // Skyline ID: reveal the city on the option buttons. Needs its own handler because the
    // generic tail below reaches for the globe, which this mode doesn't have.
    if (modeConfig.skylineIdMode) {
        if (gameState.answeredCorrectly || !gameState.targetCountry) return; // nothing to reveal yet
        gameState.answeredCorrectly = true;
        const label = skylineLabel(gameState.targetCountry);
        document.querySelectorAll('.option-btn').forEach(btn => {
            if (btn.textContent === label) btn.classList.add('correct');
        });
        const feedback = document.getElementById('feedback');
        feedback.textContent = 'This is ' + label + '.';
        feedback.className = 'feedback incorrect';
        revealSkylineCredit();
        document.getElementById('next-btn').disabled = false;
        scheduleAutoAdvance();
        return;
    }

    // Special handling for capitals-race mode
    if (modeConfig.capitalsRaceMode) {
        if (gameState.answeredCorrectly) return;
        gameState.answeredCorrectly = true;
        const correctCapital = getCapital(gameState.targetCountry);
        const feedback = document.getElementById('feedback');
        feedback.textContent = `The capital of ${gameState.targetCountry} is: ${correctCapital}`;
        feedback.className = 'feedback incorrect';
        const capitalsInput = document.getElementById('capitals-race-input');
        if (capitalsInput) capitalsInput.disabled = true;
        document.getElementById('next-btn').disabled = false;
        scheduleAutoAdvance();
        return;
    }

    if (gameState.answeredCorrectly) return; // Already answered correctly

    gameState.answeredCorrectly = true; // Mark as answered to prevent further input

    const feedback = document.getElementById('feedback');
    feedback.textContent = `The correct answer is: ${gameState.targetCountry}`;
    feedback.className = 'feedback incorrect';

    // Show the correct answer visually
    if (gameState.questionType === 'location') {
        // Highlight the country on the map
        highlightCountryOnGlobe(gameState.targetCountry);
        // Rotate to show it if autoRotate is enabled
        if (modeConfig.useGlobe && modeConfig.autoRotate) {
            rotateToCountry(gameState.targetCountry);
        }
    } else if (gameState.questionType === 'flag') {
        // Highlight correct flag
        const flagOptions = document.querySelectorAll('.flag-option');
        flagOptions.forEach(opt => {
            const img = opt.querySelector('img');
            if (img && img.src === getFlagUrl(gameState.targetCountry)) {
                opt.classList.add('correct');
            }
        });
        // The flag has been revealed — colour the country in with it, same as answering.
        fillCountryWithFlag(gameState.targetCountry);
    } else if (gameState.questionType === 'capital' || gameState.questionType === 'capitals-choice') {
        // Highlight correct capital
        const correctCapital = getCapital(gameState.targetCountry);
        const buttons = document.querySelectorAll('.option-btn');
        buttons.forEach(btn => {
            if (btn.textContent === correctCapital) {
                btn.classList.add('correct');
            }
        });
    } else if (gameState.questionType === 'identify') {
        // Already highlighted, just show in feedback
        feedback.textContent = `The highlighted location is: ${gameState.targetCountry}`;
    } else if (gameState.questionType === 'mystery-flag') {
        // Reveal and rotate to the correct country
        highlightCountryOnGlobe(gameState.targetCountry);
        rotateToCountry(gameState.targetCountry);
        feedback.textContent = `The flag belongs to: ${gameState.targetCountry}`;
    } else if (gameState.questionType === 'country-shape-id') {
        // Highlight the correct country
        countriesGroup.selectAll('path')
            .classed('target-muted', false);
        feedback.textContent = `The correct answer is: ${gameState.targetCountry}`;
        const buttons = document.querySelectorAll('.option-btn');
        buttons.forEach(btn => {
            if (btn.textContent === gameState.targetCountry) {
                btn.classList.add('correct');
            }
        });
    }

    // Determine max sub-questions based on mode
    const maxSub = maxSubForMode(modeConfig);

    // Pause on the reveal, then advance — same pacing as answering (right or wrong).
    if (gameState.subQuestionIndex < maxSub - 1) {
        clearAutoAdvance();
        autoAdvanceTimer = setTimeout(() => {
            autoAdvanceTimer = null;
            gameState.subQuestionIndex++;
            startNewQuestion();
        }, ANSWER_PAUSE_MS);
    } else {
        document.getElementById('next-btn').disabled = false;
        scheduleAutoAdvance();
    }
}

// Start a new question
function startNewQuestion() {
    // Cancel any pending auto-advance and globe spin from the previous question
    clearAutoAdvance();
    stopGlobeSpin();

    // Check if this is name-all mode
    const modeConfig = QUIZ_MODES[gameState.mode];
    if (modeConfig.nameAllMode) {
        renderNameAllMode();
        return;
    }

    // Check if this is ordering mode (population ordering)
    if (modeConfig.orderingMode) {
        renderOrderingMode();
        return;
    }

    // Skyline ID must hook in HERE, with the other map-less modes, not down at the render
    // dispatch: the shared code below dereferences countriesGroup (never created without a
    // map) and picks its target by filtering the quiz list against map features, which for
    // an empty gameState.countries recurses forever. Skyline picks its own target instead.
    if (modeConfig.skylineIdMode) {
        renderSkylineQuestion();
        return;
    }

    // Check if this is free explore mode
    if (modeConfig.freeExploreMode) {
        renderFreeExploreMode();
        return;
    }

    // "Places I've Been" — paint-the-map mode (no quiz target).
    if (modeConfig.placesMode) {
        renderPlacesMode();
        return;
    }

    // Spaceship sandbox — a tool, not a quiz.
    if (modeConfig.sandboxMode) {
        renderSpaceshipSandbox();
        return;
    }

    // Sun Path — three linked 3D views, no map and no target.
    if (modeConfig.sunPathMode) {
        renderSunPathMode();
        return;
    }

    // Sun & Moon — view-only, no target.
    if (modeConfig.sunMoonMode) {
        renderSunMoonMode();
        return;
    }

    if (modeConfig.oddOneOutMode) {
        renderOddOneOutQuestion();
        return;
    }

    // Sandbox quizzes. The ordering engine has no map, so — like population-order — it must
    // dispatch BEFORE the shared body, which dereferences countriesGroup and filters against
    // map features (and recurses forever on an empty gameState.countries).
    if (modeConfig.sbQuizMode) {
        renderSandboxQuizQuestion();
        return;
    }

    if (modeConfig.drawBorderMode) {
        renderDrawBorderQuestion();
        return;
    }

    // No target and no scoring — the whole map IS the question.
    if (modeConfig.missingSandboxMode) {
        renderMissingSandbox();
        return;
    }

    if (modeConfig.framingSandboxMode) {
        renderFramingSandbox();
        return;
    }

    if (modeConfig.projectionLabMode) {
        renderProjectionLab();
        return;
    }

    // The flag workshop — no map, no target, no score.
    if (modeConfig.flagWorkshopMode) {
        renderFlagWorkshop();
        return;
    }

    // Flag Match — one continuous board of flags, no per-question target.
    if (modeConfig.flagPlaceMode) {
        renderFlagPlaceMode();
        return;
    }

    // Map Puzzle — one continuous jigsaw board, no per-question target.
    if (modeConfig.statePuzzleMode) {
        renderStatePuzzle();
        return;
    }

    // Remove name-all-mode class if it exists
    document.querySelector('.container').classList.remove('name-all-mode');

    // Show question counter again (might have been hidden by name-all mode)
    const questionCounter = document.querySelector('.score-item:has(#current-question)');
    if (questionCounter) {
        questionCounter.style.display = '';
    }

    // Reset state
    gameState.answeredCorrectly = false;
    gameState.guessedThisQuestion = false;
    gameState.scrollLocked = false;
    document.getElementById('next-btn').disabled = true;
    document.getElementById('next-btn').style.display = 'inline-block';
    document.getElementById('next-btn').textContent = 'Next Question';
    document.getElementById('give-up-btn').style.display = 'inline-block';
    document.getElementById('give-up-btn').textContent = 'Give Up';

    // Clear feedback
    const feedback = document.getElementById('feedback');
    feedback.textContent = '';
    feedback.className = 'feedback';

    // Clear previous styling (only for non-World Quiz Layout or when starting new country)
    if (!modeConfig.useWorldQuizLayout || gameState.subQuestionIndex === 0) {
        countriesGroup.selectAll('path')
            .classed('target', false)
            .classed('target-muted', false)
            .classed('selected', false)
            .classed('incorrect', false);
        if (islandMarkersGroup) {
            islandMarkersGroup.selectAll('circle')
                .classed('target', false)
                .classed('target-muted', false)
                .classed('selected', false)
                .classed('incorrect', false);
        }
    } else if (gameState.subQuestionIndex > 0 && !modeConfig.useWorldQuizLayout) {
        // For follow-up questions in non-world-quiz modes, only clear incorrect/selected but keep target highlighted
        countriesGroup.selectAll('path')
            .classed('selected', false)
            .classed('incorrect', false);
    }

    // Clear multiple choice
    clearMultipleChoice();
    clearDebugBoundingBoxes();

    // Hide name-all input if exists
    const inputContainer = document.getElementById('name-all-input-container');
    if (inputContainer) {
        inputContainer.style.display = 'none';
    }

    // Hide capitals-race input if exists
    const capitalsRaceInputContainer = document.getElementById('capitals-race-input-container');
    if (capitalsRaceInputContainer) {
        capitalsRaceInputContainer.style.display = 'none';
    }

    // Check if game is over
    if (gameState.currentQuestion > gameState.totalQuestions) {
        endGame();
        return;
    }

    // Find-the-Capital handles its own target selection and rendering.
    if (modeConfig.findCapitalMode) {
        renderFindCapitalQuestion();
        return;
    }

    // Where Is My Spaceship? handles its own target selection and rendering.
    if (modeConfig.spaceshipMode) {
        renderSpaceshipQuestion();
        return;
    }

    // If starting a new item (subQuestionIndex === 0), select a new item
    if (gameState.subQuestionIndex === 0) {
        // Get available items that haven't been used
        const availableItems = gameState.currentQuizList.filter(item => {
            // Check if item exists in our data and hasn't been used
            const exists = gameState.countries.some(c => c.properties.name === item);
            return exists && !gameState.usedCountries.has(item);
        });

        if (availableItems.length === 0) {
            // Reset used items if we've gone through all of them
            gameState.usedCountries.clear();
            startNewQuestion();
            return;
        }

        // Select random item
        const randomIndex = Math.floor(Math.random() * availableItems.length);
        gameState.targetCountry = availableItems[randomIndex];
        gameState.usedCountries.add(gameState.targetCountry);

        // Check if this is identify-only mode
        const modeConfig = QUIZ_MODES[gameState.mode];
        if (modeConfig.identifyOnly) {
            gameState.questionType = 'identify';
        } else if (modeConfig.mysteryFlagMode) {
            gameState.questionType = 'mystery-flag';
        } else if (modeConfig.capitalsRaceMode) {
            gameState.questionType = 'capitals-race';
        } else if (modeConfig.capitalsChoiceMode) {
            gameState.questionType = 'capitals-choice';
        } else if (modeConfig.countryShapeIdMode) {
            gameState.questionType = 'country-shape-id';
        } else {
            gameState.questionType = 'location';
        }
    }

    // Update question number display
    document.getElementById('current-question').textContent = gameState.currentQuestion; syncScoreDisplay();

    // Render the appropriate question based on subQuestionIndex
    const hasFlags = modeConfig.hasFlags;

    if (modeConfig.identifyOnly) {
        // Identify mode only shows identify questions
        renderIdentifyQuestion();
    } else if (modeConfig.mysteryFlagMode) {
        renderMysteryFlagQuestion();
    } else if (modeConfig.capitalsRaceMode) {
        renderCapitalsRaceQuestion();
    } else if (modeConfig.capitalsChoiceMode) {
        renderCapitalsChoiceQuestion();
    } else if (modeConfig.countryShapeIdMode) {
        renderCountryShapeIdQuestion();
    } else if (gameState.subQuestionIndex === 0) {
        renderLocationQuestion();
    } else if (gameState.subQuestionIndex === 1 && hasFlags) {
        renderFlagQuestion();
    } else if (gameState.subQuestionIndex === 1 && !hasFlags) {
        // Skip flags for modes without flags, go to capital
        renderCapitalQuestion();
    } else if (gameState.subQuestionIndex === 2) {
        renderCapitalQuestion();
    }
}

// Render location question (original: find country/state on map)
function renderLocationQuestion() {
    gameState.questionType = 'location';
    const modeConfig = QUIZ_MODES[gameState.mode];
    const itemLabel = modeConfig.itemLabel;

    if (modeConfig.useWorldQuizLayout) {
        // For World Quiz Layout, show location prompt in question bar
        document.getElementById('world-quiz-current-question').innerHTML = `Click the globe to find: <strong>${gameState.targetCountry}</strong>`;
        document.getElementById('flag-question-text').innerHTML = '';
        document.getElementById('flag-choice-container').style.display = 'none';
        document.getElementById('flag-display-side').style.display = 'none';
        document.getElementById('flag-feedback').textContent = '';
        document.getElementById('flag-feedback').className = 'feedback';
        document.getElementById('capital-question-text').innerHTML = '';
        document.getElementById('capital-choice-container').style.display = 'none';
        document.getElementById('capital-feedback').textContent = '';
    } else {
        // Standard layout
        document.getElementById('question-text').innerHTML = `Find: <span id="country-name">${gameState.targetCountry}</span>`;
        
        document.getElementById('multiple-choice-container').classList.add('hidden');
        document.getElementById('flag-display').style.display = 'none';
    }

    // Rotate globe/map to show the target only if autoRotate is enabled
    if (isGlobeView() && modeConfig.autoRotate) {
        rotateToCountry(gameState.targetCountry);
    } else if (isGlobeView() && !modeConfig.autoRotate && !modeConfig.useWorldQuizLayout) {
        // Reset to 0,0,0 for modes that need it (but not World Quiz Layout)
        projection.rotate([0, 0, 0]);
        r_unconstrained = [0, 0, 0];
        countriesGroup.selectAll('path').attr('d', path);
        updateIslandMarkers();
    }
    // For World Quiz Layout, maintain current rotation/zoom between questions
    // For regional maps, just ensure it's visible (already fitted in loadMapData)
}

// Render flag question (show 4 flags and choose the correct one)
function renderFlagQuestion() {
    console.log('renderFlagQuestion called for:', gameState.targetCountry);
    gameState.questionType = 'flag';
    const modeConfig = QUIZ_MODES[gameState.mode];
    const itemLabel = modeConfig.itemLabel;

    // Generate multiple choice options
    const options = generateMultipleChoiceOptions(gameState.targetCountry, 'item');
    console.log('Generated options:', options);

    if (modeConfig.useWorldQuizLayout) {
        // For World Quiz Layout, show flag question in question bar
        document.getElementById('world-quiz-current-question').innerHTML = `Which flag belongs to <strong>${gameState.targetCountry}</strong>?`;
        document.getElementById('flag-question-text').innerHTML = '';
        document.getElementById('flag-display-side').style.display = 'none';

        // Keep the target country highlighted with muted color
        countriesGroup.selectAll('path')
            .filter(d => d.properties.name === gameState.targetCountry)
            .classed('target-muted', true);

        // Render flag choices in the top panel
        const grid = document.getElementById('flag-options-grid');
        grid.innerHTML = '';
        grid.className = 'flag-options-grid';

        options.forEach(option => {
            const flagDiv = document.createElement('div');
            flagDiv.className = 'flag-option';

            const flagImg = document.createElement('img');
            const flagUrl = getFlagUrl(option);
            console.log(`Setting image src for ${option} to: ${flagUrl}`);
            flagImg.src = flagUrl;
            flagImg.alt = `Flag of ${option}`;

            flagDiv.appendChild(flagImg);
            flagDiv.onclick = () => handleFlagChoiceAnswer(option, gameState.targetCountry, flagDiv);
            grid.appendChild(flagDiv);
        });

        document.getElementById('flag-choice-container').style.display = 'block';
    } else {
        // Standard layout
        document.getElementById('question-text').innerHTML = `Which flag belongs to <span id="country-name">${gameState.targetCountry}</span>?`;
        document.getElementById('flag-display').style.display = 'none';
        

        // Render flag choices
        renderFlagChoices(options, gameState.targetCountry);
    }
}

// Render flag choices (4 flag images)
function renderFlagChoices(options, correctAnswer) {
    const container = document.getElementById('multiple-choice-container');
    const grid = document.getElementById('options-grid');
    grid.innerHTML = '';
    grid.className = 'flag-options-grid';

    options.forEach(option => {
        const flagDiv = document.createElement('div');
        flagDiv.className = 'flag-option';

        const flagImg = document.createElement('img');
        flagImg.src = getFlagUrl(option);
        flagImg.alt = `Flag of ${option}`;

        flagDiv.appendChild(flagImg);
        flagDiv.onclick = () => handleFlagChoiceAnswer(option, correctAnswer, flagDiv);
        grid.appendChild(flagDiv);
    });

    container.classList.remove('hidden');
}

// Handle flag choice answer
function handleFlagChoiceAnswer(selectedAnswer, correctAnswer, element) {
    if (gameState.answeredCorrectly) return;

    const modeConfig = QUIZ_MODES[gameState.mode];
    const isCorrect = selectedAnswer === correctAnswer;

    // Visual feedback
    element.classList.add('selected');

    if (isCorrect) {
        element.classList.add('correct');

        if (modeConfig.useWorldQuizLayout) {
            // Handle correct answer logic
            gameState.answeredCorrectly = true;
            gameState.score++;
            document.getElementById('score').textContent = gameState.score; syncScoreDisplay();

            // The flag has now been asked — colour the country in with it.
            fillCountryWithFlag(correctAnswer);

            // Pause on the green confirmation, then advance to the capital question.
            clearAutoAdvance();
            autoAdvanceTimer = setTimeout(() => {
                autoAdvanceTimer = null;
                gameState.subQuestionIndex++;
                startNewQuestion();
            }, ANSWER_PAUSE_MS);
        } else {
            fillCountryWithFlag(correctAnswer);
            handleCorrectAnswer(element);
        }
    } else {
        element.classList.add('incorrect');
        handleIncorrectAnswer(element);
        // Reveal the correct flag alongside the wrong one, then advance (unscored) — the
        // world-quiz-layout branch used to just clear and loop with no reveal/advance at
        // all; both branches now share the standard wrong-answer pacing.
        scheduleWrongThenCorrect(() => {
            let correctElement = null;
            document.querySelectorAll('.flag-option').forEach(opt => {
                const img = opt.querySelector('img');
                if (img && img.src === getFlagUrl(correctAnswer)) {
                    opt.classList.add('correct');
                    correctElement = opt;
                }
            });
            // The flag has now been asked (right or wrong) — colour the country in with it,
            // same as a correct guess does.
            if (modeConfig.useWorldQuizLayout) fillCountryWithFlag(correctAnswer);
            return correctElement;
        });
    }
}

// Render capital question
function renderCapitalQuestion() {
    gameState.questionType = 'capital';
    const modeConfig = QUIZ_MODES[gameState.mode];
    const correctCapital = getCapital(gameState.targetCountry);

    // Generate multiple choice options with capitals
    const itemOptions = generateMultipleChoiceOptions(gameState.targetCountry, 'item');
    const capitalOptions = itemOptions.map(item => getCapital(item)).filter(cap => cap !== null);

    if (modeConfig.useWorldQuizLayout) {
        // For World Quiz Layout, show capital question in question bar
        document.getElementById('world-quiz-current-question').innerHTML = `What is the capital of <strong>${gameState.targetCountry}</strong>?`;
        document.getElementById('capital-question-text').innerHTML = '';

        // Keep the target country highlighted with muted color
        countriesGroup.selectAll('path')
            .filter(d => d.properties.name === gameState.targetCountry)
            .classed('target-muted', true);

        // Render capital choices in the bottom panel
        const grid = document.getElementById('capital-options-grid');
        grid.innerHTML = '';
        grid.className = 'options-grid';

        capitalOptions.forEach(option => {
            const button = document.createElement('button');
            button.className = 'option-btn';
            button.textContent = option;
            button.onclick = () => handleCapitalChoiceAnswer(option, correctCapital, button);
            grid.appendChild(button);
        });

        document.getElementById('capital-choice-container').style.display = 'block';
    } else {
        // Standard layout
        document.getElementById('question-text').innerHTML = `What is the capital of <span id="country-name">${gameState.targetCountry}</span>?`;
        document.getElementById('flag-display').style.display = 'none';
        

        renderMultipleChoice(capitalOptions, correctCapital);
    }
}

// Handle capital choice answer (for World Quiz Layout)
function handleCapitalChoiceAnswer(selectedAnswer, correctAnswer, element) {
    if (gameState.answeredCorrectly) return;

    const isCorrect = selectedAnswer === correctAnswer;

    // Visual feedback
    element.classList.add('selected');

    if (isCorrect) {
        element.classList.add('correct');

        // Handle correct answer logic
        gameState.answeredCorrectly = true;
        gameState.score++;
        document.getElementById('score').textContent = gameState.score; syncScoreDisplay();

        // Pause on the green confirmation, then advance to the next country.
        document.getElementById('next-btn').disabled = false;
        scheduleAutoAdvance();
    } else {
        element.classList.add('incorrect');
        handleIncorrectAnswer(element);
        // Reveal the correct capital alongside the wrong one, then advance (unscored) —
        // this used to just clear and loop with no reveal/advance at all.
        scheduleWrongThenCorrect(() => {
            let correctElement = null;
            document.querySelectorAll('#capital-options-grid .option-btn').forEach(btn => {
                if (btn.textContent === correctAnswer) {
                    btn.classList.add('correct');
                    correctElement = btn;
                }
            });
            return correctElement;
        });
    }
}

// Render identify question (show country/state on map, identify name)
function renderIdentifyQuestion() {
    gameState.questionType = 'identify';
    const itemLabel = QUIZ_MODES[gameState.mode].itemLabel;
    document.getElementById('question-text').innerHTML = `Which ${itemLabel} is highlighted?`;

    document.getElementById('flag-display').style.display = 'none';

    // Highlight the item on the map
    highlightCountryOnGlobe(gameState.targetCountry);

    // Stop any existing globe spin (identify mode no longer auto-spins).
    stopGlobeSpin();

    // Rotate once to bring the highlighted target into view (no continuous spin).
    if (QUIZ_MODES[gameState.mode].useGlobe) {
        rotateToCountry(gameState.targetCountry);
    }

    // Generate multiple choice options
    const options = generateMultipleChoiceOptions(gameState.targetCountry, 'item');
    renderMultipleChoice(options, gameState.targetCountry);
}

// Render name-all mode question
// ===== Name-All countdown timer =====
function stopNameAllTimer() {
    if (gameState.nameAllTimerId) { clearInterval(gameState.nameAllTimerId); gameState.nameAllTimerId = null; }
}

function renderNameAllTimer() {
    const el = document.getElementById('name-all-timer');
    if (!el) return;
    const s = Math.max(0, gameState.nameAllTimeLeft | 0);
    el.textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
    el.style.color = s <= 10 ? 'var(--incorrect)' : '';
}

function startNameAllTimer(seconds) {
    stopNameAllTimer();
    gameState.nameAllTimeLeft = seconds;
    renderNameAllTimer();
    gameState.nameAllTimerId = setInterval(() => {
        // Self-cancel if the player has left name-all mode.
        const mc = QUIZ_MODES[gameState.mode];
        if (!mc || !mc.nameAllMode) { stopNameAllTimer(); return; }
        gameState.nameAllTimeLeft--;
        renderNameAllTimer();
        if (gameState.nameAllTimeLeft <= 0) {
            stopNameAllTimer();
            if (!gameState.nameAllGaveUp) handleNameAllGiveUp(true);
        }
    }, 1000);
}

// A country is playable in Name-All if it's drawn as a polygon OR as an island dot.
function nameAllRenderable(name) {
    if (gameState.countries && gameState.countries.some(c => c.properties.name === name)) return true;
    const d = gameState.currentDataObj[name];
    return !!(d && Array.isArray(d.capitalCoords));
}

function renderNameAllMode() {
    const modeConfig = QUIZ_MODES[gameState.mode];
    gameState.questionType = 'name-all';
    gameState.foundCountries = new Set();
    gameState.nameAllStartTime = Date.now();
    gameState.nameAllGaveUp = false;
    stopNameAllTimer();

    // Add name-all-mode class to container for styling
    document.querySelector('.container').classList.add('name-all-mode');

    // Keep only items that are drawn (as a polygon or, for world countries, an island dot).
    gameState.currentQuizList = gameState.currentQuizList.filter(nameAllRenderable);
    const totalItems = gameState.currentQuizList.length;
    const itemWord = modeConfig.itemLabelPlural || 'countries';

    // Hide question counter for name-all mode
    const questionCounter = document.querySelector('.score-item:has(#current-question)');
    if (questionCounter) {
        questionCounter.style.display = 'none';
    }

    const regionLabel = modeConfig.regionLabel || 'the World';
    document.getElementById('question-text').innerHTML = `Name all ${itemWord} in ${regionLabel}! Found: <span id="found-count">0</span>/${totalItems} &nbsp;|&nbsp; ⏱ <span id="name-all-timer">--:--</span>`;

    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');

    // Create and show input field
    createNameAllInput();

    // Start the countdown (~6s per item, at least 60s).
    startNameAllTimer(Math.max(60, totalItems * 6));

    // Reset rotation — only orthographic/Mercator support .rotate(); AlbersUSA (us-states)
    // does not, so it's skipped there (its extent is already fixed).
    if (typeof projection.rotate === 'function') {
        projection.rotate([0, 0, 0]);
        r_unconstrained = [0, 0, 0];
    }

    // Ensure all countries are visible with clear borders
    countriesGroup.selectAll('path')
        .attr('d', path)
        .classed('target', false)
        .classed('incorrect', false)
        .classed('selected', false)
        .style('fill', null)        // Revert to themed land color (CSS .country)
        .style('stroke', null)
        .style('stroke-width', null)
        .style('opacity', 1);       // Ensure full opacity

    if (g) g.selectAll('g.name-all-labels').remove();

    // Reset and reposition island-dot markers for this fresh game.
    if (islandMarkersGroup) {
        islandMarkersGroup.selectAll('circle')
            .classed('target', false).classed('incorrect', false).classed('selected', false);
    }
    updateIslandMarkers();

    // Update button states
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'inline-block';
    document.getElementById('restart-btn').style.display = 'inline-block';
}

// Create input field for name-all mode
function createNameAllInput() {
    // Check if input already exists
    let inputContainer = document.getElementById('name-all-input-container');
    if (!inputContainer) {
        inputContainer = document.createElement('div');
        inputContainer.id = 'name-all-input-container';
        inputContainer.className = 'name-all-input-container';

        const input = document.createElement('input');
        input.type = 'text';
        input.id = 'name-all-input';
        input.className = 'name-all-input';
        input.autocomplete = 'off';

        inputContainer.appendChild(input);

        // Insert after question container
        const questionContainer = document.getElementById('question-container');
        questionContainer.appendChild(inputContainer);

        // Add event listener for real-time input
        input.addEventListener('input', handleNameAllInput);
        input.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
            }
        });
    }

    // Placeholder depends on the geography (country/state/county), so it's refreshed on
    // every call — not just when the element is first created — in case the player
    // switched geographies since the input was last built.
    const modeConfig = QUIZ_MODES[gameState.mode];
    const input = document.getElementById('name-all-input');
    input.placeholder = `Type a ${modeConfig.itemLabel || 'country'} name...`;

    // Show and focus input
    inputContainer.style.display = 'block';
    input.value = '';
    input.focus();
}

// Handle input changes in name-all mode
function handleNameAllInput(event) {
    if (gameState.nameAllGaveUp) return;

    const input = event.target;
    const inputValue = input.value.trim();

    if (!inputValue) return;

    // Normalize input for comparison (lowercase, remove extra spaces)
    const normalizedInput = inputValue.toLowerCase().replace(/\s+/g, ' ');

    // Check against all countries in the quiz list
    for (const countryName of gameState.currentQuizList) {
        const countryData = gameState.currentDataObj[countryName];
        if (!gameState.foundCountries.has(countryName)) {
            // Check exact match
            const normalizedCountryName = countryName.toLowerCase().replace(/\s+/g, ' ');
            if (normalizedCountryName === normalizedInput) {
                foundCountryMatch(countryName, input);
                return;
            }

            // Check alternate names if available
            if (countryData && countryData.alternateNames && Array.isArray(countryData.alternateNames)) {
                for (const altName of countryData.alternateNames) {
                    const normalizedAltName = altName.toLowerCase().replace(/\s+/g, ' ');
                    if (normalizedAltName === normalizedInput) {
                        foundCountryMatch(countryName, input);
                        return;
                    }
                }
            }
        }
    }
}

// Helper function for found country match
function foundCountryMatch(countryName, inputElement) {
    // Found a match!
    gameState.foundCountries.add(countryName);
    gameState.score++;

    // Highlight country on globe
    highlightFoundCountry(countryName);

    // Clear input
    inputElement.value = '';

    // Update counter
    updateFoundCounter();

    // Check if all countries found
    checkNameAllComplete();
}

// Highlight a found country in name-all mode (plus its overseas territories).
function highlightFoundCountry(countryName) {
    const paths = countriesGroup.selectAll('path')
        .filter(d => featureBelongsTo(d, countryName))
        .classed('target', true);
    raiseHighlight(paths);

    // Island nations are dots, not polygons — highlight the marker too.
    if (islandMarkersGroup) {
        const dots = islandMarkersGroup.selectAll('circle')
            .filter(d => featureBelongsTo(d, countryName))
            .classed('target', true);
        raiseHighlight(dots);
    }

    // Smoothly zoom to the country
    zoomAndRotateToCountry(countryName, 600);
}

// Update the found counter display
function updateFoundCounter() {
    const totalCountries = gameState.currentQuizList.length;

    document.getElementById('found-count').textContent = gameState.foundCountries.size;
    document.getElementById('score').textContent = gameState.score; syncScoreDisplay();
}

// Check if all items have been found
function checkNameAllComplete() {
    const totalItems = gameState.currentQuizList.length;

    if (gameState.foundCountries.size >= totalItems) {
        // All items found!
        stopNameAllTimer();
        const elapsedTime = Math.round((Date.now() - gameState.nameAllStartTime) / 1000);
        const minutes = Math.floor(elapsedTime / 60);
        const seconds = elapsedTime % 60;
        const timeStr = minutes > 0 ? `${minutes}m ${seconds}s` : `${seconds}s`;

        const itemWord = (QUIZ_MODES[gameState.mode].itemLabelPlural) || 'countries';
        const feedback = document.getElementById('feedback');
        feedback.textContent = `🎉 Congratulations! You named all ${totalItems} ${itemWord} in ${timeStr}!`;
        feedback.className = 'feedback correct';

        // Hide input
        const inputContainer = document.getElementById('name-all-input-container');
        if (inputContainer) {
            inputContainer.style.display = 'none';
        }

        // Update button states
        document.getElementById('give-up-btn').style.display = 'none';
    }
}

// Handle give up for name-all mode (timedOut=true when the countdown hit zero)
function handleNameAllGiveUp(timedOut) {
    gameState.nameAllGaveUp = true;
    stopNameAllTimer();

    // Hide input
    const inputContainer = document.getElementById('name-all-input-container');
    if (inputContainer) {
        inputContainer.style.display = 'none';
    }

    // Highlight all missed items in red and create list
    const missedItems = [];
    gameState.currentQuizList.forEach(itemName => {
        if (!gameState.foundCountries.has(itemName)) {
            missedItems.push(itemName);

            // Highlight in red (polygon or island dot)
            countriesGroup.selectAll('path')
                .filter(d => d.properties.name === itemName)
                .classed('incorrect', true);
            if (islandMarkersGroup) {
                islandMarkersGroup.selectAll('circle')
                    .filter(d => d.properties.name === itemName)
                    .classed('incorrect', true);
            }
        }
    });

    // Show feedback with missed items
    const totalItems = gameState.currentQuizList.length;
    const itemWord = (QUIZ_MODES[gameState.mode].itemLabelPlural) || 'countries';

    // The names, ON THE MAP. A column of forty names is a list of words; the same forty
    // written where they belong is the thing you were being asked to know, and it is the only
    // version you have any chance of remembering.
    labelMissedOnMap(missedItems);

    const feedback = document.getElementById('feedback');
    feedback.innerHTML = `
        <div>
            <p>${timedOut ? "⏰ Time's up! " : ''}You found ${gameState.foundCountries.size} out of ${totalItems} ${itemWord}.</p>
            <p style="margin-top: 10px;"><strong>Missed ${itemWord}:</strong></p>
            <div style="max-height: 200px; overflow-y: auto; margin-top: 10px; text-align: left;">
                ${missedItems.sort().map(name => `<div style="padding: 3px 0;">• ${name}</div>`).join('')}
            </div>
        </div>
    `;
    feedback.className = 'feedback incorrect';

    // The whole point of a miss list is what you do with it next. This turns it into a drill
    // over exactly those items rather than leaving the player to go and find them.
    if (missedItems.length) appendPractiseButton(feedback, missedItems.slice());

    // Update button states
    document.getElementById('give-up-btn').style.display = 'none';
}

// Write each missed name across its own shape.
//
// It has to ZOOM first. At the scale a world round is played, most of Europe is a few pixels
// across and the size guard threw away 31 of 40 labels — the feature was working perfectly and
// showing almost nothing. Framing the misses makes them big enough to write on, and is what
// you would do by hand anyway. Skipped when they are scattered across the planet, where there
// is no frame that helps and the whole world is already the right answer.
const NAME_ALL_LABEL_MIN_PX = 16;
function labelMissedOnMap(missed) {
    if (!g || !countriesGroup || !path) return;
    g.selectAll('g.name-all-labels').remove();
    const want = new Set(missed.map(normalizeName));
    const feats = (gameState.countries || []).filter(f =>
        f && f.properties && want.has(normalizeName(f.properties.name)));
    if (!feats.length) return;

    const fc = { type: 'FeatureCollection', features: feats };
    let span = 360;
    try {
        const bb = d3.geoBounds(fc);
        span = Math.max(Math.abs(bb[1][0] - bb[0][0]), Math.abs(bb[1][1] - bb[0][1]));
    } catch (_) { /* leave it as the whole world */ }
    if (span < 140 && projection && projection.fitExtent) {
        try {
            // Rotate first on a globe: fitExtent only scales and translates, so anything on the
            // far side of an orthographic would be fitted to a hemisphere it cannot appear in.
            if (typeof projection.rotate === 'function' && isGlobeView()) {
                const c = d3.geoCentroid(fc);
                if (c && isFinite(c[0])) {
                    projection.rotate([-c[0], gammaLocked ? 0 : -c[1], 0]);
                    r_unconstrained = projection.rotate().slice();
                }
            }
            const pad = Math.min(width, height) * 0.08;
            projection.fitExtent([[pad, pad], [width - pad, height - pad]], fc);
            drawCountries();
            // drawCountries rebuilds the paths and the dots, so the red highlight has to go
            // back on afterwards or the zoom silently undoes it.
            countriesGroup.selectAll('path')
                .classed('incorrect', d => d && d.properties && want.has(normalizeName(d.properties.name)));
            if (islandMarkersGroup) islandMarkersGroup.selectAll('circle')
                .classed('incorrect', d => d && d.properties && want.has(normalizeName(d.properties.name)));
        } catch (_) { /* keep the framing we had */ }
    }

    const layer = g.append('g').attr('class', 'name-all-labels');
    const seen = new Set();
    countriesGroup.selectAll('path').each(function (d) {
        const nm = d && d.properties && d.properties.name;
        if (!nm || !want.has(normalizeName(nm)) || seen.has(normalizeName(nm))) return;
        let b;
        try { b = path.bounds(d); } catch (_) { return; }
        if (!b || !isFinite(b[0][0])) return;
        const w = b[1][0] - b[0][0], h = b[1][1] - b[0][1];
        if (Math.max(w, h) < NAME_ALL_LABEL_MIN_PX) return;
        seen.add(normalizeName(nm));
        // The type shrinks with the country rather than the label being dropped: a small name
        // written small still says which shape it belongs to, and dropping it says nothing.
        const size = Math.max(7, Math.min(12, Math.max(w, h) / 4.5));
        layer.append('text').attr('class', 'name-all-label')
            .attr('x', (b[0][0] + b[1][0]) / 2).attr('y', (b[0][1] + b[1][1]) / 2)
            .attr('font-size', size + 'px')
            .attr('text-anchor', 'middle').text(displayLabelForName(nm));
    });
}

function appendPractiseButton(host, missed) {
    const wrap = document.createElement('div');
    wrap.style.marginTop = '10px';
    const btn = document.createElement('button');
    btn.className = 'control-btn';
    btn.textContent = `Practise the ${missed.length} you missed`;
    btn.addEventListener('click', () => startPractiseMissed(missed));
    wrap.appendChild(btn);
    host.appendChild(wrap);
}

// An Identify round restricted to exactly the items that were missed. Identify already takes
// its whole configuration from another mode's entry (startIdentifyMode does the same thing for
// a region), so this is that pattern with an explicit list instead of a region's full one.
function startPractiseMissed(missed) {
    const nm = QUIZ_MODES['name-all'];
    const id = QUIZ_MODES.identify;
    id.quizList = missed;
    id.dataObjKey = nm.dataObjKey;
    id.useGlobe = nm.useGlobe;
    id.useAlbersUsa = nm.useAlbersUsa || false;
    id.mapUrl = nm.mapUrl;
    id.mapObject = nm.mapObject;
    id.itemLabel = nm.itemLabel;
    id.itemLabelPlural = nm.itemLabelPlural;
    // Every one of them, not a sample: the list IS the set worth asking about.
    id.totalQuestions = missed.length;
    stopNameAllTimer();
    document.querySelector('.container').classList.remove('name-all-mode');
    const box = document.getElementById('name-all-input-container');
    if (box) box.remove();
    const counter = document.querySelector('.score-item:has(#current-question)');
    if (counter) counter.style.display = '';
    startGameWithMode('identify');
}

// ==================== MYSTERY FLAG MODE ====================

// Render mystery flag question (show flag, click globe to find country)
function renderMysteryFlagQuestion() {
    gameState.questionType = 'mystery-flag';
    const flagUrl = getFlagUrl(gameState.targetCountry);

    document.getElementById('question-text').innerHTML = `Which country does this flag belong to? <span style="font-size:0.8em;color:#888;">Find it on the globe!</span>`;

    // Show flag prominently
    const flagDisplay = document.getElementById('flag-display');
    const flagImg = document.getElementById('flag-image');
    flagImg.src = flagUrl;
    flagImg.alt = 'Mystery Flag';
    flagDisplay.style.display = 'block';

    document.getElementById('multiple-choice-container').classList.add('hidden');
}

// ==================== US FLAG ID MODE ====================

// Show a US state flag and pick its name from 4 choices. Map-less, so (like skyline) it runs
// the per-question resets the shared startNewQuestion body would otherwise have handled.
// ==================== CAPITALS RACE MODE ====================

// Render capitals race question (highlight country on globe, type the capital)
function renderCapitalsRaceQuestion() {
    gameState.questionType = 'capitals-race';

    document.getElementById('question-text').innerHTML = `What is the capital of <strong>${gameState.targetCountry}</strong>?`;
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');

    // Highlight country and rotate to it
    highlightCountryOnGlobe(gameState.targetCountry);
    rotateToCountry(gameState.targetCountry);

    // Show input
    createCapitalsRaceInput();
}

// Capitals, multiple choice: the country is highlighted on the globe and the capital is
// picked from four options. Distractors come from generateMultipleChoiceOptions' 'capital'
// mode, the same pool the Find-modes' capital sub-question uses.
function renderCapitalsChoiceQuestion() {
    gameState.questionType = 'capitals-choice';

    document.getElementById('question-text').innerHTML =
        `What is the capital of <strong>${gameState.targetCountry}</strong>?`;
    document.getElementById('flag-display').style.display = 'none';

    highlightCountryOnGlobe(gameState.targetCountry);
    rotateToCountry(gameState.targetCountry);

    const correct = getCapital(gameState.targetCountry);
    const options = generateMultipleChoiceOptions(gameState.targetCountry, 'capital');
    renderMultipleChoice(options, correct);
}

// Create input field for capitals race mode
function createCapitalsRaceInput() {
    let inputContainer = document.getElementById('capitals-race-input-container');
    if (!inputContainer) {
        inputContainer = document.createElement('div');
        inputContainer.id = 'capitals-race-input-container';
        inputContainer.className = 'name-all-input-container';

        const input = document.createElement('input');
        input.type = 'text';
        input.id = 'capitals-race-input';
        input.className = 'name-all-input';
        input.placeholder = 'Type the capital city...';
        input.autocomplete = 'off';

        inputContainer.appendChild(input);

        const questionContainer = document.getElementById('question-container');
        questionContainer.appendChild(inputContainer);

        input.addEventListener('keydown', (e) => {
            if (e.key === 'Enter') {
                e.preventDefault();
                handleCapitalsRaceSubmit();
            }
        });
    }

    inputContainer.style.display = 'block';
    const input = document.getElementById('capitals-race-input');
    input.value = '';
    input.disabled = false;
    input.focus();
}

// Handle capitals race answer submission
function handleCapitalsRaceSubmit() {
    if (gameState.answeredCorrectly) return;

    const input = document.getElementById('capitals-race-input');
    const typed = input.value.trim();
    if (!typed) return;

    const correctCapital = getCapital(gameState.targetCountry);
    if (!correctCapital) {
        console.error(`No capital data found for ${gameState.targetCountry}`);
        return;
    }
    const isCorrect = typed.toLowerCase() === correctCapital.toLowerCase();

    const feedback = document.getElementById('feedback');
    input.disabled = true;
    gameState.answeredCorrectly = true;

    if (isCorrect) {
        gameState.score++;
        document.getElementById('score').textContent = gameState.score; syncScoreDisplay();
        feedback.textContent = `Correct! ${correctCapital} is the capital of ${gameState.targetCountry}.`;
        feedback.className = 'feedback correct';
    } else {
        feedback.textContent = `Incorrect. The capital of ${gameState.targetCountry} is ${correctCapital}.`;
        feedback.className = 'feedback incorrect';
    }
    // The correct capital is already shown in the feedback text either way (a typed-input
    // answer has no separate "highlight" step to sequence), so both outcomes get the same
    // single pause before auto-advancing.
    document.getElementById('next-btn').disabled = false;
    scheduleAutoAdvance();
}

// ==================== FREE EXPLORE MODE ====================

// Render free explore mode (interactive globe with popups)
function renderFreeExploreMode() {
    gameState.questionType = 'free-explore';

    document.getElementById('question-text').innerHTML = `<strong>Explore the Globe</strong><br><span style="font-size:0.8em;color:#888;">Click any country to see details</span>`;
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');

    // Hide standard buttons and repurpose restart button for exit
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'none';
    document.getElementById('restart-btn').textContent = 'Exit Explore';
    document.getElementById('restart-btn').onclick = exitFreeExplore;
    document.getElementById('restart-btn').style.display = 'inline-block';
}

// Handle exit from free explore mode
function exitFreeExplore() {
    // Return to landing page
    goHome();
}

// ==================== "Places I've Been" mode ====================

// Enter Places-been for a region ('world' or 'us'), borrowing that region's map/data config
// wholesale (same reconfigure pattern as startIdentifyMode). `opts` carries state to restore
// from a shared URL: selectionsStr (encoded) and message.
function startPlacesMode(region, opts = {}) {
    const base = region === 'us' ? QUIZ_MODES['us-states'] : QUIZ_MODES['countries'];
    const m = QUIZ_MODES['places-been'];
    m.quizList = base.quizList;
    m.dataObjKey = base.dataObjKey;
    m.useGlobe = base.useGlobe;
    m.useAlbersUsa = base.useAlbersUsa || false;
    m.mapUrl = base.mapUrl;
    m.mapObject = base.mapObject;
    m.itemLabel = base.itemLabel;
    m.itemLabelPlural = base.itemLabelPlural;
    m.placesRegion = region;

    placesPendingSelectionsStr = opts.selectionsStr || null;
    placesPendingMessage = opts.message || '';
    startGameWithMode('places-been');
}

// Render the Places-been UI (called after the map is drawn). Restores any URL-shared state,
// swaps the quiz chrome for the category side panel, colours the map and syncs the URL.
function renderPlacesMode() {
    gameState.questionType = 'places-been';
    if (!gameState.placesSelections) gameState.placesSelections = {};

    // Restore state shared via the URL (decoded now that the region's data is loaded).
    if (placesPendingSelectionsStr != null) {
        gameState.placesSelections = decodePlaces(placesPendingSelectionsStr);
        placesPendingSelectionsStr = null;
    }
    if (placesPendingMessage) { gameState.placesMessage = placesPendingMessage; placesPendingMessage = ''; }

    // Hide the quiz chrome; repurpose Restart as an Exit button.
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'none';
    const restart = document.getElementById('restart-btn');
    restart.textContent = 'Exit';
    restart.onclick = goHome;
    restart.style.display = 'inline-block';

    buildPlacesPanel();
    refreshPlacesPanel();
    applyPlacesFills();
    updatePlacesUrl();
}

// Build the side panel (instructions + category lists + share controls) once per entry.
function buildPlacesPanel() {
    document.getElementById('question-container').classList.add('hidden');
    document.getElementById('multiple-choice-container').classList.add('hidden');

    let panel = document.getElementById('places-panel');
    if (!panel) {
        panel = document.createElement('div');
        panel.id = 'places-panel';
        panel.className = 'places-panel';
        document.getElementById('globe-side-panel').appendChild(panel);
    }
    const label = QUIZ_MODES['places-been'].itemLabel || 'place';
    panel.innerHTML = `
        <h2 class="places-title">Places I've Been</h2>
        <p class="places-hint">Click a ${label} to mark it. Each click cycles
            <strong>Visited → Lived → Passed through → clear</strong>.</p>
        <div class="places-lists" id="places-lists"></div>
        <label class="places-msg-label">Add a message to your map
            <input id="places-msg" class="places-msg" type="text" maxlength="140"
                   placeholder="e.g. Everywhere I've wandered so far">
        </label>
        <button id="places-share-btn" class="btn places-share-btn" type="button">Copy shareable link</button>
        <div class="places-share-status" id="places-share-status" role="status"></div>
    `;

    const msg = document.getElementById('places-msg');
    msg.value = gameState.placesMessage || '';
    msg.addEventListener('input', () => { gameState.placesMessage = msg.value; updatePlacesUrl(); });
    document.getElementById('places-share-btn').addEventListener('click', sharePlacesLink);

    wirePlacesListInteractions(document.getElementById('places-lists'));
}

// Delegated handlers on the (persistent) #places-lists element: click the hover ✕ to remove
// a chip, and drag a chip from one category list to another to re-file it.
function wirePlacesListInteractions(lists) {
    if (!lists) return;

    lists.addEventListener('click', e => {
        const rm = e.target.closest('.place-chip-remove');
        if (!rm) return;
        const chip = rm.closest('.place-chip');
        if (chip) removePlace(chip.dataset.place);
    });

    lists.addEventListener('dragstart', e => {
        const chip = e.target.closest('.place-chip');
        if (!chip) return;
        placesDragName = chip.dataset.place;
        e.dataTransfer.effectAllowed = 'move';
        e.dataTransfer.setData('text/plain', placesDragName);
        chip.classList.add('dragging');
    });

    lists.addEventListener('dragend', () => {
        lists.querySelectorAll('.dragging').forEach(c => c.classList.remove('dragging'));
        lists.querySelectorAll('.places-cat.drag-over').forEach(c => c.classList.remove('drag-over'));
        placesDragName = null;
    });

    lists.addEventListener('dragover', e => {
        if (!placesDragName) return;
        const cat = e.target.closest('.places-cat');
        if (!cat) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
        lists.querySelectorAll('.places-cat.drag-over').forEach(c => { if (c !== cat) c.classList.remove('drag-over'); });
        cat.classList.add('drag-over');
    });

    lists.addEventListener('dragleave', e => {
        const cat = e.target.closest('.places-cat');
        if (cat && !cat.contains(e.relatedTarget)) cat.classList.remove('drag-over');
    });

    lists.addEventListener('drop', e => {
        if (!placesDragName) return;
        const cat = e.target.closest('.places-cat');
        if (!cat) return;
        e.preventDefault();
        movePlaceToCategory(placesDragName, cat.dataset.cat);
        cat.classList.remove('drag-over');
        placesDragName = null;
    });
}

// Rebuild the three category lists (small flag + name chips) from the current selections.
function refreshPlacesPanel() {
    const host = document.getElementById('places-lists');
    if (!host) return;
    const sel = gameState.placesSelections || {};
    const byCat = { lived: [], visited: [], passed: [] };
    Object.keys(sel).forEach(name => { if (byCat[sel[name]]) byCat[sel[name]].push(name); });

    host.innerHTML = PLACE_LIST_ORDER.map(cat => {
        const meta = PLACE_META[cat];
        const names = byCat[cat].sort((a, b) => a.localeCompare(b));
        const chips = names.map(n => {
            const url = placesFlagUrl(n);
            const title = displayLabelForName(n);
            return `<span class="place-chip" draggable="true" data-place="${escAttr(n)}" title="${escAttr(title)}">` +
                   (url ? `<img class="place-chip-flag" src="${url}" alt="" draggable="false">` : '') +
                   `<span class="place-chip-name">${escAttr(title)}</span>` +
                   `<button type="button" class="place-chip-remove" aria-label="Remove ${escAttr(title)}" title="Remove">&times;</button>` +
                   `</span>`;
        }).join('');
        return `<div class="places-cat" data-cat="${cat}">
            <div class="places-cat-head">
                <span class="places-swatch ${meta.cls}"></span>
                <span class="places-cat-name">${meta.label}</span>
                <span class="places-count">${names.length}</span>
            </div>
            <div class="places-chips">${chips || '<span class="places-empty">None yet — drag chips here or click the map</span>'}</div>
        </div>`;
    }).join('');
}

// Minimal HTML-attribute escaper for interpolated place names (apostrophes, &, quotes, <).
function escAttr(s) {
    return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
}

// Remove a place entirely (the hover ✕ on a chip).
function removePlace(name) {
    if (!name || !gameState.placesSelections) return;
    delete gameState.placesSelections[name];
    applyPlacesFills();
    refreshPlacesPanel();
    updatePlacesUrl();
}

// Move a place into a different category (drag chip between lists).
function movePlaceToCategory(name, cat) {
    if (!name || !PLACE_META[cat]) return;
    if (gameState.placesSelections[name] === cat) return;
    gameState.placesSelections[name] = cat;
    applyPlacesFills();
    refreshPlacesPanel();
    updatePlacesUrl();
}

// The ISO code to use for a place: a territory's OWN code (so its own flag shows) when it
// has one, otherwise the sovereign data-object entry's code.
function placesCodeForName(name) {
    if (TERRITORY_CODE_BY_NAME[name]) return TERRITORY_CODE_BY_NAME[name];
    const data = lookupDataEntry(name, gameState.currentDataObj) ||
                 lookupDataEntry(effectiveDataName(name), gameState.currentDataObj);
    return data && data.code ? data.code : null;
}

// Quiet flag-URL lookup (no console noise) for a place name — the territory's own flag if it
// has one, else the sovereign flag.
function placesFlagUrl(name) {
    const code = placesCodeForName(name);
    return code ? `https://flagcdn.com/${code}.svg` : null;
}

// Advance a place through the category cycle and refresh map + panel + URL.
function cyclePlace(name) {
    const sel = gameState.placesSelections;
    const next = PLACE_CYCLE[sel[name] || 'none'];
    if (next == null) delete sel[name];
    else sel[name] = next;
    applyPlacesFills();
    refreshPlacesPanel();
    updatePlacesUrl();
}

// Apply the category fill class to every country path and island dot. Each feature is
// coloured by its OWN name (territories fill independently of their parent), unlike the
// quizzes where a parent fills its dependencies too. Called after every draw and cycle.
function applyPlacesFills() {
    if (!countriesGroup) return;
    const sel = gameState.placesSelections || {};
    const paint = function (d) {
        const name = d && d.properties && d.properties.name;
        const cat = name && sel[name];
        const node = d3.select(this);
        node.classed('place-visited', cat === 'visited')
            .classed('place-lived', cat === 'lived')
            .classed('place-passed', cat === 'passed');
    };
    countriesGroup.selectAll('path').each(paint);
    if (islandMarkersGroup) islandMarkersGroup.selectAll('circle').each(paint);
}

// ---- Places URL encode/decode ----
// Compact scheme grouped by category, using ISO codes: "v:us.fr~l:gb~p:ca".
function encodePlaces(sel) {
    const groups = { visited: [], lived: [], passed: [] };
    Object.keys(sel).forEach(name => {
        const code = placesCodeForName(name);
        if (code && groups[sel[name]]) groups[sel[name]].push(code);
    });
    const parts = [];
    if (groups.visited.length) parts.push('v:' + groups.visited.sort().join('.'));
    if (groups.lived.length)   parts.push('l:' + groups.lived.sort().join('.'));
    if (groups.passed.length)  parts.push('p:' + groups.passed.sort().join('.'));
    return parts.join('~');
}

function decodePlaces(str) {
    const rev = {};   // code → name: current region's data object plus territory codes
    const obj = gameState.currentDataObj || {};
    Object.keys(obj).forEach(name => { if (obj[name].code) rev[obj[name].code] = name; });
    Object.keys(TERRITORY_NAME_BY_CODE).forEach(code => { rev[code] = TERRITORY_NAME_BY_CODE[code]; });

    const catFor = { v: 'visited', l: 'lived', p: 'passed' };
    const out = {};
    (str || '').split('~').forEach(seg => {
        const i = seg.indexOf(':');
        if (i < 0) return;
        const cat = catFor[seg.slice(0, i)];
        if (!cat) return;
        seg.slice(i + 1).split('.').forEach(code => {
            const name = rev[code];
            if (name) out[name] = cat;
        });
    });
    return out;
}

// Build the query string for the current Places map (mode + region + selections + message).
function placesQueryString() {
    const p = new URLSearchParams();
    p.set('mode', 'places-been');
    p.set('region', QUIZ_MODES['places-been'].placesRegion || 'world');
    const enc = encodePlaces(gameState.placesSelections || {});
    if (enc) p.set('places', enc);
    if (gameState.placesMessage) p.set('msg', gameState.placesMessage);
    return p.toString();
}

// Keep the address bar in sync as the map is edited (no history entry per click).
function updatePlacesUrl() {
    history.replaceState(null, '', location.pathname + '?' + placesQueryString());
}

function sharePlacesLink() {
    const url = location.origin + location.pathname + '?' + placesQueryString();
    history.replaceState(null, '', url);
    copyShareLink(url, 'places-share-status');
}

// ---- Generic share / challenge plumbing ----

// Reflect a plain quiz mode in the URL so "copy link" shares that mode.
function syncModeUrl(mode) {
    const p = new URLSearchParams();
    p.set('mode', mode);
    history.replaceState(null, '', location.pathname + '?' + p.toString());
}

// Copy `url` to the clipboard, reporting success/failure into an optional status element
// (falls back to a toast when no status id is given).
function copyShareLink(url, statusId) {
    const report = ok => {
        const text = ok ? 'Link copied to clipboard!' : 'Copy failed — the link is in your address bar.';
        const status = statusId && document.getElementById(statusId);
        if (status) status.textContent = text;
        else showToast(text);
    };
    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(() => report(true)).catch(() => report(false));
    } else {
        report(false);
    }
}

// Share the current quiz as a challenge: the mode plus, once the game has ended, the score.
function shareCurrentGame() {
    const mc = QUIZ_MODES[gameState.mode];
    if (mc && mc.placesMode) { sharePlacesLink(); return; }
    const p = new URLSearchParams();
    p.set('mode', gameState.mode);
    if (gameState.ended) {
        p.set('score', String(gameState.score));
        const max = gameState.totalQuestions * maxSubForMode(mc);
        if (isFinite(max) && max > 0) p.set('max', String(max));
    }
    const url = location.origin + location.pathname + '?' + p.toString();
    history.replaceState(null, '', url);
    copyShareLink(url, null);
}

// Small transient toast in the corner (used for share confirmations).
function showToast(text) {
    let toast = document.getElementById('app-toast');
    if (!toast) {
        toast = document.createElement('div');
        toast.id = 'app-toast';
        toast.className = 'app-toast';
        document.body.appendChild(toast);
    }
    toast.textContent = text;
    toast.classList.add('show');
    clearTimeout(showToast._t);
    showToast._t = setTimeout(() => toast.classList.remove('show'), 2600);
}

// On load, start the mode named in the URL (?mode=...). Returns true if it handled routing.
function routeFromUrl() {
    const p = new URLSearchParams(location.search);
    const mode = p.get('mode');
    if (!mode) return false;

    if (mode === 'places-been') {
        const region = p.get('region') === 'us' ? 'us' : 'world';
        startPlacesMode(region, { selectionsStr: p.get('places') || '', message: p.get('msg') || '' });
        return true;
    }

    // A seeded spaceship link: same 10 sub-points and rolls for whoever opens it.
    const spots = decodeSpaceshipSeed(p.get('spots') || '');
    if (spots && spots.length && mode === 'spaceship') {
        startSpaceshipWithSeed(spots, spots.tune);
        return true;
    }

    // A challenge link (score present) shows a banner before starting the quiz.
    const score = p.get('score');
    if (score != null && QUIZ_MODES[mode]) {
        showChallengeBanner(mode, score, p.get('max'));
    }
    if (QUIZ_MODES[mode] && !QUIZ_MODES[mode].placesMode) {
        startGameWithMode(mode);
        return true;
    }
    return false;
}

// Banner shown when someone opens a challenge link, naming the score to beat.
function showChallengeBanner(mode, score, max) {
    const name = (QUIZ_MODES[mode] && QUIZ_MODES[mode].name) || mode;
    const target = max ? `${score}/${max}` : `${score}`;
    let banner = document.getElementById('challenge-banner');
    if (!banner) {
        banner = document.createElement('div');
        banner.id = 'challenge-banner';
        banner.className = 'challenge-banner';
        document.body.appendChild(banner);
    }
    banner.innerHTML = `<span>🏆 You've been challenged in <strong>${name}</strong> — beat <strong>${target}</strong>!</span>
        <button type="button" class="challenge-banner-close" aria-label="Dismiss">&times;</button>`;
    banner.classList.add('show');
    banner.querySelector('.challenge-banner-close').addEventListener('click', () => banner.classList.remove('show'));
    clearTimeout(showChallengeBanner._t);
    showChallengeBanner._t = setTimeout(() => banner.classList.remove('show'), 8000);
}

// Tear down any live in-game view (the spaceship WebGL canvas + inset, side panels, layout
// classes, running timers) so a sub-selector opened from the in-game top bar doesn't leave
// the previous mode showing behind it — notably the spaceship canvas when opening Places.
function teardownActiveGame() {
    removeSunPathMode();
    removeSunMoonPanel();
    disposeOrbital();
    removeSpaceshipInset();
    stopNameAllTimer();
    removePuzzleTray();
    removeFlagTray();
    removeSandboxPanel();
    removeSunMoonPanel();
    removeSunPathMode();
    sbTeardown();
    stopGlobeSpin();
    document.body.classList.remove('spaceship-active');
    document.body.classList.remove('state-puzzle-active');
    document.body.classList.remove('sb-tall-active');
    document.body.classList.remove('sb-wide-panel');
    document.querySelector('.container').classList.remove('globe-side-layout');
    document.querySelector('.container').classList.remove('explore-overlay-layout');
    document.querySelector('.container').classList.remove('state-puzzle-layout');
    document.querySelector('.container').classList.remove('sb-full-map');
    closeCountryPopup();
    const placesPanel = document.getElementById('places-panel');
    if (placesPanel) placesPanel.remove();
    d3.select('#globe').selectAll('*').remove();
    d3.select('#globe-world').selectAll('*').remove();
    ['map-container', 'controls', 'question-container', 'multiple-choice-container',
     'world-quiz-layout', 'world-quiz-question-bar', 'game-info'].forEach(id => {
        const el = document.getElementById(id);
        if (el) el.classList.add('hidden');
    });
}

// Show the region picker (World / USA) for Places-been.
function showPlacesModeSelector() {
    teardownActiveGame();
    document.getElementById('top-bar').style.display = 'none';
    document.getElementById('landing-header').style.display = '';

    const modeSelector = document.getElementById('mode-selector');
    modeSelector.classList.remove('hidden');
    modeSelector.innerHTML = `
        <h2>Places I've Been</h2>
        <p class="selector-sub">Fill in the map with everywhere you've been, then share it.</p>
        <div class="mode-buttons">
            <button class="mode-btn" data-places-region="world">
                <span class="mode-icon material-symbols-outlined">public</span>
                <span class="mode-name">World</span>
                <span class="mode-desc">Mark the countries you've been to</span>
            </button>
            <button class="mode-btn" data-places-region="us">
                <img class="mode-icon" src="https://flagcdn.com/us.svg" alt="USA" />
                <span class="mode-name">USA</span>
                <span class="mode-desc">Mark the US states you've been to</span>
            </button>
        </div>
        <button id="back-from-places-btn" class="btn secondary" style="margin-top: 20px;">Back</button>
    `;

    modeSelector.querySelectorAll('[data-places-region]').forEach(btn => {
        btn.addEventListener('click', (e) => startPlacesMode(e.currentTarget.dataset.placesRegion));
    });
    document.getElementById('back-from-places-btn').addEventListener('click', resetModeSelector);
}

// Show country popup with stats and flag
// Live Escape-key handler for the explore popup, so it can be unbound on close.
let exploreEscapeHandler = null;

function showCountryPopup(countryName) {
    // Territories carry the sovereign parent's flag/capital/population and are
    // titled e.g. "Puerto Rico (USA)".
    const dataName = effectiveDataName(countryName);
    const title = displayLabelForName(countryName);
    const data = lookupDataEntry(dataName, gameState.currentDataObj);
    if (!data) {
        console.warn(`No data found for ${countryName}`);
        return;
    }

    const flagUrl = getFlagUrl(dataName);
    const capital = getCapital(dataName) || 'N/A';
    const population = data.population ? data.population.toLocaleString() : 'N/A';

    const popupHtml = `
        <div class="explore-popup-content">
            <h3>${title}</h3>
            ${flagUrl ? `<img src="${flagUrl}" alt="Flag of ${title}" class="explore-flag">` : ''}
            <div class="explore-details">
                <p><strong>Capital:</strong> ${capital}</p>
                <p><strong>Population:</strong> ${population}</p>
            </div>
            <button class="btn-close">Close</button>
        </div>
    `;

    let popup = document.getElementById('explore-popup');
    if (!popup) {
        popup = document.createElement('div');
        popup.id = 'explore-popup';
        popup.className = 'explore-popup';
        document.body.appendChild(popup);
        // Close on outside click
        popup.addEventListener('click', (e) => {
            if (e.target === popup) closeCountryPopup();
        });
    }

    // In Free Explore the popup belongs to the floating top-right panel (stacked under the
    // "Explore the Globe" prompt) rather than centred over the page, so it never covers the
    // globe it is describing. Anywhere else it stays a centred body-level dialog.
    const host = document.querySelector('.container.explore-overlay-layout')
        ? document.getElementById('globe-side-panel')
        : document.body;
    if (host && popup.parentNode !== host) host.appendChild(popup);

    popup.innerHTML = popupHtml;
    popup.style.display = 'block';

    // Add close button handler
    popup.querySelector('.btn-close').addEventListener('click', closeCountryPopup);

    // Close on Escape. Parked on a module-level handle and swapped out each time, since the
    // old version only unbound itself when Escape was actually pressed — closing any other
    // way left the listener behind, and clicking through a dozen countries stacked up a
    // dozen of them.
    if (exploreEscapeHandler) document.removeEventListener('keydown', exploreEscapeHandler);
    exploreEscapeHandler = (e) => { if (e.key === 'Escape') closeCountryPopup(); };
    document.addEventListener('keydown', exploreEscapeHandler);
}

// Close the country popup, removing it from the DOM rather than just hiding it.
// Removing matters because showCountryPopup RE-PARENTS the node into #globe-side-panel for
// the Free Explore overlay layout. A merely-hidden node stays in that panel, and the next
// mode drops `explore-overlay-layout` — which is the only thing scoping the rule that tames
// it into a static card — so the base fixed/centred dialog styling takes back over and the
// popup strands itself on top of the new mode.
function closeCountryPopup() {
    if (exploreEscapeHandler) {
        document.removeEventListener('keydown', exploreEscapeHandler);
        exploreEscapeHandler = null;
    }
    const popup = document.getElementById('explore-popup');
    if (popup) popup.remove();
}

// ==================== COUNTRY SHAPE ID MODE ====================

// ---- Framing core: the country minus its far-flung specks ----
// A country's bounding box is only as tight as its most remote scrap of land, and several
// countries own a rock thousands of km from everything else: South Africa's Prince Edward
// Islands (0.02% of its area, 1400 km south-east), Norway's Bouvet Island (in the Southern
// Ocean), Ecuador's Galápagos, mainland Netherlands vs Bonaire, France vs French Guiana.
// Fitting the Shape-ID silhouette to THAT box shrinks the actual country to an unreadable
// blob. shapeFramingCore returns just the parts worth framing — an invisible bounding box,
// since the full geometry is still what gets drawn (anything excluded simply falls outside
// the viewport). Also used for the shape DESCRIPTOR, so aspect/compactness describe the
// country people would recognise rather than its outlier-stretched box.
const CORE_MIN_AREA_FRAC = 0.005; // ignore parts under 0.5% of the country's area…
const CORE_BIG_PART_FRAC = 0.25;  // …unless they rival the main landmass, then always keep
const CORE_MIN_GAP_KM = 200;      // never treat something this close as "far-flung"
const CORE_MIN_KEPT_FRAC = 0.6;   // kept <60% of the area? the country really is scattered
const DEG_KM = 111.32;

// A part's bounds as [w, s, e, n] in degrees RELATIVE to lon0, so a country straddling
// ±180° (New Zealand's Chatham Islands) measures as one continuous span. This mirrors the
// rotate-to-centroid the projection itself does before fitting.
function partRelBounds(coords, lon0) {
    let w = Infinity, s = Infinity, e = -Infinity, n = -Infinity;
    for (const ring of coords) {
        for (const p of ring) {
            let dl = p[0] - lon0;
            while (dl > 180) dl -= 360;
            while (dl < -180) dl += 360;
            if (dl < w) w = dl;
            if (dl > e) e = dl;
            if (p[1] < s) s = p[1];
            if (p[1] > n) n = p[1];
        }
    }
    return [w, s, e, n];
}

// Longest side of a [w,s,e,n] box, in km (longitude shrunk by latitude).
function boxExtentKm(b) {
    const midLat = (b[1] + b[3]) / 2 * Math.PI / 180;
    return Math.max((b[3] - b[1]) * DEG_KM, (b[2] - b[0]) * DEG_KM * Math.cos(midLat));
}

// Km of empty space between two boxes (0 if they overlap or touch).
function boxGapKm(a, b) {
    const midLat = (Math.max(a[1], b[1]) + Math.min(a[3], b[3])) / 2 * Math.PI / 180;
    const dLat = Math.max(0, b[1] - a[3], a[1] - b[3]) * DEG_KM;
    const dLon = Math.max(0, b[0] - a[2], a[0] - b[2]) * DEG_KM * Math.cos(isFinite(midLat) ? midLat : 0);
    return Math.hypot(dLat, dLon);
}

function shapeFramingCore(feature) {
    // Hand-listed exceptions first — parts that clear every threshold the rule has and still
    // wreck the frame (Svalbard for Norway). See SHAPE_CORE_OVERRIDES.
    feature = applyCoreOverride(feature);
    const parts = featureParts(feature);
    if (parts.length < 2) return feature;

    const items = parts.map(c => {
        const poly = { type: 'Polygon', coordinates: c };
        return { c, a: d3.geoArea(poly), centroid: d3.geoCentroid(poly) };
    });
    const total = items.reduce((sum, it) => sum + it.a, 0);
    if (!(total > 0)) return feature;

    items.sort((x, y) => y.a - x.a);
    const lon0 = items[0].centroid[0];
    items.forEach(it => { it.b = partRelBounds(it.c, lon0); });

    // Grow outward from the largest landmass, biggest part first: a part joins the core if
    // it is comparable in size to the main mass, or near enough to what's accumulated so
    // far. Testing against the GROWING box (not just the main part) is what keeps genuinely
    // strung-out countries whole — Indonesia reaches Papua island by island.
    const main = items[0];
    let box = main.b.slice();
    let keptArea = main.a;
    const kept = [main.c];
    for (let i = 1; i < items.length; i++) {
        const it = items[i];
        const keep = it.a >= CORE_BIG_PART_FRAC * main.a ||
            (it.a >= CORE_MIN_AREA_FRAC * total &&
                boxGapKm(box, it.b) <= Math.max(CORE_MIN_GAP_KM, boxExtentKm(box)));
        if (!keep) continue;
        kept.push(it.c);
        keptArea += it.a;
        box = [Math.min(box[0], it.b[0]), Math.min(box[1], it.b[1]),
               Math.max(box[2], it.b[2]), Math.max(box[3], it.b[3])];
    }

    // Countries that genuinely ARE a scatter of islands (Kiribati spans 4000 km of Pacific
    // with no main landmass at all) would be reduced to a single atoll — leave them whole.
    if (keptArea < CORE_MIN_KEPT_FRAC * total) return feature;
    return { type: 'MultiPolygon', coordinates: kept };
}

// Shape descriptors used to offer Shape-ID distractors that LOOK like the target.
// Built once from the loaded (10m) geometry and cached until new map data loads.
let shapeDescriptorCache = null;

// Size / elongation / compactness descriptor for a country feature. Measured on the
// framing core, so an offshore speck can't report South Africa as a tall, mostly-empty box.
function computeShapeDescriptor(feature) {
    const f = shapeFramingCore(feature);
    const area = d3.geoArea(f); // steradians (spherical area, 0..4π)
    const [[w, s], [e, n]] = d3.geoBounds(f);
    let lonSpan = e - w;
    if (lonSpan < 0) lonSpan += 360; // antimeridian wrap
    const midLat = (s + n) / 2;
    const width = lonSpan * Math.cos(midLat * Math.PI / 180); // physical width (deg-equiv)
    const height = Math.max(n - s, 1e-3);
    const aspect = width / height;                            // >1 wide, <1 tall
    // Spherical bounding-box area, for a size-independent compactness ratio.
    const bboxArea = Math.abs((lonSpan * Math.PI / 180) *
        (Math.sin(n * Math.PI / 180) - Math.sin(s * Math.PI / 180)));
    const compactness = bboxArea > 0 ? area / bboxArea : 0;   // fraction of bbox filled
    return { logArea: Math.log(Math.max(area, 1e-6)), logAspect: Math.log(Math.max(aspect, 1e-3)), compactness };
}

// name -> shape descriptor, from the largest feature per name (some names split
// into micro-polygons at high detail; the biggest carries the recognisable shape).
function buildShapeDescriptorCache() {
    const byName = new Map();
    (gameState.countries || []).forEach(f => {
        const nm = f && f.properties && f.properties.name;
        if (!nm || (f.properties && f.properties.isTerritory)) return; // territories aren't quiz answers
        const prev = byName.get(nm);
        if (!prev || d3.geoArea(f) > d3.geoArea(prev)) byName.set(nm, f);
    });
    const cache = new Map();
    byName.forEach((f, nm) => cache.set(nm, computeShapeDescriptor(f)));
    return cache;
}

function getShapeDescriptorCache() {
    if (!shapeDescriptorCache) shapeDescriptorCache = buildShapeDescriptorCache();
    return shapeDescriptorCache;
}

// The `count` quiz-list countries whose overall shape is most similar to the
// target's, by standardized (z-scored) distance in descriptor space.
function shapeSimilarNames(targetName, count) {
    const cache = getShapeDescriptorCache();
    const list = (gameState.currentQuizList || []).filter(n => cache.has(n));
    const target = cache.get(targetName);
    if (!target || list.length < 2) return [];

    const keys = ['logArea', 'logAspect', 'compactness'];
    // The silhouette is fitted to fill the view, so absolute SIZE barely affects how
    // alike two outlines look — weight form (aspect, compactness) far above area.
    const weight = { logArea: 0.35, logAspect: 1.0, compactness: 1.0 };
    // Standardize each dimension so no single feature (e.g. huge log-area range) dominates.
    const stats = {};
    keys.forEach(k => {
        const vals = list.map(n => cache.get(n)[k]);
        const mean = vals.reduce((a, b) => a + b, 0) / vals.length;
        const variance = vals.reduce((a, b) => a + (b - mean) ** 2, 0) / vals.length;
        stats[k] = { mean, sd: Math.sqrt(variance) || 1 };
    });
    // Weighted Euclidean distance target→candidate in standardized (z-score) space.
    const dist = (d) => Math.hypot(...keys.map(k => weight[k] * (d[k] - target[k]) / stats[k].sd));

    return list
        .filter(n => n !== targetName)
        .map(n => ({ name: n, d: dist(cache.get(n)) }))
        .sort((a, b) => a.d - b.d)
        .slice(0, count)
        .map(x => x.name);
}

// Build the 4 Shape-ID options: the answer + 2 shape-similar distractors + fill.
function generateShapeIdOptions(correctAnswer) {
    const list = gameState.currentQuizList || [];
    const options = [correctAnswer];
    shapeSimilarNames(correctAnswer, 2).forEach(n => { if (!options.includes(n)) options.push(n); });
    // Top up to 4 with random quiz items if similarity yielded too few.
    let guard = 0;
    while (options.length < 4 && options.length < list.length && guard++ < 500) {
        const r = list[Math.floor(Math.random() * list.length)];
        if (!options.includes(r)) options.push(r);
    }
    return shuffleArray(options);
}

// Render country shape ID question — show ONLY the target country's outline as a
// flat Mercator silhouette (no globe, neighbours, lakes or dots), then pick the name.
// Three ways to show one silhouette, from the outline plainly to a scrap of it at an angle.
// Nothing about the QUESTION changes — same countries, same shape-similar distractors — only
// how much of the shape you are given to work from.
const SHAPE_ID_TIERS = {
    outline: { label: 'Outline', desc: 'The country, upright and whole' },
    turned:  { label: 'Turned',  desc: 'The whole outline, at an unknown angle', rotate: true },
    // Starts as a handful of corners and grows back into the real coastline while you watch.
    // Answer whenever you are sure; the score is how little of it you needed.
    unfold:  { label: 'Coming Into Focus', desc: 'A few corners, sharpening to the true coastline — name it as early as you dare', unfold: true }
};
let shapeIdTier = 'outline';

// Which geography the silhouettes are cut from. Every tier works over either — a state is as
// hard to name from its outline as a country is, and rather harder for the rectangular ones.
const SHAPE_ID_REGIONS = [
    { key: 'countries', label: 'World',     icon: 'public',  desc: 'Every country' },
    { key: 'us-states', label: 'US States', icon: 'flag',    desc: 'All fifty' }
];
let shapeIdRegion = 'countries';

// Reconfigure in place from another mode's entry — the same pattern startIdentifyMode and
// startDrawBorderMode use. Two things are forced rather than copied: AlbersUSA is dropped,
// because a composite projection cannot sensibly fit itself to one state (Alaska and Hawaii
// live in insets at their own scales), and Shape ID wants a plain Mercator fitted to whatever
// it is showing; and the round count is capped at the list length, since the fifty states are
// not the two hundred countries.
function startShapeIdMode(region, tier) {
    const m = QUIZ_MODES['country-shape-id'];
    const base = QUIZ_MODES[region] || QUIZ_MODES['countries'];
    shapeIdRegion = QUIZ_MODES[region] ? region : 'countries';
    shapeIdTier = tier || shapeIdTier;
    m.shapeIdRegion = shapeIdRegion;
    m.quizList = base.quizList;
    m.dataObjKey = base.dataObjKey;
    m.mapObject = base.mapObject;
    m.itemLabel = base.itemLabel;
    m.itemLabelPlural = base.itemLabelPlural;
    m.useGlobe = false;
    m.useAlbersUsa = false;
    // The world silhouettes are judged on the outline, so they force 10m through
    // worldCountriesUrl(); every other region ships one resolution and uses its own URL.
    m.mapUrl = base.mapObject === 'countries'
        ? 'https://cdn.jsdelivr.net/npm/world-atlas@2/countries-50m.json'
        : base.mapUrl;
    m.totalQuestions = Math.min(10, base.quizList.length);
    shapeDescriptorCache = null;   // descriptors are keyed by name, and the pool just changed
    startGameWithMode('country-shape-id');
}

// The two sandbox quizzes that live under Name the Shape take a region the same way, and by the
// same reconfigure-in-place trick — `sbPool()` and `sbFeature()` read `gameState.currentQuizList`
// and `gameState.countries` and neither has ever cared which atlas they came from, so a state is
// as good a silhouette as a country with nothing else to change.
//
// AlbersUSA is forced off for the same reason Shape ID forces it off: these rounds fit a
// projection to one shape at a time, and a composite cannot do that. The shared caches are keyed
// by NAME, so they have to go when the pool does.
function startShapeQuizMode(key, region) {
    const m = QUIZ_MODES[key];
    if (!m) return;
    const base = QUIZ_MODES[region] || QUIZ_MODES['countries'];
    shapeIdRegion = QUIZ_MODES[region] ? region : 'countries';
    m.quizList = base.quizList;
    m.dataObjKey = base.dataObjKey;
    m.mapObject = base.mapObject;
    m.itemLabel = base.itemLabel;
    m.itemLabelPlural = base.itemLabelPlural;
    m.useAlbersUsa = false;
    // World rounds keep going through worldCountriesUrl() (which `sbHiRes` pushes to 10m);
    // every other region ships one resolution and uses its own URL.
    m.mapUrl = base.mapObject === 'countries'
        ? 'https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json'
        : base.mapUrl;
    m.totalQuestions = Math.min(10, base.quizList.length);
    shapeDescriptorCache = null;
    sbWholeCache.clear();
    startGameWithMode(key);
}

function renderCountryShapeIdQuestion() {
    gameState.questionType = 'country-shape-id';
    const tier = SHAPE_ID_TIERS[shapeIdTier] || SHAPE_ID_TIERS.outline;
    stopShapeUnfold();
    if (svg) svg.on('click.shapestep', null);

    const what = (QUIZ_MODES['country-shape-id'] || {}).itemLabel || 'country';
    document.getElementById('question-text').innerHTML = tier.unfold
        ? `Name it as soon as you can.`
        : tier.rotate
        ? `Which ${what} is this? <span style="opacity:.7;font-size:.85em">(turned to an unknown angle)</span>`
        : `Which ${what} is highlighted?`;
    const flagDisplay = document.getElementById('flag-display');
    if (flagDisplay) flagDisplay.style.display = 'none';

    // Locate the target feature (tolerant of accented atlas names).
    const target = (gameState.countries || []).find(
        f => f && f.properties && namesMatch(f.properties.name, gameState.targetCountry)
    );

    // Fit the Mercator projection to just this country. Rotate to its centroid
    // longitude first so shapes that straddle the antimeridian stay intact. The fit uses
    // the framing CORE, not the raw feature — otherwise a remote islet (Prince Edward for
    // South Africa, the Galápagos for Ecuador) sets the bounds and the country itself
    // shrinks to a smudge. The full geometry is still what's drawn below; excluded parts
    // just land outside the viewport.
    if (target && projection && projection.fitExtent) {
        const core = shapeFramingCore(target);
        const c = d3.geoCentroid(core);
        if (c && isFinite(c[0])) projection.rotate([-c[0], 0]);
        const pad = Math.min(width, height) * 0.12;
        projection.fitExtent([[pad, pad], [width - pad, height - pad]], core);
    }

    // Draw ONLY the target as a single borderless silhouette. Rendering the whole
    // 10m world (~250k vertices) just to show one country is far too heavy, so the
    // other features are never added to the DOM (drawCountries skips them).
    countriesGroup.selectAll('path').remove();
    g.selectAll('g.shape-id-layer').remove();
    if (target) {
        // The harder tiers wrap the silhouette in a group that is rotated about the viewport
        // centre. Rotating in SCREEN space rather than re-projecting is what keeps the framing
        // identical across tiers — re-projecting would refit the country to its new bounding
        // box, so the amount of the viewport it fills would itself become a clue.
        let host = countriesGroup;
        // The unfolding tier draws itself, frame by frame, and owns the path for the round.
        // It must NOT return out of the whole function — the answer list is still to come.
        if (tier.unfold) startShapeUnfold(target);
        else if (tier.rotate) {
            const ang = Math.round(Math.random() * 360);
            // Shrink far enough that the TURNED shape still fits. The projection was fitted to
            // the country upright, so a tall one spun a quarter turn needs the viewport's width
            // for its height and runs off the edge — Tonga came out 1,064 px tall in a 600 px
            // box. The room a w x h box needs at angle a is (w|cos|+h|sin|) by (w|sin|+h|cos|).
            let f = 1;
            try {
                const b = path.bounds(shapeFramingCore(target) || target);
                const w0 = b[1][0] - b[0][0], h0 = b[1][1] - b[0][1];
                const r = ang * DEG, ca = Math.abs(Math.cos(r)), sa = Math.abs(Math.sin(r));
                const pad2 = Math.min(width, height) * 0.12;
                f = Math.min(1, (width - 2 * pad2) / (w0 * ca + h0 * sa),
                                (height - 2 * pad2) / (w0 * sa + h0 * ca));
            } catch (_) { f = 1; }
            gameState.shapeIdAngle = ang;
            gameState.shapeIdFit = f;
            host = g.append('g').attr('class', 'shape-id-layer')
                .attr('transform', `rotate(${ang}, ${width / 2}, ${height / 2}) ` +
                                   `translate(${width / 2},${height / 2}) scale(${f}) translate(${-width / 2},${-height / 2})`);
        }
        if (!tier.unfold) {
            gameState.shapeIdTarget = target;
            host.append('path')
                .datum(target)
                .attr('class', 'country shape-target')
                .attr('d', path(target));
        }
    }

    // Multiple-choice options: the answer plus 2 distractors chosen for LOOKING like
    // the target shape (+ a random fill), so the wrong answers are genuinely tricky.
    if (tier.unfold) {
        // The whole list, not four names. Four options and a growing outline are the same
        // question asked twice — you would wait for the detail that separates those four and
        // answer then, which is not the game. Against every country in the world, the moment
        // you are sure is the moment you actually recognised it.
        sbRenderPickOne({ options: gameState.currentQuizList.map(displayLabelForName),
                          correct: displayLabelForName(gameState.targetCountry) });
        // The shape IS the button. A separate control put the thing you press somewhere other
        // than the thing you are looking at, and this board has nothing else on it to click.
        document.getElementById('question-text').innerHTML +=
            ` <span class="shape-step-wrap"><span class="shape-step-read">Points: ` +
            `<span id="shape-detail-read">3</span> — <span id="shape-step-hint">click the map for more</span>` +
            `</span></span>`;
        if (svg) svg.on('click.shapestep', (event) => { if (!svgClickDragged(event)) stepShapeUnfold(); });
        syncShapeUnfoldReadout();
        return;
    }
    const options = generateShapeIdOptions(gameState.targetCountry);
    renderMultipleChoice(options, gameState.targetCountry);
}

// ---- Coming Into Focus -------------------------------------------------------------------
// The country is drawn at almost no resolution — a few corners — and the detail is put back a
// little at a time until it is the real coastline. You answer whenever you are sure, and the
// score is how little of it you needed.
//
// It runs on the same Visvalingam-Whyatt pass the coastline model uses (`vwWeights`), which is
// what makes it work as a QUESTION rather than as a blur: VW drops the point whose triangle
// with its neighbours is smallest, so what survives at low detail is the country's actual
// corners — the cape, the bend in the river, the elbow of the border — in the order a person
// would draw them. A pixellated or smoothed version would degrade the outline into something
// no country ever had; this degrades it into a sketch of the right country.
//
// Two properties of that pass matter here and neither is incidental:
//   * the weights are forced monotonically increasing, so every threshold gives a NESTED
//     subset. Points can only ever be added as the detail rises — nothing that has appeared
//     ever disappears again, which is what stops the shape flickering as it grows.
//   * a removal that would make the ring cross itself is refused outright, so even at three
//     percent detail the silhouette is a simple polygon rather than a knot.
// The detail is stepped BY HAND, not on a clock. On a timer the round was a race against an
// animation — you were not deciding how much of the country you needed, you were waiting for it
// — and the score line ("you needed 47 points") was reporting the stopwatch rather than the
// player. With a button, spending detail is a choice and the number means what it says.
//
// The first presses follow a fixed hand-picked run — 3, 7, 12, 18, 25 — whose steps grow by one
// each time. That is the part of the round anyone is actually reading, and at those sizes every
// single point is a visible corner, so the increments want to be chosen rather than derived.
//
// After that a constant RATIO takes over, because equal absolute steps stop meaning anything:
// 3 points to 7 changes the shape completely and 3,000 to 3,004 changes nothing, and on the
// fixed run alone a 3,000-vertex country would need eighty presses. Taking whichever of the two
// is larger hands over by itself, at about 25 points, with no seam.
const SHAPE_UNFOLD_RATIO = 1.35;
const SHAPE_UNFOLD_START = 3;     // where it starts: a triangle
// Parts under this are left out entirely. It is not a rendering nicety: counting detail as a
// PERCENTAGE of a country's points made the budget hostage to its islands — South Korea's
// islets are most of its vertex count, so one percent of them was already an unmistakable
// outline of the mainland. An absolute budget fixes the arithmetic; this fixes what is counted.
const SHAPE_UNFOLD_MIN_PART_KM2 = 1000;
let shapeUnfold = null;

function startShapeUnfold(target) {
    stopShapeUnfold();
    gameState.shapeIdTarget = target;
    const R2 = 6371 * 6371;
    let rings = featureParts(target)
        .map(poly => poly[0])
        .filter(r => r && r.length > 4)
        .map(r => ({ ring: r, km2: d3.geoArea({ type: 'Polygon', coordinates: [r] }) * R2 }))
        .filter(r => r.km2 >= SHAPE_UNFOLD_MIN_PART_KM2);
    // Never end up with nothing: a country made entirely of small islands still has to be
    // drawable, so it falls back to its largest part whatever that part's size.
    if (!rings.length) {
        const all = featureParts(target).map(poly => poly[0]).filter(r => r && r.length > 4);
        if (!all.length) {
            countriesGroup.append('path').datum(target).attr('class', 'country shape-target').attr('d', path(target));
            return;
        }
        all.sort((x, y) => y.length - x.length);
        rings = [{ ring: all[0], km2: 0 }];
    }

    // One global ordering of every point in every kept ring, by VW weight.
    //
    // The endpoints of each ring come back from vwWeights as Infinity, because for an open
    // polyline the ends can never be dropped — but a ring's "ends" are just wherever the atlas
    // happened to start the arc, which is not a geographic fact about anything. Left as
    // Infinity they would each claim a slot before the budget bought a single real corner, so
    // twenty islands would spend forty points saying nothing. They are demoted to the ring's
    // own heaviest finite weight instead: important within their ring, ordinary globally.
    const prepared = rings.map(({ ring }) => {
        const w = vwWeights(ring);
        let maxFinite = 0;
        for (let i = 0; i < w.length; i++) if (isFinite(w[i]) && w[i] > maxFinite) maxFinite = w[i];
        const fixed = Array.from(w, v => (isFinite(v) ? v : (maxFinite || 1)));
        return { ring, w: fixed };
    });
    const order = [];
    prepared.forEach((pr, ri) => {
        for (let i = 0; i < pr.ring.length - 1; i++) order.push({ ri, i, w: pr.w[i] });
    });
    order.sort((x, y) => y.w - x.w);

    const layer = countriesGroup.append('path').attr('class', 'country shape-target shape-unfold');
    shapeUnfold = { target, prepared, order, total: order.length, layer,
                    points: SHAPE_UNFOLD_START, gap: 4 };
    drawShapeUnfold(SHAPE_UNFOLD_START);
}

// One press: the next visible amount of country. The fixed run's step grows by one each time
// (+4, +5, +6, +7 … giving 3, 7, 12, 18, 25) and the ratio takes over as soon as it asks for
// more, so the two never fight and the handover needs no threshold.
function stepShapeUnfold() {
    if (!shapeUnfold || gameState.questionType !== 'country-shape-id') return;
    if (gameState.answeredCorrectly || shapeUnfold.points >= shapeUnfold.total) return;
    const next = Math.max(shapeUnfold.points + shapeUnfold.gap,
                          Math.round(shapeUnfold.points * SHAPE_UNFOLD_RATIO));
    shapeUnfold.gap++;
    shapeUnfold.points = Math.min(shapeUnfold.total, next);
    drawShapeUnfold(shapeUnfold.points);
    syncShapeUnfoldReadout();
}

function syncShapeUnfoldReadout() {
    if (!shapeUnfold) return;
    const el = document.getElementById('shape-detail-read');
    if (el) el.textContent = shapeUnfold.points.toLocaleString();
    const hint = document.getElementById('shape-step-hint');
    if (hint && shapeUnfold.points >= shapeUnfold.total) hint.textContent = 'full detail';
}

// The `n` heaviest points in the country, wherever they fall. ONE budget shared across all the
// rings rather than a fraction applied to each: an island only appears once its own corners
// have out-competed the mainland's, which is the order someone sketching would reach them in.
function drawShapeUnfold(n) {
    if (!shapeUnfold) return;
    const keep = shapeUnfold.prepared.map(() => []);
    const take = Math.max(3, Math.min(shapeUnfold.total, n));
    for (let k = 0; k < take; k++) {
        const e = shapeUnfold.order[k];
        keep[e.ri].push(e.i);
    }
    const polys = [];
    keep.forEach((idxs, ri) => {
        // A ring needs three distinct points to enclose anything. Below that it has not earned
        // its place and simply is not drawn — which is what makes the islands arrive one at a
        // time rather than all at once as slivers.
        if (idxs.length < 3) return;
        idxs.sort((x, y) => x - y);
        const ring = shapeUnfold.prepared[ri].ring;
        const pts = idxs.map(i => ring[i]);
        pts.push(pts[0]);
        polys.push([pts]);
    });
    if (!polys.length) {
        const ring = shapeUnfold.prepared[0].ring;
        const step = Math.max(1, Math.floor(ring.length / 4));
        const pts = [];
        for (let i = 0; i < ring.length && pts.length < 3; i += step) pts.push(ring[i]);
        pts.push(pts[0]);
        polys.push([pts]);
    }
    shapeUnfold.layer.attr('d', path({ type: 'MultiPolygon', coordinates: polys }) || '');
}

function stopShapeUnfold() {
    shapeUnfold = null;
}

// Once the round is decided, put the country back the way round it really is — and whole. The
// tier withholds information to make the question hard; keeping it withheld through the answer
// would just make the answer unverifiable.
function revealShapeIdTruth() {
    const tier = SHAPE_ID_TIERS[shapeIdTier];
    if (tier && tier.unfold) {
        // Freeze the detail the answer was given at, note it, then snap to the real coastline.
        if (shapeUnfold) {
            const used = shapeUnfold.points;
            const tot = shapeUnfold.total;
            gameState.shapeDetails = (gameState.shapeDetails || []).concat(used);
            const layer = shapeUnfold.layer, target = shapeUnfold.target;
            stopShapeUnfold();
            layer.datum(target).attr('d', path(target));
            const fb = document.getElementById('feedback');
            if (fb) fb.innerHTML = `<strong>${displayLabelForName(gameState.targetCountry)}</strong>` +
                ` — named at <strong>${used.toLocaleString()}</strong> point${used === 1 ? '' : 's'}` +
                ` out of ${tot.toLocaleString()}.`;
        }
        return;
    }
    if (!tier || !tier.rotate || !g || !gameState.shapeIdTarget) return;
    const layer = g.select('g.shape-id-layer');
    if (layer.empty()) return;
    layer.select('path.shape-target').attr('d', path(gameState.shapeIdTarget));
    const reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const dur = reduce ? 0 : 700;
    const end = `rotate(0, ${width / 2}, ${height / 2}) ` +
                `translate(${width / 2},${height / 2}) scale(1) translate(${-width / 2},${-height / 2})`;
    if (dur) layer.transition().duration(dur).ease(d3.easeCubicInOut).attr('transform', end);
    // d3 transitions are rAF-driven and a backgrounded tab never fires it, so the finished
    // state is set unconditionally — the same backstop the puzzle's piece `settle` documents.
    setTimeout(() => { if (layer.node() && layer.node().isConnected) { layer.interrupt(); layer.attr('transform', end); } }, dur + 60);
}

// One tile per tier, in the same shape as the puzzle's difficulty picker, with the geography
// chosen on the same screen rather than behind an extra click — it is one of two answers, and
// a whole page to give it would be a page for a toggle.
// SHAPES. Everything whose question is an OUTLINE, in one place: name one, trace one, or drag a
// set of them into position. They were three separate landing tiles asking the same kind of
// question, and the puzzle in particular reads as its own genre when it is really "do you know
// this shape" with the answer given by where you put it.
function showShapeIdSelector() {
    teardownActiveGame();
    document.getElementById('top-bar').style.display = 'none';
    document.getElementById('landing-header').style.display = '';
    const sel = document.getElementById('mode-selector');
    sel.classList.remove('hidden');
    sel.innerHTML = `
        <h2>Shapes</h2>
        <p class="selector-sub">Name an outline, trace one, or drag a set of them into place.</p>
        <div class="mode-buttons">
            <button class="mode-btn" data-shapemode="state-puzzle">
                <span class="mode-icon material-symbols-outlined">extension</span>
                <span class="mode-name">Map Puzzle</span>
                <span class="mode-desc">Drag every piece into place — world, US, India, Germany, England or Mexico</span>
            </button>
            <button class="mode-btn" data-shapemode="draw-border">
                <span class="mode-icon material-symbols-outlined">gesture</span>
                <span class="mode-name">Draw the Border</span>
                <span class="mode-desc">The country is cut out of the map — trace where it goes</span>
            </button>
            ${SB_IN_SHAPES.map(k => `
            <button class="mode-btn" data-shapeplain="${k}">
                <span class="mode-icon material-symbols-outlined">${SB_QUIZZES[k].icon}</span>
                <span class="mode-name">${SB_QUIZZES[k].label}</span>
                <span class="mode-desc">${SB_QUIZZES[k].desc}</span>
            </button>`).join('')}
        </div>
        <p class="selector-sub">Or one silhouette, no map around it — how much of it do you want?</p>
        <div class="scope-toggle" role="group" aria-label="Geography">
            <span class="scope-toggle-label">From:</span>
            ${SHAPE_ID_REGIONS.map(r => `<button type="button" class="scope-btn` +
                `${r.key === shapeIdRegion ? ' active' : ''}" data-shaperegion="${r.key}">${r.label}</button>`).join('')}
        </div>
        <div class="mode-buttons">
            ${Object.keys(SHAPE_ID_TIERS).map(k => `
            <button class="mode-btn" data-shapetier="${k}">
                <span class="mode-icon material-symbols-outlined">pentagon</span>
                <span class="mode-name">${SHAPE_ID_TIERS[k].label}</span>
                <span class="mode-desc">${SHAPE_ID_TIERS[k].desc}</span>
            </button>`).join('')}
        </div>
        <p class="selector-sub">Or ask a different question about the same silhouettes.</p>
        <div class="mode-buttons">
            ${SB_IN_SHAPE_ID.map(k => `
            <button class="mode-btn" data-shapequiz="${k}">
                <span class="mode-icon material-symbols-outlined">${SB_QUIZZES[k].icon}</span>
                <span class="mode-name">${SB_QUIZZES[k].label}</span>
                <span class="mode-desc">${SB_QUIZZES[k].desc}</span>
            </button>`).join('')}
        </div>`;
    sel.querySelectorAll('[data-shaperegion]').forEach(btn => {
        btn.addEventListener('click', () => {
            shapeIdRegion = btn.dataset.shaperegion;
            sel.querySelectorAll('[data-shaperegion]').forEach(b =>
                b.classList.toggle('active', b === btn));
        });
    });
    sel.querySelectorAll('[data-shapetier]').forEach(btn => {
        btn.addEventListener('click', () => startShapeIdMode(shapeIdRegion, btn.dataset.shapetier));
    });
    sel.querySelectorAll('[data-shapequiz]').forEach(btn => {
        btn.addEventListener('click', () => startShapeQuizMode(btn.dataset.shapequiz, shapeIdRegion));
    });
    // These take the world and nothing else, so they start straight away.
    sel.querySelectorAll('[data-shapeplain]').forEach(btn => {
        btn.addEventListener('click', () => startGameWithMode(btn.dataset.shapeplain));
    });
    // The two that ask for a region of their own rather than taking this screen's.
    sel.querySelectorAll('[data-shapemode]').forEach(btn => {
        btn.addEventListener('click', () => {
            if (btn.dataset.shapemode === 'state-puzzle') showStatePuzzleSelector();
            else showDrawBorderSelector();
        });
    });
}

// ==================== SKYLINE ID MODE ====================

// Photos come from Wikimedia Commons: its API is CORS-open (origin=*) and every file
// carries machine-readable licensing, so the pool can be restricted to images we are
// actually allowed to show, and each one credited.
const COMMONS_API = 'https://commons.wikimedia.org/w/api.php';
// Obvious non-photographs that a text search still surfaces.
const SKYLINE_REJECT_TITLE = /\b(map|flag|coat of arms|seal|logo|diagram|chart|plan|locator|poster|stamp|coin|banner|icon)\b/i;
// Titles promising an actual wide city view — used to RANK, never to reject.
const SKYLINE_GOOD_TITLE = /skyline|panorama|cityscape|downtown|aerial/i;

const skylineListCache = {};      // city → Promise<candidate[]>
const skylineNoPhoto = new Set(); // cities Commons had nothing usable for (don't re-query all game)
let skylineToken = 0;             // voids in-flight searches when the question moves on
let skylineNext = null;           // { city, photo } resolved ahead of time for the next round
let skylinePrefetching = false;

function commonsMeta(meta, key) {
    return (meta && meta[key] && meta[key].value) ? String(meta[key].value) : '';
}

// extmetadata values are HTML fragments (Artist is typically a link). DOMParser builds an
// INERT document, so unlike innerHTML this can't run scripts or fire loaders on remote markup.
function stripHtml(html) {
    const doc = new DOMParser().parseFromString(String(html || ''), 'text/html');
    return (doc.body.textContent || '').replace(/\s+/g, ' ').trim();
}

// Accept public domain / CC0 (no obligations) and CC-BY / CC-BY-SA (credited under the
// photo). Everything else — NonCommercial, NoDerivatives, fair use, unrecognised — is
// dropped rather than guessed at.
function skylineLicenceOk(meta) {
    const s = (commonsMeta(meta, 'License') || commonsMeta(meta, 'LicenseShortName')).toLowerCase();
    if (!s) return false;
    if (/\bnc\b|noncommercial|\bnd\b|noderiv|fair use/.test(s)) return false;
    return /^(cc0|pd|public domain|cc[ -]by)/.test(s);
}

function commonsSearch(query) {
    const params = new URLSearchParams({
        action: 'query', format: 'json', origin: '*',
        generator: 'search', gsrsearch: query, gsrnamespace: '6', gsrlimit: '40',
        prop: 'imageinfo', iiprop: 'url|size|mime|extmetadata', iiurlwidth: '1280',
        iiextmetadatafilter: 'License|LicenseShortName|Artist'
    });
    return fetch(COMMONS_API + '?' + params).then(r => {
        if (!r.ok) throw new Error('Commons search ' + r.status);
        return r.json();
    });
}

// Turn a Commons search response into ranked, usable skyline photos.
function skylineCandidates(json, city) {
    const pages = (json && json.query && json.query.pages) || {};
    const key = normalizeName(city);
    return Object.keys(pages).map(id => {
        const page = pages[id];
        const ii = page.imageinfo && page.imageinfo[0];
        if (!ii) return null;
        if (!/^image\/(jpeg|png|webp)$/.test(ii.mime || '')) return null;  // no SVG/PDF/video
        if (!(ii.width >= 900 && ii.width > ii.height)) return null;       // a skyline is wide
        const title = String(page.title || '').replace(/^File:/, '').replace(/\.\w+$/, '');
        if (SKYLINE_REJECT_TITLE.test(title)) return null;
        if (!skylineLicenceOk(ii.extmetadata)) return null;
        return {
            url: ii.thumburl || ii.url,
            page: ii.descriptionurl,
            title: title,
            artist: stripHtml(commonsMeta(ii.extmetadata, 'Artist')) || 'Unknown photographer',
            licence: commonsMeta(ii.extmetadata, 'LicenseShortName') || commonsMeta(ii.extmetadata, 'License'),
            // Rank, don't reject: a title naming the city is a far safer bet than trusting
            // search relevance, but a good photo may still be titled "Manhattan at dusk".
            score: (normalizeName(title).includes(key) ? 2 : 0) + (SKYLINE_GOOD_TITLE.test(title) ? 1 : 0)
        };
    }).filter(Boolean).sort((a, b) => b.score - a.score);
}

// Search terms for a city. The state/country disambiguator (taken from the display label)
// is NOT optional: '"Toledo" skyline' returns Toledo, SPAIN above Toledo, Ohio, and
// '"St. Petersburg" skyline' can land in Russia — either would caption a photo with the
// wrong city and mark a right answer wrong. Adding the term costs ~5% of the usable hits
// and fixes that. A city can override the whole query via a `query` field in the data.
function skylineQuery(city) {
    const d = (gameState.currentDataObj || {})[city] || {};
    if (d.query) return d.query;
    const label = d.label || city;
    const comma = label.indexOf(',');
    const where = comma > -1 ? label.slice(comma + 1).trim() : '';
    return '"' + city + '" ' + (where ? where + ' ' : '') + 'skyline';
}

// Usable photos for a city, cached per session. A failed fetch is evicted so a network
// blip can't permanently blank a city.
function fetchSkylineCandidates(city) {
    if (skylineListCache[city]) return skylineListCache[city];
    const p = commonsSearch(skylineQuery(city)).then(j => skylineCandidates(j, city).slice(0, 6));
    p.catch(() => { delete skylineListCache[city]; });
    skylineListCache[city] = p;
    return p;
}

// Find a city Commons actually has a usable photo for. Whether one exists is only knowable
// after searching, so a miss retries with another city — and is remembered, so a barren city
// isn't re-queried every round. The pick is reserved (added to usedCountries) before the
// search returns, so a prefetch and a live pick can never land on the same city.
async function resolveSkylineTarget() {
    const data = gameState.currentDataObj || {};
    for (let attempt = 0; attempt < 8; attempt++) {
        const pool = Object.keys(data).filter(
            c => !gameState.usedCountries.has(c) && !skylineNoPhoto.has(c));
        if (!pool.length) return null;
        const city = pool[Math.floor(Math.random() * pool.length)];
        gameState.usedCountries.add(city);
        const list = await fetchSkylineCandidates(city).catch(() => []);
        if (list.length) return { city: city, photo: list[Math.floor(Math.random() * list.length)] };
        skylineNoPhoto.add(city);
    }
    return null;
}

// Resolve the NEXT round in the background while the player is still reading this one. A
// Commons search takes 0.5–6 s — far too long to spend on a spinner between questions.
function prefetchNextSkyline() {
    if (skylineNext || skylinePrefetching) return;
    skylinePrefetching = true;
    resolveSkylineTarget()
        .then(r => { skylineNext = r; })
        .catch(() => { })
        .then(() => { skylinePrefetching = false; });
}

function skylineLabel(name) {
    const d = (gameState.currentDataObj || {})[name];
    return (d && d.label) || name;
}

// Lower = better distractor. Same country dominates (Dallas vs Houston vs Austin), then
// same region; within a tier, closeness in population — so a megacity is never offered
// against a suburb. Population is compared on a log scale because the list spans 200k–30M.
function skylineDistractorScore(name, me, data) {
    const d = data[name] || {};
    const lg = p => Math.log10(Math.max(p || 1, 1));
    let s = 0;
    if (d.country && d.country === me.country) s -= 1000;
    else if (d.region && d.region === me.region) s -= 500;
    return s + Math.abs(lg(d.population) - lg(me.population)) * 100;
}

// 4 options as display labels: the answer plus its 3 most confusable neighbours.
function generateSkylineOptions(correct) {
    const data = gameState.currentDataObj || {};
    const me = data[correct] || {};
    const ranked = Object.keys(data).filter(n => n !== correct)
        .sort((a, b) => skylineDistractorScore(a, me, data) - skylineDistractorScore(b, me, data));
    // Draw from the closest handful rather than strictly the top 3, so replaying a city
    // doesn't always serve the same three wrong answers.
    const picks = shuffleArray(ranked.slice(0, 8)).slice(0, 3);
    return shuffleArray([correct].concat(picks)).map(skylineLabel);
}

function setSkylineStatus(text) {
    const el = document.getElementById('skyline-status');
    if (!el) return;
    el.textContent = text || '';
    el.style.display = text ? '' : 'none';
}

function showSkylinePhoto(photo) {
    const img = document.getElementById('skyline-image');
    document.getElementById('skyline-display').style.display = 'block';
    document.getElementById('skyline-credit').style.display = 'none';
    img.style.display = 'none';
    setSkylineStatus('Loading photo…');
    img.onload = () => { img.style.display = ''; setSkylineStatus(''); };
    img.onerror = () => setSkylineStatus('That photo failed to load — press Next for another city.');
    img.src = photo.url;
}

// Credit appears only once the round is decided. It has to wait: the Commons file title
// almost always names the city, so showing it up front would hand over the answer.
function revealSkylineCredit() {
    const credit = document.getElementById('skyline-credit');
    const photo = gameState.skylinePhoto;
    if (!credit || !photo) return;
    const link = document.createElement('a');
    link.href = photo.page;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = photo.title;
    credit.textContent = '';
    credit.append(link, document.createTextNode(
        ' · ' + photo.artist + ' · ' + photo.licence + ' · via Wikimedia Commons'));
    credit.style.display = '';
}

// Render a Skyline ID question: find a real photo of some large city's skyline, show it,
// and offer 4 city names. No map is involved at any point.
async function renderSkylineQuestion() {
    gameState.questionType = 'skyline-id';

    // This mode short-circuits the shared startNewQuestion body (which needs a map), so the
    // per-question resets it would have run have to happen here.
    document.getElementById('map-container').classList.add('hidden');
    document.getElementById('world-quiz-layout').classList.add('hidden');
    document.getElementById('question-container').classList.remove('hidden');
    clearMultipleChoice();
    gameState.answeredCorrectly = false;
    gameState.guessedThisQuestion = false;
    const nextBtn = document.getElementById('next-btn');
    nextBtn.disabled = true;
    nextBtn.style.display = 'inline-block';
    nextBtn.textContent = 'Next Question';
    const giveUpBtn = document.getElementById('give-up-btn');
    giveUpBtn.style.display = 'inline-block';
    giveUpBtn.textContent = 'Give Up';
    const feedback = document.getElementById('feedback');
    feedback.textContent = '';
    feedback.className = 'feedback';

    if (gameState.currentQuestion > gameState.totalQuestions) { endGame(); return; }

    // Drop the previous round's answer up front, so that if no photo can be found the error
    // state can't be given-up on and reveal a stale city/credit.
    gameState.targetCountry = null;
    gameState.skylinePhoto = null;

    const token = ++skylineToken;
    document.getElementById('question-text').textContent = 'Which city is this?';
    document.getElementById('skyline-display').style.display = 'block';
    document.getElementById('skyline-image').style.display = 'none';
    document.getElementById('skyline-credit').style.display = 'none';

    // Usually the previous round already resolved this one in the background.
    let picked = skylineNext;
    skylineNext = null;
    if (!picked) {
        setSkylineStatus('Finding a skyline…');
        picked = await resolveSkylineTarget();
        if (token !== skylineToken) return;   // a newer question superseded this one
    }

    if (!picked) {
        setSkylineStatus('Couldn’t reach Wikimedia Commons for a skyline photo. ' +
            'Check your connection, then press Next to try another city.');
        nextBtn.disabled = false;
        return;
    }

    gameState.targetCountry = picked.city;
    gameState.skylinePhoto = picked.photo;
    // resolveSkylineTarget already reserved this, but re-assert it: a pick prefetched during
    // a PREVIOUS game was reserved in a usedCountries that the new game then cleared, so
    // without this the carried-over city could come up a second time in the same game.
    gameState.usedCountries.add(picked.city);

    document.getElementById('question-text').innerHTML =
        'Which city is this? <span style="font-size:0.8em;color:#888;">Read the skyline.</span>';
    showSkylinePhoto(picked.photo);
    renderMultipleChoice(generateSkylineOptions(picked.city), skylineLabel(picked.city));
    prefetchNextSkyline();
}

// ==================== POPULATION ORDERING MODE ====================

// Render population ordering mode
function renderOrderingMode() {
    const modeConfig = QUIZ_MODES[gameState.mode];
    const criteria = modeConfig.orderingCriteria; // 'population'

    // Hide map-related elements
    document.getElementById('map-container').classList.add('hidden');
    document.getElementById('world-quiz-layout').classList.add('hidden');

    // Show question container
    document.getElementById('question-container').classList.remove('hidden');

    // Select 5 random countries with population data
    const countriesWithData = gameState.currentQuizList.filter(country => {
        const data = gameState.currentDataObj[country];
        return data && data[criteria];
    });

    // Randomly select 5 countries
    const shuffled = shuffleArray([...countriesWithData]);
    const selectedCountries = shuffled.slice(0, 5);

    // Store the correct order (by population, descending)
    const correctOrder = [...selectedCountries].sort((a, b) => {
        const popA = gameState.currentDataObj[a][criteria];
        const popB = gameState.currentDataObj[b][criteria];
        return popB - popA; // Descending order
    });

    gameState.correctOrder = correctOrder;
    gameState.currentCountries = selectedCountries;

    // Create question text
    document.getElementById('question-text').innerHTML = `
        <strong>Drag to order these countries by population</strong><br>
        <small>(Highest to Lowest)</small>
    `;

    // Create ordering container
    let orderingContainer = document.getElementById('ordering-container');
    if (!orderingContainer) {
        orderingContainer = document.createElement('div');
        orderingContainer.id = 'ordering-container';
        orderingContainer.className = 'ordering-container';
        document.getElementById('question-container').appendChild(orderingContainer);
    }

    // Clear container and drop any result-grid state from the previous round.
    orderingContainer.classList.remove('results-mode');
    orderingContainer.innerHTML = '';
    if (gameState._orderArrowResize) {
        window.removeEventListener('resize', gameState._orderArrowResize);
        gameState._orderArrowResize = null;
    }

    // Create draggable items with flag
    const items = selectedCountries.map(country => {
        const data = gameState.currentDataObj[country];
        const flagUrl = getFlagUrl(country);
        return {
            id: country,
            content: `
                <div class="country-bubble">
                    <img src="${flagUrl}" alt="${country}" class="bubble-flag">
                    <span class="bubble-name">${country}</span>
                </div>
            `,
            data: data
        };
    });

    // Initialize drag-to-reorder
    if (gameState.dragInstance) {
        gameState.dragInstance.items = items;
        gameState.dragInstance.render();
        gameState.dragInstance.attachEventListeners();
    } else {
        gameState.dragInstance = new DragToReorder(orderingContainer, items, {
            itemClass: 'draggable-item',
            dragClass: 'dragging',
            overClass: 'drag-over'
        });
    }

    // Update button states
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'none';

    // Create submit button
    let submitBtn = document.getElementById('submit-order-btn');
    if (!submitBtn) {
        submitBtn = document.createElement('button');
        submitBtn.id = 'submit-order-btn';
        submitBtn.className = 'btn';
        submitBtn.textContent = 'Submit Answer';
        submitBtn.onclick = checkOrderingAnswer;
        document.getElementById('controls').appendChild(submitBtn);
    }
    submitBtn.style.display = 'inline-block';
    submitBtn.disabled = false;
}

// Check ordering answer
function checkOrderingAnswer() {
    const userOrder = gameState.dragInstance.getCurrentOrder();
    const correctOrder = gameState.correctOrder;

    // Calculate score using pair-wise comparison
    const score = calculatePairwiseScore(userOrder, correctOrder);

    // Update game score (convert percentage to points out of 10)
    const points = Math.round(score / 10);
    gameState.score += points;
    document.getElementById('score').textContent = gameState.score; syncScoreDisplay();

    // Show feedback (the short score message only — the correct order is now shown in-place
    // as a grid via renderOrderingResult, not repeated as a list here).
    const feedback = document.getElementById('feedback');
    if (score === 100) {
        feedback.innerHTML = `<div class="feedback correct">
            Perfect! 🎉 You got 100% of pairs in the correct order! (+${points} points)
        </div>`;
    } else if (score >= 70) {
        feedback.innerHTML = `<div class="feedback partial">
            Good! You got ${score}% of pairs in the correct order. (+${points} points)
        </div>`;
    } else {
        feedback.innerHTML = `<div class="feedback incorrect">
            You got ${score}% of pairs in the correct order. (+${points} points)
        </div>`;
    }

    // Replace the draggable bubbles with the result grid: the player's order as a flag-only
    // column on the left, the correct order (flag · name · population) filling the rest, and
    // arrows mapping each guess to where that country actually belongs.
    renderOrderingResult(userOrder, correctOrder);

    // Hide the submit button — the round is decided.
    const submitBtn = document.getElementById('submit-order-btn');
    if (submitBtn) { submitBtn.disabled = true; submitBtn.style.display = 'none'; }

    // MANUAL advance, deliberately: the result grid is the whole payoff of this mode — five
    // guesses, five true ranks and the arrows between them — and a timed advance pulls it
    // away mid-read. Every other distance-scored mode still auto-advances; this one waits.
    // (Advancing goes through the shared goToNextQuestion(), which increments
    // currentQuestion — this used to ALSO increment it here directly, so every round
    // advanced the counter by 2 and the game ended after half the rounds.)
    clearAutoAdvance();
    const nextBtn = document.getElementById('next-btn');
    nextBtn.style.display = 'inline-block';
    nextBtn.disabled = false;
    nextBtn.textContent = gameState.currentQuestion >= gameState.totalQuestions
        ? 'See Results' : 'Next Round';
}

// Replace the draggable bubbles with a result grid: the player's submitted order as a
// flag-only column on the left, the correct order (flag · name · value) filling the
// rest, and curved arrows linking each guess to the country's true position.
//
// `formatValue` is the one thing that differs between the ordering rounds — population for
// population-order, great-circle distance for the sandbox's Near to Far. Everything else here
// (and every .order-* rule in the stylesheet) keys only on country names and DOM geometry, so
// a caller-supplied formatter is the whole generalisation.
function renderOrderingResult(userOrder, correctOrder, formatValue) {
    const container = document.getElementById('ordering-container');
    if (!container) return;
    const dataObj = gameState.currentDataObj;
    const fmt = formatValue || (c => {
        const d = dataObj && dataObj[c];
        return d && d.population != null ? d.population.toLocaleString() : '';
    });

    const correctIndexOf = {};
    correctOrder.forEach((c, j) => { correctIndexOf[c] = j; });

    const guessRows = userOrder.map(c => `
        <div class="order-guess" data-country="${c}">
            <img src="${getFlagUrl(c)}" alt="${c}" class="order-flag">
        </div>`).join('');

    const correctRows = correctOrder.map((c, j) => `
        <div class="order-correct-row" data-country="${c}">
            <span class="oc-rank">${j + 1}</span>
            <img src="${getFlagUrl(c)}" alt="${c}" class="order-flag">
            <span class="oc-name">${displayLabelForName(c)}</span>
            <span class="oc-pop">${fmt(c)}</span>
        </div>`).join('');

    container.classList.add('results-mode');
    container.innerHTML = `
        <div class="order-result">
            <div class="order-guesses" aria-label="Your order">${guessRows}</div>
            <div class="order-correct" aria-label="Correct order">${correctRows}</div>
            <svg class="order-arrows" aria-hidden="true">
                <defs>
                    <marker id="order-arrowhead-correct" viewBox="0 0 10 10" refX="8" refY="5"
                            markerWidth="6" markerHeight="6" orient="auto-start-reverse">
                        <path class="ah-correct" d="M0,0 L10,5 L0,10 z"></path>
                    </marker>
                    <marker id="order-arrowhead-moved" viewBox="0 0 10 10" refX="8" refY="5"
                            markerWidth="6" markerHeight="6" orient="auto-start-reverse">
                        <path class="ah-moved" d="M0,0 L10,5 L0,10 z"></path>
                    </marker>
                </defs>
            </svg>
        </div>`;

    // Draw arrows from measured DOM positions. Row heights are fixed by CSS (independent of
    // flag-image load), so getBoundingClientRect is accurate immediately — draw synchronously
    // rather than relying on requestAnimationFrame (which is throttled when the tab isn't
    // visible). A follow-up rAF re-draw absorbs any late layout shift (e.g. web-font swap).
    const redraw = () => drawOrderArrows(container, correctIndexOf);
    redraw();
    requestAnimationFrame(redraw);
    if (gameState._orderArrowResize) window.removeEventListener('resize', gameState._orderArrowResize);
    gameState._orderArrowResize = () => {
        if (!container.querySelector('.order-arrows')) {
            window.removeEventListener('resize', gameState._orderArrowResize);
            gameState._orderArrowResize = null;
            return;
        }
        drawOrderArrows(container, correctIndexOf);
    };
    window.addEventListener('resize', gameState._orderArrowResize);
}

// Draw one curved arrow per guess, from the right edge of the guess flag to the left edge
// of the matching correct-order row. Correctly-placed guesses are green, moved ones muted.
function drawOrderArrows(container, correctIndexOf) {
    const result = container.querySelector('.order-result');
    const svg = container.querySelector('.order-arrows');
    if (!result || !svg) return;

    const rect = result.getBoundingClientRect();
    svg.setAttribute('viewBox', `0 0 ${rect.width} ${rect.height}`);
    svg.setAttribute('width', rect.width);
    svg.setAttribute('height', rect.height);
    svg.querySelectorAll('path.order-connector').forEach(n => n.remove());

    const rowByCountry = {};
    result.querySelectorAll('.order-correct-row').forEach(r => { rowByCountry[r.dataset.country] = r; });

    result.querySelectorAll('.order-guess').forEach((g, i) => {
        const country = g.dataset.country;
        const target = rowByCountry[country];
        if (!target) return;
        const gr = g.getBoundingClientRect(), tr = target.getBoundingClientRect();
        const x1 = gr.right - rect.left, y1 = gr.top + gr.height / 2 - rect.top;
        const x2 = tr.left - rect.left, y2 = tr.top + tr.height / 2 - rect.top;
        const dx = Math.max(24, (x2 - x1) * 0.5);   // horizontal control-point pull for the curve

        const correct = correctIndexOf[country] === i;
        const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
        path.setAttribute('d', `M ${x1} ${y1} C ${x1 + dx} ${y1} ${x2 - dx} ${y2} ${x2 - 2} ${y2}`);
        path.setAttribute('class', 'order-connector ' + (correct ? 'is-correct' : 'is-moved'));
        path.setAttribute('marker-end', correct ? 'url(#order-arrowhead-correct)' : 'url(#order-arrowhead-moved)');
        svg.appendChild(path);
    });
}


// Centroid [lon, lat] for a quiz item: the polygon centroid when it exists,
// otherwise the island marker's capital coordinates (capitalCoords is [lat, lon]).
// Memoised against the feature list itself, so anything that replaces that list (a detail
// change, Who's Missing's surgery) invalidates it for free. At 10m a centroid is a walk over
// tens of thousands of vertices, and the sandbox draw loops ask for hundreds of them per round.
let sbCentroidCache = { src: null, map: new Map() };
function getCountryCentroid(countryName) {
    if (sbCentroidCache.src !== gameState.countries) {
        sbCentroidCache = { src: gameState.countries, map: new Map() };
    }
    if (sbCentroidCache.map.has(countryName)) return sbCentroidCache.map.get(countryName);
    const out = computeCountryCentroid(countryName);
    sbCentroidCache.map.set(countryName, out);
    return out;
}

function computeCountryCentroid(countryName) {
    const country = gameState.countries && gameState.countries.find(c => c.properties.name === countryName);
    if (country) return d3.geoCentroid(country);
    const data = (gameState.currentDataObj || {})[countryName];
    if (data && Array.isArray(data.capitalCoords)) return [data.capitalCoords[1], data.capitalCoords[0]];
    return null;
}

// d3.interpolate for a projection.rotate() array that always takes the SHORT way around
// each axis, so spinning to a country never crosses the whole globe when the target is just
// across the ±180° seam. Each target angle is nudged by ±360° so its delta lands in [-180,180].
function interpolateRotateShortest(from, to) {
    const adjusted = to.map((v, i) => {
        let d = (v - from[i]) % 360;
        if (d > 180) d -= 360;
        if (d < -180) d += 360;
        return from[i] + d;
    });
    return d3.interpolate(from, adjusted);
}

// Rotate globe to show target country
function rotateToCountry(countryName) {
    if (!isGlobeView()) return; // No rotation in flat (Mercator) view
    const centroid = getCountryCentroid(countryName);
    if (!centroid) return;

    d3.transition()
        .duration(1000)
        .tween('rotate', () => {
            const r = interpolateRotateShortest(projection.rotate(), [-centroid[0], -centroid[1]]);
            return t => {
                projection.rotate(r(t));
                countriesGroup.selectAll('path').attr('d', path);
                updateIslandMarkers();
            };
        })
        .on('end', () => {
            r_unconstrained = projection.rotate().slice();
        });
}

// Zoom and rotate to show target country (for quiz feedback)
function zoomAndRotateToCountry(countryName, duration = 800) {
    if (!isGlobeView()) return Promise.resolve(); // No rotation in flat (Mercator) view
    const centroid = getCountryCentroid(countryName);
    if (!centroid) return Promise.resolve();

    const modeConfig = QUIZ_MODES[gameState.mode];

    return new Promise(resolve => {
        d3.transition()
            .duration(duration)
            .tween('zoom-rotate', () => {
                const r = interpolateRotateShortest(projection.rotate(), [-centroid[0], -centroid[1]]);
                const s = d3.interpolate(projection.scale(), 400); // Zoom in a bit
                return t => {
                    projection.rotate(r(t));
                    projection.scale(s(t));
                    countriesGroup.selectAll('path').attr('d', path);
                    updateIslandMarkers();

                    // Update ocean circle for globe view
                    if (modeConfig.useGlobe) {
                        g.select('circle').attr('r', s(t));
                    }
                };
            })
            .on('end', () => {
                r_unconstrained = projection.rotate().slice();
                resolve();
            });
    });
}

// Enhanced drag functions for interactive rotations (versor-based)
let v0, r0, q0;
let r_unconstrained = null;  // Track unconstrained rotation for quaternion continuity
let gammaLocked = true;  // When true, gamma (tilt/roll) is locked to 0 (north-up). Default on so the globe stays upright.

function dragStart(event) {
    // Don't allow dragging if scrolling is locked
    if (gameState.scrollLocked) return;

    // Hand the globe over: any auto-spin still running (Odd One Out framing its four
    // candidates, say) would otherwise keep writing rotations underneath the drag.
    d3.select(document.documentElement).interrupt('oddspin');

    const p = d3.pointer(event, this);
    r0 = projection.rotate();
    v0 = versor.cartesian(projection.invert(p));
    q0 = versor(r_unconstrained || r0);
}

function dragging(event) {
    // Don't allow dragging if scrolling is locked
    if (gameState.scrollLocked) return;

    const p = d3.pointer(event, this);
    // Temporarily set rotation to r0 to compute inverse (for sticky rotation)
    projection.rotate(r0);
    const v1 = versor.cartesian(projection.invert(p));
    // Compute new rotation
    const q1 = versor.multiply(q0, versor.delta(v0, v1));
    const r1 = versor.rotation(q1);

    if (gammaLocked) {
        // North-up mode: keep gamma at 0 and clamp latitude so the globe can't flip.
        // Store the constrained rotation so the next drag stays north-up (no gamma drift).
        const constrainedLat = Math.max(-85, Math.min(85, r1[1]));
        const locked = [r1[0], constrainedLat, 0];
        projection.rotate(locked);
        r_unconstrained = locked;
    } else {
        // Free trackball: apply the full quaternion so the grabbed point follows
        // the cursor exactly and the globe tilts smoothly over the poles.
        projection.rotate(r1);
        r_unconstrained = r1;
    }
    countriesGroup.selectAll('path').attr('d', path);
    updateIslandMarkers();
}

function dragEnd() {
    // Drag ended, r_unconstrained is preserved for next drag
}

// Versor helper functions for proper spherical rotation
// Based on Fil's versor package (canonical D3 implementation)
function versor(e) {
    var l = e[0] / 2 * Math.PI / 180, sl = Math.sin(l), cl = Math.cos(l);
    var p = e[1] / 2 * Math.PI / 180, sp = Math.sin(p), cp = Math.cos(p);
    var g = e[2] / 2 * Math.PI / 180, sg = Math.sin(g), cg = Math.cos(g);
    return [
        cl * cp * cg + sl * sp * sg,
        sl * cp * cg - cl * sp * sg,
        cl * sp * cg + sl * cp * sg,
        cl * cp * sg - sl * sp * cg
    ];
}

versor.cartesian = function(e) {
    const lambda = e[0] * Math.PI / 180;
    const phi = e[1] * Math.PI / 180;
    const cosPhi = Math.cos(phi);
    return [cosPhi * Math.cos(lambda), cosPhi * Math.sin(lambda), Math.sin(phi)];
};

versor.dot = function(a, b) {
    let sum = 0;
    for (let i = 0; i < 3; i++) sum += a[i] * b[i];
    return sum;
};

versor.cross = function(a, b) {
    return [
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0]
    ];
};

versor.delta = function(v0, v1) {
    var w = versor.cross(v0, v1), l = Math.sqrt(versor.dot(w, w));
    if (!l) return [1, 0, 0, 0];
    // A quaternion rotating by angle θ has components [cos(θ/2), axis·sin(θ/2)].
    // Use the half-angle so the grabbed point tracks the cursor 1:1 (canonical
    // Jason Davies / Fil versor dragging). The previous full-angle form rotated
    // by 2θ, which made the globe spin twice as fast and lurch over the poles.
    var t = Math.acos(Math.max(-1, Math.min(1, versor.dot(v0, v1)))) / 2;
    var s = Math.sin(t) / l;
    return [Math.cos(t), w[2] * s, -w[1] * s, w[0] * s];
};

versor.multiply = function(a, b) {
    return [
        a[0] * b[0] - a[1] * b[1] - a[2] * b[2] - a[3] * b[3],
        a[0] * b[1] + a[1] * b[0] + a[2] * b[3] - a[3] * b[2],
        a[0] * b[2] - a[1] * b[3] + a[2] * b[0] + a[3] * b[1],
        a[0] * b[3] + a[1] * b[2] - a[2] * b[1] + a[3] * b[0]
    ];
};

versor.rotation = function(q) {
    return [
        Math.atan2(2 * (q[0] * q[1] + q[2] * q[3]), 1 - 2 * (q[1] * q[1] + q[2] * q[2])) * 180 / Math.PI,
        Math.asin(Math.max(-1, Math.min(1, 2 * (q[0] * q[2] - q[3] * q[1])))) * 180 / Math.PI,
        Math.atan2(2 * (q[0] * q[3] + q[1] * q[2]), 1 - 2 * (q[2] * q[2] + q[3] * q[3])) * 180 / Math.PI
    ];
};

// End game
function endGame() {
    // Stop globe spinning
    stopGlobeSpin();
    gameState.ended = true;

    const modeConfig = QUIZ_MODES[gameState.mode];

    // Odd One Out: the traits were withheld all game, so the payoff is seeing all ten at once.
    if (modeConfig.oddOneOutMode) {
        document.getElementById('question-text').innerHTML =
            `Game Over — <strong>${gameState.score}/${gameState.totalQuestions}</strong>`;
        clearMultipleChoice();
        const feedback = document.getElementById('feedback');
        feedback.innerHTML = oddOneOutSummaryHtml();
        feedback.className = 'feedback';
        document.getElementById('next-btn').disabled = true;
        document.getElementById('give-up-btn').style.display = 'none';
        appendChallengeButton(feedback);
        return;
    }

    // Sandbox quizzes score out of 10 per round; the pinpoint ones also carry a mean error.
    // A plain fact round is worth 1, but a fact round with a speed bonus tops up to 10.
    if (modeConfig.sbQuizMode) {
        const spec = SB_QUIZZES[gameState.mode];
        const perRound = (modeConfig.sbEngine === 'fact' && !(spec && spec.speedBonus)) ? 1 : 10;
        const max = gameState.totalQuestions * perRound;
        document.getElementById('question-text').innerHTML =
            `Game Over — <strong>${gameState.score}/${max}</strong>`;
        clearMultipleChoice();
        const feedback = document.getElementById('feedback');
        const pct = max ? Math.round(gameState.score / max * 100) : 0;
        let line = `${pct}% — ${pct >= 80 ? 'excellent' : pct >= 60 ? 'solid' : pct >= 40 ? 'not bad' : 'room to grow'}.`;
        if (modeConfig.sbEngine === 'pinpoint') {
            const avg = Math.round((gameState.totalDistanceKm || 0) / gameState.totalQuestions);
            line += ` Average miss: <strong>${avg.toLocaleString()} km</strong>.`;
        }
        feedback.innerHTML = line;
        feedback.className = 'feedback ' + (pct >= 60 ? 'correct' : 'incorrect');
        document.getElementById('next-btn').disabled = true;
        document.getElementById('give-up-btn').style.display = 'none';
        appendChallengeButton(feedback);
        return;
    }

    // Distance-scored modes (Find the Capital, Where Is My Spaceship?, Place the Countries).
    if (modeConfig.findCapitalMode || modeConfig.spaceshipMode) {
        document.getElementById('question-text').innerHTML = 'Game Over!';
        clearMultipleChoice();
        const unit = modeConfig.spaceshipMode ? 'locations' : 'capitals';
        const total = Math.round(gameState.totalDistanceKm || 0);
        const avg = Math.round((gameState.totalDistanceKm || 0) / gameState.totalQuestions);
        const feedback = document.getElementById('feedback');
        let biasLine = '';
        if (modeConfig.findCapitalMode) {
            drawCapitalSummaryMap();
            const bias = capitalBias(gameState.capitalLog);
            if (bias) {
                const parts = [];
                if (Math.abs(bias.ew) > 120) parts.push(`<strong>${Math.round(Math.abs(bias.ew)).toLocaleString()} km ${bias.ew < 0 ? 'west' : 'east'}</strong>`);
                if (Math.abs(bias.ns) > 120) parts.push(`<strong>${Math.round(Math.abs(bias.ns)).toLocaleString()} km ${bias.ns < 0 ? 'south' : 'north'}</strong>`);
                biasLine = parts.length
                    ? `<br><span style="font-size:.9em">On average you guessed ${parts.join(' and ')} of the truth.</span>`
                    : `<br><span style="font-size:.9em">No consistent direction to your misses — they scatter evenly around the answers.</span>`;
            }
        }
        feedback.innerHTML = `Total distance: <strong>${total.toLocaleString()} km</strong> over ${gameState.totalQuestions} ${unit}<br>` +
            `Average: <strong>${avg.toLocaleString()} km</strong> per guess — ${capitalRating(avg)}` + biasLine;
        feedback.className = 'feedback ' + (avg < 1000 ? 'correct' : 'incorrect');
        document.getElementById('next-btn').disabled = true;
        document.getElementById('give-up-btn').style.display = 'none';
        appendChallengeButton(feedback);
        return;
    }

    if (modeConfig.flagPlaceMode) {
        document.getElementById('question-text').innerHTML = 'Flags complete!';
        clearMultipleChoice();
        const total = gameState.flagTotal || 0;
        const misses = gameState.flagMisses || 0;
        const feedback = document.getElementById('feedback');
        feedback.innerHTML = `You matched <strong>${gameState.score}/${total}</strong> flags` +
            ` with <strong>${misses}</strong> wrong drop${misses === 1 ? '' : 's'}.`;
        feedback.className = 'feedback ' + (gameState.score === total ? 'correct' : 'incorrect');
        document.getElementById('next-btn').disabled = true;
        document.getElementById('give-up-btn').style.display = 'none';
        appendChallengeButton(feedback);
        return;
    }

    // The puzzle can't be "failed" — every piece ends up placed — so it reports how many the
    // player got home themselves, against the clock and the misdrop count.
    if (modeConfig.statePuzzleMode) {
        stopPuzzleTimer();
        document.getElementById('question-text').innerHTML = 'Puzzle complete!';
        clearMultipleChoice();
        const total = gameState.puzzleTotal || 0;
        const secs = gameState.puzzleElapsed || 0;
        const misses = gameState.puzzleMisses || 0;
        const feedback = document.getElementById('feedback');

        // Blind mode is distance-and-time scored, not pieces-placed, so it reports its own
        // numbers: points out of the theoretical max, plus the average miss.
        if (gameState.puzzleBlind) {
            const done = gameState.puzzlePlaced ? gameState.puzzlePlaced.size : 0;
            const maxPts = total * PUZZLE_POINTS_PER_STATE;
            const pts = Math.round(gameState.puzzlePoints || 0);
            const avg = puzzleAvgErrorKm();
            feedback.innerHTML =
                `<strong>${pts}/${maxPts}</strong> points over ${done}/${total} ${modeConfig.itemLabelPlural || 'pieces'}` +
                (avg == null ? '' : ` &nbsp;|&nbsp; average error <strong>${Math.round(avg).toLocaleString()} km</strong>`) +
                ` &nbsp;|&nbsp; <strong>${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}</strong>` +
                `<br>${puzzleBlindRating(avg, done, total)}`;
            feedback.className = 'feedback ' + (avg != null && avg < 400 && done === total ? 'correct' : 'incorrect');
            document.getElementById('next-btn').disabled = true;
            document.getElementById('give-up-btn').style.display = 'none';
            appendChallengeButton(feedback);
            return;
        }
        feedback.innerHTML =
            `You placed <strong>${gameState.score}/${total}</strong> ${modeConfig.itemLabelPlural || 'pieces'} in ` +
            `<strong>${Math.floor(secs / 60)}:${String(secs % 60).padStart(2, '0')}</strong> ` +
            `with <strong>${misses}</strong> misdrop${misses === 1 ? '' : 's'} — ` +
            puzzleRating(secs, misses, total, gameState.score);
        feedback.className = 'feedback ' + (gameState.score === total && misses <= total * 0.5 ? 'correct' : 'incorrect');
        document.getElementById('next-btn').disabled = true;
        document.getElementById('give-up-btn').style.display = 'none';
        appendChallengeButton(feedback);
        return;
    }

    const maxSub = maxSubForMode(modeConfig);
    const maxScore = gameState.totalQuestions * maxSub;
    const percentage = Math.round((gameState.score / maxScore) * 100);

    document.getElementById('question-text').innerHTML = 'Game Over!';
    clearMultipleChoice();

    const feedback = document.getElementById('feedback');
    feedback.textContent = `You scored ${gameState.score}/${maxScore} (${percentage}%)`;
    feedback.className = percentage >= 70 ? 'feedback correct' : 'feedback incorrect';

    document.getElementById('next-btn').disabled = true;
    appendChallengeButton(feedback);
}

// Add a "Challenge a friend" button under the final-score feedback: copies a link that
// carries this mode + score so the recipient sees a beat-my-score banner.
function appendChallengeButton(feedback) {
    if (!feedback) return;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'btn challenge-share-btn';
    btn.textContent = '🏆 Challenge a friend';
    btn.addEventListener('click', shareCurrentGame);
    feedback.appendChild(document.createElement('br'));
    feedback.appendChild(btn);
}

// Restart game
function restartGame() {
    const currentMode = gameState.mode;
    const currentDataObj = gameState.currentDataObj;
    const currentQuizList = gameState.currentQuizList;
    const countries = gameState.countries;
    const prevTotal = gameState.totalQuestions;

    gameState = {
        score: 0,
        currentQuestion: 1,
        totalQuestions: prevTotal,
        targetCountry: null,
        countries: countries, // Keep loaded map data
        answeredCorrectly: false,
        usedCountries: new Set(),
        questionType: null,
        currentAnswer: null,
        multipleChoiceOptions: [],
        subQuestionIndex: 0,
        maxSubQuestions: 3,
        mode: currentMode,
        currentDataObj: currentDataObj,
        currentQuizList: currentQuizList
    };

    document.getElementById('score').textContent = '0'; syncScoreDisplay();
    document.getElementById('current-question').textContent = '1';

    startNewQuestion();
}

// Go back to home/mode selector
function goHome() {
    d3.select('#globe').selectAll('*').remove();
    d3.select('#globe-world').selectAll('*').remove();

    // Clean up any in-progress mode state
    closeCountryPopup();
    stopNameAllTimer();
    removePuzzleTray();
    removeFlagTray();
    removeSandboxPanel();
    removeSunMoonPanel();
    removeSunPathMode();
    removeSpaceshipInset();
    disposeOrbital();
    document.body.classList.remove('spaceship-active');
    document.body.classList.remove('state-puzzle-active');
    document.body.classList.remove('sb-tall-active');
    document.body.classList.remove('sb-wide-panel');
    document.querySelector('.container').classList.remove('globe-side-layout');
    document.querySelector('.container').classList.remove('explore-overlay-layout');
    document.querySelector('.container').classList.remove('state-puzzle-layout');
    document.querySelector('.container').classList.remove('sb-full-map');

    // Tear down the Places panel and return to a clean, mode-less URL.
    const placesPanel = document.getElementById('places-panel');
    if (placesPanel) placesPanel.remove();
    history.replaceState(null, '', location.pathname);

    document.getElementById('top-bar').style.display = 'none';
    document.getElementById('landing-header').style.display = '';

    document.getElementById('mode-selector').classList.remove('hidden');
    document.getElementById('states-selector').classList.add('hidden');
    document.getElementById('game-info').classList.add('hidden');
    document.getElementById('question-container').classList.add('hidden');
    document.getElementById('controls').classList.add('hidden');
    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('map-container').classList.add('hidden');
    document.getElementById('world-quiz-layout').classList.add('hidden');
    document.getElementById('world-quiz-question-bar').classList.add('hidden');

    // Always return to the top-level menu (not a leftover sub-selector) and scroll up.
    resetModeSelector();
    window.scrollTo(0, 0);
    document.getElementById('mode-selector').scrollTop = 0;
}

// Event listeners
function setupEventListeners() {
    // Mode selection from main mode selector
    document.querySelectorAll('#mode-selector .mode-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const mode = e.currentTarget.dataset.mode;
            if (mode === 'find') {
                showFindModeSelector();
            } else if (mode === 'identify') {
                showIdentifyModeSelector();
            } else if (mode === 'name-all') {
                showNameAllModeSelector();
            } else if (mode === 'places') {
                showPlacesModeSelector();
            } else if (mode === 'state-puzzle') {
                showStatePuzzleSelector();
            } else if (mode === 'shapes' || mode === 'country-shape-id') {
                showShapeIdSelector();
            } else if (mode === 'explore') {
                showExploreSelector();
            } else if (mode === 'capitals') {
                showCapitalsSelector();
            } else if (mode === 'flags') {
                showFlagsSelector();
            } else if (mode === 'spaceship') {
                showSpaceshipSelector();
            } else if (mode === 'sandbox') {
                showSandboxSelector();
            } else {
                startGameWithMode(mode);
            }
        });
    });

    // States sub-mode selection
    document.querySelectorAll('#states-selector .mode-btn').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const mode = e.currentTarget.dataset.mode;
            startGameWithMode(mode);
        });
    });

    // Back button in states selector
    document.getElementById('back-to-modes-btn').addEventListener('click', () => {
        document.getElementById('states-selector').classList.add('hidden');
        document.getElementById('mode-selector').classList.remove('hidden');
    });

    // Home link in header — both the in-game top-bar title and the big landing-page
    // title/logo always take the user back to the mode selector.
    const homeLink = document.getElementById('home-link');
    if (homeLink) {
        homeLink.addEventListener('click', goHome);
    } else {
        console.error('home-link element not found');
    }
    const landingHeader = document.getElementById('landing-header');
    if (landingHeader) landingHeader.addEventListener('click', goHome);

    // All/Random-10 scope toggle (Find + Identify selector screens). Delegated on the
    // persistent #mode-selector container since showFindModeSelector/showIdentifyModeSelector
    // rewrite its innerHTML wholesale every time they're opened.
    const modeSelectorEl = document.getElementById('mode-selector');
    if (modeSelectorEl) {
        modeSelectorEl.addEventListener('click', (e) => {
            const btn = e.target.closest('.scope-btn');
            if (!btn) return;
            const group = btn.closest('.scope-toggle');
            const isAll = btn.dataset.scope === 'all';
            if (group.dataset.for === 'find') findQuizScopeAll = isAll;
            else if (group.dataset.for === 'identify') identifyQuizScopeAll = isAll;
            group.querySelectorAll('.scope-btn').forEach(b => b.classList.toggle('active', b === btn));
        });
    }

    // Helper to switch modes from the top bar
    function switchToMode(mode) {
        d3.select('#globe').selectAll('*').remove();
        d3.select('#globe-world').selectAll('*').remove();
        document.getElementById('game-info').classList.add('hidden');
        document.getElementById('question-container').classList.add('hidden');
        document.getElementById('controls').classList.add('hidden');
        document.getElementById('multiple-choice-container').classList.add('hidden');
        document.getElementById('world-quiz-layout').classList.add('hidden');
        document.getElementById('world-quiz-question-bar').classList.add('hidden');
        startGameWithMode(mode);
    }

    // Top bar dropdown toggles
    function closeAllDropdowns() {
        document.querySelectorAll('.icon-dropdown').forEach(d => d.classList.remove('open'));
    }

    document.getElementById('find-mode-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        const dd = document.getElementById('find-dropdown');
        const wasOpen = dd.classList.contains('open');
        closeAllDropdowns();
        if (!wasOpen) dd.classList.add('open');
    });

    document.getElementById('identify-mode-btn').addEventListener('click', (e) => {
        e.stopPropagation();
        const dd = document.getElementById('identify-dropdown');
        const wasOpen = dd.classList.contains('open');
        closeAllDropdowns();
        if (!wasOpen) dd.classList.add('open');
    });

    document.addEventListener('click', () => closeAllDropdowns());

    // Find dropdown items
    document.querySelectorAll('#find-dropdown .dropdown-item').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            closeAllDropdowns();
            switchToMode(e.currentTarget.dataset.mode);
        });
    });

    // Identify dropdown items
    document.querySelectorAll('#identify-dropdown .dropdown-item').forEach(btn => {
        btn.addEventListener('click', (e) => {
            e.stopPropagation();
            closeAllDropdowns();
            const region = e.currentTarget.dataset.identifyRegion;
            d3.select('#globe').selectAll('*').remove();
            d3.select('#globe-world').selectAll('*').remove();
            startIdentifyMode(region);
        });
    });

    // Direct mode icon buttons (name-all, population-order, mystery-flag, capitals-race)
    document.querySelectorAll('.top-bar-modes > .mode-icon-btn[data-mode]').forEach(btn => {
        btn.addEventListener('click', (e) => {
            const mode = e.currentTarget.dataset.mode;
            // Places-been and the States Puzzle need a choice made first (region /
            // difficulty), so open their selectors rather than starting a mode directly.
            if (mode === 'places') { showPlacesModeSelector(); return; }
            if (mode === 'state-puzzle') { showStatePuzzleSelector(); return; }
            if (mode === 'shapes' || mode === 'country-shape-id') { showShapeIdSelector(); return; }
            if (mode === 'explore') { showExploreSelector(); return; }
            if (mode === 'capitals') { showCapitalsSelector(); return; }
            if (mode === 'flags') { showFlagsSelector(); return; }
            if (mode === 'spaceship') { showSpaceshipSelector(); return; }
            if (mode === 'sandbox') { showSandboxSelector(); return; }
            if (mode) switchToMode(mode);
        });
    });

    // Next button
    document.getElementById('next-btn').addEventListener('click', () => {
        const mc = QUIZ_MODES[gameState.mode];
        // In Find-the-Capital, this button submits the guess before advancing.
        if (mc && mc.findCapitalMode && !gameState.capitalSubmitted) {
            submitCapitalGuess();
            return;
        }
        if (mc && mc.spaceshipMode && !gameState.capitalSubmitted) {
            submitSpaceshipGuess();
            return;
        }
        // Sandbox pinpoint/order: the first press scores the round, the second advances.
        if (mc && mc.sbQuizMode && !gameState.sbAnswered) {
            if (mc.sbEngine === 'pinpoint') { sbSubmitPinpoint(); return; }
            if (mc.sbEngine === 'order') { sbSubmitOrder(); return; }
            if (mc.sbEngine === 'multi') { sbSubmitMulti(); return; }
            if (mc.sbEngine === 'estimate') { sbSubmitEstimate(); return; }
            if (mc.sbEngine === 'picker') { sbSubmitPicker(); return; }
            if (mc.sbEngine === 'connect') { sbSubmitConnect(); return; }
        }
        // Draw the Border: the first press scores the traced loop and reveals the real one.
        if (mc && mc.drawBorderMode && drawBorderState && !drawBorderState.done) {
            revealDrawnBorder();
            return;
        }
        // Move to next item (also cancels any pending auto-advance)
        goToNextQuestion();
    });

    // Give up button
    document.getElementById('give-up-btn').addEventListener('click', giveUp);

    // Restart button
    document.getElementById('restart-btn').addEventListener('click', restartGame);

    // Gamma lock toggle
    document.getElementById('gamma-lock-toggle').addEventListener('click', function() {
        gammaLocked = !gammaLocked;
        this.textContent = gammaLocked ? 'Tilt: Locked' : 'Tilt: Free';
        if (gammaLocked) {
            const r = projection.rotate();
            projection.rotate([r[0], r[1], 0]);
            r_unconstrained = [r[0], r[1], 0];
            countriesGroup.selectAll('path').attr('d', path);
            updateIslandMarkers();
        }
    });

    // Projection toggle (globe <-> flat Mercator)
    const projToggleBtn = document.getElementById('projection-toggle');
    if (projToggleBtn) projToggleBtn.addEventListener('click', toggleFlatGlobe);

    // Level-of-detail toggle (cycles low → medium → high) for world maps
    const detailBtn = document.getElementById('detail-toggle');
    if (detailBtn) detailBtn.addEventListener('click', function () {
        mapDetail = DETAIL_ORDER[(DETAIL_ORDER.indexOf(mapDetail) + 1) % DETAIL_ORDER.length];
        this.textContent = 'Detail: ' + mapDetail.charAt(0).toUpperCase() + mapDetail.slice(1);
        reloadWorldDetail();
    });

    // Orbit-height slider: re-aims the orbital camera (altitude → distance + default tilt).
    const orbitHeightSlider = document.getElementById('tune-orbit-height');
    if (orbitHeightSlider) {
        const label = document.getElementById('tune-orbit-height-val');
        orbitHeightSlider.addEventListener('input', function () {
            orbitAltitudeKm = +this.value;
            if (label) label.textContent = orbitAltitudeKm.toLocaleString() + ' km';
            if (orbCam) { orbCam.tilt = defaultOrbitTilt(); orbitalRender(); }
        });
    }

    // "500 m tiles" toggle: fetch NASA's full-res Blue Marble tiles live and stitch the visible
    // cap (not bundled with the app). Off = the lighter single-globe crop / local tiles.
    const hires500 = document.getElementById('tune-hires-500m');
    if (hires500) {
        hires500.addEventListener('change', function () {
            orbitalUse500m = this.checked;
            if (orbCam) orbitalRefreshCap([orbCam.lon, orbCam.lat]);
        });
    }

    // Atmosphere gradient: independent space/earth spread sliders, the linear/tangent
    // earth-side toggle, and the 5-stop editor.
    const atmoSpreadSpace = document.getElementById('tune-atmo-spread-space');
    if (atmoSpreadSpace) {
        const label = document.getElementById('tune-atmo-spread-space-val');
        atmoSpreadSpace.addEventListener('input', function () {
            atmoSpreadSpaceKm = +this.value;
            if (label) label.textContent = atmoSpreadSpaceKm + ' km';
            applyAtmoUniforms();
            orbitalRender();
        });
    }
    const atmoSpreadEarth = document.getElementById('tune-atmo-spread-earth');
    if (atmoSpreadEarth) {
        const label = document.getElementById('tune-atmo-spread-earth-val');
        atmoSpreadEarth.addEventListener('input', function () {
            atmoSpreadEarthKm = +this.value;
            if (label) label.textContent = atmoSpreadEarthKm + ' km';
            applyAtmoUniforms();
            orbitalRender();
        });
    }
    const atmoTangent = document.getElementById('tune-atmo-tan-earth');
    if (atmoTangent) {
        atmoTangent.addEventListener('change', function () {
            atmoEarthTangentFade = this.checked;
            applyAtmoUniforms();
            orbitalRender();
        });
    }
    buildAtmoEditor();

    // "Country outlines" hint button (spaceship only; shown/labelled in the mode setup).
    const hintBtn = document.getElementById('hint-outlines-toggle');
    if (hintBtn) {
        hintBtn.addEventListener('click', function () {
            setOrbitalHint(!orbitalHintOn);
            this.textContent = 'Outlines: ' + (orbitalHintOn ? 'On' : 'Off');
        });
    }

    const colourBtn = document.getElementById('map-colour-toggle');
    if (colourBtn) colourBtn.addEventListener('click', () => setMapColour(!mapColourOn));

    // Orbital scoring-weight sliders.
    [
        ['tune-score-acc', 'tune-score-acc-val', v => { scoreAccuracyWeight = v; }, v => String(v)],
        ['tune-score-speed', 'tune-score-speed-val', v => { scoreSpeedWeight = v; }, v => String(v)],
        ['tune-score-pan', 'tune-score-pan-val', v => { scorePanWeight = v; }, v => v.toFixed(2)],
        ['tune-score-dist', 'tune-score-dist-val', v => { scoreDistScaleKm = v; }, v => v.toLocaleString() + ' km'],
        ['tune-score-time', 'tune-score-time-val', v => { scoreTimeScaleSec = v; }, v => v + ' s']
    ].forEach(([id, valId, setter, fmt]) => {
        const el = document.getElementById(id);
        if (!el) return;
        const lab = document.getElementById(valId);
        el.addEventListener('input', function () { const v = +this.value; setter(v); if (lab) lab.textContent = fmt(v); });
    });

    // Site-wide answer-reveal/advance pause (every quiz mode).
    const answerPauseSlider = document.getElementById('tune-answer-pause');
    if (answerPauseSlider) {
        const label = document.getElementById('tune-answer-pause-val');
        answerPauseSlider.addEventListener('input', function () {
            ANSWER_PAUSE_MS = +this.value;
            if (label) label.textContent = this.value + ' ms';
        });
    }

    // Live tuning sliders (dot pixel threshold, dot spacing).
    const dotSizeSlider = document.getElementById('tune-dotsize');
    if (dotSizeSlider) {
        const label = document.getElementById('tune-dotsize-val');
        dotSizeSlider.addEventListener('input', function () {
            DOT_PIXEL_THRESHOLD = +this.value;
            if (label) label.textContent = this.value;
            updateIslandMarkers();
        });
    }
    const dotSpaceSlider = document.getElementById('tune-dotspace');
    if (dotSpaceSlider) {
        const label = document.getElementById('tune-dotspace-val');
        dotSpaceSlider.addEventListener('input', function () {
            DOT_SPACING = +this.value;
            if (label) label.textContent = this.value;
            updateIslandMarkers();
        });
    }
    // US States Puzzle: base snap radius (difficulty scales it) and the snap click.
    const puzzleSnapSlider = document.getElementById('tune-puzzle-snap');
    if (puzzleSnapSlider) {
        const label = document.getElementById('tune-puzzle-snap-val');
        puzzleSnapSlider.addEventListener('input', function () {
            puzzleSnapRadius = +this.value;
            if (label) label.textContent = this.value;
        });
    }
    const puzzleSoundToggle = document.getElementById('tune-puzzle-sound');
    if (puzzleSoundToggle) {
        puzzleSoundToggle.addEventListener('change', function () {
            puzzleSoundOn = this.checked;
        });
    }
    // Blind-mode scoring: the accuracy/speed balance and the two falloff scales.
    [['tune-puzzle-balance', v => { puzzleScoreBalance = v; }, v => `${v}% / ${100 - v}%`],
     ['tune-puzzle-dist',    v => { puzzleDistScale = v; },    v => `${v} km`],
     ['tune-puzzle-time',    v => { puzzleTimeScale = v; },    v => `${v} s`]
    ].forEach(([id, set, fmt]) => {
        const slider = document.getElementById(id);
        if (!slider) return;
        const label = document.getElementById(id + '-val');
        slider.addEventListener('input', function () {
            set(+this.value);
            if (label) label.textContent = fmt(+this.value);
        });
    });
    // Settings pop-up: open/close the tuning-slider modal.
    const settingsBtn = document.getElementById('settings-btn');
    const settingsOverlay = document.getElementById('settings-overlay');
    const settingsClose = document.getElementById('settings-close');
    if (settingsBtn && settingsOverlay) {
        const openSettings = () => settingsOverlay.classList.remove('hidden');
        const closeSettings = () => settingsOverlay.classList.add('hidden');
        settingsBtn.addEventListener('click', openSettings);
        if (settingsClose) settingsClose.addEventListener('click', closeSettings);
        // Close on backdrop click (but not when clicking inside the panel).
        settingsOverlay.addEventListener('click', (e) => { if (e.target === settingsOverlay) closeSettings(); });
        document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeSettings(); });
    }

    // Share button: copy a link to the current mode (or, once a game has ended, a challenge
    // link carrying the score). Places-been routes to its own richer share.
    const shareBtn = document.getElementById('share-btn');
    if (shareBtn) shareBtn.addEventListener('click', shareCurrentGame);

    // Debug validity overlay toggle (button + 'd' keyboard shortcut)
    const debugBtn = document.getElementById('debug-validity-toggle');
    if (debugBtn) debugBtn.addEventListener('click', toggleDebugValidity);
    document.addEventListener('keydown', (e) => {
        if (e.key !== 'd' && e.key !== 'D') return;
        // Ignore when typing into an input/textarea
        const tag = document.activeElement && document.activeElement.tagName;
        if (tag === 'INPUT' || tag === 'TEXTAREA') return;
        toggleDebugValidity();
    });
}

// Show find mode selector (choose region)
// ==================== FIND THE CAPITAL ====================
// Show a capital name; the player clicks the world map to guess its location.
// Scored by total great-circle distance over all rounds (lower is better).
let capitalMarkersGroup = null;

function clearCapitalMarkers() {
    if (capitalMarkersGroup) { capitalMarkersGroup.remove(); capitalMarkersGroup = null; }
}

function ensureCapitalMarkersGroup() {
    if (!capitalMarkersGroup) capitalMarkersGroup = g.append('g').attr('class', 'capital-markers');
    return capitalMarkersGroup;
}

function renderFindCapitalQuestion() {
    gameState.questionType = 'capital-location';
    gameState.capitalSubmitted = false;
    gameState.currentGuess = null;
    if (gameState.totalDistanceKm == null) gameState.totalDistanceKm = 0;

    // Pick a country with known capital coordinates that hasn't been used yet.
    const pool = gameState.currentQuizList.filter(n => {
        const d = gameState.currentDataObj[n];
        return d && Array.isArray(d.capitalCoords);
    });
    let target = pool[Math.floor(Math.random() * pool.length)];
    let guard = 0;
    while (gameState.usedCountries.has(target) && gameState.usedCountries.size < pool.length && guard++ < 500) {
        target = pool[Math.floor(Math.random() * pool.length)];
    }
    gameState.usedCountries.add(target);
    gameState.targetCountry = target;
    const data = gameState.currentDataObj[target];
    gameState.capitalAnswer = [data.capitalCoords[1], data.capitalCoords[0]]; // [lon, lat]

    clearCapitalMarkers();

    const sameName = data.capital === target;
    document.getElementById('question-text').innerHTML =
        `Round ${gameState.currentQuestion}/${gameState.totalQuestions} — Where is <strong>${data.capital}</strong>${sameName ? '' : ` <span style="opacity:.75">(capital of ${target})</span>`}?` +
        ` &nbsp;Click the map, then Submit.` +
        `<br><span style="font-size:.85em;opacity:.8">Total distance so far: ${Math.round(gameState.totalDistanceKm).toLocaleString()} km</span>`;

    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('flag-display').style.display = 'none';

    const nextBtn = document.getElementById('next-btn');
    nextBtn.textContent = 'Submit Guess';
    nextBtn.disabled = true;
    nextBtn.style.display = 'inline-block';
    document.getElementById('give-up-btn').style.display = 'inline-block';
    document.getElementById('give-up-btn').textContent = 'Skip';
}

function handleCapitalGuessClick(event) {
    const mc = QUIZ_MODES[gameState.mode];
    if (!mc || !mc.findCapitalMode || gameState.capitalSubmitted) return;
    if (svgClickDragged(event)) return;   // a swipe across a static board is not a guess
    const p = d3.pointer(event, svg.node());
    const geo = projection.invert(p);
    if (!geo || isNaN(geo[0])) return;
    gameState.currentGuess = geo;
    const grp = ensureCapitalMarkersGroup();
    let m = grp.select('.guess-marker');
    if (m.empty()) m = grp.append('circle').attr('class', 'guess-marker').attr('r', 6);
    m.attr('cx', p[0]).attr('cy', p[1]);
    document.getElementById('next-btn').disabled = false;
}

function revealCapitalAnswer(extraLine) {
    const grp = ensureCapitalMarkersGroup();
    const ap = projection(gameState.capitalAnswer);
    if (gameState.currentGuess) {
        const gp = projection(gameState.currentGuess);
        grp.append('line').attr('class', 'guess-line')
            .attr('x1', gp[0]).attr('y1', gp[1]).attr('x2', ap[0]).attr('y2', ap[1]);
    }
    grp.append('circle').attr('class', 'answer-marker').attr('r', 6).attr('cx', ap[0]).attr('cy', ap[1]);

    const nextBtn = document.getElementById('next-btn');
    nextBtn.textContent = (gameState.currentQuestion >= gameState.totalQuestions) ? 'See Results' : 'Next';
    nextBtn.disabled = false;
    document.getElementById('give-up-btn').style.display = 'none';

    // Distance-scored — no discrete right/wrong to reveal, so a single pause after the
    // result is shown (matching a correct-answer's pacing) before auto-advancing. The
    // relabelled Next/See Results button above still works as a manual skip.
    scheduleAutoAdvance();
}

function submitCapitalGuess() {
    if (gameState.capitalSubmitted || !gameState.currentGuess) return;
    gameState.capitalSubmitted = true;
    const dKm = d3.geoDistance(gameState.currentGuess, gameState.capitalAnswer) * 6371;
    gameState.totalDistanceKm += dKm;
    logCapitalRound(gameState.currentGuess, dKm);

    const data = gameState.currentDataObj[gameState.targetCountry];
    const feedback = document.getElementById('feedback');
    feedback.innerHTML = `<strong>${data.capital}</strong> — your guess was <strong>${Math.round(dKm).toLocaleString()} km</strong> away.` +
        ` &nbsp;Total: ${Math.round(gameState.totalDistanceKm).toLocaleString()} km`;
    feedback.className = 'feedback ' + (dKm < 500 ? 'correct' : 'incorrect');

    if (dKm < 500) { gameState.score++; document.getElementById('score').textContent = gameState.score; syncScoreDisplay(); }
    revealCapitalAnswer();
}

function skipCapitalGuess() {
    if (gameState.capitalSubmitted) return;
    if (gameState.currentGuess) { submitCapitalGuess(); return; }
    gameState.capitalSubmitted = true;
    gameState.totalDistanceKm += 5000; // skip penalty
    logCapitalRound(null, null);
    const data = gameState.currentDataObj[gameState.targetCountry];
    const feedback = document.getElementById('feedback');
    feedback.innerHTML = `Skipped. <strong>${data.capital}</strong> is marked on the map (+5,000 km penalty).` +
        ` &nbsp;Total: ${Math.round(gameState.totalDistanceKm).toLocaleString()} km`;
    feedback.className = 'feedback incorrect';
    revealCapitalAnswer();
}

// Every round is kept, because the score is a running total and each round's map is wiped
// before you can learn anything from it. Ten numbers added up tell you how you did; ten guesses
// drawn on one map tell you HOW you were wrong, which is a different and more useful thing.
function logCapitalRound(guess, km) {
    gameState.capitalLog = gameState.capitalLog || [];
    gameState.capitalLog.push({
        country: gameState.targetCountry,
        capital: (gameState.currentDataObj[gameState.targetCountry] || {}).capital,
        answer: gameState.capitalAnswer.slice(),
        guess: guess ? guess.slice() : null,
        km: km
    });
}

// The systematic part of the error, in kilometres east/west and north/south. A mean over
// SIGNED offsets, not over distances: distances always average to something positive and say
// nothing, while the signed mean is exactly the bias that survives ten rounds — most people
// carry a constant pull toward the middle of whatever map they learned on.
function capitalBias(log) {
    const kept = (log || []).filter(r => r.guess);
    if (kept.length < 3) return null;
    let ew = 0, ns = 0;
    kept.forEach(r => {
        let dLon = r.guess[0] - r.answer[0];
        if (dLon > 180) dLon -= 360;
        if (dLon < -180) dLon += 360;
        const midLat = (r.guess[1] + r.answer[1]) / 2;
        ew += dLon * 111.320 * Math.cos(midLat * DEG);
        ns += (r.guess[1] - r.answer[1]) * 110.574;
    });
    return { ew: ew / kept.length, ns: ns / kept.length, n: kept.length };
}

// The whole game on one map: every answer as a dot, every guess tied to it by a line coloured
// by how far off it was. Reuses the blind puzzle's error ramp, so "green is close" means the
// same thing in both modes.
function drawCapitalSummaryMap() {
    const log = gameState.capitalLog || [];
    if (!log.length || !svg || !projection || !g) return;
    if (projection.center) fitCapitalWorld(projection);
    drawCountries();
    clearCapitalMarkers();
    const grp = ensureCapitalMarkersGroup();
    grp.classed('capital-summary', true);
    log.forEach(r => {
        const ap = projection(r.answer);
        if (!ap || !isFinite(ap[0])) return;
        if (r.guess) {
            const gp = projection(r.guess);
            if (gp && isFinite(gp[0])) {
                grp.append('line').attr('class', 'summary-line')
                    .attr('stroke', puzzleErrorColor(r.km))
                    .attr('x1', gp[0]).attr('y1', gp[1]).attr('x2', ap[0]).attr('y2', ap[1]);
                grp.append('circle').attr('class', 'summary-guess')
                    .attr('stroke', puzzleErrorColor(r.km))
                    .attr('r', 4).attr('cx', gp[0]).attr('cy', gp[1]);
            }
        }
        grp.append('circle').attr('class', 'summary-answer').attr('r', 3.2)
            .attr('cx', ap[0]).attr('cy', ap[1]);
    });
}

function capitalRating(avgKm) {
    if (avgKm < 300) return 'World-class! 🌍';
    if (avgKm < 800) return 'Great geography! 🧭';
    if (avgKm < 1500) return 'Solid effort 👍';
    if (avgKm < 3000) return 'Room to improve 🗺️';
    return 'Back to the atlas! 📚';
}

// ==================== US STATES PUZZLE ====================
// A jigsaw over the AlbersUSA map. Every state starts as a piece jumbled into a tray beside
// the board; drag one onto the map and it snaps home once it lands within the difficulty's
// snap radius. A piece only ever snaps into ITS OWN slot — the drop offset is measured
// against that state's real position, so a Kansas-shaped piece over Nebraska is a miss.
//
// The whole interaction hinges on one coordinate trick: each tray piece is its own <svg>
// whose viewBox IS that feature's projected bounding box, in board user units. So
// d3.pointer(event, pieceSvg) returns the grab point already in BOARD coordinates, and the
// misplacement of a drop is simply (cursor-in-board-coords − grab-point). No CTM maths, no
// bbox bookkeeping, and it stays correct however the tray happens to be scaled by CSS.

// Difficulty controls what the board shows, how forgiving the snap is, and whether the
// ghost gives a hit away. Easy and Medium are snap-to-fit jigsaws scored on pieces placed;
// Hard is a different game entirely (see `blind` below) scored on distance and time.
const PUZZLE_DIFFICULTY = {
    easy:   { board: 'slots',      labels: true,  snap: 1,   showHit: true },
    medium: { board: 'silhouette', labels: false, snap: 0.2, showHit: false },
    // Blind: one state at a time, no snapping, nothing accumulates on the board — every
    // placement is made against an empty silhouette with no reference from earlier ones.
    hard:   { board: 'silhouette', labels: false, blind: true, showHit: false }
};

function puzzleRules() {
    const mc = QUIZ_MODES[gameState.mode] || {};
    return PUZZLE_DIFFICULTY[mc.puzzleDifficulty] || PUZZLE_DIFFICULTY.easy;
}

// The snap radius actually in force, in board user units. Blind mode never snaps.
function puzzleActiveSnap() {
    const r = puzzleRules();
    return r.blind ? 0 : puzzleSnapRadius * (r.snap || 0);
}

// ---- Blind (Hard) scoring ----
// Points per state balance how close the drop was against how long it took, on the same
// exp(-x/scale) curves the spaceship view uses. All three are Settings sliders.
let puzzleScoreBalance = 70;   // % of each point from accuracy; the rest from speed
let puzzleDistScale = 300;     // km at which the accuracy term falls to ~37%
let puzzleTimeScale = 10;      // seconds at which the speed term falls to ~37%
const PUZZLE_POINTS_PER_STATE = 10;

// Great-circle error (km) of a placement: the drop offset is in board user units, so
// un-project both the true position and the dropped one and measure between them.
function puzzlePlacementErrorKm(feature, drop) {
    const c = path.centroid(feature);
    if (!c || isNaN(c[0]) || !drop) return 0;
    const dropped = [c[0] + drop[0], c[1] + drop[1]];
    const a = projection.invert ? projection.invert(c) : null;
    const b = projection.invert ? projection.invert(dropped) : null;
    if (a && b && !isNaN(a[0]) && !isNaN(b[0])) {
        return d3.geoDistance(a, b) * 6371;
    }
    // geoAlbersUsa is a composite and inverts to null in the gaps between its insets, so
    // fall back to the local scale: km per board unit, measured right at the true position.
    const probe = projection.invert ? projection.invert([c[0] + 10, c[1]]) : null;
    const kmPerUnit = (a && probe && !isNaN(probe[0]))
        ? (d3.geoDistance(a, probe) * 6371) / 10
        : 4;   // ~4 km per unit across the lower 48 at this projection scale
    return Math.hypot(drop[0], drop[1]) * kmPerUnit;
}

// Green (dead on) → amber → red (miles out), for tinting a blind placement by its error.
// The ceiling follows the tuning slider, so recalibrating the scoring recalibrates the
// colours with it. Theme variables are read live so both palettes work.
function puzzleErrorColor(km) {
    const cs = getComputedStyle(document.documentElement);
    const good = (cs.getPropertyValue('--correct') || '#5d7f52').trim();
    const mid = (cs.getPropertyValue('--partial-border') || '#cdab5e').trim();
    const bad = (cs.getPropertyValue('--incorrect') || '#a8584e').trim();
    const ceiling = Math.max(50, puzzleDistScale * 4);   // 1200 km at the default 300
    const t = Math.min(1, Math.max(0, (km || 0) / ceiling));
    return t < 0.5
        ? d3.interpolateRgb(good, mid)(t * 2)
        : d3.interpolateRgb(mid, bad)((t - 0.5) * 2);
}

// Points for one blind placement, and the accuracy/speed split behind them.
function puzzleBlindPoints(errorKm, seconds) {
    const acc = Math.exp(-Math.max(0, errorKm) / Math.max(1, puzzleDistScale));
    const speed = Math.exp(-Math.max(0, seconds) / Math.max(1, puzzleTimeScale));
    const w = Math.min(100, Math.max(0, puzzleScoreBalance)) / 100;
    return PUZZLE_POINTS_PER_STATE * (w * acc + (1 - w) * speed);
}

// The states that can actually be played: in the quiz list, and projectable. d3.geoAlbersUsa
// drops everything outside the 50 states (Puerto Rico included) — those project to null and
// yield infinite bounds, so they can't be drawn, let alone placed.
function puzzlePieceFeatures() {
    // Normalised, since the world atlas carries accents the quiz lists don't ("São Tomé").
    const list = new Set((gameState.currentQuizList || []).map(normalizeName));
    return (gameState.countries || []).filter(f => {
        if (!f.properties || !list.has(normalizeName(f.properties.name))) return false;
        const b = path.bounds(f);
        return isFinite(b[0][0]) && isFinite(b[0][1]) && isFinite(b[1][0]) && isFinite(b[1][1]) &&
               (b[1][0] - b[0][0]) > 0 && (b[1][1] - b[0][1]) > 0;
    });
}

// ---- The snap click ----
// Synthesised rather than shipped as an asset: a short noise burst with a steep decay,
// band-passed to a woody click. The context is created lazily inside a pointerup/button
// handler, which is a user gesture, so autoplay policy lets it start unsuspended.
let puzzleAudioCtx = null;
let puzzleSoundOn = true;

function puzzleAudio() {
    if (!puzzleSoundOn) return null;
    try {
        if (!puzzleAudioCtx) {
            const AC = window.AudioContext || window.webkitAudioContext;
            if (!AC) return null;
            puzzleAudioCtx = new AC();
        }
        if (puzzleAudioCtx.state === 'suspended') puzzleAudioCtx.resume();
        return puzzleAudioCtx;
    } catch (_) {
        return null;   // no audio hardware / blocked — the puzzle plays on silently
    }
}

function playPuzzleClick() {
    const ctx = puzzleAudio();
    if (!ctx) return;
    const dur = 0.05;
    const frames = Math.max(1, Math.ceil(ctx.sampleRate * dur));
    const buf = ctx.createBuffer(1, frames, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < frames; i++) {
        // (1-t)^7 decay: nearly all the energy in the first few ms, so it reads as a tick
        // rather than a hiss.
        const t = i / frames;
        data[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 7);
    }
    const src = ctx.createBufferSource();
    src.buffer = buf;
    const band = ctx.createBiquadFilter();
    band.type = 'bandpass';
    band.frequency.value = 1650;
    band.Q.value = 0.9;
    const gain = ctx.createGain();
    gain.gain.value = 0.16;   // soft — this fires up to 50 times a game
    src.connect(band).connect(gain).connect(ctx.destination);
    src.start();
    src.stop(ctx.currentTime + dur);
}

// On-screen pixels per board user unit. The board SVG is a fixed 800x600 viewBox scaled to
// fit its container with preserveAspectRatio="meet", so the effective scale is the smaller
// of the two ratios. Used only to size tray pieces and the drag ghost so they match the
// board visually — none of the snap maths depends on it.
function puzzleBoardScale() {
    return boardScreenFrame()[2];
}

// Draw the board: empty slots (Easy/Medium) or a seamless silhouette (Hard), plus the layer
// that placed pieces land in. Called by drawCountries instead of the normal clickable map.
function drawPuzzleBoard() {
    const rules = puzzleRules();
    const silhouette = rules.board === 'silhouette';
    countriesGroup.selectAll('*').remove();

    const feats = puzzlePieceFeatures();

    // The silhouette board wants the outer shape with no internal borders. That needs no
    // union geometry: filling every state with no stroke renders the union for free (CSS
    // gives the fill a hairline same-colour stroke to close antialiasing seams along
    // shared edges).
    countriesGroup.append('g')
        .attr('class', silhouette ? 'puzzle-silhouette' : 'puzzle-slots')
        .selectAll('path').data(feats).enter().append('path')
        .attr('class', silhouette ? 'puzzle-fill' : 'puzzle-slot')
        .attr('d', path);

    if (rules.labels) {
        const labels = countriesGroup.append('g').attr('class', 'puzzle-labels');
        feats.forEach(f => {
            const b = path.bounds(f);
            if (Math.max(b[1][0] - b[0][0], b[1][1] - b[0][1]) < PUZZLE_LABEL_MIN_PX) return;
            const c = path.centroid(f);
            if (!c || isNaN(c[0])) return;
            labels.append('text').attr('class', 'puzzle-label')
                .attr('data-state', f.properties.name)
                .attr('x', c[0]).attr('y', c[1]).attr('text-anchor', 'middle')
                .text(f.properties.name);
        });
    }

    // Placed pieces go above the slots so they read as filled-in, not outlined; their names
    // sit in a layer above that, so a later neighbour's fill can't paint over an earlier label.
    countriesGroup.append('g').attr('class', 'puzzle-placed-layer');
    countriesGroup.append('g').attr('class', 'puzzle-placed-labels');
}

function renderStatePuzzle() {
    const rules = puzzleRules();
    gameState.questionType = 'state-puzzle';
    gameState.puzzlePlaced = new Set();
    gameState.puzzleMisses = 0;
    gameState.puzzleStart = Date.now();
    gameState.puzzleElapsed = null;
    gameState.puzzleOrder = null;       // reshuffle the tray for a fresh game
    gameState.puzzleBlind = !!rules.blind;
    gameState.puzzleErrors = [];        // blind mode: km off, per placement
    gameState.puzzlePoints = 0;         // blind mode: fractional points, rounded for display
    gameState.puzzleDrops = [];         // blind mode: {name, drop, errorKm} for the reveal
    gameState.puzzlePieceStart = null;
    clearPuzzleDropTimer();
    stopPuzzleTimer();
    cancelPuzzleDrag();

    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');

    drawPuzzleBoard();

    const total = puzzlePieceFeatures().length;
    gameState.puzzleTotal = total;
    gameState.totalQuestions = total;   // so the top bar's n/total reads as placed/pieces
    gameState.currentQuestion = 0;
    const totalEl = document.getElementById('total-questions');
    if (totalEl) totalEl.textContent = String(total);

    // Built here (not in updatePuzzleStatus) so a Restart rebuilds the counts from scratch
    // rather than updating stale spans left over from the previous game.
    const noun = QUIZ_MODES[gameState.mode].itemLabelPlural || 'pieces';
    document.getElementById('question-text').innerHTML = rules.blind
        ? `Place each ${QUIZ_MODES[gameState.mode].itemLabel || 'piece'} on the blank map — <span id="puzzle-placed-count">0</span>/${total}` +
          ` &nbsp;|&nbsp; ⏱ <span id="puzzle-timer">0:00</span>` +
          ` &nbsp;|&nbsp; avg error: <span id="puzzle-avg-error">–</span>`
        : `Drag the ${noun} into place — <span id="puzzle-placed-count">0</span>/${total} placed` +
          ` &nbsp;|&nbsp; ⏱ <span id="puzzle-timer">0:00</span>` +
          ` &nbsp;|&nbsp; misdrops: <span id="puzzle-misses">0</span>` +
          ` &nbsp;|&nbsp; left: <span id="puzzle-remaining">0</span>`;

    // One delegated listener on the strip, because refreshPuzzleTray rewrites its innerHTML
    // after every placement — per-piece listeners would have to be re-attached each time.
    buildPuzzleTray();
    refreshPuzzleTray();
    updatePuzzleStatus();
    startPuzzleTimer();
    // Blind mode times each placement individually, starting the moment it's presented.
    if (rules.blind) gameState.puzzlePieceStart = Date.now();

    document.getElementById('next-btn').style.display = 'none';
    const giveUpBtn = document.getElementById('give-up-btn');
    giveUpBtn.style.display = 'inline-block';
    giveUpBtn.textContent = rules.blind ? 'End Round' : 'Solve It';
    document.getElementById('restart-btn').style.display = 'inline-block';
    const feedback = document.getElementById('feedback');
    feedback.textContent = '';
    feedback.className = 'feedback';
}

// ---- The tray ----
// Unplaced pieces live in a tray beside the board (inside #globe-side-panel, so
// globe-side-layout already columns it next to the map and stacks it underneath on narrow
// screens). One coordinate trick keeps the whole interaction cheap: each tray piece is its
// own <svg> whose viewBox IS that piece's bounding box in BOARD user units, so
// d3.pointer(event, pieceSvg) returns the grab point already in board coordinates however
// the tray happens to be scaled by CSS. A drop's misplacement is then just
// cursor-in-board minus grab-point — no CTM arithmetic anywhere — and puzzleSnapRadius,
// being in those same board units, is exactly as forgiving on a phone as on a desktop.

const TRAY_PIECE_MAX = 78;   // px: longest edge of a tray piece's box
const TRAY_PIECE_MIN = 24;   // px: floor, so Rhode Island is still grabbable

// ---- The world board's per-piece Mercator ----
// On a Mercator, a shape's distortion is decided entirely by WHERE it is, so a piece cut from
// the board and parked in a tray is a lie: Greenland in the corner is drawn at Greenland's
// latitude whether or not that is where you think it goes. On the world board each piece
// therefore carries its own scale.
//
// The whole correction is ONE UNIFORM SCALE IN PROJECTED SPACE, about the point being
// dragged. Mercator's scale factor is 1/cos(phi) in BOTH axes, so a shape moved from latitude
// a to latitude b is the same shape at cos(a)/cos(b) times the size — no rotation, no shear.
// Doing it in projected space rather than by rotating the sphere is not just cheaper, it is
// what keeps meridians vertical: a great-circle carry rotates the local frame everywhere
// except at its anchor, so the further a point sat from that anchor the more it skewed, which
// is exactly the "slightly off" wobble the rotation version had. It also cannot wrap: nothing
// crosses the antimeridian, so a piece can no longer split into a phantom copy while it is
// still over the tray.
//   * parked in the tray a piece is scaled to the equator (cos of its own centroid latitude),
//     which is the least-distorted view of it;
//   * dragged, it grows and shrinks live with the cursor's latitude;
//   * dropped where it belongs the ratio is exactly 1, so it matches the board precisely.
// Every other board (AlbersUSA, the regional Mercators) keeps the plain translation: their
// pieces are cut from one small map at one scale, so there is nothing to correct for.
function puzzleDynamicMercator() {
    const mc = QUIZ_MODES[gameState.mode];
    return !!(mc && mc.statePuzzleMode && mc.mapObject === 'countries');
}

// Mercator runs to infinity at the poles, so a cursor dragged off the top of the board would
// otherwise blow a piece up without limit. Clamp the latitude the scale is allowed to read.
const PUZZLE_CARRY_LAT_MAX = 78;
function puzzleLatAt(boardPt) {
    const g = (projection && projection.invert) ? projection.invert(boardPt) : null;
    if (!g || isNaN(g[1])) return null;
    return Math.max(-PUZZLE_CARRY_LAT_MAX, Math.min(PUZZLE_CARRY_LAT_MAX, g[1]));
}

// Size ratio for the same shape seen at `latTo` instead of `latFrom`.
function puzzleLatRatio(latFrom, latTo) {
    if (latFrom == null || latTo == null) return 1;
    const r = Math.cos(latFrom * Math.PI / 180) / Math.cos(latTo * Math.PI / 180);
    return isFinite(r) && r > 0 ? r : 1;
}

// The piece transform: board geometry scaled by `r` about `from`, with `from` landing on `to`.
// Written as translate·scale so the ghost can reuse one static path and only swap attributes.
function puzzlePieceTransform(from, to, r) {
    return `translate(${(to[0] - r * from[0]).toFixed(3)},${(to[1] - r * from[1]).toFixed(3)}) scale(${r.toFixed(5)})`;
}

// The board-unit bounding box of that transformed piece.
function puzzleScaledBounds(b, from, to, r) {
    return [[to[0] + (b[0][0] - from[0]) * r, to[1] + (b[0][1] - from[1]) * r],
            [to[0] + (b[1][0] - from[0]) * r, to[1] + (b[1][1] - from[1]) * r]];
}

// Screen mapping of the board's user-unit coordinate system: [originX, originY, pxPerUnit].
// Read from the live viewBox + client rect, so it is correct at any container size and
// needs no bookkeeping when the layout changes.
function boardScreenFrame() {
    const node = svg && svg.node ? svg.node() : null;
    if (!node) return [0, 0, 1];
    const r = node.getBoundingClientRect();
    const vb = node.viewBox && node.viewBox.baseVal;
    const vw = (vb && vb.width) || width, vh = (vb && vb.height) || height;
    if (!r.width || !r.height || !vw || !vh) return [0, 0, 1];
    const k = Math.min(r.width / vw, r.height / vh);   // preserveAspectRatio: meet
    return [r.left + (r.width - vw * k) / 2 - ((vb && vb.x) || 0) * k,
            r.top + (r.height - vh * k) / 2 - ((vb && vb.y) || 0) * k, k];
}

// Create the tray shell once per game and wire its single delegated pointerdown.
function buildPuzzleTray() {
    let tray = document.getElementById('puzzle-tray');
    if (!tray) {
        tray = document.createElement('div');
        tray.id = 'puzzle-tray';
        tray.className = 'puzzle-tray';
        tray.innerHTML =
            '<div class="puzzle-tray-head">' +
            '<span class="puzzle-tray-title">Pieces</span>' +
            '<span class="puzzle-tray-hint">Drag each one onto the map</span>' +
            '</div><div class="puzzle-pieces" id="puzzle-pieces"></div>';
        (document.getElementById('globe-side-panel') || document.body).appendChild(tray);
        document.getElementById('puzzle-pieces').addEventListener('pointerdown', startPuzzleDrag);
    }
    const hint = tray.querySelector('.puzzle-tray-hint');
    if (hint) {
        hint.textContent = gameState.puzzleBlind
            ? 'One at a time — nothing snaps, and nothing stays on the board'
            : 'Drag each one onto the map';
    }
    tray.style.display = '';
}

// Rebuild the tray: every piece not yet placed, in the order shuffled once per game.
function refreshPuzzleTray() {
    const host = document.getElementById('puzzle-pieces');
    if (!host || !path) return;
    const feats = puzzlePieceFeatures();
    if (!gameState.puzzleOrder) gameState.puzzleOrder = shuffleArray(feats.map(f => f.properties.name));
    const byName = new Map(feats.map(f => [f.properties.name, f]));
    let remaining = gameState.puzzleOrder.filter(n => !gameState.puzzlePlaced.has(n));
    // Blind mode hands out one piece at a time — see the note on refreshing below.
    if (gameState.puzzleBlind) remaining = remaining.slice(0, 1);

    const k = puzzleBoardScale();
    const dyn = puzzleDynamicMercator();
    const html = remaining.map(n => {
        const f = byName.get(n);
        if (!f) return '';
        const d = path(f);
        let b = path.bounds(f);
        if (!d || !isFinite(b[0][0])) return '';
        // World pieces are shown at their equator size — the piece's own centroid latitude
        // scaled away — so the tray shows the country, not Mercator's opinion of it.
        let tf = '', from = null, r = 1;
        if (dyn) {
            from = path.centroid(f);
            r = puzzleLatRatio(puzzleLatAt(from), 0);
            if (!from || isNaN(from[0])) { from = [b[0][0], b[0][1]]; r = 1; }
            tf = ` transform="${puzzlePieceTransform(from, from, r)}"`;
            b = puzzleScaledBounds(b, from, from, r);
        }
        const w = b[1][0] - b[0][0], h = b[1][1] - b[0][1];
        if (!isFinite(w) || !isFinite(h) || w <= 0 || h <= 0) return '';
        // Sized against the board so the tray reads at the same scale, then clamped: a piece
        // has to be big enough to grab and small enough not to own the tray.
        const long = Math.max(w, h) * k;
        const px = Math.max(TRAY_PIECE_MIN, Math.min(TRAY_PIECE_MAX, long));
        const s = px / Math.max(w, h);
        return `<svg class="puzzle-piece-btn" data-state="${n.replace(/"/g, '&quot;')}"` +
               ` data-scale="${r}" data-from="${from ? from[0] + ',' + from[1] : ''}"` +
               ` viewBox="${b[0][0].toFixed(2)} ${b[0][1].toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)}"` +
               ` width="${(w * s).toFixed(1)}" height="${(h * s).toFixed(1)}"` +
               ` preserveAspectRatio="xMidYMid meet"><title>${n}</title>` +
               `<path class="puzzle-piece-shape" d="${d}"${tf}/></svg>`;
    }).join('');
    host.innerHTML = html;

    const rem = document.getElementById('puzzle-remaining');
    if (rem) rem.textContent = String(remaining.length);
}

// ---- Dragging a piece ----
// The ghost is a position:fixed overlay on <body>, not a <g> inside the board: the tray sits
// outside the map, so an in-SVG ghost would be clipped — and therefore invisible — for the
// whole first half of every drag. Its viewBox is nevertheless in BOARD units and it is sized
// at the board's own px-per-unit, so what you drag is pixel-for-pixel what will land.
function startPuzzleDrag(event) {
    if (event.button > 0 || puzzleDrag) return;
    const el = event.target.closest ? event.target.closest('.puzzle-piece-btn') : null;
    if (!el) return;
    const name = el.getAttribute('data-state');
    const feature = puzzlePieceFeatures().find(f => f.properties.name === name);
    if (!feature || gameState.puzzlePlaced.has(name)) return;
    event.preventDefault();

    // The grab point, already in board units (the tray piece's viewBox is board coordinates).
    const grab = d3.pointer(event, el);
    let homeGrab = grab;
    if (puzzleDynamicMercator()) {
        // The tray piece is drawn scaled about its centroid, so undo that scale to find where
        // on the BOARD the grabbed point belongs. Everything downstream measures against it.
        const r = parseFloat(el.getAttribute('data-scale')) || 1;
        const from = (el.getAttribute('data-from') || '').split(',').map(Number);
        if (from.length === 2 && isFinite(from[0]) && r > 0) {
            homeGrab = [from[0] + (grab[0] - from[0]) / r, from[1] + (grab[1] - from[1]) / r];
        }
    }
    // The latitude the piece is drawn AT is read from the grabbed point, not the centroid, so
    // that dropping it exactly home gives a ratio of exactly 1 and a pixel-perfect match.
    const homeLat = puzzleDynamicMercator() ? puzzleLatAt(homeGrab) : null;

    const ghost = document.createElement('div');
    ghost.className = 'puzzle-ghost';
    ghost.innerHTML = '<svg preserveAspectRatio="xMidYMid meet"><path class="puzzle-piece-shape"/></svg>';
    document.body.appendChild(ghost);

    puzzleDrag = {
        name, feature, el, ghost,
        ghostSvg: ghost.firstChild, ghostPath: ghost.firstChild.firstChild,
        boardPath: path(feature), boardBounds: path.bounds(feature),
        homeGrab, homeLat, scale: 1, cursor: homeGrab.slice(), pointerId: event.pointerId
    };
    el.classList.add('in-hand');

    window.addEventListener('pointermove', onPuzzleDragMove);
    window.addEventListener('pointerup', onPuzzleDragEnd);
    window.addEventListener('pointercancel', onPuzzleDragEnd);
    try { el.setPointerCapture(event.pointerId); } catch (_) { /* best effort */ }
    onPuzzleDragMove(event);
}

// How far the grabbed point is from where it belongs, in board units. This IS the snap test,
// on every board: for a carried world piece the cursor is the carried point by construction,
// and for a translated one the grab travels with the piece.
function puzzleDropVector() {
    if (!puzzleDrag) return null;
    return [puzzleDrag.cursor[0] - puzzleDrag.homeGrab[0],
            puzzleDrag.cursor[1] - puzzleDrag.homeGrab[1]];
}

function puzzleDropOffset() {
    const v = puzzleDropVector();
    return v ? Math.hypot(v[0], v[1]) : Infinity;
}

function onPuzzleDragMove(event) {
    if (!puzzleDrag) return;
    const p = d3.pointer(event, svg.node());   // board units, valid even outside the board
    if (!p || isNaN(p[0])) return;
    puzzleDrag.cursor = p;

    // One static path, one transform: the piece is the board geometry scaled by the latitude
    // ratio about the grabbed point, with that point pinned under the cursor.
    const r = puzzleDrag.homeLat != null ? puzzleLatRatio(puzzleDrag.homeLat, puzzleLatAt(p)) : 1;
    puzzleDrag.scale = r;
    const b = puzzleScaledBounds(puzzleDrag.boardBounds, puzzleDrag.homeGrab, p, r);
    if (isFinite(b[0][0])) {
        const x0 = b[0][0], y0 = b[0][1];
        const w = Math.max(1e-3, b[1][0] - b[0][0]), h = Math.max(1e-3, b[1][1] - b[0][1]);
        const [ox, oy, k] = boardScreenFrame();
        puzzleDrag.ghostSvg.setAttribute('viewBox', `${x0.toFixed(2)} ${y0.toFixed(2)} ${w.toFixed(2)} ${h.toFixed(2)}`);
        puzzleDrag.ghostSvg.setAttribute('width', (w * k).toFixed(1));
        puzzleDrag.ghostSvg.setAttribute('height', (h * k).toFixed(1));
        puzzleDrag.ghostPath.setAttribute('d', puzzleDrag.boardPath);
        puzzleDrag.ghostPath.setAttribute('transform', puzzlePieceTransform(puzzleDrag.homeGrab, p, r));
        puzzleDrag.ghost.style.left = (ox + x0 * k) + 'px';
        puzzleDrag.ghost.style.top = (oy + y0 * k) + 'px';
    }
    const hit = puzzleRules().showHit && puzzleDropOffset() <= puzzleActiveSnap();
    puzzleDrag.ghost.classList.toggle('will-snap', hit);
}

function onPuzzleDragEnd() {
    if (!puzzleDrag) return;
    const { name, feature, cursor, homeGrab, scale } = puzzleDrag;
    const drop = puzzleDropVector().slice();
    // How the piece actually looked at the moment of release, so the blind reveal can redraw
    // it exactly rather than sliding an unscaled shape into place.
    const shown = { from: homeGrab.slice(), to: cursor.slice(), scale };
    const snapped = Math.hypot(drop[0], drop[1]) <= puzzleActiveSnap();
    cancelPuzzleDrag();

    if (gameState.puzzleBlind) { commitBlindPlacement(name, feature, drop, shown); return; }

    if (snapped) {
        placePuzzlePiece(name, true, drop);
    } else {
        gameState.puzzleMisses = (gameState.puzzleMisses || 0) + 1;
        const feedback = document.getElementById('feedback');
        feedback.textContent = 'Not quite — that piece goes somewhere else.';
        feedback.className = 'feedback incorrect';
        refreshPuzzleTray();   // springs back into the tray
    }
    updatePuzzleStatus();
    if (gameState.puzzlePlaced.size >= gameState.puzzleTotal) finishPuzzle();
}

function cancelPuzzleDrag() {
    if (!puzzleDrag) return;
    window.removeEventListener('pointermove', onPuzzleDragMove);
    window.removeEventListener('pointerup', onPuzzleDragEnd);
    window.removeEventListener('pointercancel', onPuzzleDragEnd);
    try { puzzleDrag.el.releasePointerCapture(puzzleDrag.pointerId); } catch (_) { /* best effort */ }
    puzzleDrag.el.classList.remove('in-hand');
    if (puzzleDrag.ghost && puzzleDrag.ghost.parentNode) puzzleDrag.ghost.parentNode.removeChild(puzzleDrag.ghost);
    puzzleDrag = null;
}

function removePuzzleTray() {
    stopPuzzleTimer();
    cancelPuzzleDrag();
    const tray = document.getElementById('puzzle-tray');
    if (tray) tray.remove();
    if (gameState && gameState._puzzleResize) {
        window.removeEventListener('resize', gameState._puzzleResize);
        gameState._puzzleResize = null;
    }
}

function updatePuzzleStatus() {
    const placed = gameState.puzzlePlaced ? gameState.puzzlePlaced.size : 0;
    const placedEl = document.getElementById('puzzle-placed-count');
    if (placedEl) placedEl.textContent = String(placed);
    const missEl = document.getElementById('puzzle-misses');
    if (missEl) missEl.textContent = String(gameState.puzzleMisses || 0);
    const avgEl = document.getElementById('puzzle-avg-error');
    if (avgEl) avgEl.textContent = puzzleAvgErrorKm() == null
        ? '–'
        : Math.round(puzzleAvgErrorKm()).toLocaleString() + ' km';
    renderPuzzleTimer();
}

// Mean placement error so far, or null before the first placement.
function puzzleAvgErrorKm() {
    const e = gameState.puzzleErrors;
    if (!e || !e.length) return null;
    return e.reduce((s, v) => s + v, 0) / e.length;
}

function stopPuzzleTimer() {
    if (gameState && gameState.puzzleTimerId) {
        clearInterval(gameState.puzzleTimerId);
        gameState.puzzleTimerId = null;
    }
    clearPuzzleDropTimer();
}

function renderPuzzleTimer() {
    const el = document.getElementById('puzzle-timer');
    if (!el || !gameState.puzzleStart) return;
    const s = gameState.puzzleElapsed != null
        ? gameState.puzzleElapsed
        : Math.floor((Date.now() - gameState.puzzleStart) / 1000);
    el.textContent = `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

function startPuzzleTimer() {
    stopPuzzleTimer();
    renderPuzzleTimer();
    gameState.puzzleTimerId = setInterval(() => {
        // Self-cancel if the player has left the puzzle (same guard as the name-all timer).
        const mc = QUIZ_MODES[gameState.mode];
        if (!mc || !mc.statePuzzleMode) { stopPuzzleTimer(); return; }
        renderPuzzleTimer();
    }, 1000);
}

// ---- Dragging a piece ----

// ---- Blind (Hard) placement ----
// Record where the player dropped this state, score it, and hand out the next one. The
// board is deliberately left untouched: with nothing accumulating on it, every state after
// the first is still placed against a bare silhouette.
function commitBlindPlacement(name, feature, drop, shown) {
    if (!gameState.puzzlePlaced || gameState.puzzlePlaced.has(name)) return;
    gameState.puzzlePlaced.add(name);

    const errorKm = puzzlePlacementErrorKm(feature, drop);
    const seconds = gameState.puzzlePieceStart
        ? (Date.now() - gameState.puzzlePieceStart) / 1000
        : 0;
    const points = puzzleBlindPoints(errorKm, seconds);

    gameState.puzzleErrors.push(errorKm);
    // The from/to/scale of the released piece travels with the record, so the world board's
    // reveal redraws what was dropped instead of sliding an unscaled shape into place.
    gameState.puzzleDrops.push({ name, drop, errorKm, shown });
    gameState.puzzlePoints += points;
    gameState.score = Math.round(gameState.puzzlePoints);
    gameState.currentQuestion = gameState.puzzlePlaced.size;

    playPuzzleClick();

    const feedback = document.getElementById('feedback');
    feedback.innerHTML = `<strong>${name}</strong> — ` +
        (errorKm < 25
            ? 'just about spot on!'
            : `<strong>${Math.round(errorKm).toLocaleString()} km</strong> off`) +
        ` &nbsp;(+${points.toFixed(1)} pts in ${seconds.toFixed(1)}s)`;
    feedback.className = 'feedback ' + (errorKm < 300 ? 'correct' : 'incorrect');

    document.getElementById('score').textContent = gameState.score;
    const cq = document.getElementById('current-question');
    if (cq) cq.textContent = String(gameState.puzzlePlaced.size);
    syncScoreDisplay();

    refreshPuzzleTray();   // this piece is spent; the tray hands out the next one
    updatePuzzleStatus();

    // Show the piece exactly where it was dropped, tinted by how far off it was — the only
    // feedback the player gets. It is cleared again before the next state is handed out, so
    // nothing accumulates on the board to reference.
    const layer = countriesGroup.select('.puzzle-placed-layer');
    let drawn = null;
    if (!layer.empty()) {
        drawn = layer.append('path')
            .attr('class', 'puzzle-blind-drop')
            .attr('d', path(feature))
            .attr('transform', shown
                ? puzzlePieceTransform(shown.from, shown.to, shown.scale)
                : `translate(${drop[0]},${drop[1]})`)
            .style('fill', puzzleErrorColor(errorKm))
            .style('animation', `puzzleBlindFade ${ANSWER_PAUSE_MS}ms ease-out forwards`);
    }

    const done = gameState.puzzlePlaced.size >= gameState.puzzleTotal;
    // Paced by the shared ANSWER_PAUSE_MS like every other mode's reveal, and tracked so a
    // restart or a mode switch mid-pause can't fire this against fresh state.
    clearPuzzleDropTimer();
    gameState.puzzleDropTimer = setTimeout(() => {
        gameState.puzzleDropTimer = null;
        if (drawn) drawn.remove();
        const mc = QUIZ_MODES[gameState.mode];
        if (!mc || !mc.statePuzzleMode) return;   // player left during the pause
        if (done) {
            finishPuzzle();
        } else {
            refreshPuzzleTray();
            gameState.puzzlePieceStart = Date.now();   // the next state's clock starts now
        }
    }, ANSWER_PAUSE_MS);
}

function clearPuzzleDropTimer() {
    if (gameState && gameState.puzzleDropTimer) {
        clearTimeout(gameState.puzzleDropTimer);
        gameState.puzzleDropTimer = null;
    }
}

// End-of-round payoff for blind mode: the map the player actually built. Every state is
// drawn where THEY put it, keeping the colour that graded it, so the whole run reads at a
// glance — a green USA that looks about right, or an amber sprawl that doesn't. Faint
// leader lines back to each state's true position show what the colours are measuring.
function revealBlindPlacements() {
    if (!countriesGroup || countriesGroup.empty()) return;
    const byName = new Map(puzzlePieceFeatures().map(f => [f.properties.name, f]));
    const drops = gameState.puzzleDrops || [];
    if (!drops.length) return;

    const lines = countriesGroup.append('g').attr('class', 'puzzle-reveal-marks');
    const layer = countriesGroup.append('g').attr('class', 'puzzle-reveal-layer');

    drops.forEach(({ name, drop, errorKm, shown }) => {
        const f = byName.get(name);
        if (!f) return;
        const c = path.centroid(f);
        if (c && !isNaN(c[0])) {
            lines.append('line').attr('class', 'puzzle-reveal-line')
                .attr('x1', c[0]).attr('y1', c[1])
                .attr('x2', c[0] + drop[0]).attr('y2', c[1] + drop[1]);
        }
        // Redraw the piece as it was at the moment of release (scale and all); the plain
        // translate is the fallback for records made before that was tracked.
        layer.append('path')
            .attr('class', 'puzzle-reveal')
            .attr('d', path(f))
            .attr('transform', shown
                ? puzzlePieceTransform(shown.from, shown.to, shown.scale)
                : `translate(${drop[0]},${drop[1]})`)
            .style('fill', puzzleErrorColor(errorKm));
    });
}


// Commit a piece to the board. award:false is used by Solve It, which fills the map in but
// shouldn't credit the player for it (and skips the animation/click — 47 of each at once
// would be a mess). `from` is the drop offset in board units, animated back to zero.
function placePuzzlePiece(name, award = true, from = null) {
    if (!gameState.puzzlePlaced || gameState.puzzlePlaced.has(name)) return;
    const feature = puzzlePieceFeatures().find(f => f.properties.name === name);
    if (!feature) return;
    gameState.puzzlePlaced.add(name);

    const layer = countriesGroup.select('.puzzle-placed-layer');
    if (!layer.empty()) {
        const node = layer.append('path').datum(feature)
            .attr('class', 'puzzle-placed' + (award ? '' : ' revealed'))
            .attr('d', path);

        // "Sucked in": the piece appears where it was actually dropped, slightly oversized,
        // and is pulled the last few pixels into its slot as it settles to true size.
        const reduceMotion = window.matchMedia &&
            window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        if (award && from && !reduceMotion) {
            const c = path.centroid(feature);
            if (c && !isNaN(c[0])) {
                // Scale about the piece's own centroid, then offset by the drop delta.
                const at = (dx, dy, s) =>
                    `translate(${c[0]},${c[1]}) scale(${s}) translate(${-c[0]},${-c[1]}) translate(${dx},${dy})`;
                const settle = () => node.attr('transform', null).style('opacity', null);
                node.attr('transform', at(from[0], from[1], 1.12))
                    .style('opacity', 0.55)
                    .transition().duration(190).ease(d3.easeCubicOut)
                    .attr('transform', at(0, 0, 1))
                    .style('opacity', 1)
                    .on('end interrupt cancel', settle);
                // Safety net: the transition is rAF-driven, so a backgrounded tab (or an
                // interrupt that never fires) would otherwise strand the piece offset and
                // oversized ON the board. setTimeout still runs when rAF is throttled, so
                // the correct final state is guaranteed either way.
                setTimeout(settle, 260);
            }
        }
        if (award) playPuzzleClick();
    }
    // Name the piece now that it's home — the board doubles as a labelled map as you fill it
    // in. Skipped for anything too small to hold readable text (same threshold as the Easy
    // slot labels) and for blind mode, whose placements are wiped after the grading pause.
    const labels = countriesGroup.select('.puzzle-placed-labels');
    if (!labels.empty() && !gameState.puzzleBlind) {
        const b = path.bounds(feature);
        const c = path.centroid(feature);
        if (c && !isNaN(c[0]) && isFinite(b[0][0]) &&
            Math.max(b[1][0] - b[0][0], b[1][1] - b[0][1]) >= PUZZLE_LABEL_MIN_PX) {
            labels.append('text')
                .attr('class', 'puzzle-placed-label' + (award ? '' : ' revealed'))
                .attr('data-state', name)
                .attr('x', c[0]).attr('y', c[1])
                .attr('text-anchor', 'middle').attr('dy', '0.32em')
                .text(name);
        }
    }
    // Easy mode's slot label would otherwise show through the piece now covering it.
    countriesGroup.selectAll('.puzzle-label')
        .filter(function () { return this.getAttribute('data-state') === name; })
        .remove();

    if (award) {
        gameState.score++;
        const feedback = document.getElementById('feedback');
        feedback.textContent = `${name} — placed!`;
        feedback.className = 'feedback correct';
    }
    gameState.currentQuestion = gameState.puzzlePlaced.size;
    document.getElementById('score').textContent = gameState.score;
    const cq = document.getElementById('current-question');
    if (cq) cq.textContent = String(gameState.puzzlePlaced.size);
    syncScoreDisplay();
    // Re-pack rather than just deleting the piece: the pile closes up around the gap so it
    // stays as compact as it can be for the rest of the game.
    refreshPuzzleTray();
}

// The Give Up handler. In blind mode there's nothing to solve — the states you never got
// to simply go unscored — so it just ends the round. Otherwise it fills the board in.
function solveStatePuzzle() {
    if (!gameState.puzzlePlaced) return;
    if (gameState.puzzleBlind) { finishPuzzle(); return; }
    // One click for the lot rather than fifty overlapping ones.
    if (gameState.puzzlePlaced.size < gameState.puzzleTotal) playPuzzleClick();
    puzzlePieceFeatures().forEach(f => placePuzzlePiece(f.properties.name, false));
    updatePuzzleStatus();
    finishPuzzle();
}

function finishPuzzle() {
    if (gameState.puzzleElapsed == null && gameState.puzzleStart) {
        gameState.puzzleElapsed = Math.floor((Date.now() - gameState.puzzleStart) / 1000);
    }
    stopPuzzleTimer();
    cancelPuzzleDrag();
    const trayHost = document.getElementById('puzzle-pieces');
    if (trayHost) trayHost.innerHTML = '';
    if (gameState.puzzleBlind) revealBlindPlacements();
    endGame();
}

// Remove the tray and every scrap of puzzle state (timer, drag, resize listener).

// Blind mode is rated on the average miss — but only once the whole set has been placed,
// since ending the round after five easy states shouldn't read as a triumph.
function puzzleBlindRating(avgKm, done, total) {
    if (avgKm == null) return 'No states placed.';
    if (done < total) return `Round ended early — ${total - done} left unplaced.`;
    if (avgKm < 100) return 'Uncanny — you know this map by heart.';
    if (avgKm < 250) return 'Excellent placement.';
    if (avgKm < 500) return 'Solid — most states landed close.';
    if (avgKm < 1000) return 'Roughly right, but the middle of the country drifted.';
    return 'Worth another go.';
}

// Rate the run. Time-per-piece only means anything if the player actually finished it
// themselves, so a board completed by "Solve It" is rated on how far they got instead.
function puzzleRating(seconds, misses, total, earned) {
    if (!total) return '';
    if (earned < total) {
        const frac = earned / total;
        if (frac >= 0.75) return 'so close — one more go.';
        if (frac >= 0.4) return 'over halfway there.';
        if (frac > 0) return 'the rest were filled in for you.';
        return 'have a real go next time!';
    }
    const perPiece = seconds / total;
    if (misses === 0 && perPiece < 4) return 'flawless.';
    if (misses <= total * 0.2 && perPiece < 6) return 'excellent.';
    if (misses <= total * 0.5) return 'solid work.';
    if (misses <= total) return 'getting there.';
    return 'worth another go.';
}

// ==================== TOPOLOGY-DERIVED COUNTRY FACTS ====================
// Who borders whom, and who has a coast, read straight out of the TopoJSON rather than
// shipped as another data file. Both fall out of the arc table: topojson.neighbors gives
// adjacency for free, and an arc used by exactly ONE geometry is a shore rather than a
// shared border — so a country with no such arc is landlocked, and one with no neighbours
// but plenty of shore is an island. Cached per resolution, since the arcs differ between
// the 110m and 50m sources.
let countryFactsCache = null;

function ensureCountryFacts() {
    const url = worldCountriesUrl();
    if (countryFactsCache && countryFactsCache.url === url) return countryFactsCache;
    const topo = worldTopoCache[url];
    if (!topo || !topo.objects || !topo.objects.countries || !topojson.neighbors) return null;
    const geoms = topo.objects.countries.geometries;
    const names = geoms.map(g => {
        const n = getCountryName(g.id);
        return /^Country /.test(n) ? null : n;   // ids the name table doesn't know
    });

    // ---- adjacency ----
    //
    // A shared border that runs through a LAKE is not a land border: the DRC and Tanzania are on
    // opposite shores of Tanganyika and share nothing but a horizon. Natural Earth draws the
    // countries meeting in the middle of the water, so the arc table says they touch — and every
    // consequence of that (the neighbour lists, the border graph, who may bite whom in Who's
    // Missing) inherited the mistake. A pair is dropped when EVERY arc they share lies in water.
    const arcsRaw = topo.arcs && topo.transform ? null : topo.arcs;
    const inAnyLake = q => (lakeCutRings || []).some(lk =>
        !(lk.bb[0] > q[0] || lk.bb[2] < q[0] || lk.bb[1] > q[1] || lk.bb[3] < q[1]) && ghPointIn(q, lk.ring));
    const arcPts = sbDecodeArcs(topo);
    const sharedArcs = new Map();
    const noteArc = (a, nm) => {
        const k = a < 0 ? ~a : a;
        if (!sharedArcs.has(k)) sharedArcs.set(k, new Set());
        sharedArcs.get(k).add(nm);
    };
    const walkA = (arcs, depth, fn) => { if (depth === 0) { fn(arcs); return; } arcs.forEach(a => walkA(a, depth - 1, fn)); };
    const dOf = g => g.type === 'Polygon' ? 2 : (g.type === 'MultiPolygon' ? 3 : -1);
    geoms.forEach((g, i) => { const d = dOf(g); if (d > 0 && names[i]) walkA(g.arcs, d, a => noteArc(a, names[i])); });
    const wetPair = new Map();
    sharedArcs.forEach((who, k) => {
        if (who.size !== 2) return;
        const pts = arcPts[k];
        if (!pts || pts.length < 2) return;
        const mid = pts[pts.length >> 1];
        const key = [...who].sort().join(String.fromCharCode(0));
        const wet = inAnyLake(mid);
        const cur = wetPair.get(key);
        wetPair.set(key, { wet: (cur ? cur.wet : 0) + (wet ? 1 : 0), dry: (cur ? cur.dry : 0) + (wet ? 0 : 1) });
    });
    const throughWater = (a, b) => {
        const v = wetPair.get([a, b].sort().join(String.fromCharCode(0)));
        return !!(v && v.wet && !v.dry);
    };

    const neighbours = new Map();
    const nb = topojson.neighbors(geoms);
    geoms.forEach((g, i) => {
        if (!names[i]) return;
        const set = new Set();
        (nb[i] || []).forEach(j => {
            if (!names[j] || names[j] === names[i]) return;
            if (throughWater(names[i], names[j])) return;
            set.add(names[j]);
        });
        // A name can appear twice in the atlas (mainland + a stray micro-polygon); union them.
        if (neighbours.has(names[i])) set.forEach(v => neighbours.get(names[i]).add(v));
        else neighbours.set(names[i], set);
    });

    // ---- coastline: arcs used exactly once ----
    const use = new Map();
    const bump = a => { const k = a < 0 ? ~a : a; use.set(k, (use.get(k) || 0) + 1); };
    // `depth` counts down to 0 = a single arc index. A Polygon's arcs are rings of indices
    // (depth 2); a MultiPolygon adds one more level (depth 3). Passing anything less hands
    // whole arrays to the counter, every key is then unique, and EVERY country reads as
    // coastal — which is exactly what happened the first time round.
    const walkArcs = (arcs, depth, fn) => {
        if (depth === 0) { fn(arcs); return; }
        arcs.forEach(a => walkArcs(a, depth - 1, fn));
    };
    const depthOf = g => g.type === 'Polygon' ? 2 : (g.type === 'MultiPolygon' ? 3 : -1);
    geoms.forEach(g => { const d = depthOf(g); if (d > 0) walkArcs(g.arcs, d, bump); });

    const coastal = new Set();
    geoms.forEach((g, i) => {
        if (!names[i]) return;
        const d = depthOf(g);
        if (d < 1) return;
        walkArcs(g.arcs, d, a => {
            const k = a < 0 ? ~a : a;
            if (use.get(k) === 1) coastal.add(names[i]);
        });
    });

    const island = new Set();
    neighbours.forEach((set, name) => { if (!set.size && coastal.has(name)) island.add(name); });

    countryFactsCache = { url, neighbours, coastal, island };
    return countryFactsCache;
}

// Neighbours restricted to the quiz list (so a chain never asks for a country the game
// doesn't otherwise know about).
function playableNeighbours(name) {
    const facts = ensureCountryFacts();
    if (!facts) return [];
    const list = new Set((gameState.currentQuizList || []).map(normalizeName));
    return [...(facts.neighbours.get(name) || [])].filter(n => list.has(normalizeName(n)));
}

// ==================== ODD ONE OUT ====================
// Four countries highlighted at once; three share something and one doesn't. The trait is
// only named after the answer, so the highlight itself is the whole question.
const ODD_TRAITS = [
    {
        key: 'continent',
        label: c => `all in ${c}`,
        groups: () => {
            const cd = window.continentData || {};
            return Object.keys(cd).map(c => ({ tag: c, names: cd[c] }));
        }
    },
    {
        key: 'hemisphere',
        label: h => `all in the ${h}ern hemisphere`,
        groups: () => {
            const north = [], south = [];
            (gameState.countries || []).forEach(f => {
                const c = d3.geoCentroid(f);
                if (!c || !isFinite(c[1])) return;
                (c[1] >= 0 ? north : south).push(f.properties.name);
            });
            return [{ tag: 'north', names: north }, { tag: 'south', names: south }];
        }
    },
    {
        key: 'landlocked',
        label: () => 'all landlocked',
        groups: () => {
            const facts = ensureCountryFacts();
            if (!facts) return [];
            const land = [];
            facts.neighbours.forEach((_, n) => { if (!facts.coastal.has(n)) land.push(n); });
            return [{ tag: 'landlocked', names: land }];
        }
    },
    {
        key: 'island',
        label: () => 'all island nations',
        groups: () => {
            const facts = ensureCountryFacts();
            return facts ? [{ tag: 'island', names: [...facts.island] }] : [];
        }
    },
    {
        // "Three of these border Bolivia; one does not." The only trait here whose group is
        // defined by a country rather than by a category, and the only one that needs to choose
        // its own outsider: a random one is dismissed by continent without anybody thinking about
        // a border, so the odd one out has to be a country that comes CLOSE and does not touch.
        key: 'neighbour',
        label: tag => `all border ${displayLabelForName(tag)}`,
        groups: () => {
            const facts = ensureCountryFacts();
            if (!facts) return [];
            const out = [];
            facts.neighbours.forEach((_, n) => {
                const nb = playableNeighbours(n);
                if (nb.length >= 3) out.push({ tag: n, names: nb });
            });
            return out;
        },
        outsiders: (grp, list) => {
            const nbSet = new Set((grp.names || []).map(normalizeName));
            nbSet.add(normalizeName(grp.tag));
            const c0 = getCountryCentroid(grp.tag);
            if (!c0) return null;
            return list.filter(n => !nbSet.has(normalizeName(n)))
                .map(n => ({ n, d: getCountryCentroid(n) ? sbKmBetween(c0, getCountryCentroid(n)) : Infinity }))
                .filter(x => isFinite(x.d)).sort((a, b) => a.d - b.d)
                .slice(0, 6).map(x => x.n);
        }
    }
];

function renderOddOneOutQuestion() {
    gameState.questionType = 'odd-one-out';
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'inline-block';
    document.getElementById('give-up-btn').textContent = 'Give Up';
    document.getElementById('restart-btn').style.display = 'inline-block';

    const puzzle = buildOddOneOut();
    if (!puzzle) {
        document.getElementById('question-text').textContent = 'Not enough data for this round.';
        return;
    }
    gameState.oddPuzzle = puzzle;
    gameState.targetCountry = puzzle.odd;
    gameState.currentAnswer = puzzle.odd;
    if (!gameState.oddHistory) gameState.oddHistory = [];

    // Highlight all four, numbered so the buttons and the map read together.
    highlightOddCandidates(puzzle.options);
    document.getElementById('question-text').innerHTML =
        `Round ${gameState.currentQuestion}/${gameState.totalQuestions} — ` +
        `three of these four have something in common. <strong>Which is the odd one out?</strong>`;
    renderMultipleChoice(puzzle.options, puzzle.odd);
}

// Say what the other three shared, and keep the round for the end-of-game review.
function recordOddAnswer(picked, correct) {
    const p = gameState.oddPuzzle;
    if (!p || p.answered) return;
    p.answered = true;
    p.picked = picked;
    p.correct = correct;
    (gameState.oddHistory = gameState.oddHistory || []).push(p);
    const feedback = document.getElementById('feedback');
    feedback.innerHTML = (correct
        ? `<strong>${p.odd}</strong> — right. `
        : `It was <strong>${p.odd}</strong>. `) +
        `${p.shared.join(', ')} are ${p.why}.`;
    feedback.className = 'feedback ' + (correct ? 'correct' : 'incorrect');
}

// The end-of-game review: all ten rounds with what they shared and what was picked.
function oddOneOutSummaryHtml() {
    const rows = (gameState.oddHistory || []);
    if (!rows.length) return '';
    return `<div class="odd-review"><h3>Every round</h3>` + rows.map((p, i) => `
        <div class="odd-review-row ${p.correct ? 'right' : 'wrong'}">
            <span class="odd-review-n">${i + 1}</span>
            <span class="odd-review-body">
                <strong>${p.odd}</strong> was the odd one out —
                ${p.shared.join(', ')} are ${p.why}.
                ${p.correct ? '' : `<em>You picked ${p.picked}.</em>`}
            </span>
        </div>`).join('') + `</div>`;
}

// Pick a trait, three countries with it and one without — all four drawn on the map, so
// every candidate has to actually exist as geometry.
function buildOddOneOut() {
    const drawn = new Set((gameState.countries || []).map(f => normalizeName(f.properties.name)));
    const list = (gameState.currentQuizList || []).filter(n => drawn.has(normalizeName(n)));
    if (list.length < 8) return null;
    const inList = new Set(list.map(normalizeName));

    const traits = shuffleArray(ODD_TRAITS);
    for (const trait of traits) {
        const groups = shuffleArray(trait.groups().filter(g => g && g.names));
        for (const grp of groups) {
            const members = shuffleArray(grp.names.filter(n => inList.has(normalizeName(n))));
            if (members.length < 3) continue;
            const memberSet = new Set(members.map(normalizeName));
            // A trait may pick its own distractors — see the `neighbour` trait, where a random
            // country from the far side of the world is not a wrong answer anybody would consider.
            const outsiders = trait.outsiders
                ? (trait.outsiders(grp, list.filter(n => !memberSet.has(normalizeName(n)))) || [])
                : list.filter(n => !memberSet.has(normalizeName(n)));
            if (!outsiders.length) continue;
            const odd = outsiders[Math.floor(Math.random() * outsiders.length)];
            return {
                trait: trait.key,
                why: trait.label(grp.tag),
                shared: members.slice(0, 3),
                odd,
                options: shuffleArray(members.slice(0, 3).concat([odd]))
            };
        }
    }
    return null;
}

function highlightOddCandidates(names) {
    if (!countriesGroup) return;
    countriesGroup.selectAll('path').classed('odd-candidate', false);
    countriesGroup.selectAll('path')
        .filter(d => d && d.properties && names.some(n => namesMatch(n, d.properties.parent || d.properties.name)))
        .classed('odd-candidate', true)
        .raise();
    // Frame all four at once: spin to the centroid of the set. r_unconstrained is kept in
    // step on EVERY tick, not just at the end — a drag that interrupts the spin otherwise
    // resumes from the pre-spin rotation and the globe visibly snaps backwards, which reads
    // as the map fighting you rather than panning.
    const feats = (gameState.countries || []).filter(f =>
        names.some(n => namesMatch(n, f.properties.name)));
    if (!feats.length || !projection.rotate) return;
    const c = d3.geoCentroid({ type: 'FeatureCollection', features: feats });
    if (!c || !isFinite(c[0])) return;
    const target = [-c[0], -c[1], 0];
    d3.transition('oddspin').duration(700).tween('oddspin', () => {
        const i = interpolateRotateShortest(projection.rotate(), target);
        return t => {
            // The tween outlives the round that started it — 700 ms is long enough to leave the
            // mode entirely — and the next mode may be on a projection with no rotation at all,
            // since `d3.geoAlbersUsa` is a composite and has none. One frame landing in that gap
            // threw, which is how the map puzzle came to report a rotation error about a board
            // that does not rotate.
            if (!projection || typeof projection.rotate !== 'function') return;
            projection.rotate(i(t));
            r_unconstrained = projection.rotate().slice();
            if (countriesGroup) countriesGroup.selectAll('path').attr('d', path);
            updateIslandMarkers();
        };
    });
}

// ==================== DRAW THE BORDER ====================
// The target country is cut out of the map — its neighbours are drawn, its own outline is
// not — and the player traces where it should be. Scored by how far the drawn loop sits
// from the real one, symmetrically (each sampled point of each loop against the other).
let drawBorderState = null;

function renderDrawBorderQuestion() {
    gameState.questionType = 'draw-border';
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('restart-btn').style.display = 'inline-block';

    const target = pickDrawBorderTarget();
    if (!target) { document.getElementById('question-text').textContent = 'No suitable country.'; return; }
    gameState.targetCountry = target.properties.name;
    gameState.usedCountries.add(gameState.targetCountry);

    // Frame the country's neighbourhood: its own extent, padded, so there is context but the
    // hole is obviously the shape being asked for.
    const core = shapeFramingCore(target) || target;
    projection.fitExtent([[width * 0.22, height * 0.22], [width * 0.78, height * 0.78]], core);
    gameState.initialScale = projection.scale();

    drawBorderState = { points: [], drawing: false, done: false, closed: false, target,
                        baseScale: projection.scale() };
    countriesGroup.selectAll('*').remove();   // drawCountries only appends
    drawCountries();          // repaints with the target hidden (see drawCountries' branch)
    ensureDrawBorderLayer();

    document.getElementById('question-text').innerHTML =
        `Round ${gameState.currentQuestion}/${gameState.totalQuestions} — draw the outline of ` +
        `<strong>${displayLabelForName(gameState.targetCountry)}</strong> in the gap.` +
        `<br><span style="font-size:.85em;opacity:.8">Drag to trace; release to finish.</span>`;
    const next = document.getElementById('next-btn');
    next.textContent = 'Submit';
    next.disabled = true;
    next.style.display = 'inline-block';
    const giveUp = document.getElementById('give-up-btn');
    giveUp.style.display = 'inline-block';
    giveUp.textContent = 'Show Answer';
}

// The board: context WITHOUT the answer. On the world map that means coastlines only — no
// country borders at all, so a landlocked target leaves no trace — and on a state map it means
// every other border, foreign and internal. Either way, every arc the target owns is dropped,
// which is what leaves the hole to be traced.
//
// It is done with topojson.mesh's filter rather than by drawing features and hiding one:
// mesh receives the two geometries sharing each arc (the same one twice for an exterior arc),
// so "not the target's" and "coastline only" are both just predicates on that pair. Drawing
// per-feature can't express it — a neighbour's outline still traces the target's border.
function drawBorderBoard() {
    const mc = QUIZ_MODES[gameState.mode];
    const target = gameState.targetCountry;
    const topo = gameState.mapTopology;
    const objName = mc.mapObject;
    const obj = topo && objName && topo.objects && topo.objects[objName];

    if (obj && topojson.mesh) {
        const nameOf = geom => objName === 'states' ? getStateName(geom.id) : getCountryName(geom.id);
        const isTarget = geom => target && namesMatch(nameOf(geom), target);
        // EXTERIOR arcs only, on every board. On the world that means coastlines with no
        // country borders; on a state map it means the coast and the international border of
        // the whole union, with no state lines — the same question either way, and a state is
        // as hard to place among its neighbours as a country is.
        const mesh = topojson.mesh(topo, obj, (a, b) => a === b && !isTarget(a));
        shadeCoastline(mesh, obj, isTarget);
        const d = path(mesh);
        if (d) countriesGroup.append('path').attr('class', 'draw-context').attr('d', d);
        return;
    }

    // GeoJSON regions (India, Germany, England, Mexico) ship no arcs to filter, so the
    // neighbours are outlined and the target's own edge is then painted out along its path.
    countriesGroup.selectAll('path.draw-context')
        .data(gameState.countries.filter(f => !namesMatch(f.properties.name, target)))
        .enter().append('path')
        .attr('class', 'draw-context')
        .attr('d', path);
    const tf = (gameState.countries || []).find(f => namesMatch(f.properties.name, target));
    if (tf) {
        countriesGroup.append('path').attr('class', 'draw-erase').attr('d', path(tf));
    }
}

// Which way is the sea? A hard black coastline with a blurred blue band fading away from it on
// the water side only. The band is the same wide stroke as the line, masked to everything that
// is NOT land — masking is what makes it one-sided, since a stroke has no idea which of its
// flanks is water.
//
// There used to be a brown band on the inland flank as well. It said nothing the line had not
// already said (there is a coast here), and it put a smudge over the ground the player has to
// trace their border across.
function shadeCoastline(mesh, obj, isTarget) {
    const d = path(mesh);
    if (!d) return;
    let defs = svg.select('defs');
    if (defs.empty()) defs = svg.append('defs');
    defs.selectAll('#coast-blur, #coast-sea-mask').remove();

    const blur = defs.append('filter').attr('id', 'coast-blur')
        .attr('x', '-30%').attr('y', '-30%').attr('width', '160%').attr('height', '160%');
    blur.append('feGaussianBlur').attr('stdDeviation', 4);

    // The land, minus the country being asked for (its own shore is not shaded either).
    const land = { type: 'FeatureCollection', features: (gameState.countries || [])
        .filter(f => !namesMatch(f.properties.name, gameState.targetCountry)) };
    const landPath = path(land);
    if (!landPath) return;

    // Sea = the whole board with the land punched out.
    const mask = defs.append('mask').attr('id', 'coast-sea-mask');
    mask.append('rect').attr('x', -width).attr('y', -height)
        .attr('width', width * 3).attr('height', height * 3).attr('fill', '#fff');
    mask.append('path').attr('d', landPath).attr('fill', '#000');

    const shade = countriesGroup.append('g').attr('class', 'coast-shade');
    shade.append('path').attr('class', 'coast-shade-sea').attr('d', d)
        .attr('mask', 'url(#coast-sea-mask)').attr('filter', 'url(#coast-blur)');
    // The shore itself, hard and black on top of the fade. The board is otherwise all thin grey
    // context lines, so this is what says "this edge is real, the rest is background".
    shade.append('path').attr('class', 'coast-line').attr('d', d);
}

function pickDrawBorderTarget() {
    const feats = (gameState.countries || []).filter(f => {
        const n = f.properties && f.properties.name;
        if (!n || gameState.usedCountries.has(n)) return false;
        if (!(gameState.currentQuizList || []).some(q => namesMatch(q, n))) return false;
        // Big enough to trace: at least a hundredth of a steradian keeps it to countries with
        // a recognisable outline rather than specks.
        return d3.geoArea(f) > 0.0015;
    });
    if (!feats.length) return null;
    return feats[Math.floor(Math.random() * feats.length)];
}

function ensureDrawBorderLayer() {
    if (!svg) return;
    g.selectAll('.draw-border-layer').remove();
    const layer = g.append('g').attr('class', 'draw-border-layer');
    layer.append('path').attr('class', 'draw-border-truth').style('display', 'none');
    layer.append('path').attr('class', 'draw-border-ink');
    svg.on('pointerdown.draw', startBorderStroke);
}

function startBorderStroke(event) {
    if (!drawBorderState || drawBorderState.done) return;
    event.preventDefault();
    drawBorderState.points = [];
    drawBorderState.drawing = true;
    window.addEventListener('pointermove', onBorderStrokeMove);
    window.addEventListener('pointerup', endBorderStroke);
    window.addEventListener('pointercancel', endBorderStroke);
    onBorderStrokeMove(event);
}

// Points are kept in LON/LAT, not screen pixels: the board zooms, and a stroke recorded in
// pixels would drift off the map the moment it did (and score against the wrong place).
function onBorderStrokeMove(event) {
    if (!drawBorderState || !drawBorderState.drawing) return;
    const p = d3.pointer(event, svg.node());
    if (!p || isNaN(p[0])) return;
    const geo = projection.invert ? projection.invert(p) : null;
    if (!geo || isNaN(geo[0])) return;
    const pts = drawBorderState.points;
    const last = pts.length ? projection(pts[pts.length - 1]) : null;
    if (last && Math.hypot(p[0] - last[0], p[1] - last[1]) < 2) return;   // thin the stream
    pts.push(geo);
    renderBorderInk(false);
}

// Project the stroke for the current view. `close` draws the loop shut, which is what the
// scorer measures against.
function renderBorderInk(close) {
    if (!drawBorderState) return;
    const pts = drawBorderState.points.map(q => projection(q)).filter(q => q && !isNaN(q[0]));
    if (pts.length < 2) { g.select('.draw-border-ink').attr('d', null); return; }
    g.select('.draw-border-ink').attr('d',
        'M' + pts.map(q => q[0].toFixed(1) + ',' + q[1].toFixed(1)).join('L') + (close ? 'Z' : ''));
}

function endBorderStroke() {
    if (!drawBorderState) return;
    drawBorderState.drawing = false;
    window.removeEventListener('pointermove', onBorderStrokeMove);
    window.removeEventListener('pointerup', endBorderStroke);
    window.removeEventListener('pointercancel', endBorderStroke);
    if (drawBorderState.points.length > 4) {
        drawBorderState.closed = true;
        renderBorderInk(true);
        document.getElementById('next-btn').disabled = false;
    }
}

// Re-path everything after a zoom: the context map, its shading, the stroke, the answer.
function redrawDrawBorder() {
    if (!drawBorderState || !countriesGroup) return;
    countriesGroup.selectAll('*').remove();
    drawBorderBoard();
    renderBorderInk(!!drawBorderState.closed);
    if (drawBorderState.done) g.select('.draw-border-truth').attr('d', path(drawBorderState.target));
}

// Zoom, about the cursor, bounded either side of the framing this round was fitted to. The
// floor is well below 1 because pulling BACK is how you place a shape: the round fits the
// neighbourhood, and to know whether you are drawing Uruguay in the right part of South America
// you have to be able to see South America.
const DRAW_ZOOM_MIN = 0.3, DRAW_ZOOM_MAX = 3.5;
function zoomDrawBorder(event) {
    if (!drawBorderState || drawBorderState.drawing) return;
    const base = drawBorderState.baseScale || projection.scale();
    const delta = -event.deltaY * (event.deltaMode === 1 ? 0.05 : event.deltaMode ? 1 : 0.002);
    const next = Math.max(base * DRAW_ZOOM_MIN, Math.min(base * DRAW_ZOOM_MAX,
        projection.scale() * Math.pow(2, delta)));
    if (next === projection.scale()) return;
    const mouse = d3.pointer(event, svg.node());
    const geo = projection.invert ? projection.invert(mouse) : null;
    projection.scale(next);
    if (geo && !isNaN(geo[0])) {
        const after = projection(geo);      // keep the point under the cursor put
        if (after && !isNaN(after[0])) {
            const t = projection.translate();
            projection.translate([t[0] + (mouse[0] - after[0]), t[1] + (mouse[1] - after[1])]);
        }
    }
    redrawDrawBorder();
}

// Mean distance in km between the drawn loop and the true outline, measured BOTH ways: a
// scribble inside the country would score well one-way, and a loop round the whole continent
// would score well the other way. Only the symmetric mean punishes both.
function scoreDrawnBorder() {
    const st = drawBorderState;
    if (!st || st.points.length < 5) return null;
    const truth = borderSamplePoints(st.target, 160);
    if (!truth.length) return null;
    const drawn = st.points.slice();   // already lon/lat
    if (drawn.length < 5) return null;

    const sym = (a, b) => (drawMeanNearest(a, b) + drawMeanNearest(b, a)) / 2;
    const overall = sym(drawn, truth);

    // The same error splits two ways, and people fail in one way or the other rather than in
    // both: the right shape in the wrong place, or the right place with the wrong shape. One
    // number averages those into something that describes neither.
    //
    // POSITION is the gap between the two loops' centroids. FORM is the symmetric mean again,
    // measured after sliding the drawn loop onto the true centroid — which removes exactly the
    // placement error and leaves whatever is left over, i.e. size and shape.
    const cen = pts => {
        let x = 0, y = 0, z = 0;
        pts.forEach(([lo, la]) => {
            const p = lo * DEG, t = la * DEG, c = Math.cos(t);
            x += c * Math.cos(p); y += c * Math.sin(p); z += Math.sin(t);
        });
        const r = Math.hypot(x, y, z) || 1;
        return [Math.atan2(y, x) / DEG, Math.asin(z / r) / DEG];
    };
    const cd = cen(drawn), ct = cen(truth);
    const positionKm = d3.geoDistance(cd, ct) * EARTH_R_KM;
    // Slide, don't rotate: a lon/lat offset is what "you drew it in the wrong place" means, and
    // the cos correction keeps the shift a real distance rather than a number of degrees.
    const dLat = ct[1] - cd[1];
    const dLon = (ct[0] - cd[0]);
    const shifted = drawn.map(([lo, la]) => [lo + dLon, Math.max(-89, Math.min(89, la + dLat))]);
    const formKm = sym(shifted, truth);
    return { overall, positionKm, formKm };
}

function drawMeanNearest(from, to) {
    let sum = 0;
    for (const p of from) {
        let best = Infinity;
        for (const q of to) {
            const d = d3.geoDistance(p, q);
            if (d < best) best = d;
        }
        sum += best;
    }
    return sum / from.length * EARTH_R_KM;
}

// Evenly-ish spaced points along the feature's largest ring.
function borderSamplePoints(feature, n) {
    const parts = featureParts(feature);
    if (!parts.length) return [];
    let ring = null, bestLen = 0;
    parts.forEach(p => { if (p[0] && p[0].length > bestLen) { bestLen = p[0].length; ring = p[0]; } });
    if (!ring) return [];
    const step = Math.max(1, Math.floor(ring.length / n));
    const out = [];
    for (let i = 0; i < ring.length; i += step) out.push(ring[i]);
    return out;
}

function revealDrawnBorder() {
    const st = drawBorderState;
    if (!st || st.done) return;
    st.done = true;
    svg.on('pointerdown.draw', null);
    g.select('.draw-border-truth').style('display', null).attr('d', path(st.target));

    const res = scoreDrawnBorder();
    const feedback = document.getElementById('feedback');
    if (res == null) {
        feedback.textContent = 'Nothing drawn — the outline is shown in green.';
        feedback.className = 'feedback partial';
    } else {
        // Five points for putting it in the right place and five for getting the shape right,
        // rather than ten for a single averaged miss. Scoring the two separately is what makes
        // the split worth reporting: a good outline dropped in the wrong country used to be
        // worth almost nothing, which told the player their trace was bad when it was their
        // placement that was.
        const posPts = 5 * Math.exp(-res.positionKm / DRAW_BORDER_SCALE_KM);
        const formPts = 5 * Math.exp(-res.formKm / DRAW_BORDER_FORM_SCALE_KM);
        const points = Math.round(posPts + formPts);
        gameState.score += points;
        gameState.drawErrors = (gameState.drawErrors || []).concat(res.overall);
        document.getElementById('score').textContent = gameState.score;
        syncScoreDisplay();
        const word = (v, good, ok) => v < good ? 'good' : (v < ok ? 'close' : 'off');
        feedback.innerHTML =
            `<strong>+${points}</strong> — average miss ${Math.round(res.overall).toLocaleString()} km<br>` +
            `<span style="font-size:.9em">Position <strong>${Math.round(posPts)}/5</strong> ` +
            `(centre ${Math.round(res.positionKm).toLocaleString()} km ${word(res.positionKm, 150, 400)}) ` +
            `· Shape <strong>${Math.round(formPts)}/5</strong> ` +
            `(${Math.round(res.formKm).toLocaleString()} km ${word(res.formKm, 120, 320)})</span>`;
        feedback.className = 'feedback ' + (points >= 7 ? 'correct' : points >= 4 ? 'partial' : 'incorrect');
    }
    const next = document.getElementById('next-btn');
    next.textContent = gameState.currentQuestion >= gameState.totalQuestions ? 'See Results' : 'Next';
    next.disabled = false;
    document.getElementById('give-up-btn').style.display = 'none';
}

const DRAW_BORDER_SCALE_KM = 250;   // centre offset at which the position half scores ~37%
// Form is judged tighter than position: once the loop is sitting on the right place, being
// 200 km out on its outline is a much worse trace than being 200 km out on where you put it.
const DRAW_BORDER_FORM_SCALE_KM = 180;

// ==================== SUN & MOON ====================
// View-only: where the sun and moon are directly overhead right now (or at any date/time you
// pick), the sunrise line between them, and the night side shaded. All of it is drawn with
// d3.geoCircle — the night hemisphere IS a 90° circle around the antisolar point, and the
// twilight bands are the same circle at 96° and 102°, so the projection does all the work
// and the shapes stay correct on the globe and the flat map alike.
//
// The astronomy is the standard low-precision series (sun ~0.01°, moon ~0.3°) — far below
// what a pixel on a world map can show, and it needs no ephemeris data.

let sunMoonState = null;   // { date, showZones, satellite, rasterToken }

function julianDay(date) { return date.getTime() / 86400000 + 2440587.5; }

// Greenwich mean sidereal time, in hours.
function gmstHours(jd) {
    const d = jd - 2451545.0;
    return ((18.697374558 + 24.06570982441908 * d) % 24 + 24) % 24;
}

const DEG = Math.PI / 180;

// Equatorial → the point on Earth where that body is directly overhead.
function subPointFrom(raDeg, decDeg, jd) {
    let lon = raDeg - gmstHours(jd) * 15;
    lon = ((lon % 360) + 540) % 360 - 180;
    return [lon, decDeg];
}

// Sun: mean longitude + equation of centre, then obliquity. (Astronomical Almanac's
// "low precision formulae for the Sun", good to ~0.01° for a century either side of 2000.)
function solarPosition(date) {
    const jd = julianDay(date);
    const n = jd - 2451545.0;
    const L = (280.460 + 0.9856474 * n) % 360;
    const g = ((357.528 + 0.9856003 * n) % 360) * DEG;
    const lambda = (L + 1.915 * Math.sin(g) + 0.020 * Math.sin(2 * g)) * DEG;
    const eps = (23.439 - 0.0000004 * n) * DEG;
    const dec = Math.asin(Math.sin(eps) * Math.sin(lambda));
    const ra = Math.atan2(Math.cos(eps) * Math.sin(lambda), Math.cos(lambda));
    return { sub: subPointFrom(ra / DEG, dec / DEG, jd), lambda: lambda / DEG, jd };
}

// Moon: the truncated ELP series everyone uses for a quick position — the four biggest
// longitude terms and the two biggest latitude ones. ~0.3°, which is a third of the moon's
// own width and invisible at world-map scale.
function lunarPosition(date) {
    const jd = julianDay(date);
    const d = jd - 2451545.0;
    const L = (218.316 + 13.176396 * d) * DEG;   // mean longitude
    const M = (134.963 + 13.064993 * d) * DEG;   // mean anomaly
    const F = (93.272 + 13.229350 * d) * DEG;    // argument of latitude
    const D = (297.850 + 12.190749 * d) * DEG;   // mean elongation from the sun
    const lambda = (L / DEG + 6.289 * Math.sin(M) + 1.274 * Math.sin(2 * D - M)
                    + 0.658 * Math.sin(2 * D) + 0.214 * Math.sin(2 * M)) * DEG;
    const beta = (5.128 * Math.sin(F) + 0.281 * Math.sin(M + F)) * DEG;
    const eps = (23.439 - 0.0000004 * d) * DEG;
    const ra = Math.atan2(Math.sin(lambda) * Math.cos(eps) - Math.tan(beta) * Math.sin(eps),
                          Math.cos(lambda));
    const dec = Math.asin(Math.sin(beta) * Math.cos(eps) +
                          Math.cos(beta) * Math.sin(eps) * Math.sin(lambda));
    return { sub: subPointFrom(ra / DEG, dec / DEG, jd), lambda: lambda / DEG };
}

// Illuminated fraction, from the sun–moon elongation. 0 = new, 1 = full.
function moonPhase(date) {
    const sun = solarPosition(date), moon = lunarPosition(date);
    const elong = ((moon.lambda - sun.lambda) % 360 + 360) % 360;
    return { fraction: (1 - Math.cos(elong * DEG)) / 2, elongation: elong };
}

function phaseName(elong) {
    const names = ['New', 'Waxing crescent', 'First quarter', 'Waxing gibbous',
                   'Full', 'Waning gibbous', 'Last quarter', 'Waning crescent'];
    return names[Math.floor(((elong + 22.5) % 360) / 45)];
}

function antipode(p) { return [((p[0] + 360) % 360) - 180, -p[1]]; }

function renderSunMoonMode() {
    gameState.questionType = 'sun-moon';
    gameState.scrollLocked = false;
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'none';
    const restart = document.getElementById('restart-btn');
    restart.style.display = 'inline-block';
    restart.textContent = 'Exit';
    restart.onclick = goHome;

    if (!sunMoonState) sunMoonState = { date: new Date(), showZones: false, satellite: false };
    document.getElementById('question-text').innerHTML =
        '<strong>Sun &amp; Moon</strong> — where each is directly overhead, the sunrise line ' +
        'between them, and the night side shaded. Pick any date and time in the panel.';
    buildSunMoonPanel();
    drawSunMoonLayers();
}

// ---- the drawing ----
// Night is a 90° cap round the antisolar point; twilight is the same cap at 96° and 102°.
// Stacking the three (widest first) makes the bands for free — each adds its own alpha.
const TWILIGHT_RADII = [102, 96, 90];

function drawSunMoonLayers() {
    if (!svg || !sunMoonState || !g) return;
    g.selectAll('.sun-moon-layer').remove();
    const layer = g.append('g').attr('class', 'sun-moon-layer');

    const date = sunMoonState.date;
    const sun = solarPosition(date).sub;
    const moon = lunarPosition(date).sub;
    const dark = antipode(sun);

    drawLatitudeLines(layer);
    if (sunMoonState.showZones) drawNauticalZones(layer);

    TWILIGHT_RADII.forEach((r, i) => {
        const cap = d3.geoCircle().center(dark).radius(r)();
        const d = path(cap);
        if (d) layer.append('path').attr('class', 'sun-moon-night night-' + i).attr('d', d);
    });
    // The sunrise/sunset line itself.
    const term = path(d3.geoCircle().center(dark).radius(90)());
    if (term) layer.append('path').attr('class', 'sun-moon-terminator').attr('d', term);
    // And the same line for the moon — where it is rising or setting right now. Dotted, so
    // the two never read as the same thing.
    const moonLine = path(d3.geoCircle().center(antipode(moon)).radius(90)());
    if (moonLine) layer.append('path').attr('class', 'sun-moon-moonline').attr('d', moonLine);

    markSubPoint(layer, sun, 'sun', '☀');
    markMoon(layer, moon, sun, date);
    if (sunMoonState.here) markHere(layer, sunMoonState.here);
    renderSunMoonReadout();
}

// The tropics and the polar circles: the latitudes where the sun's behaviour changes, which
// is the whole point of the view. Their positions ARE the obliquity, so they are derived from
// it rather than typed in — at 23.44° and 90−23.44°.
const OBLIQUITY_DEG = 23.4392911;
function drawLatitudeLines(layer) {
    const lines = layer.append('g').attr('class', 'sun-moon-latlines');
    const marks = [
        { lat: OBLIQUITY_DEG, cls: 'tropic', label: 'Tropic of Cancer' },
        { lat: -OBLIQUITY_DEG, cls: 'tropic', label: 'Tropic of Capricorn' },
        { lat: 90 - OBLIQUITY_DEG, cls: 'polar', label: 'Arctic Circle' },
        { lat: -(90 - OBLIQUITY_DEG), cls: 'polar', label: 'Antarctic Circle' },
        { lat: 0, cls: 'equator', label: 'Equator' }
    ];
    marks.forEach(m => {
        const line = { type: 'LineString', coordinates: d3.range(-180, 181, 3).map(lon => [lon, m.lat]) };
        const d = path(line);
        if (!d) return;
        lines.append('path').attr('class', 'sun-moon-latline ' + m.cls).attr('d', d);
        // One label per line, placed wherever that parallel is currently facing us.
        const anchorLon = isGlobeView() && projection.rotate ? -projection.rotate()[0] : -160;
        const p = projection([anchorLon + 30, m.lat]);
        if (p && !isNaN(p[0]) && onVisibleSide([anchorLon + 30, m.lat])) {
            lines.append('text').attr('class', 'sun-moon-latlabel')
                .attr('x', p[0]).attr('y', p[1] - 3).text(m.label);
        }
    });
}

// The moon drawn as it actually looks: a disc with the terminator as an ellipse, rotated so
// the bright limb points at the sun. The lit fraction sets the ellipse's width — |1−2k| — so
// k=0.5 collapses it to a straight line (half moon) and k=1 bulges it back out to the full
// circle. The position angle is taken on screen, from the moon's sub-point toward the sun's,
// which is what a viewer under it would see.
function markMoon(layer, moonPt, sunPt, date) {
    const p = projection(moonPt);
    if (!p || isNaN(p[0]) || !onVisibleSide(moonPt)) return;
    const k = moonPhase(date).fraction;
    const r = 11;
    const sp = projection(sunPt);
    const ang = (sp && !isNaN(sp[0])) ? Math.atan2(sp[1] - p[1], sp[0] - p[0]) * 180 / Math.PI : 0;
    const rx = r * Math.abs(1 - 2 * k);
    const inner = k > 0.5 ? 1 : 0;
    const gp = layer.append('g').attr('class', 'sun-moon-mark moon')
        .attr('transform', `translate(${p[0].toFixed(1)},${p[1].toFixed(1)}) rotate(${ang.toFixed(1)})`);
    gp.append('circle').attr('class', 'moon-dark').attr('r', r);
    gp.append('path').attr('class', 'moon-lit')
        .attr('d', `M0,${-r} A${r},${r} 0 0 1 0,${r} A${rx.toFixed(2)},${r} 0 0 ${inner} 0,${-r} Z`);
}

// The viewer's own position, if they have shared it.
function markHere(layer, here) {
    const p = projection(here);
    if (!p || isNaN(p[0]) || !onVisibleSide(here)) return;
    const gp = layer.append('g').attr('class', 'sun-moon-here');
    gp.append('circle').attr('cx', p[0]).attr('cy', p[1]).attr('r', 5);
    gp.append('circle').attr('class', 'here-ring').attr('cx', p[0]).attr('cy', p[1]).attr('r', 10);
    gp.append('text').attr('x', p[0]).attr('y', p[1] - 14).attr('text-anchor', 'middle').text('You');
}

// A body's sub-point, hidden when it is round the back of the globe.
function markSubPoint(layer, lonlat, cls, glyph) {
    const p = projection(lonlat);
    if (!p || isNaN(p[0]) || !onVisibleSide(lonlat)) return;
    const gp = layer.append('g').attr('class', 'sun-moon-mark ' + cls);
    gp.append('circle').attr('cx', p[0]).attr('cy', p[1]).attr('r', 11);
    gp.append('text').attr('x', p[0]).attr('y', p[1]).attr('text-anchor', 'middle')
      .attr('dy', '0.35em').text(glyph);
}

// On the orthographic globe, is this point on the near side?
function onVisibleSide(lonlat) {
    if (!isGlobeView() || !projection.rotate) return true;
    const r = projection.rotate();
    return d3.geoDistance(lonlat, [-r[0], -r[1]]) < Math.PI / 2;
}

// Nautical time zones: 15° bands centred on each multiple of 15°, which is what the sun
// actually does. Political zones wander all over that and would need their own dataset.
function drawNauticalZones(layer) {
    const zones = layer.append('g').attr('class', 'sun-moon-zones');
    for (let k = -12; k < 12; k++) {
        const edge = k * 15 + 7.5;
        const line = { type: 'LineString', coordinates: d3.range(-80, 81, 4).map(lat => [edge, lat]) };
        const d = path(line);
        if (d) zones.append('path').attr('class', 'sun-moon-zone-line').attr('d', d);
    }
    for (let k = -11; k <= 12; k++) {
        const centre = [k * 15, 0];
        if (!onVisibleSide(centre)) continue;
        const p = projection(centre);
        if (!p || isNaN(p[0])) continue;
        zones.append('text').attr('class', 'sun-moon-zone-label')
            .attr('x', p[0]).attr('y', p[1]).attr('text-anchor', 'middle')
            .text(k === 0 ? 'UTC' : (k > 0 ? '+' + k : String(k)));
    }
}

// Called from updateIslandMarkers, i.e. after every re-path of the map.
function updateModeOverlays() {
    const mc = QUIZ_MODES[gameState.mode];
    if (!mc) return;
    if (mc.sunMoonMode && sunMoonState) {
        drawSunMoonLayers();
        if (sunMoonState.satellite) scheduleSunMoonRaster();
    }
    if (mc.drawBorderMode && drawBorderState && drawBorderState.done) {
        g.select('.draw-border-truth').attr('d', path(drawBorderState.target));
    }
    if (mc.sbQuizMode) sbUpdateOverlay();
    if (mc.missingSandboxMode) msDrawStory();
}

// ---- satellite ----
// The Blue Marble texture is equirectangular, so any projection can be filled from it by
// walking destination pixels, inverting each to a lon/lat and sampling. Half-resolution and
// debounced: it is a still image that only changes when the map does, so a one-off ~20 ms
// reprojection is cheaper than any per-frame trickery.
const SUNMOON_RASTER_W = 480;
let sunMoonTexture = null;      // { data, w, h } sampled once from the jpg
let sunMoonRasterTimer = null;

function loadSunMoonTexture() {
    if (sunMoonTexture) return Promise.resolve(sunMoonTexture);
    return new Promise(resolve => {
        const img = new Image();
        img.onload = () => {
            const w = 1024, h = 512;
            const cv = document.createElement('canvas');
            cv.width = w; cv.height = h;
            const ctx = cv.getContext('2d', { willReadFrequently: true });
            ctx.drawImage(img, 0, 0, w, h);
            try {
                sunMoonTexture = { data: ctx.getImageData(0, 0, w, h).data, w, h };
            } catch (_) { sunMoonTexture = null; }
            resolve(sunMoonTexture);
        };
        img.onerror = () => resolve(null);
        img.src = EARTH_TEX_LOW;
    });
}

function scheduleSunMoonRaster() {
    if (sunMoonRasterTimer) clearTimeout(sunMoonRasterTimer);
    sunMoonRasterTimer = setTimeout(drawSunMoonRaster, 120);
}

function drawSunMoonRaster() {
    sunMoonRasterTimer = null;
    if (!sunMoonState || !sunMoonState.satellite || !g) return;
    loadSunMoonTexture().then(tex => {
        if (!tex || !sunMoonState || !sunMoonState.satellite) return;
        const w = SUNMOON_RASTER_W, h = Math.round(w * height / width);
        const cv = document.createElement('canvas');
        cv.width = w; cv.height = h;
        const ctx = cv.getContext('2d');
        const out = ctx.createImageData(w, h);
        const sx = width / w, sy = height / h;
        for (let y = 0; y < h; y++) {
            for (let x = 0; x < w; x++) {
                const px = x * sx, py = y * sy;
                const ll = projection.invert ? projection.invert([px, py]) : null;
                const o = (y * w + x) * 4;
                if (!ll || isNaN(ll[0]) || Math.abs(ll[1]) > 90) { out.data[o + 3] = 0; continue; }
                // Orthographic's invert happily returns a lon/lat for pixels OUTSIDE the disc
                // (and Mercator's wraps past ±180), so a pixel only counts if projecting the
                // answer lands back where it started. One round-trip, no per-projection maths.
                const back = projection(ll);
                if (!back || Math.abs(back[0] - px) > 1.5 || Math.abs(back[1] - py) > 1.5) {
                    out.data[o + 3] = 0; continue;
                }
                const tx = Math.min(tex.w - 1, Math.max(0, Math.floor((ll[0] + 180) / 360 * tex.w)));
                const ty = Math.min(tex.h - 1, Math.max(0, Math.floor((90 - ll[1]) / 180 * tex.h)));
                const s = (ty * tex.w + tx) * 4;
                out.data[o] = tex.data[s]; out.data[o + 1] = tex.data[s + 1];
                out.data[o + 2] = tex.data[s + 2]; out.data[o + 3] = 255;
            }
        }
        ctx.putImageData(out, 0, 0);
        let img = g.select('.sun-moon-raster');
        if (img.empty()) img = g.insert('image', ':first-child').attr('class', 'sun-moon-raster');
        // PNG, not JPEG: everything off the globe is transparent, and JPEG has no alpha —
        // it would flatten the whole surround to a black rectangle over the map.
        img.attr('x', 0).attr('y', 0).attr('width', width).attr('height', height)
           .attr('preserveAspectRatio', 'none')
           .attr('href', cv.toDataURL('image/png'));
    });
}

function clearSunMoonRaster() {
    if (g) g.selectAll('.sun-moon-raster').remove();
}

// ---- panel ----
function buildSunMoonPanel() {
    let panel = document.getElementById('sun-moon-panel');
    if (!panel) {
        panel = document.createElement('div');
        panel.id = 'sun-moon-panel';
        panel.className = 'sandbox-panel';
        panel.innerHTML = `
            <div class="sandbox-title">Sun &amp; Moon</div>
            <div class="sandbox-readout" id="sun-moon-readout"></div>
            <div class="sandbox-edit">
                <label class="sandbox-slider"><span>Date</span>
                    <input type="date" id="sun-moon-date"></label>
                <label class="sandbox-slider"><span>Time</span>
                    <input type="time" id="sun-moon-time"></label>
                <div class="sandbox-nudge">
                    <button class="btn secondary" data-shift="-1440">−1d</button>
                    <button class="btn secondary" data-shift="-60">−1h</button>
                    <button class="btn secondary" data-shift="60">+1h</button>
                    <button class="btn secondary" data-shift="1440">+1d</button>
                </div>
                <label class="sun-moon-check"><input type="checkbox" id="sun-moon-zones"> Time-zone overlay</label>
                <label class="sun-moon-check"><input type="checkbox" id="sun-moon-sat"> Satellite imagery</label>
            </div>
            <div class="sandbox-actions">
                <button class="btn secondary" id="sun-moon-now">Now</button>
                <button class="btn secondary" id="sun-moon-here">Locate me</button>
                <button class="btn" id="sun-moon-play">▶ Play year</button>
            </div>
            <div class="sandbox-status" id="sun-moon-status" role="status">
                Times are UTC. Drag the globe to spin it.</div>`;
        (document.getElementById('globe-side-panel') || document.body).appendChild(panel);

        panel.querySelectorAll('[data-shift]').forEach(b => b.addEventListener('click', () => {
            sunMoonState.date = new Date(sunMoonState.date.getTime() + (+b.dataset.shift) * 60000);
            syncSunMoonInputs(); drawSunMoonLayers();
        }));
        document.getElementById('sun-moon-now').addEventListener('click', () => {
            stopSunMoonTour();
            sunMoonState.date = new Date();
            syncSunMoonInputs(); drawSunMoonLayers();
        });
        document.getElementById('sun-moon-here').addEventListener('click', locateSunMoonViewer);
        document.getElementById('sun-moon-play').addEventListener('click', toggleSunMoonTour);
        ['sun-moon-date', 'sun-moon-time'].forEach(id =>
            document.getElementById(id).addEventListener('input', readSunMoonInputs));
        document.getElementById('sun-moon-zones').addEventListener('change', function () {
            sunMoonState.showZones = this.checked; drawSunMoonLayers();
        });
        document.getElementById('sun-moon-sat').addEventListener('change', function () {
            sunMoonState.satellite = this.checked;
            document.querySelector('.container').classList.toggle('satellite-map', this.checked);
            if (this.checked) drawSunMoonRaster(); else clearSunMoonRaster();
        });
    }
    panel.style.display = '';
    syncSunMoonInputs();
}

// The inputs are UTC, so the date/time boxes are filled from the UTC parts rather than the
// local ones — otherwise a user east of Greenwich sees the clock jump when they press Now.
function syncSunMoonInputs() {
    const d = sunMoonState.date;
    const p2 = n => String(n).padStart(2, '0');
    const dateEl = document.getElementById('sun-moon-date');
    const timeEl = document.getElementById('sun-moon-time');
    if (dateEl) dateEl.value = `${d.getUTCFullYear()}-${p2(d.getUTCMonth() + 1)}-${p2(d.getUTCDate())}`;
    if (timeEl) timeEl.value = `${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())}`;
}

function readSunMoonInputs() {
    const dateEl = document.getElementById('sun-moon-date');
    const timeEl = document.getElementById('sun-moon-time');
    if (!dateEl || !timeEl || !dateEl.value) return;
    const [Y, M, D] = dateEl.value.split('-').map(Number);
    const [h, m] = (timeEl.value || '00:00').split(':').map(Number);
    const next = new Date(Date.UTC(Y, M - 1, D, h || 0, m || 0));
    if (!isFinite(next.getTime())) return;
    sunMoonState.date = next;
    drawSunMoonLayers();
}

function renderSunMoonReadout() {
    const el = document.getElementById('sun-moon-readout');
    if (!el || !sunMoonState) return;
    const d = sunMoonState.date;
    const sun = solarPosition(d).sub, moon = lunarPosition(d).sub;
    const ph = moonPhase(d);
    const fmt = p => `${Math.abs(p[1]).toFixed(1)}°${p[1] >= 0 ? 'N' : 'S'}, ` +
                     `${Math.abs(p[0]).toFixed(1)}°${p[0] >= 0 ? 'E' : 'W'}`;
    el.innerHTML =
        `<strong>${d.toISOString().slice(0, 16).replace('T', ' ')} UTC</strong><br>` +
        `☀ overhead at ${fmt(sun)}<br>` +
        `☾ overhead at ${fmt(moon)}<br>` +
        `<span class="sandbox-note">${phaseName(ph.elongation)} · ` +
        `${Math.round(ph.fraction * 100)}% lit</span>`;
}

// Geolocation is a permission prompt, so it only ever runs from this button — never on load.
function locateSunMoonViewer() {
    const status = document.getElementById('sun-moon-status');
    if (!navigator.geolocation) { status.textContent = 'This browser has no location support.'; return; }
    status.textContent = 'Asking your browser for your location…';
    navigator.geolocation.getCurrentPosition(
        pos => {
            if (!sunMoonState) return;
            sunMoonState.here = [pos.coords.longitude, pos.coords.latitude];
            status.textContent = `You are at ${pos.coords.latitude.toFixed(2)}°, ${pos.coords.longitude.toFixed(2)}°.`;
            if (isGlobeView() && projection.rotate) {
                projection.rotate([-sunMoonState.here[0], -sunMoonState.here[1], 0]);
                r_unconstrained = projection.rotate().slice();
                countriesGroup.selectAll('path').attr('d', path);
            }
            updateIslandMarkers();
            drawSunMoonLayers();
        },
        err => { status.textContent = 'Location unavailable (' + err.message + ').'; },
        { timeout: 10000, maximumAge: 600000 }
    );
}

// ---- The scripted year ----
// Walks a whole year in ~40 s, pausing at the four turning points to say what the lines on
// the map are doing. The date does the moving; the layers already follow it, so the tour is
// just a clock plus a caption track.
const SUN_TOUR_DAYS_PER_SEC = 9.5;         // ~38 s for a full year
const SUN_TOUR_STOPS = [
    { md: '03-20', title: 'March equinox',
      text: 'Day and night are equal everywhere. The terminator runs pole to pole, and the sun is overhead on the equator.' },
    { md: '06-21', title: 'June solstice',
      text: 'The sun is overhead on the Tropic of Cancer — its furthest north. Everywhere inside the Arctic Circle has 24-hour daylight; the Antarctic Circle has none.' },
    { md: '09-22', title: 'September equinox',
      text: 'Back to equal day and night, with the sun crossing the equator southbound.' },
    { md: '12-21', title: 'December solstice',
      text: 'The sun is overhead on the Tropic of Capricorn. Now it is the Antarctic Circle in permanent daylight and the Arctic in permanent night.' }
];
let sunTour = null;

function toggleSunMoonTour() {
    if (sunTour) { stopSunMoonTour(); return; }
    const year = sunMoonState.date.getUTCFullYear();
    sunTour = {
        year,
        date: new Date(Date.UTC(year, 0, 1, 12, 0)),
        last: performance.now(),
        held: 0,
        stop: null,
        raf: null
    };
    document.getElementById('sun-moon-play').textContent = '■ Stop';
    sunTour.raf = requestAnimationFrame(stepSunMoonTour);
}

function stopSunMoonTour() {
    if (!sunTour) return;
    cancelAnimationFrame(sunTour.raf);
    sunTour = null;
    const btn = document.getElementById('sun-moon-play');
    if (btn) btn.textContent = '▶ Play year';
    const cap = document.getElementById('sun-moon-caption');
    if (cap) cap.remove();
}

function stepSunMoonTour(now) {
    if (!sunTour || !sunMoonState) return;
    const dt = Math.min(0.1, (now - sunTour.last) / 1000);
    sunTour.last = now;

    // Hold at a turning point for a beat so the caption can be read.
    if (sunTour.held > 0) {
        sunTour.held -= dt;
    } else {
        sunTour.date = new Date(sunTour.date.getTime() + dt * SUN_TOUR_DAYS_PER_SEC * 86400000);
        const md = sunTour.date.toISOString().slice(5, 10);
        const hit = SUN_TOUR_STOPS.find(s => s.md === md && s.md !== sunTour.stop);
        if (hit) { sunTour.stop = hit.md; sunTour.held = 3.2; showSunMoonCaption(hit); }
    }
    if (sunTour.date.getUTCFullYear() > sunTour.year) { stopSunMoonTour(); return; }

    sunMoonState.date = sunTour.date;
    syncSunMoonInputs();
    drawSunMoonLayers();
    sunTour.raf = requestAnimationFrame(stepSunMoonTour);
}

function showSunMoonCaption(stop) {
    let cap = document.getElementById('sun-moon-caption');
    if (!cap) {
        cap = document.createElement('div');
        cap.id = 'sun-moon-caption';
        cap.className = 'sun-moon-caption';
        (document.getElementById('map-container') || document.body).appendChild(cap);
    }
    cap.innerHTML = `<strong>${stop.title}</strong><span>${stop.text}</span>`;
    cap.classList.remove('flash');
    void cap.offsetWidth;      // restart the entrance animation
    cap.classList.add('flash');
}

function removeSunMoonPanel() {
    stopSunMoonTour();
    const p = document.getElementById('sun-moon-panel');
    if (p) p.remove();
    if (sunMoonRasterTimer) { clearTimeout(sunMoonRasterTimer); sunMoonRasterTimer = null; }
    document.querySelector('.container').classList.remove('satellite-map');
    sunMoonState = null;
}

// ==================== SUN PATH ====================
// Why sunrise and sunset move through the year, shown four ways AT THE SAME INSTANT. One
// clock — latitude, longitude, day-of-year, hour — drives every pane, so the panes are four
// views of a single state rather than four animations that happen to look similar:
//
//   SKY      the celestial hemisphere over the observer: N/E/S/W on the ground, the sun's
//            daily ring solid above the horizon and dotted below, the rise/set points marked
//            and the day and night arcs labelled with their lengths.
//   SPACE    the earth tilted in space, with the reference angles drawn: the axial tilt, the
//            observer's latitude off the equator, and the horizon as the tangent plane at
//            their feet — which is what fixes the sun's maximum and minimum elevation.
//   GROUND   a normal camera (not a fisheye) looking at the sun, tracking it round and
//            following it below the horizon on a dotted line.
//   MAP      the sunrise line on a Mercator. Click it to move the observer.
//
// The astronomy is the same two lines as everywhere else:
//      sin(altitude) = sin(lat)sin(dec) + cos(lat)cos(dec)cos(H)
//      cos(H0)       = -tan(lat)tan(dec)          (H0 = half the day length)

let sunPathState = null;

// The month is kept only as a disambiguator — there are two of each, and "spring/summer" would
// be wrong for half the latitudes this mode can show.
const SUNPATH_STOPS = [
    { day: 79,  short: 'Mar equinox',  label: 'March equinox' },
    { day: 172, short: 'Jun solstice', label: 'June solstice' },
    { day: 265, short: 'Sep equinox',  label: 'September equinox' },
    { day: 355, short: 'Dec solstice', label: 'December solstice' }
];

// Solar declination for a day of the year (Spencer's Fourier form, ~0.1 deg).
function declinationForDay(day) {
    const g = 2 * Math.PI / 365 * (day - 1 + 0.5);
    return (0.006918 - 0.399912 * Math.cos(g) + 0.070257 * Math.sin(g)
            - 0.006758 * Math.cos(2 * g) + 0.000907 * Math.sin(2 * g)
            - 0.002697 * Math.cos(3 * g) + 0.001480 * Math.sin(3 * g)) * 180 / Math.PI;
}

function sunAltitude(latDeg, decDeg, hourAngleDeg) {
    const la = latDeg * DEG, de = decDeg * DEG, H = hourAngleDeg * DEG;
    return Math.asin(Math.sin(la) * Math.sin(de) + Math.cos(la) * Math.cos(de) * Math.cos(H)) / DEG;
}

// Measured from north, clockwise through east.
function sunAzimuth(latDeg, decDeg, hourAngleDeg) {
    const la = latDeg * DEG, de = decDeg * DEG, H = hourAngleDeg * DEG;
    const y = -Math.sin(H) * Math.cos(de);
    const x = Math.cos(la) * Math.sin(de) - Math.sin(la) * Math.cos(de) * Math.cos(H);
    return ((Math.atan2(y, x) / DEG) + 360) % 360;
}

// Half-day length in degrees of hour angle. The two polar cases are answers, not errors.
function halfDayAngle(latDeg, decDeg) {
    const c = -Math.tan(latDeg * DEG) * Math.tan(decDeg * DEG);
    if (c <= -1) return { deg: 180, polar: 'day' };
    if (c >= 1) return { deg: 0, polar: 'night' };
    return { deg: Math.acos(c) / DEG, polar: null };
}

function riseAngle(latDeg) { return 90 - Math.abs(latDeg); }

// The live state, as one object every pane reads.
function sunPathNow() {
    const s = sunPathState;
    const dec = declinationForDay(s.day);
    const H = (s.hour - 12) * 15;                       // hour angle, degrees
    return {
        lat: s.lat, lon: s.lon, day: s.day, hour: s.hour, dec, H,
        alt: sunAltitude(s.lat, dec, H),
        az: sunAzimuth(s.lat, dec, H),
        hd: halfDayAngle(s.lat, dec)
    };
}

// Which of the panes are on. Any of the four can go: a person watching the sunrise line move
// through a year does not want three quarters of the screen given to the other three, and the
// dome and the ground view are two ways of saying the same thing that are worth seeing one at a
// time as well as together.
const SUNPATH_PANES = [
    { key: 'dome',   cell: 'sun-path-dome-cell',    label: 'Skydome' },
    { key: 'globe',  cell: 'sun-path-globe-cell',   label: 'Globe' },
    { key: 'ground', cell: 'sun-path-horizon-cell', label: 'POV' },
    { key: 'map',    cell: 'sun-path-map-cell',     label: 'Map' }
];

// Show or hide the cells and let what is left fill the stage. The count goes on the stage as a
// data attribute and the CSS does the rest; the only thing that cannot be expressed in CSS is
// which cell should span two columns when there are three, so that one is marked here.
function syncSunPathPanes() {
    if (!sunPathState) return;
    const stage = document.getElementById('sun-path-stage');
    if (!stage) return;
    const on = SUNPATH_PANES.filter(p => sunPathState.panes[p.key] !== false);
    SUNPATH_PANES.forEach(p => {
        const cell = document.getElementById(p.cell);
        if (cell) { cell.hidden = sunPathState.panes[p.key] === false; cell.classList.remove('sp-wide'); }
    });
    if (on.length === 3) {
        const last = document.getElementById(on[2].cell);
        if (last) last.classList.add('sp-wide');
    }
    stage.dataset.shown = String(on.length || 1);
    SUNPATH_PANES.forEach(p => {
        const box = document.getElementById('sp-pane-' + p.key);
        if (box) box.checked = sunPathState.panes[p.key] !== false;
    });
    // The canvases are sized from their cells, so they have to be re-measured after the cells
    // have been resized — and the SVG panes derive their viewBox from the cell aspect too.
    requestAnimationFrame(() => {
        if (!sunPathState) return;
        sizeSunPathCanvases();
        updateSunPath();
    });
}

// ---- the moon, on Sun Path's own clock ----
// Sun Path keeps a day-of-year and an hour rather than a Date, because everything it draws about
// the SUN comes out of two angles and needs no calendar. The moon does need one: its position is
// a function of the actual date, not of the declination. So the clock is turned into a UTC Date
// on demand, and the moon is then read off the same machinery Sun & Moon uses.
function sunPathDate(now) {
    const year = new Date().getUTCFullYear();
    const ms = Date.UTC(year, 0, 1) + (now.day - 1) * 86400000 + now.hour * 3600000;
    return new Date(ms);
}

// The moon's altitude and azimuth for the observer, its illuminated fraction, and which limb is
// lit. A body's sub-point IS its declination and the longitude it is overhead, so the local hour
// angle is just the observer's longitude minus that — the same relation the sun's own hour angle
// has here, which is why `sunAltitude` and `sunAzimuth` can be handed the moon unchanged.
// THE MOON, DRAWN AS IT LOOKS. The terminator on a sphere seen from here is a circle seen edge
// on, which is an ELLIPSE: half-width r|1-2k| for an illuminated fraction k. At k = 0.5 it
// collapses to a straight line and the moon is exactly half lit; at k = 1 it bulges back out to
// the full circle. So one path covers every phase continuously, and the eight named phases are
// only names for places along it — which is why the shape must be built from k rather than from
// a bucket. `bright` is the screen angle the lit limb points along.
//
// Appended into `g`, which the caller has already translated to the moon's position.
function sunPathMoonGlyph(g, r, k, brightDeg, cls) {
    const kk = Math.max(0, Math.min(1, k));
    const rx = r * Math.abs(1 - 2 * kk);
    // Which way the lit crescent bows. Under half, the terminator curves the same way as the limb
    // and the lit part is a crescent; over half it curves the other way and the DARK part is.
    const inner = kk > 0.5 ? 1 : 0;
    const gp = g.append('g').attr('class', (cls || '') + ' sp-moon-glyph')
        .attr('transform', `rotate(${(brightDeg || 0).toFixed(1)})`);
    gp.append('circle').attr('class', 'sp-moon-dark').attr('r', r);
    gp.append('path').attr('class', 'sp-moon-lit')
        .attr('d', `M0,${-r} A${r},${r} 0 0 1 0,${r} A${rx.toFixed(2)},${r} 0 0 ${inner} 0,${-r} Z`);
    gp.append('circle').attr('class', 'sp-moon-rim').attr('r', r);
    return gp;
}

// The moon at some other hour of the same day, for drawing its track. Its own motion across the
// sky over one day is small next to the earth's turn, so the sub-point is taken once and only the
// hour angle is walked — which is the same approximation the sun's track makes about the
// declination, and wrong by about half a degree at the ends.
function sunPathMoonAt(now, hourAngleDeg) {
    const m = sunPathMoonNow(now);
    if (!m) return null;
    const H = ((hourAngleDeg + 540) % 360) - 180;
    return { alt: sunAltitude(now.lat, m.dec, H), az: sunAzimuth(now.lat, m.dec, H), k: m.k };
}

function sunPathMoonNow(now) {
    if (typeof lunarPosition !== 'function') return null;
    const date = sunPathDate(now);
    const m = lunarPosition(date);
    if (!m || !m.sub) return null;
    const dec = m.sub[1];
    const H = ((now.lon - m.sub[0] + 540) % 360) - 180;
    const ph = moonPhase(date);
    return {
        alt: sunAltitude(now.lat, dec, H),
        az: sunAzimuth(now.lat, dec, H),
        sub: m.sub, dec, H,
        k: ph.fraction,
        // Waxing has the sun to its west in the sky, so the lit limb faces the other way from a
        // waning moon. One sign is all the drawing needs.
        limb: ph.elongation < 180 ? 1 : -1,
        phase: phaseName(ph.elongation)
    };
}

function renderSunPathMode() {
    gameState.questionType = 'sun-path';
    gameState.scrollLocked = true;
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'none';
    const restart = document.getElementById('restart-btn');
    restart.style.display = 'inline-block';
    restart.textContent = 'Exit';
    restart.onclick = goHome;
    document.getElementById('question-text').innerHTML =
        '<strong>Sun &amp; Moon</strong> — one moment, four views of it: the skydome, the globe, the ' +
        'view from where you are standing, and the map. Click the map (or double-click the globe) ' +
        'to move; switch any view off to give the rest the screen.';

    const today = new Date();
    const day = Math.floor((today - new Date(today.getUTCFullYear(), 0, 0)) / 86400000);
    if (!sunPathState) {
        sunPathState = { lat: 51, lon: 0, day, hour: 12, playing: false, raf: null, mode: 'day',
                         panes: { dome: true, globe: true, ground: true, map: true },
                         trackSun: true, showMoon: false, satellite: false, figure: 'pin',
                         tropics: true, dayLengths: true, zones: false };
    }
    if (!sunPathState.panes) sunPathState.panes = { dome: true, globe: true, ground: true, map: true };
    buildSunPathStage();
    buildSunPathPanel();
    syncSunPathPanes();
    updateSunPath();
}

// ---- the stage ----
function buildSunPathStage() {
    const host = document.getElementById('map-container');
    if (!host) return;
    // Same guard ensureOrbital/ensureSpaceshipInset use: the stage is absolutely positioned, so
    // the host has to be a positioning context or it anchors to the viewport and covers the page.
    host.style.position = host.style.position || 'relative';
    document.body.classList.add('sun-path-active');
    const svgEl = document.getElementById('globe');
    if (svgEl) svgEl.style.display = 'none';
    const old = document.getElementById('sun-path-stage');
    if (old) old.remove();
    const stage = document.createElement('div');
    stage.id = 'sun-path-stage';
    stage.className = 'sun-path-stage';
    stage.innerHTML = `
        <div class="sun-path-cell" id="sun-path-dome-cell">
            <div class="sun-path-cap">Skydome<span id="sun-path-dome-note"></span></div>
        </div>
        <div class="sun-path-cell" id="sun-path-globe-cell">
            <div class="sun-path-cap">Globe<span id="sun-path-globe-note"></span></div>
            <button class="sp-view-reset" id="sun-path-view-reset"
                    title="Back to the default view: edge-on to the sunlight">Reset view</button>
        </div>
        <div class="sun-path-cell" id="sun-path-horizon-cell">
            <div class="sun-path-cap" id="sun-path-horizon-cap">POV<span id="sun-path-horizon-note"></span></div>
            <svg id="sun-path-horizon" viewBox="0 0 400 220" preserveAspectRatio="xMidYMid meet"></svg>
        </div>
        <div class="sun-path-cell" id="sun-path-map-cell">
            <div class="sun-path-cap">Map<span id="sun-path-map-note"></span></div>
            <svg id="sun-path-map" viewBox="0 0 400 220" preserveAspectRatio="xMidYMid meet"></svg>
        </div>`;
    host.appendChild(stage);
    const resetBtn = document.getElementById('sun-path-view-reset');
    if (resetBtn) resetBtn.addEventListener('click', resetSunPathView);
    buildSunPathMap();
    wireSunPathGroundDrag();
    withThree(() => { ensureSunPathThree(); updateSunPath(); });
    if (!sunPathState.resizeBound) {
        sunPathState.resizeBound = true;
        window.addEventListener('resize', () => { if (sunPathState) sizeSunPathCanvases(); });
    }
    // A window-resize listener alone misses the layout SETTLING — the stage is built before the
    // mode's own CSS (min-height, the panel below) has shaped it, so the first measurement is of
    // a box that no longer exists. Observing the cells catches that and any later reflow.
    if (window.ResizeObserver && !sunPathState.ro) {
        sunPathState.ro = new ResizeObserver(() => {
            if (!sunPathState) return;
            sizeSunPathCanvases();
            updateSunPath();          // the horizon SVG derives its viewBox from the cell aspect
        });
        stage.querySelectorAll('.sun-path-cell').forEach(c => sunPathState.ro.observe(c));
    }
}

// Panning the ground view by hand, for when it is not locked on the sun. Degrees per pixel is
// taken from the pane's own scale, so a drag moves the view by exactly the angle it moves the
// picture — the same equal-angle contract the projection itself keeps.
function wireSunPathGroundDrag() {
    const el = document.getElementById('sun-path-horizon');
    if (!el || el.dataset.dragWired) return;
    el.dataset.dragWired = '1';
    let from = null;
    el.style.touchAction = 'none';
    el.addEventListener('pointerdown', e => {
        if (!sunPathState || sunPathState.trackSun) return;
        const r = el.getBoundingClientRect();
        from = { x: e.clientX, y: e.clientY, w: r.width || 1,
                 az: sunPathState.groundAz == null ? sunPathNow().az : sunPathState.groundAz,
                 el: sunPathState.groundEl || 0 };
        try { el.setPointerCapture(e.pointerId); } catch (_) { /* not fatal */ }
    });
    el.addEventListener('pointermove', e => {
        if (!from || !sunPathState) return;
        const perPx = GROUND_FOV / from.w;
        sunPathState.groundAz = ((from.az - (e.clientX - from.x) * perPx) % 360 + 360) % 360;
        sunPathState.groundEl = Math.max(-80, Math.min(80, from.el + (e.clientY - from.y) * perPx));
        updateSunPath();
    });
    const stop = () => { from = null; };
    el.addEventListener('pointerup', stop);
    el.addEventListener('pointercancel', stop);
    el.addEventListener('pointerleave', stop);
}

// ---- three.js: the dome and the globe ----
function ensureSunPathThree() {
    const T = window.THREE;
    if (!T || !sunPathState || sunPathState.three) return;
    const mk = (cellId, camPos, ortho) => {
        const cell = document.getElementById(cellId);
        if (!cell) return null;
        const canvas = document.createElement('canvas');
        cell.appendChild(canvas);
        const renderer = new T.WebGLRenderer({ canvas, antialias: true, alpha: true });
        renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
        const scene = new T.Scene();
        // The space pane is ISOMETRIC: an orthographic camera keeps the tilt, latitude and sun
        // arcs true angles wherever they sit in the frame, which a perspective one does not —
        // and it is what makes the pane read as a diagram rather than a photograph.
        const camera = ortho
            ? new T.OrthographicCamera(-2, 2, 2, -2, 0.1, 40)
            : new T.PerspectiveCamera(42, 1.6, 0.01, 100);
        camera.position.set(camPos[0], camPos[1], camPos[2]);
        camera.lookAt(0, 0, 0);
        return { renderer, scene, camera, canvas, cell, camDist: ortho ? 8 : 0 };
    };
    const dome = mk('sun-path-dome-cell', [2.6, 1.6, 3.1], false);
    const globe = mk('sun-path-globe-cell', [0, 0, 8], true);
    if (!dome || !globe) return;
    sunPathState.three = { dome, globe };
    if (!sunPathState.view) sunPathState.view = { ...SUNPATH_VIEW_DEFAULT };
    if (!sunPathState.domeView) sunPathState.domeView = { ...SUNPATH_DOME_DEFAULT };
    buildDomeScene();
    buildGlobeScene();
    applySunPathGlobeCamera();
    applySunPathDomeCamera();
    // The leader lines and their labels are built in the CAMERA's basis — that is what makes them
    // a tidy screen-space column whichever way the globe is pivoted — so a drag has to rebuild
    // them. Without it they stayed where the old camera had put them and slid off their own
    // parallels, which is exactly what "the labels move with the camera" describes.
    wireSunPathDrag(globe.canvas, 'view', () => {
        applySunPathGlobeCamera();
        sunPathAutoFrame();
        if (sunPathState) updateSunPath();
    });
    wireSunPathDrag(dome.canvas, 'domeView', () => { applySunPathDomeCamera(); sunPathAutoFrame(); });
    wireSunPathGlobePick(globe);
    sizeSunPathCanvases();
}

// How much room each scene actually needs, MEASURED rather than guessed. The old fixed 1.6 /
// 1.5 had to be conservative because the widest thing in either pane is a text sprite whose
// extent depends on its string ("sun 56°  (year: 62° to 16°)" is over a world unit wide), so
// it left both panes zoomed well out. Sprites are measured from their own scale, meshes and
// lines from their geometry's bounding sphere in world space.
// The camera distance at which everything in the scene just fits — solved PER AXIS, not from a
// bounding sphere. A sphere is badly conservative here: the widest thing in either pane is a
// text sprite ("sun 56°  (year: 62° to 16°)" is over a world unit across), and a sphere big
// enough to contain it pushes the camera back as if the pane were that tall too. These panes are
// wide and short, so horizontal room is exactly what they have spare.
//
// For a camera at dir*d looking at the origin, a point p is inside the frustum when
// |p·right| <= tanH·(d - p·dir) and |p·up| <= tanV·(d - p·dir); solving each for d and taking
// the max over every point gives the tightest distance that clips nothing.
function sunPathFrameDistance(v) {
    const T = window.THREE;
    v.scene.updateMatrixWorld(true);
    const dir = v.camera.position.clone();
    if (dir.lengthSq() < 1e-6) dir.set(0, 0, 1);
    dir.normalize();
    const right = new T.Vector3().crossVectors(new T.Vector3(0, 1, 0), dir);
    if (right.lengthSq() < 1e-6) right.set(1, 0, 0);
    right.normalize();
    const up = new T.Vector3().crossVectors(dir, right).normalize();
    const tanV = Math.tan(v.camera.fov * Math.PI / 360);
    const tanH = tanV * Math.max(0.2, v.camera.aspect);
    let need = 0;
    const consider = (p, padX, padY) => {
        const along = p.dot(dir);
        need = Math.max(need,
            along + (Math.abs(p.dot(right)) + padX) / tanH,
            along + (Math.abs(p.dot(up)) + padY) / tanV);
    };
    const tmp = new T.Vector3();
    v.scene.traverse(o => {
        if (o.userData && o.userData.noFrame) return;
        if (o.isSprite) {
            // Sprites are billboarded, so their extent is already in the right/up plane.
            consider(new T.Vector3().setFromMatrixPosition(o.matrixWorld), o.scale.x / 2, o.scale.y / 2);
            return;
        }
        if (!o.geometry) return;
        const pos = o.geometry.attributes && o.geometry.attributes.position;
        // Walk the real vertices when there aren't many. A bounding sphere is exact for the
        // earth and the dome (they ARE spheres) but wildly conservative for the flat things —
        // the ground disc and the parallel rings are seen almost edge-on, so a sphere of their
        // radius claims several times the vertical room they actually use, and that alone was
        // holding both cameras back.
        if (pos && pos.count > 0 && pos.count <= 4096) {
            const stride = pos.count > 512 ? 3 : 1;
            for (let i = 0; i < pos.count; i += stride) {
                tmp.fromBufferAttribute(pos, i).applyMatrix4(o.matrixWorld);
                consider(tmp, 0, 0);
            }
            return;
        }
        if (!o.geometry.boundingSphere) o.geometry.computeBoundingSphere();
        const bs = o.geometry.boundingSphere;
        if (!bs) return;
        const c = bs.center.clone().applyMatrix4(o.matrixWorld);
        const s = Math.max(Math.abs(o.scale.x), Math.abs(o.scale.y), Math.abs(o.scale.z));
        consider(c, bs.radius * s, bs.radius * s);
    });
    return need || 4;
}

// Re-frame only when the requirement moves more than 2%: label text changes width every tick
// (56° to 5°), and following that exactly would make the camera breathe all through a playback.
function sunPathAutoFrame() {
    const th = sunPathState && sunPathState.three;
    if (!th) return;
    [th.dome, th.globe].forEach(v => {
        // 8% margin: the cell's caption strip sits over the top of the canvas, so content that
        // merely fits the frustum still lands underneath the title.
        if (v.camera.isOrthographicCamera) {
            // FIXED zoom, not a fit. The earth is exactly 2 units across, so a half-height of
            // 1/0.9 makes it 90% of the frame and keeps it there. Solving for content instead
            // meant the pane breathed every time a label changed width or the figure and its
            // little dome swung round the limb — the planet changing size to keep a 0.075-unit
            // stick figure in shot, which is not a trade anyone wants.
            const halfH = 1 / 0.9;
            const aspect = Math.max(0.2, v.camera.aspect || 1);
            if (v.halfH !== halfH || v.halfAspect !== aspect) {
                v.halfH = halfH; v.halfAspect = aspect;
                const halfW = halfH * aspect;
                v.camera.left = -halfW; v.camera.right = halfW;
                v.camera.top = halfH; v.camera.bottom = -halfH;
                v.camera.updateProjectionMatrix();
            }
            return;
        }
        const need = sunPathFrameDistance(v) * 1.08;
        if (!v.frameDist || Math.abs(need - v.frameDist) / v.frameDist > 0.02) {
            v.frameDist = need;
            v.camera.position.setLength(need);
            v.camera.lookAt(0, 0, 0);
            v.camera.updateProjectionMatrix();
        }
    });
}

// Half-extents the scene needs in the camera's own right/up plane, for an orthographic fit.
function sunPathOrthoExtent(v) {
    const T = window.THREE;
    v.scene.updateMatrixWorld(true);
    const dir = v.camera.position.clone();
    if (dir.lengthSq() < 1e-6) dir.set(0, 0, 1);
    dir.normalize();
    const right = new T.Vector3().crossVectors(new T.Vector3(0, 1, 0), dir);
    if (right.lengthSq() < 1e-6) right.set(1, 0, 0);
    right.normalize();
    const up = new T.Vector3().crossVectors(dir, right).normalize();
    let mx = 0, my = 0;
    const tmp = new T.Vector3();
    const take = (p, padX, padY) => {
        mx = Math.max(mx, Math.abs(p.dot(right)) + padX);
        my = Math.max(my, Math.abs(p.dot(up)) + padY);
    };
    v.scene.traverse(o => {
        if (o.userData && o.userData.noFrame) return;
        if (o.isSprite) { take(new T.Vector3().setFromMatrixPosition(o.matrixWorld), o.scale.x / 2, o.scale.y / 2); return; }
        if (!o.geometry) return;
        const pos = o.geometry.attributes && o.geometry.attributes.position;
        if (pos && pos.count > 0 && pos.count <= 4096) {
            const stride = pos.count > 512 ? 3 : 1;
            for (let i = 0; i < pos.count; i += stride) {
                tmp.fromBufferAttribute(pos, i).applyMatrix4(o.matrixWorld);
                take(tmp, 0, 0);
            }
            return;
        }
        if (!o.geometry.boundingSphere) o.geometry.computeBoundingSphere();
        const bs = o.geometry.boundingSphere;
        if (!bs) return;
        const c = bs.center.clone().applyMatrix4(o.matrixWorld);
        const s = Math.max(Math.abs(o.scale.x), Math.abs(o.scale.y), Math.abs(o.scale.z));
        take(c, bs.radius * s, bs.radius * s);
    });
    return { x: mx || 1.5, y: my || 1.5 };
}

// ---- Earth-in-space: free look ----
// Default is edge-on to the sunlight (elevation 0, looking down +Z with the sun off at +X), so
// the terminator runs straight down the middle — the diagram view. Drag to pivot off it.
const SUNPATH_VIEW_DEFAULT = { az: 0, el: 0 };
function applySunPathGlobeCamera() {
    const th = sunPathState && sunPathState.three && sunPathState.three.globe;
    if (!th) return;
    const o = sunPathState.view || SUNPATH_VIEW_DEFAULT;
    const az = o.az * DEG, el = Math.max(-85, Math.min(85, o.el)) * DEG;
    const d = th.camDist || 8;
    th.camera.position.set(Math.sin(az) * Math.cos(el) * d, Math.sin(el) * d, Math.cos(az) * Math.cos(el) * d);
    th.camera.up.set(0, 1, 0);
    th.camera.lookAt(0, 0, 0);
    th.camera.updateProjectionMatrix();
}

function resetSunPathView() {
    if (!sunPathState) return;
    sunPathState.view = { az: SUNPATH_VIEW_DEFAULT.az, el: SUNPATH_VIEW_DEFAULT.el };
    applySunPathGlobeCamera();
    sunPathAutoFrame();
    renderSunPathThree();
}

// The sky dome turns the same way, about its own default three-quarter view.
const SUNPATH_DOME_DEFAULT = { az: 40, el: 27 };
function applySunPathDomeCamera() {
    const th = sunPathState && sunPathState.three && sunPathState.three.dome;
    if (!th) return;
    const o = sunPathState.domeView || SUNPATH_DOME_DEFAULT;
    // TRACK SUN swings the camera round the ground's normal so it always looks along the sun's
    // own compass bearing — the dome's answer to the ground pane's locked camera, and the reason
    // the two panes agree about what "over there" means. The drag still works: it is an offset
    // from the sun's bearing rather than from north.
    // MINUS the azimuth. The camera's own angle is measured the other way round from a compass
    // bearing — azimuth runs clockwise from north and this angle runs anticlockwise from +Z — so
    // adding it turned the dome the wrong way and the sun crossed the sky backwards.
    const track = sunPathState.trackSun ? -(sunPathState.sunAz || 0) : 0;
    const az = (o.az + track) * DEG, el = Math.max(-85, Math.min(85, o.el)) * DEG;
    const d = th.frameDist || th.camera.position.length() || 4.4;
    th.camera.position.set(Math.sin(az) * Math.cos(el) * d, Math.sin(el) * d, Math.cos(az) * Math.cos(el) * d);
    th.camera.up.set(0, 1, 0);
    th.camera.lookAt(0, 0, 0);
    th.camera.updateProjectionMatrix();
    th.frameDist = 0;      // the fit depends on the view direction, so let it re-solve
}

// DOUBLE-CLICK THE GLOBE TO STAND THERE. The map below can already be clicked, but the globe is
// the pane somebody is looking at when they think "what about here" — and it is the only one
// showing the far side of the world at all.
//
// A double-click rather than a single one, because the single click is the end of a drag: this
// pane's whole interaction is pivoting it, and every pivot would otherwise relocate the observer.
//
// The ray is cast by hand rather than through THREE.Raycaster: it is one sphere at the origin,
// which is a quadratic, and the answer then has to be un-rotated back through the two transforms
// the pane applies (the holder's tilt and the earth's spin) to become a longitude.
function wireSunPathGlobePick(v) {
    if (!v || !v.canvas || v.canvas.dataset.pickWired) return;
    v.canvas.dataset.pickWired = '1';
    v.canvas.addEventListener('dblclick', e => {
        const T = window.THREE;
        const th = sunPathState && sunPathState.three && sunPathState.three.globe;
        if (!T || !th || !th.earth) return;
        const r = v.canvas.getBoundingClientRect();
        const nx = ((e.clientX - r.left) / r.width) * 2 - 1;
        const ny = -(((e.clientY - r.top) / r.height) * 2 - 1);
        // An orthographic camera: the ray is parallel, so its origin is the point on the near
        // plane and its direction is the view direction. Both come out of the camera's matrices
        // without any of the perspective algebra a projected ray would need.
        const origin = new T.Vector3(nx, ny, -1).unproject(v.camera);
        const dir = new T.Vector3(0, 0, -1).transformDirection(v.camera.matrixWorld).normalize();
        // |origin + t·dir|² = 1
        const b = 2 * origin.dot(dir), c = origin.lengthSq() - 1;
        const disc = b * b - 4 * c;
        if (disc < 0) return;                       // the click missed the globe
        const t = (-b - Math.sqrt(disc)) / 2;       // the near root: the face we can see
        const hit = origin.clone().add(dir.clone().multiplyScalar(t));
        // Into the HOLDER's frame — the tilt undone, the spin still in — because that is the frame
        // this pane's own forward mapping is written in. Both the observer and the moon are placed
        // by `(cos L·cos lat, sin lat, −sin L·cos lat)` for a RELATIVE longitude L, so inverting
        // exactly that is the only way to be sure of the sign. Going through the earth MESH's
        // frame instead means reasoning about SphereGeometry's own seam convention on top, which
        // is where the longitude came out mirrored.
        th.holder.updateMatrixWorld(true);
        const local = th.holder.worldToLocal(hit.clone()).normalize();
        const la = Math.asin(Math.max(-1, Math.min(1, local.y))) / DEG;
        const rel = Math.atan2(-local.z, local.x) / DEG;
        // And back to an absolute longitude by adding whatever that frame measures from: the
        // sub-solar meridian while tracking, the observer's own while the earth is held still.
        const track = sunPathState.trackSun !== false;
        const now = sunPathNow();
        const origin0 = track ? (now.lon - now.H) : now.lon;
        const lo = rel + origin0;
        if (!isFinite(la) || !isFinite(lo)) return;
        sunPathState.lat = Math.max(-89, Math.min(89, la));
        sunPathState.lon = ((lo + 540) % 360) - 180;
        updateSunPath();
    });
}

// Pointer-drag to pivot. Listeners go on before setPointerCapture (and the capture is wrapped),
// following the same convention as the puzzle and flag drags. `apply` is what differs between
// the two panes — rotation only, never pan or zoom, in either.
function wireSunPathDrag(canvas, key, apply) {
    if (!canvas || canvas.dataset.dragWired) return;
    canvas.dataset.dragWired = '1';
    let last = null;
    const move = e => {
        if (!last || !sunPathState) return;
        const v = sunPathState[key] || (sunPathState[key] = { ...SUNPATH_VIEW_DEFAULT });
        v.az -= (e.clientX - last.x) * 0.5;
        v.el = Math.max(-85, Math.min(85, v.el + (e.clientY - last.y) * 0.5));
        last = { x: e.clientX, y: e.clientY };
        apply();
        renderSunPathThree();
        e.preventDefault();
    };
    const up = e => {
        last = null;
        window.removeEventListener('pointermove', move);
        window.removeEventListener('pointerup', up);
        try { canvas.releasePointerCapture(e.pointerId); } catch (_) { /* best effort */ }
    };
    canvas.addEventListener('pointerdown', e => {
        last = { x: e.clientX, y: e.clientY };
        window.addEventListener('pointermove', move);
        window.addEventListener('pointerup', up);
        try { canvas.setPointerCapture(e.pointerId); } catch (_) { /* best effort */ }
        e.preventDefault();
    });
    canvas.style.cursor = 'grab';
    canvas.style.touchAction = 'none';
}

function sizeSunPathCanvases() {
    const th = sunPathState && sunPathState.three;
    if (!th) return;
    [th.dome, th.globe].forEach(v => {
        // Size the DRAWING BUFFER only (updateStyle = false) and let CSS (width/height: 100%)
        // size the element. Letting three.js write inline px sizes made the canvas a flow child
        // whose own height fed back into the cell it was measured from, so it settled at 333px
        // inside a 191px cell and the globe was clipped out of its own pane.
        v.canvas.style.width = '';
        v.canvas.style.height = '';
        const r = v.cell.getBoundingClientRect();
        const w = Math.max(1, Math.round(r.width)), h = Math.max(1, Math.round(r.height));
        v.renderer.setSize(w, h, false);
        v.camera.aspect = w / h;
        v.camera.updateProjectionMatrix();
        // Aspect just changed, so the fit has to be re-solved from scratch — drop the cached
        // distance/extent rather than let the 2% hysteresis hold a stale one across a resize.
        v.frameDist = 0;
        v.halfH = 0;
    });
    sunPathAutoFrame();
    renderSunPathThree();
}

function renderSunPathThree() {
    const th = sunPathState && sunPathState.three;
    if (!th) return;
    th.dome.renderer.render(th.dome.scene, th.dome.camera);
    th.globe.renderer.render(th.globe.scene, th.globe.camera);
}

function themeColor(name, fallback) {
    const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
    return new window.THREE.Color(v || fallback);
}

// A text sprite that always faces the camera — used for every label in both 3D panes.
// Unbolded serif, like every other label in this mode: these are annotations on a diagram, not
// interface chrome, and a bold sans sprite sits on top of the picture rather than in it.
const SUNPATH_LABEL_FONT = "Georgia, 'Iowan Old Style', 'Palatino Linotype', Palatino, serif";
function makeLabel(text, colour, scale) {
    const T = window.THREE;
    const pad = 8, font = 40;
    const meas = document.createElement('canvas').getContext('2d');
    meas.font = `${font}px ${SUNPATH_LABEL_FONT}`;
    const w = Math.ceil(meas.measureText(text).width) + pad * 2;
    const cv = document.createElement('canvas');
    cv.width = w; cv.height = font + pad * 2;
    const ctx = cv.getContext('2d');
    ctx.font = `${font}px ${SUNPATH_LABEL_FONT}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.lineWidth = 5;
    ctx.strokeStyle = 'rgba(8,12,20,0.7)';
    ctx.strokeText(text, cv.width / 2, cv.height / 2);
    ctx.fillStyle = colour || '#eef2fa';
    ctx.fillText(text, cv.width / 2, cv.height / 2);
    const sp = new T.Sprite(new T.SpriteMaterial({
        map: new T.CanvasTexture(cv), transparent: true, depthTest: false
    }));
    const s = scale || 0.2;
    sp.scale.set(s * cv.width / cv.height, s, 1);
    sp.userData.labelW = sp.scale.x;      // callers that left-align need the width
    return sp;
}

// The five fixed parallels every view shares. The observer's own latitude is added as a sixth
// at draw time — it is the only one that moves.
const SUNPATH_PARALLELS = [
    { lat: 90 - OBLIQUITY_DEG,    name: 'Arctic Circle',       cls: 'polar' },
    { lat: OBLIQUITY_DEG,         name: 'Tropic of Cancer',    cls: 'tropic' },
    { lat: 0,                     name: 'Equator',             cls: 'equator' },
    { lat: -OBLIQUITY_DEG,        name: 'Tropic of Capricorn', cls: 'tropic' },
    { lat: -(90 - OBLIQUITY_DEG), name: 'Antarctic Circle',    cls: 'polar' }
];

// The six, in latitude order, with the observer's own slotted in.
function sunPathParallels(lat) {
    const all = SUNPATH_PARALLELS.map(p => ({ ...p, you: false }));
    all.push({ lat, name: 'You', cls: 'you', you: true });
    return all.sort((a, b) => b.lat - a.lat);
}

// Hours of daylight at a latitude for a given solar declination.
function sunPathDayHours(lat, dec) {
    const hd = halfDayAngle(lat, dec);
    if (hd.polar === 'day') return 24;
    if (hd.polar === 'night') return 0;
    return hd.deg / 15 * 2;
}

function lineFrom(points, colour, opacity) {
    const T = window.THREE;
    return new T.Line(new T.BufferGeometry().setFromPoints(points),
        new T.LineBasicMaterial({ color: colour, transparent: true, opacity: opacity == null ? 1 : opacity }));
}

// Dashes, built by hand: LineDashedMaterial needs computeLineDistances and still renders
// solid on some drivers, and every dotted line here is short enough to just emit segments.
function dashedFrom(points, colour, opacity) {
    const T = window.THREE;
    const seg = [];
    for (let i = 0; i + 1 < points.length; i += 2) seg.push(points[i], points[i + 1]);
    return new T.LineSegments(new T.BufferGeometry().setFromPoints(seg),
        new T.LineBasicMaterial({ color: colour, transparent: true, opacity: opacity == null ? 0.6 : opacity }));
}

// --- SKY: the celestial dome ---
function buildDomeScene() {
    const T = window.THREE;
    const th = sunPathState.three.dome;
    const s = th.scene;

    // The dome itself: a plain translucent shell, no lattice — the reference marks below are
    // what should be readable, and a wireframe just competes with them.
    s.add(new T.Mesh(
        new T.SphereGeometry(1, 48, 24, 0, Math.PI * 2, 0, Math.PI / 2),
        new T.MeshBasicMaterial({ color: themeColor('--ocean-1', '#aebfca'), transparent: true,
                                  opacity: 0.12, side: T.DoubleSide, depthWrite: false })));
    // Kept on the state: the satellite checkbox re-textures this disc rather than rebuilding
    // the scene, and a north-up patch of real ground has to be able to follow the observer.
    const groundDisc = new T.Mesh(
        new T.CircleGeometry(1, 64).rotateX(-Math.PI / 2),
        new T.MeshBasicMaterial({ color: themeColor('--land', '#cbc3a4'), transparent: true, opacity: 0.92 }));
    s.add(groundDisc);
    sunPathState.domeGround = groundDisc;
    refreshSunPathDomeGround();

    // The compass rose on the ground: the two cardinal axes plus a ring of ticks, so an
    // azimuth can actually be read off rather than guessed.
    const rose = new T.Group();
    rose.add(lineFrom([new T.Vector3(0, 0.002, -1), new T.Vector3(0, 0.002, 1)], 0x6b7583, 0.55));
    rose.add(lineFrom([new T.Vector3(-1, 0.002, 0), new T.Vector3(1, 0.002, 0)], 0x6b7583, 0.55));
    for (let a = 0; a < 360; a += 15) {
        const r0 = (a % 90 === 0) ? 0.86 : (a % 45 === 0 ? 0.92 : 0.95);
        const v = altAzVector(0, a);
        rose.add(lineFrom([v.clone().multiplyScalar(r0).setY(0.002), v.clone().setY(0.002)], 0x6b7583, 0.5));
    }
    rose.add(circleLine(1.0, 0x6b7583, 'horizontal', 0.002));
    s.add(rose);

    [['N', 0], ['E', 90], ['S', 180], ['W', 270]].forEach(([txt, az]) => {
        const v = altAzVector(0, az).multiplyScalar(1.14);
        const sp = makeLabel(txt, '#f2f5fa', 0.19);
        sp.position.set(v.x, 0.06, v.z);
        s.add(sp);
    });

    th.sun = new T.Mesh(new T.SphereGeometry(0.05, 16, 16), new T.MeshBasicMaterial({ color: 0xffcf5c }));
    s.add(th.sun);
    th.figure = makeSunPathFigure(SUNPATH_FIGURE_H); // you, at the centre of your own sky
    s.add(th.figure);
    th.dyn = new T.Group();   // everything that changes with lat/day/hour
    s.add(th.dyn);
}

function circleLine(r, colour, plane, y) {
    const T = window.THREE;
    const pts = [];
    for (let i = 0; i <= 96; i++) {
        const a = i / 96 * Math.PI * 2;
        pts.push(plane === 'horizontal'
            ? new T.Vector3(Math.cos(a) * r, y || 0, Math.sin(a) * r)
            : new T.Vector3(0, Math.sin(a) * r, Math.cos(a) * r));
    }
    return lineFrom(pts, colour, 0.6);
}

// Unit vector for altitude/azimuth in the dome's frame (-Z north, +X east, +Y up).
function altAzVector(altDeg, azDeg) {
    const T = window.THREE;
    const alt = altDeg * DEG, az = azDeg * DEG;
    return new T.Vector3(Math.cos(alt) * Math.sin(az), Math.sin(alt), -Math.cos(alt) * Math.cos(az));
}

function clearGroup(grp) {
    while (grp.children.length) {
        const c = grp.children.pop();
        if (c.geometry) c.geometry.dispose();
        if (c.material && c.material.map) c.material.map.dispose();
        if (c.material) c.material.dispose();
    }
}

function updateDomeScene(now) {
    const T = window.THREE, th = sunPathState.three && sunPathState.three.dome;
    if (!th) return;
    clearGroup(th.dyn);

    // The track is a closed loop in hour angle, so it has to be cut into runs cyclically.
    // Collecting every below-horizon point into one array instead concatenated two disjoint
    // stretches — pre-dawn (H from -180) and post-dusk (H to +180) — which drew a dashed chord
    // straight across the sky between sunrise and sunset, and put the night label on the seam
    // between them (down at the horizon, on top of the compass letters) instead of at midnight.
    const pts = [];
    for (let H = -180; H < 180; H += 2) {
        const alt = sunAltitude(now.lat, now.dec, H);
        pts.push({ lit: alt >= 0, v: altAzVector(alt, sunAzimuth(now.lat, now.dec, H)).multiplyScalar(1.004) });
    }
    const runs = [];
    pts.forEach(p => {
        const last = runs[runs.length - 1];
        if (last && last.lit === p.lit) last.pts.push(p.v);
        else runs.push({ lit: p.lit, pts: [p.v] });
    });
    if (runs.length > 1 && runs[0].lit === runs[runs.length - 1].lit) {
        const first = runs.shift();                       // the loop closes: one run wraps the ends
        runs[runs.length - 1].pts.push(...first.pts);
    }
    runs.forEach(r => {
        if (r.pts.length < 2) return;
        th.dyn.add(r.lit ? lineFrom(r.pts, 0xf0a92b, 1) : dashedFrom(r.pts, 0xf0a92b, 0.45));
    });
    const longestRun = lit => runs.filter(r => r.lit === lit && r.pts.length > 2)
        .sort((a, b) => b.pts.length - a.pts.length)[0];

    // Where it rises and sets, and how long each arc lasts.
    if (!now.hd.polar) {
        [[-now.hd.deg, 'Sunrise'], [now.hd.deg, 'Sunset']].forEach(([H, txt]) => {
            const az = sunAzimuth(now.lat, now.dec, H);
            const v = altAzVector(0, az);
            th.dyn.add(lineFrom([v.clone().setY(0.004), v.clone().setY(0.26)], 0xd05c4a, 0.95));
            const lab = makeLabel(`${txt} ${Math.round(az)}°`, '#ffd9d2', 0.115);
            lab.position.set(v.x * 1.05, 0.34, v.z * 1.05);
            th.dyn.add(lab);
        });
    }
    // Arc labels: the lit arc and the dark one, placed on their own halves of the track.
    const dayH = now.hd.polar === 'day' ? 24 : now.hd.polar === 'night' ? 0 : now.hd.deg / 15 * 2;
    const dayRun = longestRun(true), nightRun = longestRun(false);
    if (dayRun) {
        const lab = makeLabel(`${dayH.toFixed(1)} h of daylight`, '#ffe6b0', 0.12);
        lab.position.copy(dayRun.pts[Math.floor(dayRun.pts.length / 2)].clone().multiplyScalar(1.16));
        th.dyn.add(lab);
    }
    if (nightRun) {
        const lab = makeLabel(`${(24 - dayH).toFixed(1)} h of night`, '#b9c4d6', 0.12);
        lab.position.copy(nightRun.pts[Math.floor(nightRun.pts.length / 2)].clone().multiplyScalar(1.16));
        th.dyn.add(lab);
    }

    // The moon, on the same dome and at the same instant, when it is asked for. Pale and small:
    // it is here to say where it is relative to the sun, which is the thing about the moon that
    // is genuinely hard to picture, and it must not compete with the arc.
    if (sunPathState.showMoon) {
        const m = sunPathMoonNow(now);
        if (m) {
            // ITS TRACK, not a caption. The sun already gets an arc across this dome and the
            // moon's is the same construction on its own declination — and two arcs at different
            // tilts is the whole story of why the moon rises later each night, which no
            // percentage was ever going to tell.
            const above = [], below = [];
            for (let Hh = -180; Hh <= 180; Hh += 2) {
                const mm = sunPathMoonAt(now, Hh);
                if (!mm) continue;
                const v = altAzVector(mm.alt, mm.az);
                (mm.alt >= 0 ? above : below).push(v);
            }
            if (above.length > 1) th.dyn.add(lineFrom(above, 0xf2f4f8, 0.7));
            if (below.length > 1) th.dyn.add(dashedFrom(below, 0xf2f4f8, 0.3));
            const mp = altAzVector(m.alt, m.az).multiplyScalar(1.004);
            const ball = new T.Mesh(new T.SphereGeometry(0.03, 18, 12),
                new T.MeshBasicMaterial({ color: m.alt >= 0 ? 0xeeece4 : 0x8f95a3,
                                          transparent: true, opacity: m.alt >= 0 ? 1 : 0.5 }));
            ball.position.copy(mp);
            th.dyn.add(ball);
        }
    }

    // The sun itself, at the current hour, with its ray aimed at the OBSERVER rather than
    // dropped vertically to the ground. The vertical drop line read as "the sun is over there",
    // which is the one thing it isn't — sunlight arrives along the line of sight, and that line
    // is also what the shadow below is the projection of.
    const p = altAzVector(now.alt, now.az).multiplyScalar(1.004);
    th.sun.position.copy(p);
    // The sun stays on show all night, following the dotted half of its own track under the
    // ground — dimmed and hollowed out so it plainly reads as "down there", not "up there".
    th.sun.visible = true;
    th.sun.material.color.set(now.alt >= 0 ? 0xffcf5c : 0x8a7a52);
    th.sun.material.opacity = now.alt >= 0 ? 1 : 0.55;
    th.sun.material.transparent = now.alt < 0;
    const eye = new T.Vector3(0, SUNPATH_FIGURE_H * 0.55, 0);
    if (now.alt > 0) {
        th.dyn.add(lineFrom([p, eye], 0xf0a92b, 0.5));
        th.dyn.add(sunPathShadow(now.alt, now.az, SUNPATH_FIGURE_H, 0.95));
    } else {
        // Same ray, dotted, so the link to the figure survives the night.
        const seg = [];
        for (let i = 0; i < 24; i++) seg.push(p.clone().lerp(eye, i / 24));
        th.dyn.add(dashedFrom(seg, 0xf0a92b, 0.32));
    }
}

// A person standing at the centre, for scale and for something to cast the shadow. Deliberately
// crude: at this size anything more detailed is a red smudge.
const SUNPATH_FIGURE_H = 0.13;
// Four ways to draw the observer. At this size (about a tenth of the dome's radius, so ~12px
// on screen) legibility beats anatomy, which is why the options run from a literal figure to a
// plain marker. Switchable in the panel; `sunPathState.figure` holds the choice.
const SUNPATH_FIGURE_STYLES = [
    { key: 'person',  label: 'Person' },
    { key: 'stick',   label: 'Stick figure' },
    { key: 'pin',     label: 'Map pin' },
    { key: 'beacon',  label: 'Beacon' }
];

function makeSunPathFigure(height, colour, style) {
    const T = window.THREE;
    const g = new T.Group();
    const mat = new T.MeshBasicMaterial({ color: colour == null ? 0xd0392b : colour });
    const h = height;
    const add = (geo, y) => { const m = new T.Mesh(geo, mat); m.position.y = y; g.add(m); return m; };
    switch (style || (sunPathState && sunPathState.figure) || 'person') {
        case 'stick':
            // Thin limbs: reads as a person, but the strokes go sub-pixel when the pane is small.
            add(new T.CylinderGeometry(h * 0.045, h * 0.045, h * 0.42, 6), h * 0.21);
            add(new T.BoxGeometry(h * 0.34, h * 0.05, h * 0.05), h * 0.60);
            add(new T.CylinderGeometry(h * 0.05, h * 0.05, h * 0.34, 6), h * 0.60);
            add(new T.SphereGeometry(h * 0.15, 10, 8), h * 0.86);
            break;
        case 'pin':
            // The classic teardrop marker: a ball on a spike. Unmistakable at any size, but it
            // says "a place" rather than "a person standing here".
            add(new T.ConeGeometry(h * 0.20, h * 0.55, 12).rotateX(Math.PI), h * 0.28);
            add(new T.SphereGeometry(h * 0.24, 12, 10), h * 0.72);
            break;
        case 'beacon':
            // A tapered obelisk — the most legible of the four when the pane is tiny, and the
            // least literal.
            add(new T.CylinderGeometry(h * 0.05, h * 0.22, h * 0.80, 10), h * 0.40);
            add(new T.SphereGeometry(h * 0.09, 10, 8), h * 0.86);
            break;
        default:
            // Solid silhouette: tapered legs, a broader chest, a round head. Holds its shape
            // when it shrinks, which the stick figure does not.
            add(new T.CylinderGeometry(h * 0.10, h * 0.15, h * 0.45, 8), h * 0.225);
            add(new T.CylinderGeometry(h * 0.17, h * 0.13, h * 0.34, 8), h * 0.62);
            add(new T.SphereGeometry(h * 0.17, 10, 8), h * 0.90);
    }
    return g;
}

// The shadow it throws: a tapered sliver on the ground, pointing away from the sun and as long
// as height/tan(altitude) — which is why it runs away to nothing as the sun nears the horizon.
function rebuildSunPathDomeFigure() {
    const th = sunPathState && sunPathState.three && sunPathState.three.dome;
    if (!th || !th.figure) return;
    th.scene.remove(th.figure);
    th.figure.traverse(o => { if (o.geometry) o.geometry.dispose(); });
    th.figure = makeSunPathFigure(SUNPATH_FIGURE_H);
    th.scene.add(th.figure);
}

function sunPathShadow(altDeg, azDeg, height, maxLen) {
    const T = window.THREE;
    const away = altAzVector(0, (azDeg + 180) % 360).normalize();
    const side = new T.Vector3(0, 1, 0).cross(away).normalize();
    const len = Math.min(maxLen, height / Math.max(0.09, Math.tan(Math.max(0.5, altDeg) * DEG)));
    // CONSTANT width. The sun is a far-off source, so a shadow lengthens without spreading —
    // tying width to length made a low-sun shadow fan out like a torch beam. The earlier
    // complaint that it looked faint before noon was never the opacity (which never changed):
    // it was a ~2px hairline. The answer is a wider constant width and more contrast, not taper.
    const w0 = height * 0.30, w1 = w0 * 0.86;
    const y = 0.004;
    const a = side.clone().multiplyScalar(w0), b = side.clone().multiplyScalar(-w0);
    const tip = away.clone().multiplyScalar(len);
    const c = tip.clone().add(side.clone().multiplyScalar(-w1));
    const d = tip.clone().add(side.clone().multiplyScalar(w1));
    const pts = [a, b, c, a, c, d].map(v => new T.Vector3(v.x, y, v.z));
    const geo = new T.BufferGeometry().setFromPoints(pts);
    return new T.Mesh(geo, new T.MeshBasicMaterial({
        color: 0x33291c, transparent: true, opacity: 0.58, side: T.DoubleSide, depthWrite: false
    }));
}

// --- SPACE: the earth, its tilt, and the observer's horizon ---
// The earth carries the SAME map as the Sunrise-line pane, so the two panes are visibly one
// planet rather than two diagrams. The texture is built from whatever land features that pane
// loaded (it may still be fetching), so the material starts flat and is filled in by
// refreshSunPathEarthTexture once they land.
function buildGlobeScene() {
    const th = sunPathState.three.globe;
    const built = buildEarthInSpace(th.scene);
    th.holder = built.holder;
    th.earth = built.earth;
    th.dyn = built.dyn;
    th.holderDyn = built.holderDyn;
    // The light and the sun's two marks, so the pane can move them when the earth is held still.
    th.light = built.light;
    th.sunBall = built.sunBall;
    th.sunRay = built.sunRay;
}

// An equirectangular canvas of the world in the Sunrise-line pane's own colours, wrapped onto
// the sphere.
//
// Drawn straight, NOT mirrored. An earlier version flipped it, which looked self-consistent
// (the geography sat under the observer correctly) but was compensating for the globe spinning
// the wrong way — two reflections cancelling, so every check that used the same position
// formula passed while the displayed world was east-west backwards. With the spin fixed
// (see updateGlobeScene) the plain map is the correct one.
// The canvas itself, with no reference to any particular pane — so a second Earth-in-space
// (the Read the Daylight reveal) can be built from the same world without owning Sun Path's
// state. Returns null while the land features are still loading.
// ---- the satellite imagery ----
// One Blue Marble, shared by every pane that can use it: the earth in space, the dome's ground
// disc and the horizon's ground fill. It is the same 2048x1024 equirectangular the orbital view
// keeps as its base sphere, so nothing new is downloaded and nothing new is committed.
//
// The night side is DERIVED rather than fetched. NASA's Black Marble is a separate 60 MB image
// and there is nowhere to put it; darkening and cooling the day image gives the same reading at
// the size these panes are drawn — the terminator is the thing being looked at, not the city
// lights. `scripts/build-earth-night.py` fetches the real one for anybody who wants it, and it
// is picked up automatically if it is there.
const SUNPATH_DAY_TEX = 'data/textures/earth-bmng-2048.jpg';
// The night side comes from NASA's own servers rather than from this repository. It is a several
// megabyte image that one checkbox in one mode wants, so committing it would cost every visitor
// who never ticks that box; fetched lazily it costs only the people who do. A LOCAL copy wins if
// it is there — scripts/build-earth-night.py writes one — so anybody who would rather not depend
// on a third party need not.
//
// Two remote candidates, tried in order, because over the life of a static site a URL eventually
// moves.
const SUNPATH_NIGHT_TEX = [
    'data/textures/earth-night-2048.jpg',
    'https://eoimages.gsfc.nasa.gov/images/imagerecords/79000/79765/dnb_land_ocean_ice.2012.3600x1800.jpg',
    'https://cdn.jsdelivr.net/gh/turban/webgl-earth@master/images/2_no_clouds_4k.jpg'
];
let sunPathSat = { day: null, night: null, tried: false, nightTried: false };

// Calls back ONLY when the image arrives. A failed load calls back never, and that is the point:
// the caller's callback re-runs the draw, so calling it on failure with nothing loaded sends it
// straight back here, and back again — a synchronous loop that blew the stack the first time the
// checkbox was ticked before the file had landed.
function ensureSunPathSat(cb) {
    if (sunPathSat.day) { if (cb) cb(); return; }
    if (sunPathSat.tried) return;
    sunPathSat.tried = true;
    const im = new Image();
    im.onload = () => { sunPathSat.day = im; if (cb) cb(); };
    im.onerror = () => { /* left tried: retrying every frame would hammer a 404 */ };
    im.src = SUNPATH_DAY_TEX;
    // The night image blocks nobody, so it is fetched alongside and simply turns up.
    ensureSunPathNight();
}

// City lights, lazily, from whichever source answers first. `crossOrigin` is set because the
// image may be drawn into a canvas, and a tainted canvas cannot be read back — a silent failure
// that would look like the ground going black rather than like a permissions problem.
function ensureSunPathNight(cb) {
    if (sunPathSat.night) { if (cb) cb(); return; }
    if (sunPathSat.nightTried) return;
    sunPathSat.nightTried = true;
    let i = 0;
    const tryNext = () => {
        if (i >= SUNPATH_NIGHT_TEX.length) return;
        const url = SUNPATH_NIGHT_TEX[i++];
        const im = new Image();
        if (/^https?:/.test(url)) im.crossOrigin = 'anonymous';
        im.onload = () => {
            sunPathSat.night = im;
            if (sunPathState) updateSunPath();
            if (cb) cb();
        };
        im.onerror = tryNext;
        im.src = url;
    };
    tryNext();
}


// The ground seen from standing height, rendered PER PIXEL rather than pasted on as a pattern.
//
// A pattern was wrong in the way that matters: the ground recedes, so a square of it near the
// horizon covers a tiny slice of the frame and a square at your feet covers a huge one. Tiling a
// flat image over that gave a smear with no depth in it, which is what "completely messed up"
// describes. Here every pixel below the horizon is turned back into a ray, the ray is intersected
// with the ground plane, and the resulting distance and bearing are looked up in the imagery. The
// result has real perspective: the texture compresses toward the horizon of its own accord.
//
// The eye is HIGH, and deliberately. At standing height the whole visible ground is a couple of
// kilometres across, which on a 2048-wide world image is a single pixel repeated — the render is
// then perfectly correct and perfectly featureless. From twenty kilometres up the foreground is
// tens of kilometres and the horizon hundreds, which is the scale that image has something to
// say at. The pane is a diagram of the sky rather than a photograph, so there is no true answer
// here; there is only the height at which the ground has any texture to show.
const SUNPATH_EYE_KM = 20;
// Re-rendered only when the view has actually moved. Playing a day moves the camera with the sun,
// so this is not free, but a degree of bearing is far below what the imagery resolves.
let sunPathGroundCache = { key: null, cv: null };
function sunPathGroundImage(camAlt, camAz, fovDeg, W, H, lat, lon) {
    const img = sunPathSat.day;
    if (!img) return null;
    const key = [Math.round(camAlt), Math.round(camAz), Math.round(fovDeg), W, H,
                 lat.toFixed(2), lon.toFixed(2)].join('|');
    if (sunPathGroundCache.key === key) return sunPathGroundCache.url;
    // Drawn at a quarter scale and stretched back up: this is a soft, hazy surface with no fine
    // detail worth resolving, and a full-size per-pixel loop on every clock tick is not free.
    const w = Math.max(24, Math.round(W / 4)), h = Math.max(24, Math.round(H / 4));
    const src = document.createElement('canvas');
    src.width = img.width; src.height = img.height;
    const sctx = src.getContext('2d', { willReadFrequently: true });
    sctx.drawImage(img, 0, 0);
    const sdata = sctx.getImageData(0, 0, img.width, img.height).data;
    const cv = document.createElement('canvas');
    cv.width = w; cv.height = h;
    const ctx = cv.getContext('2d');
    const out = ctx.createImageData(w, h);
    const kdeg = (W / 2) / (fovDeg / 2);          // the pane's own pixels per degree
    const cosA = Math.cos(camAlt * DEG), sinA = Math.sin(camAlt * DEG);
    for (let py = 0; py < h; py++) {
        // Back to the pane's coordinates, then to the camera-frame angles the projection uses.
        const ay = (H / 2 - (py + 0.5) * (H / h)) / kdeg;      // degrees up from centre
        for (let px = 0; px < w; px++) {
            const ax = ((px + 0.5) * (W / w) - W / 2) / kdeg;  // degrees right of centre
            // The ray in the camera frame, then rotated into the observer's frame by the camera's
            // own altitude. Azimuth is handled as a bearing offset below, which is exact because
            // the ground is a plane and a bearing is a bearing.
            const ca = Math.cos(ay * DEG), sa = Math.sin(ay * DEG);
            const cx2 = Math.cos(ax * DEG), sx2 = Math.sin(ax * DEG);
            const fwd = ca * cx2, rgt = ca * sx2, upv = sa;
            // Rotate about the camera's right axis by the camera's altitude.
            const up2 = upv * cosA + fwd * sinA;
            const fw2 = fwd * cosA - upv * sinA;
            const i4 = (py * w + px) * 4;
            if (up2 >= -0.004) { out.data[i4 + 3] = 0; continue; }   // at or above the horizon
            const horiz = Math.hypot(fw2, rgt);
            const distKm = SUNPATH_EYE_KM * horiz / (-up2);
            if (!isFinite(distKm) || distKm > 4000) { out.data[i4 + 3] = 0; continue; }
            const bearing = camAz + Math.atan2(rgt, fw2) / DEG;
            // Flat-earth offset, which at these distances is the right answer to five figures.
            const dLat = distKm / 111.32 * Math.cos(bearing * DEG);
            const dLon = distKm / 111.32 * Math.sin(bearing * DEG) /
                Math.max(0.08, Math.cos((lat + dLat / 2) * DEG));
            const la = Math.max(-89.9, Math.min(89.9, lat + dLat));
            const lo = ((lon + dLon + 540) % 360) - 180;
            const sx = Math.min(img.width - 1, Math.max(0, Math.round((lo + 180) / 360 * img.width)));
            const sy = Math.min(img.height - 1, Math.max(0, Math.round((90 - la) / 180 * img.height)));
            const j = (sy * img.width + sx) * 4;
            out.data[i4] = sdata[j];
            out.data[i4 + 1] = sdata[j + 1];
            out.data[i4 + 2] = sdata[j + 2];
            out.data[i4 + 3] = 255;
        }
    }
    ctx.putImageData(out, 0, 0);
    // The data URL is cached, not the canvas: `toDataURL` is the expensive half of this and it
    // was being paid on every draw even when the pixels had not changed.
    const url = cv.toDataURL('image/jpeg', 0.85);
    sunPathGroundCache = { key, url };
    return url;
}

// THE GROUND UNDER THE DOME, as a real map of where the observer is standing.
//
// The projection is AZIMUTHAL EQUIDISTANT centred on them, and that is not a free choice: the
// disc is being looked at from its own centre, so what a viewer reads off it is direction and
// distance from that centre — which is exactly the pair this projection keeps true. Every bearing
// from the middle is a straight line at its true compass angle, and distance along it is to
// scale, so the compass rose drawn on top of the disc means what it says at every radius. A
// Mercator patch would have neither property and would put north-east at some other angle.
//
// The disc is textured north-up, which is why the dome's own compass rose lines up with it.
const SUNPATH_LOCAL_SPAN_KM = 900;      // the radius the disc covers on the ground
function sunPathLocalMap(lat, lon, px) {
    const N = px || 1024;
    // Same trap, same fix: whichever of the two actually has features in it.
    const feats = ((sunPathState && (sunPathState.landFeatures || []).length)
                   ? sunPathState.landFeatures
                   : (gameState.countries || []));
    const cv = document.createElement('canvas');
    cv.width = N; cv.height = N;
    const ctx = cv.getContext('2d');
    const radiusDeg = SUNPATH_LOCAL_SPAN_KM / 111.32;
    const proj = d3.geoAzimuthalEquidistant()
        .rotate([-lon, -lat])
        .translate([N / 2, N / 2])
        .scale((N / 2) / (radiusDeg * DEG))
        .clipAngle(179)
        .precision(0.3);

    if (sunPathState && sunPathState.satellite && sunPathSat.day) {
        // The imagery, re-projected pixel by pixel: an inverse for each destination pixel, then a
        // lookup in the equirectangular source. The same walk the spaceship view's own satellite
        // reprojection does, and for the same reason — a destination-side loop can fill any
        // projection at all, where a source-side one can fill none of them.
        const img = sunPathSat.day;
        const sc = document.createElement('canvas');
        sc.width = img.width; sc.height = img.height;
        const sctx = sc.getContext('2d', { willReadFrequently: true });
        sctx.drawImage(img, 0, 0);
        const sd = sctx.getImageData(0, 0, img.width, img.height).data;
        const out = ctx.createImageData(N, N);
        for (let y = 0; y < N; y++) {
            for (let x = 0; x < N; x++) {
                const ll = proj.invert([x + 0.5, y + 0.5]);
                const i4 = (y * N + x) * 4;
                if (!ll || !isFinite(ll[0])) { out.data[i4 + 3] = 0; continue; }
                const sx = Math.min(img.width - 1, Math.max(0, Math.round((ll[0] + 180) / 360 * img.width)));
                const sy = Math.min(img.height - 1, Math.max(0, Math.round((90 - ll[1]) / 180 * img.height)));
                const j = (sy * img.width + sx) * 4;
                out.data[i4] = sd[j];
                out.data[i4 + 1] = sd[j + 1];
                out.data[i4 + 2] = sd[j + 2];
                out.data[i4 + 3] = 255;
            }
        }
        ctx.putImageData(out, 0, 0);
        return cv;
    }

    if (!feats.length) return null;
    ctx.fillStyle = '#9fb8cc';
    ctx.fillRect(0, 0, N, N);
    const pth = d3.geoPath(proj, ctx);
    ctx.beginPath();
    feats.forEach(f => pth(f));
    ctx.fillStyle = '#cbc3a4';
    ctx.fill();
    ctx.lineWidth = Math.max(1, N / 340);
    ctx.strokeStyle = '#a79c78';
    ctx.stroke();
    return cv;
}

function sunPathEarthCanvas(features) {
    const feats = features || sunPathState && sunPathState.landFeatures || gameState.countries || [];
    if (!feats.length) return null;
    const W = 2048, Hh = 1024;
    const cv = document.createElement('canvas');
    cv.width = W; cv.height = Hh;
    const ctx = cv.getContext('2d');
    // Satellite, when it is on and the image is here. The vector map is not a fallback anybody
    // should be ashamed of — it is the clearer of the two at this size — so it stays the default.
    if (sunPathState && sunPathState.satellite && sunPathSat.day) {
        ctx.drawImage(sunPathSat.day, 0, 0, W, Hh);
        return cv;
    }
    ctx.fillStyle = '#9fb8cc';                    // .sp-map-ocean
    ctx.fillRect(0, 0, W, Hh);
    ctx.save();
    const proj = d3.geoEquirectangular().scale(W / (2 * Math.PI)).translate([W / 2, Hh / 2]).precision(0.2);
    const p = d3.geoPath(proj, ctx);
    ctx.beginPath();
    feats.forEach(f => p(f));
    ctx.fillStyle = '#cbc3a4';                    // .sp-map-land
    ctx.fill();
    ctx.lineWidth = 1.2;
    ctx.strokeStyle = '#a79c78';
    ctx.stroke();
    ctx.restore();
    return cv;
}

// Paint that canvas onto an earth mesh.
function applyEarthTexture(mesh, cv) {
    const T = window.THREE;
    if (!T || !mesh || !cv) return;
    const tex = new T.CanvasTexture(cv);
    if (T.SRGBColorSpace) tex.colorSpace = T.SRGBColorSpace;
    if (mesh.material.map) mesh.material.map.dispose();
    mesh.material.map = tex;
    mesh.material.color = new T.Color(0xffffff);
    mesh.material.needsUpdate = true;
}

function refreshSunPathEarthTexture(force) {
    const th = sunPathState && sunPathState.three && sunPathState.three.globe;
    if (!window.THREE || !th || !th.earth) return;
    // The image arrives over a load event, so a first call with satellite on has nothing to draw
    // yet: ask for it and come back. `force` is the checkbox's own call, which must not be
    // short-circuited by a texture that is already painted.
    if (sunPathState.satellite && !sunPathSat.day) {
        ensureSunPathSat(() => { if (sunPathState) { refreshSunPathEarthTexture(true); updateSunPath(); } });
        return;                      // nothing to paint yet; the callback comes back here
    }
    const cv = sunPathEarthCanvas();
    if (!cv) return;
    applyEarthTexture(th.earth, cv);
    sunPathState.earthTexCanvas = cv;
    // The dome's ground disc is the same imagery seen from a metre up.
    refreshSunPathDomeGround();
}

// The ground under the observer in the dome pane: a patch of real surface when satellite is on,
// the flat land colour when it is not.
// How big the dome's ground disc is drawn. 1024 across a 900 km radius is about 1.8 km a pixel,
// which is roughly what a 2048-wide world image holds and well past what a disc this size shows.
const SUNPATH_PATCH_PX = 1024;
// ONE LOCATION, EVERY PANE. `sunPathState.lat/lon` is the only place the observer lives, and each
// pane derives its own picture from it on every update — except this disc, which is a texture and
// therefore has to be told. It was built once and never re-cut, so moving the observer moved the
// sun's arc, the globe's marker and the map's pin while the ground under the dome quietly stayed
// where it had started: three panes at the new place and one at the old.
//
// Rebuilt only when the location actually changes, since re-projecting the world into a 1024 px
// disc is not something to do sixty times a second.
let sunPathDomeGroundAt = null;
function refreshSunPathDomeGround(force) {
    const T = window.THREE;
    const disc = sunPathState && sunPathState.domeGround;
    if (!T || !disc) return;
    const key = [sunPathState.lat.toFixed(3), sunPathState.lon.toFixed(3),
                 !!sunPathState.satellite, !!sunPathSat.day].join('|');
    if (!force && sunPathDomeGroundAt === key) return;
    sunPathDomeGroundAt = key;
    // Drawn whenever there is anything to draw it FROM — the vector world always, the imagery when
    // satellite is on. The disc is the ground the observer is standing on, and a plain coloured
    // circle says nothing at all about where that is.
    //
    // `a || b` is the wrong test between two arrays: an EMPTY array is truthy, so
    // `gameState.countries || landFeatures` returns the empty one and never looks at the full
    // one. In this mode `gameState.countries` is often empty and `landFeatures` holds the world,
    // which is exactly the case that silently left the disc a flat colour.
    const have = ((gameState.countries || []).length ? gameState.countries
                  : (sunPathState.landFeatures || []));
    const want = !!(have.length || sunPathSat.day);
    if (!want) {
        if (disc.material.map) { disc.material.map.dispose(); disc.material.map = null; }
        disc.material.color = new T.Color(themeColor('--land', '#cbc3a4'));
        disc.material.opacity = 0.92;
        disc.material.needsUpdate = true;
        return;
    }
    const cv = sunPathLocalMap(sunPathState.lat, sunPathState.lon, SUNPATH_PATCH_PX);
    if (!cv) return;
    const tex = new T.CanvasTexture(cv);
    if (T.SRGBColorSpace) tex.colorSpace = T.SRGBColorSpace;
    if (disc.material.map) disc.material.map.dispose();
    disc.material.map = tex;
    disc.material.color = new T.Color(0xffffff);
    disc.material.opacity = 1;
    disc.material.needsUpdate = true;
}

// ---- the Earth-in-space pane, as a reusable scene ----
// Sun Path's globe pane and Read the Daylight's reveal are the same picture: a textured earth
// on a tilted axis, lit from +X, ringed by the fixed parallels. Everything below is expressed
// against an explicit scene rather than sunPathState, so either caller can build one.
// Returns the handles both of them need.
function buildEarthInSpace(scene, opts) {
    const T = window.THREE;
    const o = opts || {};
    const holder = new T.Group();
    scene.add(holder);

    const earth = new T.Mesh(new T.SphereGeometry(1, 64, 48),
        new T.MeshLambertMaterial({ color: 0x9fb8cc }));
    holder.add(earth);
    applyEarthTexture(earth, sunPathEarthCanvas(o.features));

    const sun = new T.DirectionalLight(0xffffff, 2.6);
    sun.position.set(5, 0, 0);
    scene.add(sun);
    // Enough ambient that the night side stays readable. The default view is edge-on to the
    // sunlight, so the middle of the visible face sits exactly on the terminator where Lambert
    // shading is zero — with a darker ambient the whole pane read as an unlit ball.
    scene.add(new T.AmbientLight(0x3c5170, 1.6));

    // The sun, with its ray to the sub-solar point. Both are tagged noFrame: the auto-framing
    // must ignore them or it would pull the camera back far enough to fit a body 3.3 radii away
    // and shrink the earth to a marble. Handles come back so the caller can move them — which is
    // what happens when the earth is held still and the sun is the thing that goes round.
    //
    // The 'Sunlight' label is gone. It named the one object in the pane nobody was going to
    // mistake for anything else, and it was the widest sprite in the scene.
    let sunBall = null, sunRay = null;
    if (o.sunBall !== false) {
        sunBall = new T.Mesh(new T.SphereGeometry(0.13, 16, 16), new T.MeshBasicMaterial({ color: 0xffcf5c }));
        sunBall.position.set(3.3, 0, 0);
        sunBall.userData.noFrame = true;
        scene.add(sunBall);
        sunRay = lineFrom([new T.Vector3(3.1, 0, 0), new T.Vector3(1.02, 0, 0)], 0xffcf5c, 0.85);
        sunRay.userData.noFrame = true;
        scene.add(sunRay);
    }

    // Fixed furniture on the globe: the axis, the equator, the tropics and polar circles.
    holder.add(lineFrom([new T.Vector3(0, -1.5, 0), new T.Vector3(0, 1.5, 0)], 0xffd28a, 0.9));
    holder.add(parallelRing(0, 0xffffff, 0.8));
    [OBLIQUITY_DEG, -OBLIQUITY_DEG].forEach(l => holder.add(parallelRing(l, 0xd9a441, 0.6)));
    [90 - OBLIQUITY_DEG, -(90 - OBLIQUITY_DEG)].forEach(l => holder.add(parallelRing(l, 0x7fb6d9, 0.6)));

    const dyn = new T.Group();
    scene.add(dyn);          // horizon plane + angle marks live in WORLD space, not the tilted frame
    const holderDyn = new T.Group();
    holder.add(holderDyn);
    return { holder, earth, dyn, holderDyn, light: sun, sunBall, sunRay };
}

// Leader lines out to a left-hand column, one per parallel that is actually facing us.
//
// Everything is built in the CAMERA's own basis and then converted back to world space, which
// is what lets a scene the user can pivot still produce a tidy screen-space column: the leader
// runs level (constant camera-y), the labels all start at the same camera-x, and the leaders
// begin clear of the longest of them. Only the near half of each ring is considered — a leader
// to a point round the back would cross the planet to get there.
function sunPathGlobeLeaders(th, now) {
    const T = window.THREE;
    const cam = th.camera;
    const dir = cam.position.clone().normalize();
    const right = new T.Vector3().crossVectors(new T.Vector3(0, 1, 0), dir).normalize();
    const up = new T.Vector3().crossVectors(dir, right).normalize();
    const halfW = Math.abs(cam.right || 2), halfH = Math.abs(cam.top || 2);
    const tilt = new T.Vector3(0, 0, 1);
    const xLabel = -halfW * 0.985;

    const rows = [];
    sunPathParallels(now.lat).forEach(par => {
        const rr = Math.cos(par.lat * DEG), yy = Math.sin(par.lat * DEG);
        let best = null;
        for (let a = 0; a < 360; a += 3) {
            // Ring point in holder space, then tipped into world space by the declination.
            const v = new T.Vector3(Math.cos(a * DEG) * rr, yy, Math.sin(a * DEG) * rr)
                .multiplyScalar(1.004).applyAxisAngle(tilt, -now.dec * DEG);
            if (v.dot(dir) <= 0.06) continue;                 // facing away
            const x = v.dot(right);
            if (!best || x < best.x) best = { x, y: v.dot(up), z: v.dot(dir), v };
        }
        if (!best) return;
        rows.push({ par, best });
    });
    if (!rows.length) return;

    const labels = rows.map(({ par }) => makeLabel(par.name, par.you ? '#ffc9c0' : '#dbe6f4', 0.088));
    const maxW = Math.max(...labels.map(l => l.userData.labelW));
    const xLeader = xLabel + maxW + 0.06;

    rows.forEach(({ par, best }, i) => {
        const lab = labels[i];
        const toWorld = (cx, cy, cz) => right.clone().multiplyScalar(cx)
            .add(up.clone().multiplyScalar(cy)).add(dir.clone().multiplyScalar(cz));
        // Left-aligned: the sprite is centred on its position, so shift it half a width right.
        lab.position.copy(toWorld(xLabel + lab.userData.labelW / 2, best.y, best.z));
        th.dyn.add(lab);
        const colour = par.you ? 0xd05c4a : (par.cls === 'equator' ? 0xffffff : par.cls === 'tropic' ? 0xd9a441 : 0x7fb6d9);
        th.dyn.add(lineFrom([toWorld(xLeader, best.y, best.z), toWorld(best.x, best.y, best.z)],
            colour, par.you ? 0.95 : 0.6));
    });
}

function parallelRing(latDeg, colour, opacity) {
    const T = window.THREE;
    const r = Math.cos(latDeg * DEG), y = Math.sin(latDeg * DEG);
    const pts = [];
    for (let i = 0; i <= 96; i++) {
        const a = i / 96 * Math.PI * 2;
        pts.push(new T.Vector3(Math.cos(a) * r * 1.004, y * 1.004, Math.sin(a) * r * 1.004));
    }
    return lineFrom(pts, colour, opacity);
}

// An arc between two directions, for marking an angle.
function angleArc(from, to, radius, colour, opacity) {
    const T = window.THREE;
    const a = from.clone().normalize(), b = to.clone().normalize();
    const pts = [];
    for (let i = 0; i <= 32; i++) {
        const v = new T.Vector3().copy(a).lerp(b, i / 32).normalize().multiplyScalar(radius);
        pts.push(v);
    }
    return lineFrom(pts, colour, opacity == null ? 0.9 : opacity);
}

function updateGlobeScene(now) {
    const T = window.THREE, th = sunPathState.three && sunPathState.three.globe;
    if (!th) return;
    clearGroup(th.dyn);
    clearGroup(th.holderDyn);

    // TWO FRAMES, and the switch between them is what Track sun means in this pane.
    //
    // TRACKING (the original): the light is nailed to +X and the earth turns under it, so the
    // sub-solar point holds still in the frame and the day sweeps across the geography. The tilt
    // is carried by the holder — tipping the axis by the declination is what puts the sub-solar
    // latitude where it belongs.
    //
    // NOT TRACKING: the earth holds still and the SUN goes round it, which is the view from the
    // ground rather than from the sun. The tilt then has to move from the earth to the sun's
    // path: with the axis upright, the sun runs its daily circle at the declination's own
    // latitude about that axis, which is exactly what a diurnal circle is. Physically the same
    // picture; the difference is only which of the two is held still, and that is the whole of
    // what somebody switching this off is asking to see.
    const track = sunPathState.trackSun !== false;
    th.holder.rotation.set(0, 0, track ? -now.dec * DEG : 0);
    // SphereGeometry places an unmirrored equirectangular map's longitude L at mesh angle -L.
    // Tracking, the sub-solar longitude (lon - H) has to land at +X; held still, the observer's
    // own longitude does, so their meridian faces the camera's default position and the sun
    // visibly comes round to them.
    if (th.earth) th.earth.rotation.y = (track ? (now.H - now.lon) : -now.lon) * DEG;
    // Where the sunlight comes from. Tracking, +X and nothing else; held still, the daily circle.
    // The sub-solar longitude is `lon - H`, so RELATIVE to the observer's meridian — which is
    // what the earth is aligned to when it is held still — the sun sits at -H. Everything else in
    // this pane maps a relative longitude L to z = -cos(lat)·sin(L), so the sun's z is
    // -cos(dec)·sin(-H) = +cos(dec)·sin(H). Writing the minus by analogy with the observer's own
    // position (which is at +H, not -H) sent it round the sky backwards — and the moon, which is
    // built from its own sub-point and needs no such reasoning, was right all along.
    const sunDir = track
        ? new T.Vector3(1, 0, 0)
        : new T.Vector3(Math.cos(now.dec * DEG) * Math.cos(now.H * DEG),
                        Math.sin(now.dec * DEG),
                        Math.cos(now.dec * DEG) * Math.sin(now.H * DEG));
    if (th.light) th.light.position.copy(sunDir.clone().multiplyScalar(5));
    if (th.sunBall) th.sunBall.position.copy(sunDir.clone().multiplyScalar(3.3));
    if (th.sunRay) {
        const pts = [sunDir.clone().multiplyScalar(3.0), sunDir.clone().multiplyScalar(1.02)];
        th.sunRay.geometry.setFromPoints(pts);
        th.sunRay.geometry.computeBoundingSphere();
    }

    // The moon, as a body rather than a marker: a small sphere out past the earth in the
    // direction of its own sub-point, lit from wherever the sun is. Placed at a tenth of the real
    // distance — sixty earth radii would put it three screens away and the pane would either
    // frame a marble or lose the moon entirely — and tagged noFrame for the same reason the sun
    // is. What it is honestly showing is the DIRECTION, which is the thing worth seeing.
    if (sunPathState.showMoon) {
        const m = sunPathMoonNow(now);
        if (m && m.sub) {
            // The sub-lunar point in the same frame as everything else: tracking, longitudes are
            // measured from the sub-solar meridian; held still, from the observer's own.
            const rel = track ? (m.sub[0] - (now.lon - now.H)) : (m.sub[0] - now.lon);
            const la = m.sub[1] * DEG, lo = rel * DEG;
            const dir = new T.Vector3(Math.cos(la) * Math.cos(lo), Math.sin(la),
                                      -Math.cos(la) * Math.sin(lo));
            if (track) dir.applyAxisAngle(new T.Vector3(0, 0, 1), -now.dec * DEG);
            const ball = new T.Mesh(new T.SphereGeometry(0.075, 20, 14),
                new T.MeshLambertMaterial({ color: 0xd8d4c8 }));
            ball.position.copy(dir.clone().multiplyScalar(2.35));
            ball.userData.noFrame = true;
            th.dyn.add(ball);
            const lab = makeLabel(`moon ${(m.k * 100).toFixed(0)}%`, '#d6dbe6', 0.1);
            lab.position.copy(dir.clone().multiplyScalar(2.62));
            lab.userData.noFrame = true;
            th.dyn.add(lab);
        }
    }

    // The observer's parallel — the sixth, and the only one that moves.
    th.holderDyn.add(parallelRing(now.lat, 0xd05c4a, 0.9));
    sunPathGlobeLeaders(th, now);
    const r = Math.cos(now.lat * DEG), y = Math.sin(now.lat * DEG);
    // Hour angle 0 = local noon = facing the sun. In the tilted frame that is +X.
    //
    // The z term is NEGATIVE and that sets the handedness of the whole pane. The earth turns
    // eastward about +Y, and east at a point is Y x up — which at the +X meridian is -Z. So as
    // the hour advances the observer must move toward -Z. With +sin(H) the globe span backwards
    // and the entire world came out mirrored east-west: measuring the sun's azimuth in the
    // observer's own local frame returned 360 - az (249 deg at 09:00 instead of 111 deg).
    // Tracking, the observer rides round with the hour angle. Held still, they stay put at their
    // own meridian and it is the sun that moves — which is the point of holding it still.
    const spin = (track ? now.H : 0) * DEG;
    const local = new T.Vector3(Math.cos(spin) * r, y, -Math.sin(spin) * r);
    // No marker ball: the figure standing on the horizon disc below IS the observer, and two
    // markers for one person only invited the question of which was which.

    // The observer's HORIZON: the tangent plane at their feet. Its edge-on line is what makes
    // "how high is the sun" a visible angle rather than an assertion.
    const up = local.clone().normalize();
    const east = new T.Vector3(0, 1, 0).cross(up).normalize();
    const north = up.clone().cross(east).normalize();
    const disc = [];
    for (let i = 0; i <= 64; i++) {
        const a = i / 64 * Math.PI * 2;
        disc.push(up.clone().multiplyScalar(1.001)
            .add(east.clone().multiplyScalar(Math.cos(a) * 0.42))
            .add(north.clone().multiplyScalar(Math.sin(a) * 0.42)));
    }
    th.holderDyn.add(lineFrom(disc, 0x4fc3f7, 0.95));

    // The Sky-above-you pane, in miniature and in place: a faint dome standing on that horizon
    // circle, with the sun's track arcing over it. This is the whole point of showing both — the
    // dome the observer stands under IS this tangent disc, seen from outside.
    const DOME_R = 0.42;
    const domeGeo = new T.SphereGeometry(DOME_R, 28, 14, 0, Math.PI * 2, 0, Math.PI / 2);
    const dome = new T.Mesh(domeGeo, new T.MeshBasicMaterial({
        color: 0x8fd3f4, transparent: true, opacity: 0.13, side: T.DoubleSide, depthWrite: false
    }));
    dome.position.copy(up.clone().multiplyScalar(1.001));
    // SphereGeometry's own +Y is the dome's zenith; aim it along the observer's up.
    dome.quaternion.setFromUnitVectors(new T.Vector3(0, 1, 0), up);
    th.holderDyn.add(dome);

    // The sun's arc over that dome, in the observer's own alt/az frame — the same curve the
    // Sky-above-you pane draws, so the two read as the same object.
    const base = up.clone().multiplyScalar(1.001);
    const localVec = (alt, az) => base.clone()
        .add(up.clone().multiplyScalar(Math.sin(alt * DEG) * DOME_R))
        .add(east.clone().multiplyScalar(Math.cos(alt * DEG) * Math.sin(az * DEG) * DOME_R))
        .add(north.clone().multiplyScalar(Math.cos(alt * DEG) * Math.cos(az * DEG) * DOME_R));
    const arcRuns = [];
    let run = null;
    for (let Hh = -180; Hh <= 180; Hh += 3) {
        const a = sunAltitude(now.lat, now.dec, Hh);
        const lit = a >= 0;
        if (!run || run.lit !== lit) { run = { lit, pts: [] }; arcRuns.push(run); }
        run.pts.push(localVec(a, sunAzimuth(now.lat, now.dec, Hh)));
    }
    if (arcRuns.length > 1 && arcRuns[0].lit === arcRuns[arcRuns.length - 1].lit) {
        const first = arcRuns.shift();                 // the track is a closed loop in hour angle
        arcRuns[arcRuns.length - 1].pts.push(...first.pts);
    }
    arcRuns.forEach(r => {
        if (r.pts.length < 2) return;
        th.holderDyn.add(r.lit ? lineFrom(r.pts, 0xf0a92b, 0.95) : dashedFrom(r.pts, 0xf0a92b, 0.4));
    });
    if (now.alt > -6) {
        const ball = new T.Mesh(new T.SphereGeometry(0.028, 10, 10),
            new T.MeshBasicMaterial({ color: 0xffcf5c }));
        ball.position.copy(localVec(now.alt, now.az));
        th.holderDyn.add(ball);
    }

    // The same figure as the sky pane, standing on the same horizon disc — the point being that
    // the tangent plane here and the ground there are one surface. Built in the observer's own
    // (east, north, up) basis and then dropped into place, so the shadow lies flat on the disc.
    const FIG_H = 0.075;
    const fig = makeSunPathFigure(FIG_H);
    fig.position.copy(base);
    fig.quaternion.setFromUnitVectors(new T.Vector3(0, 1, 0), up);
    th.holderDyn.add(fig);
    if (now.alt > 0) {
        const awayAz = (now.az + 180) % 360;
        const away = north.clone().multiplyScalar(Math.cos(awayAz * DEG))
            .add(east.clone().multiplyScalar(Math.sin(awayAz * DEG))).normalize();
        const side = up.clone().cross(away).normalize();
        const len = Math.min(DOME_R * 0.92, FIG_H / Math.max(0.09, Math.tan(Math.max(0.5, now.alt) * DEG)));
        const w0 = FIG_H * 0.30, w1 = w0 * 0.86;      // constant width — see sunPathShadow
        const o0 = base.clone().add(up.clone().multiplyScalar(0.0015));
        const tip = o0.clone().add(away.clone().multiplyScalar(len));
        const pts = [
            o0.clone().add(side.clone().multiplyScalar(w0)),
            o0.clone().add(side.clone().multiplyScalar(-w0)),
            tip.clone().add(side.clone().multiplyScalar(-w1)),
            o0.clone().add(side.clone().multiplyScalar(w0)),
            tip.clone().add(side.clone().multiplyScalar(-w1)),
            tip.clone().add(side.clone().multiplyScalar(w1))
        ];
        th.holderDyn.add(new T.Mesh(new T.BufferGeometry().setFromPoints(pts),
            new T.MeshBasicMaterial({ color: 0x241c12, transparent: true, opacity: 0.62,
                                      side: T.DoubleSide, depthWrite: false })));
    }

    // Latitude, marked as the angle from the equatorial plane up to the observer.
    const eqFoot = new T.Vector3(local.x, 0, local.z).normalize();
    th.holderDyn.add(angleArc(eqFoot, up, 0.55, 0xd05c4a, 0.9));
    const latLab = makeLabel(`${Math.abs(now.lat).toFixed(0)}° latitude`, '#ffc9c0', 0.10);
    latLab.position.copy(eqFoot.clone().lerp(up, 0.5).normalize().multiplyScalar(0.72));
    th.holderDyn.add(latLab);

    // Axial tilt, marked in WORLD space between the tipped axis and the orbital normal.
    // The zoom is locked (the earth is always 90% of the frame height), so these have to fit
    // inside that frame rather than expect the camera to back off for them: the orbital-normal
    // line stops just above the pole, the tilt arc sits just off the surface, and the label is
    // pushed sideways in CAMERA space — there is plenty of horizontal room in a pane this wide,
    // and sideways is the one direction that stays clear whichever way the globe is pivoted.
    const axis = new T.Vector3(0, 1, 0).applyAxisAngle(new T.Vector3(0, 0, 1), -now.dec * DEG);
    th.dyn.add(lineFrom([new T.Vector3(0, 0, 0), new T.Vector3(0, 1.08, 0)], 0x8a94a6, 0.45));
    th.dyn.add(angleArc(new T.Vector3(0, 1, 0), axis, 1.03, 0xffd28a, 0.95));
    const tiltLab = makeLabel(`${Math.abs(now.dec).toFixed(1)}° toward the sun`, '#ffe6b0', 0.105);
    const camDir = th.camera.position.clone().normalize();
    const camRight = new T.Vector3().crossVectors(new T.Vector3(0, 1, 0), camDir).normalize();
    tiltLab.position.copy(new T.Vector3(0, 1, 0).lerp(axis, 0.5).normalize().multiplyScalar(0.99)
        .add(camRight.multiplyScalar(0.12 + tiltLab.userData.labelW / 2)));
    th.dyn.add(tiltLab);

    // The sun's elevation for this observer, as an arc from their horizon up to the sunbeam,
    // plus the year's extremes at this latitude — the swing the seasons actually produce.
    const toSun = new T.Vector3(1, 0, 0);
    const worldUp = up.clone().applyAxisAngle(new T.Vector3(0, 0, 1), -now.dec * DEG);
    const horizonDir = toSun.clone().sub(worldUp.clone().multiplyScalar(toSun.dot(worldUp))).normalize();
    if (horizonDir.lengthSq() > 0.01) {
        th.dyn.add(angleArc(horizonDir, toSun, 0.9, 0xf0a92b, 0.95));
        // No label on this arc. The angle is drawn, the number is in the readout below, and a
        // sprite here was the widest thing in the pane — the auto-framing solves for whatever it
        // can see, so a long string shrank the earth itself to make room for it.
    }
}

// ---- GROUND: a normal camera pointed at the sun ----
// Not a fisheye and not the whole track: a 60-degree window that follows the sun round,
// which is what a person standing there would actually see. Below the horizon the sun keeps
// going on a dotted line, so "it is coming back up over there" stays visible.
// Wider than any real lens, and it can afford to be: with equal angles per pixel there is no
// edge penalty for opening it up, which is exactly what a rectilinear camera could not do. 150
// degrees puts most of a day's arc on screen at once without stretching any of it.
const GROUND_FOV = 150;

// The sky, keyed on the sun's altitude. Two colours per stop — zenith and horizon — because a
// flat fill can't show the thing that actually makes a sunset read as a sunset: the warm band
// sitting UNDER a still-blue dome. Interpolated between the bracketing stops, so dusk is a
// continuous slide rather than a set of states.
const SKY_STOPS = [
    { alt:  90, top: '#2c6cb4', bot: '#a9cde9' },
    { alt:  20, top: '#3777b9', bot: '#bedaef' },
    { alt:   6, top: '#3a6ea4', bot: '#f4c68f' },
    { alt:   0, top: '#335f95', bot: '#f0a165' },
    { alt:  -4, top: '#294a7d', bot: '#d97a4e' },
    { alt:  -8, top: '#1d3663', bot: '#9c5060' },
    { alt: -14, top: '#122444', bot: '#4a3559' },
    { alt: -20, top: '#0a1123', bot: '#131b2e' }
];

function skyColoursFor(alt) {
    const s = SKY_STOPS;
    if (alt >= s[0].alt) return s[0];
    if (alt <= s[s.length - 1].alt) return s[s.length - 1];
    for (let i = 0; i + 1 < s.length; i++) {
        if (alt <= s[i].alt && alt >= s[i + 1].alt) {
            const t = (s[i].alt - alt) / (s[i].alt - s[i + 1].alt);
            return {
                top: d3.interpolateRgb(s[i].top, s[i + 1].top)(t),
                bot: d3.interpolateRgb(s[i].bot, s[i + 1].bot)(t)
            };
        }
    }
    return s[0];
}

// A skyline, as a sum of sines of the TRUE azimuth — so the hills are pinned to compass
// directions and stay put as the camera pans, instead of sliding with the viewport.
// A FLAT horizon. What was here was a sum of four sine waves standing in for hills, and it was
// the one invented thing in a pane full of measured ones: it implied a landscape this mode knows
// nothing about, and every reading taken against it — where the sun sets, how high it is — was
// being taken against fiction. Sea level is both honest and the only horizon that means the same
// thing at every one of the places this pane can be pointed at.
function horizonReliefDeg() { return 0; }

function drawSunPathHorizon(now) {
    const svgH = d3.select('#sun-path-horizon');
    if (svgH.empty()) return;
    svgH.selectAll('*').remove();
    // Fill the cell rather than letterbox inside a fixed box: the pane is near-square, so a
    // 400x220 viewBox threw away half the height and left the sky a thin strip.
    const box = svgH.node().getBoundingClientRect();
    const W = 400;
    const H = box.width > 0 ? Math.round(W * Math.max(0.4, Math.min(2.2, box.height / box.width))) : 220;
    svgH.attr('viewBox', `0 0 ${W} ${H}`);
    // EQUAL ANGLES, EQUAL PIXELS. A degree of sky is the same number of pixels wherever it sits
    // in the frame, which is the only sense in which a wide-angle view can be called undistorted,
    // and the only one that matters here: the whole point of the pane is the SHAPE of the arc,
    // measured in degrees, and a projection that stretches the edges is drawing a different arc
    // from the one the sky has.
    //
    // This replaces a rectilinear (gnomonic) camera. Gnomonic is the photographer's undistorted
    // lens — straight lines stay straight — but it pays for that with a tan(), and across a 104
    // degree field tan() magnifies the edges more than threefold. That edge stretch is what reads
    // as a fisheye bulge, even though gnomonic is the exact opposite of a fisheye; it also
    // flattened the sun's arc toward the frame edges, which is the one thing this pane exists to
    // show honestly.
    //
    // What it costs: the horizon is a great circle and no longer a straight line, so it is
    // sampled and drawn as a shallow curve. That is what a wide panorama actually looks like.
    const kpx = (W / 2) / (GROUND_FOV / 2);                 // pixels per degree, both axes
    // Where the camera looks. Tracking, it is locked on the sun and the sun sits dead centre;
    // not tracking, it is a compass bearing and an elevation the viewer sets by dragging, and the
    // sun crosses the frame the way it crosses a window.
    const camAlt = sunPathState.trackSun ? now.alt : (sunPathState.groundEl || 0);
    const camAz = sunPathState.trackSun ? now.az
        : ((sunPathState.groundAz == null ? now.az : sunPathState.groundAz) + 360) % 360;
    const altR = camAlt * DEG, azR = camAz * DEG;
    const dirOf = (aAlt, aAz) => {                          // unit vector in (east, north, up)
        const ca = Math.cos(aAlt * DEG);
        return [ca * Math.sin(aAz * DEG), ca * Math.cos(aAz * DEG), Math.sin(aAlt * DEG)];
    };
    const f = dirOf(camAlt, camAz);                        // where the camera looks
    // right = normalize(f × zenith), which reduces to a purely horizontal vector depending on
    // AZIMUTH ALONE — so it stays well defined right up to the zenith, where the azimuth's own
    // 180° flip rolls the picture over of its own accord.
    const right = [Math.cos(azR), -Math.sin(azR), 0];
    const upc = [-Math.sin(altR) * Math.sin(azR), -Math.sin(altR) * Math.cos(azR), Math.cos(altR)];
    const dot3 = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
    const project = (alt, az) => {
        const p = dirOf(alt, az);
        const ax = Math.atan2(dot3(p, right), dot3(p, f)) / DEG;    // degrees left/right of centre
        const ay = Math.asin(Math.max(-1, Math.min(1, dot3(p, upc)))) / DEG;   // degrees up/down
        if (Math.abs(ax) > 179) return null;                        // directly behind
        return [W / 2 + kpx * ax, H / 2 - kpx * ay];
    };
    // On the centre column the vertical axis IS altitude, exactly, so the tick scale is linear
    // and needs no trigonometry at all.
    const altToY = a => H / 2 - kpx * (a - camAlt);
    const horizonY = altToY(0);

    // Sky: the gradient is anchored to the HORIZON rather than to the frame, so the warm band
    // stays where the sun actually is however the camera is pitched or rolled.
    const sky = skyColoursFor(now.alt);
    const defs = svgH.append('defs');
    const grad = defs.append('linearGradient').attr('id', 'sp-sky-grad')
        .attr('gradientUnits', 'userSpaceOnUse')
        .attr('x1', 0).attr('y1', horizonY - H).attr('x2', 0).attr('y2', horizonY);
    grad.append('stop').attr('offset', '0%').attr('stop-color', sky.top);
    grad.append('stop').attr('offset', '100%').attr('stop-color', sky.bot);
    svgH.append('rect').attr('width', W).attr('height', H).attr('fill', 'url(#sp-sky-grad)');

    // Ground: the skyline projected through the same camera, filled down past the frame edge.
    const dayness = Math.max(0, Math.min(1, (now.alt + 12) / 24));
    const groundCol = d3.interpolateRgb('#0d1017', '#6f6647')(dayness);
    {
        const pts = [];
        for (let t = -GROUND_FOV; t <= GROUND_FOV; t += 1.5) {
            const az = camAz + t;
            const q = project(horizonReliefDeg(az), az);
            if (q && q[0] > -W && q[0] < 2 * W) pts.push(q);
        }
        if (pts.length > 1) {
            pts.sort((a, b) => a[0] - b[0]);
            let d = `M${(-W).toFixed(1)},${H + 80}L${pts[0][0].toFixed(1)},${pts[0][1].toFixed(1)}`;
            for (let i = 1; i < pts.length; i++) d += `L${pts[i][0].toFixed(1)},${pts[i][1].toFixed(1)}`;
            d += `L${(2 * W).toFixed(1)},${H + 80}Z`;
            // A real ground plane when satellite is on: every pixel below the horizon traced
            // back to a point on the ground and looked up in the imagery, so the texture
            // compresses toward the horizon the way ground does. Clipped to the same skyline
            // polygon, so the relief still cuts into it.
            const gimg = sunPathState.satellite
                ? sunPathGroundImage(camAlt, camAz, GROUND_FOV, W, H, now.lat, now.lon) : null;
            if (gimg) {
                const cid = 'sp-ground-clip';
                defs.selectAll('#' + cid).remove();
                defs.append('clipPath').attr('id', cid).append('path').attr('d', d);
                const gg = svgH.append('g').attr('clip-path', `url(#${cid})`);
                gg.append('image').attr('href', gimg)
                    .attr('x', 0).attr('y', 0).attr('width', W).attr('height', H)
                    .attr('preserveAspectRatio', 'none');
                // Night is the same wash the flat fill uses, laid over the imagery.
                svgH.append('path').attr('d', d).attr('fill', '#0d1017')
                    .attr('opacity', (1 - dayness) * 0.82).attr('class', 'sp-ground-night');
            } else {
                svgH.append('path').attr('d', d).attr('fill', groundCol).attr('class', 'sp-ground-fill');
            }
        }
    }
    // The horizon, sampled rather than ruled: it is a great circle, and in an equal-angle
    // panorama a great circle is a shallow curve unless it runs through the centre.
    if (horizonY > -80 && horizonY < H + 80) {
        const hp = [];
        for (let t = -GROUND_FOV; t <= GROUND_FOV; t += 1.5) {
            const q = project(0, camAz + t);
            if (q && q[0] > -W && q[0] < 2 * W) hp.push(q);
        }
        if (hp.length > 1) {
            hp.sort((a, b) => a[0] - b[0]);
            svgH.append('path').attr('class', 'sp-horizon').attr('fill', 'none')
                .attr('d', 'M' + hp.map(q => q[0].toFixed(1) + ',' + q[1].toFixed(1)).join('L'));
        }
    }

    // The sun's track, cut into RUNS. Sorting samples into one above/below pair concatenates
    // stretches that are not continuous — the pre-dawn arc and the post-dusk one, and either of
    // them split again wherever the track leaves the camera's azimuth window — and drawing that
    // as a single polyline is the straight line that cut across the dotted arc.
    const line = pts => 'M' + pts.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join('L');
    const runs = [];
    let cur = null;
    for (let Hh = -180; Hh <= 180; Hh += 0.25) {
        const alt = sunAltitude(now.lat, now.dec, Hh);
        const az = sunAzimuth(now.lat, now.dec, Hh);
        const q = project(alt, az);
        const lit = alt >= 0;
        if (!q || q[0] < -W || q[0] > 2 * W || q[1] < -H || q[1] > 2 * H) { cur = null; continue; }
        if (!cur || cur.lit !== lit) { cur = { lit, pts: [] }; runs.push(cur); }
        cur.pts.push(q);
    }
    runs.forEach(r => {
        if (r.pts.length < 2) return;
        svgH.append('path').attr('class', 'sp-track' + (r.lit ? '' : ' below')).attr('d', line(r.pts));
    });

    // Altitude ticks UP THE MIDDLE, where the scale is exact. The vertical axis is only truly
    // altitude on the centre column — the camera's own vertical circle — and a gauge pinned to
    // the left edge was reading a column where it is merely close, while sitting as far as it
    // could get from the arc it is there to measure.
    const horizonInFrame = horizonY > 12 && horizonY < H - 12;
    const axX = W / 2;
    for (let a = -80; a <= 90; a += 20) {
        if (a === 0 && horizonInFrame) continue;    // the horizon line is already the 0 mark
        const y = altToY(a);
        if (!isFinite(y) || y < 12 || y > H - 12) continue;
        svgH.append('line').attr('class', 'sp-tick')
            .attr('x1', axX - 5).attr('x2', axX + 5).attr('y1', y).attr('y2', y);
        svgH.append('text').attr('class', 'sp-ticklabel').attr('x', axX + 9)
            .attr('y', y + 3.5).text(a + '°');
    }
    // Compass ticks along the horizon, wherever that line happens to fall.
    if (horizonInFrame) {
        for (let az = 0; az < 360; az += 10) {
            const q = project(0, az);
            if (!q || q[0] < 6 || q[0] > W - 6) continue;
            const card = { 0: 'N', 90: 'E', 180: 'S', 270: 'W' }[az];
            // Hung off the horizon WHERE IT ACTUALLY IS at that bearing rather than off one ruled
            // line: the curve means the two part company toward the edges of a wide frame.
            const hy = q[1];
            svgH.append('line').attr('class', 'sp-tick').attr('x1', q[0]).attr('x2', q[0])
                .attr('y1', hy).attr('y2', hy + (card ? 10 : 5));
            if (card || az % 30 === 0) {
                svgH.append('text').attr('class', card ? 'sp-compass' : 'sp-ticklabel')
                    .attr('x', q[0]).attr('y', hy + (card ? 24 : 18)).attr('text-anchor', 'middle')
                    .text(card || az + '°');
            }
        }
    }

    // The moon, when it is asked for: same camera, same projection, its own altitude and azimuth
    // for this instant. It is drawn as a disc with its lit fraction, which is the one thing about
    // the moon that changes fast enough to be worth watching alongside the sun.
    if (sunPathState.showMoon) {
        const m = sunPathMoonNow(now);
        if (m) {
            // The moon's own track across this sky, in white — the same construction as the sun's,
            // and the whole reason to draw it: the two arcs together are what "the moon rises an
            // hour later each night" looks like.
            const mruns = [];
            let mcur = null;
            for (let Hh = -180; Hh <= 180; Hh += 1) {
                const mm = sunPathMoonAt(now, Hh);
                if (!mm) continue;
                const q2 = project(mm.alt, mm.az);
                const lit = mm.alt >= 0;
                if (!q2 || q2[0] < -W || q2[0] > 2 * W || q2[1] < -H || q2[1] > 2 * H) { mcur = null; continue; }
                if (!mcur || mcur.lit !== lit) { mcur = { lit, pts: [] }; mruns.push(mcur); }
                mcur.pts.push(q2);
            }
            mruns.forEach(r2 => {
                if (r2.pts.length < 2) return;
                svgH.append('path').attr('class', 'sp-moontrack' + (r2.lit ? '' : ' below'))
                    .attr('d', line(r2.pts));
            });
            const q = project(m.alt, m.az);
            if (q && q[0] > -20 && q[0] < W + 20) {
                // Which way the lit limb points, ON SCREEN: from the moon toward the sun, in this
                // projection, so it turns as the pair move round each other rather than being
                // pinned to one side of the disc.
                const sq2 = project(now.alt, now.az);
                const bright = sq2 ? Math.atan2(sq2[1] - q[1], sq2[0] - q[0]) / DEG : 0;
                const g2 = svgH.append('g').attr('class', m.alt >= 0 ? 'sp-moon' : 'sp-moon below')
                    .attr('transform', `translate(${q[0].toFixed(1)},${q[1].toFixed(1)})`);
                sunPathMoonGlyph(g2, 7, m.k, bright);
            }
        }
    }

    // The sun. Dead centre while the camera is tracking it, and wherever it happens to be when
    // it is not — which is the whole difference the switch makes.
    const sq = project(now.alt, now.az);
    if (sq && sq[0] > -20 && sq[0] < W + 20) {
        svgH.append('circle').attr('class', now.alt >= 0 ? 'sp-sun' : 'sp-sun below')
            .attr('cx', sq[0]).attr('cy', sq[1]).attr('r', 9);
        svgH.append('text').attr('class', 'sp-altlabel').attr('x', sq[0])
            .attr('y', sq[1] - 14 < 12 ? sq[1] + 22 : sq[1] - 14)
            .attr('text-anchor', 'middle').text(`${now.alt.toFixed(0)}°`);
    }
}

// ---- Where in the orbit we are ----
// A schematic inset for the space pane: sun at the centre, the earth's orbit as a circle, the
// four turning points marked and the earth on it for the current date. Heliocentric longitude
// is taken as a linear walk of the year anchored so day 79 (the March equinox) is 0 — good to a
// couple of days, which is inside the width of the dot.
function drawSunPathOrbitInset(now) {
    const svg = d3.select('#sun-path-orbit-inset');
    if (svg.empty()) return;
    svg.selectAll('*').remove();
    const cx = 60, cy = 60, R = 40;
    const ang = d => ((d - 79) / 365.25) * 360;                 // degrees round the orbit
    const at = (d, r) => [cx + Math.cos(ang(d) * DEG) * r, cy - Math.sin(ang(d) * DEG) * r];

    svg.append('circle').attr('class', 'sp-orb-path').attr('cx', cx).attr('cy', cy).attr('r', R);
    svg.append('circle').attr('class', 'sp-orb-sun').attr('cx', cx).attr('cy', cy).attr('r', 6);
    SUNPATH_STOPS.forEach(s => {
        const p = at(s.day, R);
        svg.append('circle').attr('class', 'sp-orb-stop').attr('cx', p[0]).attr('cy', p[1]).attr('r', 2.4);
        const lp = at(s.day, R + 11);
        svg.append('text').attr('class', 'sp-orb-lab')
            .attr('x', lp[0]).attr('y', lp[1] + 2.5).attr('text-anchor', 'middle')
            .text(s.short.split(' ')[1] === 'solstice' ? 'sol' : 'eq');
    });
    const e = at(now.day, R);
    // The axis keeps a FIXED direction in space — that is the whole reason the seasons happen —
    // so it is drawn at the same screen angle all year, and the tilt toward or away from the sun
    // is something you read off rather than something the drawing asserts.
    const tiltDir = [Math.cos(-100 * DEG), Math.sin(-100 * DEG)];
    svg.append('line').attr('class', 'sp-orb-axis')
        .attr('x1', e[0] - tiltDir[0] * 7).attr('y1', e[1] - tiltDir[1] * 7)
        .attr('x2', e[0] + tiltDir[0] * 7).attr('y2', e[1] + tiltDir[1] * 7);
    svg.append('circle').attr('class', 'sp-orb-earth').attr('cx', e[0]).attr('cy', e[1]).attr('r', 4.5);
}







// ---- MAP: the sunrise line, clickable ----
let sunPathMap = null;
function buildSunPathMap() {
    const el = document.getElementById('sun-path-map');
    if (!el) return;
    const W = 400, H = 220;
    const svgM = d3.select(el);
    svgM.selectAll('*').remove();
    const proj = d3.geoEquirectangular().scale(W / (2 * Math.PI)).translate([W / 2, H / 2]).precision(0);
    const p = d3.geoPath().projection(proj);
    svgM.append('rect').attr('width', W).attr('height', H).attr('class', 'sp-map-ocean');
    // The satellite basemap sits UNDER the vector coastlines rather than replacing them: the
    // twilight caps drawn on top are what make it a day/night picture, and an outline still helps
    // at this size. Its href is set per draw, since the projection may be rotated to follow the
    // sun and the image has to move with it.
    const sat = svgM.append('g').attr('class', 'sp-map-sat');
    const land = svgM.append('g');
    // Whatever features this pane draws are also what the Earth-in-space globe is textured
    // with, so they are stashed rather than just drawn — the two panes must be one planet.
    const useFeatures = feats => {
        sunPathState.landFeatures = feats;
        // The FEATURE goes on the path. Without it, re-pathing after a rotation calls the path
        // generator with `undefined` and every country is assigned an empty `d` — which is why
        // the map vanished the moment Play moved the sun far enough to re-centre it.
        feats.forEach(f => {
            const d = p(f);
            if (d) land.append('path').datum(f).attr('class', 'sp-map-land').attr('d', d);
        });
        refreshSunPathEarthTexture();
        renderSunPathThree();
    };
    if ((gameState.countries || []).length) {
        useFeatures(gameState.countries);
    } else {
        // The world map this mode loads is whatever the last mode left behind; if there is
        // none, fetch the coarse one so the pane is never empty.
        fetchWorldTopo('https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json')
            .then(topo => {
                if (!sunPathState) return;
                useFeatures(topojson.feature(topo, topo.objects.countries).features);
            }).catch(() => {});
    }
    const dyn = svgM.append('g').attr('class', 'sp-map-dyn');

    // ZOOM AND PAN as a transform on the whole picture rather than by re-projecting. Every layer
    // here is drawn in the projection's own units and redrawn constantly, so a transform on one
    // containing group is the single place a zoom can live and be respected by all of them at
    // once — imagery, coastlines, terminator and bars — without any of them knowing about it.
    const wrap = svgM.append('g').attr('class', 'sp-map-zoom');
    wrap.node().appendChild(sat.node());
    wrap.node().appendChild(land.node());
    wrap.node().appendChild(dyn.node());

    // A click MOVES THE OBSERVER and a drag pans, so the two have to be told apart: the same 8 px
    // slop the rest of the app uses for exactly this question. The pointer is then un-transformed
    // before it is inverted, or a click on a zoomed map lands wherever it would have landed
    // unzoomed.
    let down = null;
    svgM.on('pointerdown.sp', function (event) { down = d3.pointer(event, this); });
    svgM.on('click', function (event) {
        const pt = d3.pointer(event, this);
        if (down && Math.hypot(pt[0] - down[0], pt[1] - down[1]) > 8) return;
        const t = d3.zoomTransform(svgM.node());
        const ll = proj.invert([(pt[0] - t.x) / t.k, (pt[1] - t.y) / t.k]);
        if (!ll || isNaN(ll[0])) return;
        sunPathState.lat = Math.max(-89, Math.min(89, ll[1]));
        sunPathState.lon = ll[0];
        updateSunPath();
    });
    svgM.call(d3.zoom().scaleExtent([1, 12])
        .translateExtent([[0, 0], [W, H]])
        .on('zoom', ev => wrap.attr('transform', ev.transform)));

    sunPathMap = { svg: svgM, proj, path: p, dyn, sat, land, W, H, wrap };
}

// The satellite basemap for the sunrise-line pane. The image is equirectangular and so is the
// pane, so this is a straight blit — rolled sideways when the map is centred on the sun, which is
// two draws of the same picture rather than a re-projection.
//
// The night side needs no image of its own: the twilight caps drawn over the top ARE the night.
// Where a real Black Marble is present it is clipped to the 90 degree cap and laid under them, so
// the dark half shows city lights instead of only being dark.
function sunPathDrawSatellite(c0) {
    const m = sunPathMap;
    if (!m) return;
    const on = !!(sunPathState.satellite);
    // The class is what the stylesheet keys the outline-only land off. Hanging that off the mere
    // EXISTENCE of the satellite group made every map unfilled, satellite or not: the group is
    // created once and lives there empty.
    m.svg.classed('sp-sat-on', on && !!sunPathSat.day);
    if (!on) { m.sat.selectAll('*').remove(); m.satShown = false; m.satAt = null; return; }
    if (!sunPathSat.day) {
        ensureSunPathSat(() => { if (sunPathState) updateSunPath(); });
        return;
    }
    if (m.satShown && m.satAt === c0 && !m.satDirty) return;
    m.satDirty = false;
    m.satShown = true;
    m.satAt = c0;
    m.sat.selectAll('*').remove();
    const W = m.W, H = m.H;
    // A rotation of c0 degrees east shifts the image left by that fraction of its width; two
    // copies side by side cover whatever wraps round the edge.
    const dx = -c0 / 360 * W;
    const put = (href, cls) => {
        [-1, 0, 1].forEach(k => {
            m.sat.append('image').attr('class', cls)
                .attr('href', href).attr('x', dx + k * W).attr('y', 0)
                .attr('width', W).attr('height', H)
                .attr('preserveAspectRatio', 'none');
        });
    };
    put(sunPathSat.day.src, 'sp-map-sat-day');
    m.sat.append('rect').attr('width', W).attr('height', H).attr('class', 'sp-map-sat-veil');
}

function drawSunPathMap(now) {
    if (!sunPathMap) return;
    const { proj, path: p, dyn, sat, land } = sunPathMap;
    dyn.selectAll('*').remove();
    // TRACK SUN centres the map on the sub-solar meridian, so the sunrise line stands still and
    // the earth slides underneath it. Off, the map is the map and the line sweeps across it.
    // Everything downstream measures longitude relative to `c0`, which is the centre either way.
    const c0 = sunPathState.trackSun ? (((now.lon - now.H) + 540) % 360) - 180 : 0;
    if ((sunPathMap.rot || 0) !== c0) {
        sunPathMap.rot = c0;
        proj.rotate([-c0, 0]);
        land.selectAll('path').attr('d', f => (f && p(f)) || '');
        sunPathMap.satDirty = true;
    }

    // The sub-solar point for this day and hour, then the night cap around its antipode.
    // Hour angle is the observer's longitude MINUS the sub-solar one (H = lon - subLon), so
    // this has to be lon - H. It was -H - lon, which mirrors the sun about the prime meridian:
    // correct only at lon 0 (the default, which is why it looked fine), and at 90 deg E it put
    // local solar noon on the far side of the planet from the observer.
    const subLon = now.lon - now.H;
    const sun = [((subLon + 540) % 360) - 180, now.dec];
    const dark = antipode(sun);
    // Longitudes are measured as an offset from the map's own centre, which is the only way the
    // bars below stay right when the projection is rotated to follow the sun. `lonToX` therefore
    // takes a DELTA rather than a longitude, and never wraps: a span ending exactly at the far
    // edge has to land there rather than back at the near one.
    const mapW = sunPathMap.W || 400, lonToX = dl => mapW / 2 + dl * (mapW / 360);
    sunPathDrawSatellite(c0);
    [102, 96, 90].forEach((r, i) => {
        const d = p(d3.geoCircle().center(dark).radius(r)());
        if (d) dyn.append('path').attr('class', 'sp-map-night n' + i).attr('d', d);
    });
    // City lights, if the optional Black Marble is present: clipped to the night cap, so it is
    // the dark half of the world that lights up and the day half is untouched.
    if (sunPathState.satellite && sunPathSat.night && sunPathSat.day) {
        const capD = p(d3.geoCircle().center(dark).radius(90)());
        if (capD) {
            const cid = 'sp-night-clip';
            let defs = sunPathMap.svg.select('defs');
            if (defs.empty()) defs = sunPathMap.svg.append('defs');
            defs.selectAll('#' + cid).remove();
            defs.append('clipPath').attr('id', cid).append('path').attr('d', capD);
            const W = sunPathMap.W, H = sunPathMap.H, dx = -c0 / 360 * W;
            const gN = dyn.append('g').attr('clip-path', `url(#${cid})`).attr('class', 'sp-map-sat-night');
            [-1, 0, 1].forEach(k => gN.append('image').attr('href', sunPathSat.night.src)
                .attr('x', dx + k * W).attr('y', 0).attr('width', W).attr('height', H)
                .attr('preserveAspectRatio', 'none'));
        }
    }

    const term = p(d3.geoCircle().center(dark).radius(90)());
    if (term) dyn.append('path').attr('class', 'sp-map-term').attr('d', term);

    // The six parallels, each split into its lit and dark spans and labelled with their lengths.
    // The split is the whole point: the day is the arc of longitudes within the half-day angle
    // of the sub-solar meridian, so these bars ARE the day-length curve, read straight off the
    // map — and they slide bodily westward with the sunlight while their proportions change only
    // with the date.
    sunPathParallels(now.lat).forEach(par => {
        // The observer's own parallel is not furniture — it is where they are — so it survives
        // the tropic-line switch, which is about the five fixed ones. (`you`, not `me`: the flag
        // sunPathParallels actually sets. Guessing the name switched off the one line that
        // should never go.)
        if (!sunPathState.tropics && !par.you) return;
        const y = proj([0, par.lat]);
        if (!y || !isFinite(y[1])) return;
        const yy = y[1];
        const hd = halfDayAngle(par.lat, now.dec);
        const dayH = sunPathDayHours(par.lat, now.dec);
        const g = dyn.append('g').attr('class', 'sp-par sp-par-' + par.cls);
        // Split at the antimeridian rather than letting a span wrap the whole way round. The
        // endpoints are normalised BEFORE they are mapped to x, and the mapping itself must not
        // wrap — a span ending at exactly +180° has to land at the right-hand edge, not back at
        // the left one, or every night bar measures the full width of the map.
        const norm = l => ((l - c0 + 540) % 360) - 180;
        const spansFor = (l0, l1) => {
            const a = norm(l0), b = norm(l1);
            return b <= a ? [[a, 180], [-180, b]] : [[a, b]];
        };
        const bar = (spans, lit, hours) => {
            let widest = null;
            spans.forEach(([s0, s1]) => {
                const x0 = lonToX(s0), x1 = lonToX(s1);
                if (Math.abs(x1 - x0) < 0.5) return;
                g.append('line').attr('class', 'sp-par-bar' + (lit ? ' lit' : ' dark'))
                    .attr('x1', x0).attr('x2', x1).attr('y1', yy).attr('y2', yy);
                [x0, x1].forEach(x => g.append('line').attr('class', 'sp-par-cap' + (lit ? ' lit' : ' dark'))
                    .attr('x1', x).attr('x2', x).attr('y1', yy - 3).attr('y2', yy + 3));
                if (!widest || Math.abs(x1 - x0) > Math.abs(widest[1] - widest[0])) widest = [x0, x1];
            });
            if (sunPathState.dayLengths && widest && Math.abs(widest[1] - widest[0]) > 26) {
                g.append('text').attr('class', 'sp-par-hrs' + (lit ? ' lit' : ' dark'))
                    .attr('x', (widest[0] + widest[1]) / 2).attr('y', yy - 3.5)
                    .attr('text-anchor', 'middle').text(`${hours.toFixed(1)} h`);
            }
        };
        if (hd.polar === 'day') bar([[-180, 180]], true, 24);
        else if (hd.polar === 'night') bar([[-180, 180]], false, 24);
        else {
            bar(spansFor(subLon - hd.deg, subLon + hd.deg), true, dayH);
            bar(spansFor(subLon + hd.deg, subLon - hd.deg), false, 24 - dayH);
        }
        g.append('text').attr('class', 'sp-par-name').attr('x', 3).attr('y', yy - 3.5).text(par.name);
    });

    // The moon: where it is overhead, and the line where it is rising or setting. Dotted, so it
    // never reads as the sunrise line — the same distinction Sun & Moon draws.
    if (sunPathState.showMoon) {
        const m = sunPathMoonNow(now);
        if (m && m.sub) {
            const ml = p(d3.geoCircle().center(antipode(m.sub)).radius(90)());
            if (ml) dyn.append('path').attr('class', 'sp-map-moonline').attr('d', ml);
            const mp = proj(m.sub);
            if (mp) {
                const g2 = dyn.append('g').attr('class', 'sp-map-moon')
                    .attr('transform', `translate(${mp[0].toFixed(1)},${mp[1].toFixed(1)})`);
                // The lit limb points at the sub-solar point, measured on this map.
                const sp2 = proj(sun);
                const bright = sp2 ? Math.atan2(sp2[1] - mp[1], sp2[0] - mp[0]) / DEG : 0;
                sunPathMoonGlyph(g2, 5, m.k, bright);
            }
        }
    }

    const sp = proj(sun);
    if (sp) dyn.append('circle').attr('class', 'sp-map-sun').attr('cx', sp[0]).attr('cy', sp[1]).attr('r', 5);
    const me = proj([now.lon, now.lat]);
    if (me) {
        // The same figure as the other two panes, shrunk to a glyph — and casting its shadow
        // directly away from the sub-solar point, which on this map is simply the direction from
        // the sun marker to the observer (taken with the wrap, so it stays right across ±180°).
        if (now.alt > 0) {
            // Same shadow the sky dome casts: a local bearing of az+180, and a length of
            // height/tan(altitude). Deriving the direction from the SCREEN vector between the
            // sun marker and the observer instead looked fine in the mid-latitudes and snapped
            // through 180° near the poles, where that vector swings round as the sub-solar point
            // wraps past the observer's longitude. Azimuth has no such discontinuity.
            const b = (now.az + 180) * DEG;
            const len = Math.max(5, Math.min(26, 7 / Math.max(0.12, Math.tan(now.alt * DEG))));
            dyn.append('line').attr('class', 'sp-map-me-shadow')
                .attr('x1', me[0]).attr('y1', me[1] + 3)
                .attr('x2', me[0] + Math.sin(b) * len).attr('y2', me[1] + 3 - Math.cos(b) * len);
        }
        // The same figure the other panes are showing. A stick figure five pixels high on a world
        // map was a smudge whatever it was meant to be, which is why the pin is the default here
        // even though a person is the default in the panes where a person is legible.
        const fg = dyn.append('g').attr('class', 'sp-map-me-fig')
            .attr('transform', `translate(${me[0].toFixed(1)},${me[1].toFixed(1)})`);
        const fig = (sunPathState.figure || 'pin');
        if (fig === 'pin') {
            fg.append('path').attr('class', 'sp-map-me-pin')
                .attr('d', 'M0,0 C-4.4,-5.2 -3.4,-10.4 0,-10.4 C3.4,-10.4 4.4,-5.2 0,0 Z');
            fg.append('circle').attr('class', 'sp-map-me-pinhole').attr('cy', -7).attr('r', 1.5);
        } else if (fig === 'beacon') {
            fg.append('line').attr('class', 'sp-map-me-body').attr('x1', 0).attr('y1', 0).attr('x2', 0).attr('y2', -9);
            fg.append('circle').attr('class', 'sp-map-me').attr('cy', -10.4).attr('r', 2.2);
        } else {
            fg.append('circle').attr('class', 'sp-map-me').attr('cx', 0).attr('cy', -5.4).attr('r', 1.9);
            fg.append('line').attr('class', 'sp-map-me-body').attr('x1', 0).attr('y1', -3.6).attr('x2', 0).attr('y2', 1.4);
            fg.append('line').attr('class', 'sp-map-me-body').attr('x1', -2).attr('y1', 3.4).attr('x2', 0).attr('y2', 1.4);
            fg.append('line').attr('class', 'sp-map-me-body').attr('x1', 2).attr('y1', 3.4).attr('x2', 0).attr('y2', 1.4);
        }
    }
}

// ---- one update, every pane ----
function updateSunPath() {
    if (!sunPathState) return;
    const now = sunPathNow();

    drawSunPathHorizon(now);
    drawSunPathMap(now);
    drawSunPathOrbitInset(now);
    if (sunPathState.three) {
        // The one place every pane is brought up to date with the shared location. The disc keys
        // itself on lat/lon, so this costs nothing until the observer actually moves.
        refreshSunPathDomeGround();
        // The dome's camera depends on the sun when it is tracking, so it is re-aimed here rather
        // than only when somebody drags it.
        const wasAz = sunPathState.sunAz;
        sunPathState.sunAz = now.az;
        if (sunPathState.trackSun && Math.abs((wasAz == null ? 1e9 : wasAz) - now.az) > 0.05)
            applySunPathDomeCamera();
        updateDomeScene(now);
        updateGlobeScene(now);
        sunPathAutoFrame();          // both panes zoom to whatever is actually in them
        renderSunPathThree();
    }

    const dayH = now.hd.polar === 'day' ? 24 : now.hd.polar === 'night' ? 0 : now.hd.deg / 15 * 2;
    const dateStr = new Date(Date.UTC(2001, 0, 1) + (Math.round(sunPathState.day) - 1) * 86400000)
        .toLocaleDateString(undefined, { month: 'long', day: 'numeric', timeZone: 'UTC' });
    const hh = Math.floor(sunPathState.hour), mm = Math.round((sunPathState.hour - hh) * 60);
    const clock = `${String(hh % 24).padStart(2, '0')}:${String(mm % 60).padStart(2, '0')}`;
    const set = (id, html) => { const el = document.getElementById(id); if (el) el.innerHTML = html; };
    set('sun-path-dome-note', ` · ${dayH.toFixed(1)} h of daylight`);
    set('sun-path-globe-note', ` · sun overhead at ${now.dec.toFixed(1)}°`);
    set('sun-path-horizon-note', ` · sun ${now.alt.toFixed(0)}° at ${Math.round(now.az)}°`);
    set('sun-path-map-note', ' · click to move');
    set('sun-path-readout',
        `<strong>${dateStr}, ${clock}</strong> local solar time<br>` +
        `<strong>${Math.abs(now.lat).toFixed(1)}°${now.lat >= 0 ? 'N' : 'S'} ` +
        `${Math.abs(now.lon).toFixed(1)}°${now.lon >= 0 ? 'E' : 'W'}</strong><br>` +
        `Daylight: <strong>${now.hd.polar ? (now.hd.polar === 'day' ? '24 h' : '0 h') : dayH.toFixed(1) + ' h'}</strong> · ` +
        `sun now <strong>${now.alt.toFixed(1)}°</strong><br>` +
        `<span class="sandbox-note">Track meets the horizon at ${riseAngle(now.lat).toFixed(0)}° — ` +
        `steep at the equator, shallow near the poles.</span>`);

    const sync = (id, val, label) => {
        const el = document.getElementById(id);
        if (el && Math.abs(+el.value - val) > 0.51) el.value = String(Math.round(val));
        const lab = document.getElementById(id + '-val');
        if (lab) lab.textContent = label;
    };
    const sp = sunPathState.speed == null ? 1 : sunPathState.speed;
    const spLab = document.getElementById('sun-path-speed-val');
    if (spLab) spLab.textContent = (sp < 1 ? sp.toFixed(2) : sp.toFixed(1)) + '×';

    // Light up whichever turning point we are sitting on, and whichever clock is running. The
    // year snaps exactly onto these days, so an exact-ish match is the right test.
    document.querySelectorAll('#sun-path-stops button').forEach(b => {
        b.classList.toggle('active', Math.abs(+b.dataset.stopDay - sunPathState.day) < 0.75);
    });
    const dayBtn = document.getElementById('sun-path-play-day');
    const yearBtn = document.getElementById('sun-path-play-year');
    if (dayBtn) dayBtn.classList.toggle('active', !!sunPathState.playing && sunPathState.mode === 'day');
    if (yearBtn) yearBtn.classList.toggle('active', !!sunPathState.playing && sunPathState.mode === 'year');
    sync('sun-path-lat', sunPathState.lat, `${Math.abs(sunPathState.lat).toFixed(0)}°${sunPathState.lat >= 0 ? 'N' : 'S'}`);
    sync('sun-path-day', sunPathState.day, dateStr);
    sync('sun-path-hour', sunPathState.hour, clock);
}

// ---- panel ----
function buildSunPathPanel() {
    let panel = document.getElementById('sun-path-panel');
    if (!panel) {
        panel = document.createElement('div');
        panel.id = 'sun-path-panel';
        panel.className = 'sandbox-panel';
        panel.innerHTML = `
            <div class="sandbox-title">Sun Path</div>
            <div class="sp-orbit-row">
                <svg class="sp-orbit-inset" id="sun-path-orbit-inset" viewBox="0 0 120 120"
                     preserveAspectRatio="xMidYMid meet"></svg>
                <div class="sandbox-readout" id="sun-path-readout"></div>
            </div>
            <div class="sandbox-edit">
                <label class="sandbox-slider"><span>Lat</span>
                    <input type="range" id="sun-path-lat" min="-89" max="89" step="1" value="51">
                    <span class="sandbox-note" id="sun-path-lat-val"></span></label>
                <label class="sandbox-slider"><span>Date</span>
                    <input type="range" id="sun-path-day" min="1" max="365" step="1" value="1">
                    <span class="sandbox-note" id="sun-path-day-val"></span></label>
                <label class="sandbox-slider"><span>Hour</span>
                    <input type="range" id="sun-path-hour" min="0" max="24" step="0.25" value="12">
                    <span class="sandbox-note" id="sun-path-hour-val"></span></label>
                <label class="sandbox-slider"><span>Speed</span>
                    <input type="range" id="sun-path-speed" min="-20" max="20" step="1" value="0">
                    <span class="sandbox-note" id="sun-path-speed-val"></span></label>
                <div class="sandbox-nudge" id="sun-path-stops"></div>
                <div class="sp-panes" id="sun-path-panes">
                    <span class="sp-group-lab">Views</span>
                    ${SUNPATH_PANES.map(v => `<label class="sandbox-check">` +
                        `<input type="checkbox" id="sp-pane-${v.key}" checked> ${v.label}</label>`).join('')}
                </div>
                <div class="sp-panes">
                    <span class="sp-group-lab">Show</span>
                    <label class="sandbox-check"><input type="checkbox" id="sp-track-sun" checked>
                        Track sun</label>
                    <label class="sandbox-check"><input type="checkbox" id="sp-show-moon">
                        Show moon</label>
                    <label class="sandbox-check"><input type="checkbox" id="sp-satellite">
                        Satellite</label>
                    <label class="sandbox-check"><input type="checkbox" id="sp-tropics" checked>
                        Tropic lines</label>
                    <label class="sandbox-check"><input type="checkbox" id="sp-daylen" checked>
                        Day lengths</label>
                    <label class="sandbox-check"><input type="checkbox" id="sp-zones">
                        Time zones</label>
                </div>
                <label class="sandbox-check"><span>Figure</span>
                    <select id="sun-path-figure">${SUNPATH_FIGURE_STYLES.map(f =>
                        `<option value="${f.key}">${f.label}</option>`).join('')}</select></label>
            </div>
            <div class="sandbox-actions">
                <button class="btn secondary" id="sun-path-here">My latitude</button>
                <button class="btn secondary" id="sun-path-play-day">▶ Day</button>
                <button class="btn" id="sun-path-play-year">▶ Year</button>
            </div>
            <div class="sandbox-status" id="sun-path-status" role="status"></div>`;
        (document.getElementById('globe-side-panel') || document.body).appendChild(panel);

        document.getElementById('sun-path-lat').addEventListener('input', function () {
            sunPathState.lat = +this.value; updateSunPath();
        });
        document.getElementById('sun-path-day').addEventListener('input', function () {
            sunPathState.day = +this.value; updateSunPath();
        });
        document.getElementById('sun-path-hour').addEventListener('input', function () {
            sunPathState.hour = +this.value; updateSunPath();
        });
        // Speed is a signed EXPONENT, so one slider spans a 16x slow-motion to 16x fast range
        // symmetrically and lands exactly on 1x in the middle. Negative runs the clock backwards,
        // which is the only way to watch the sun set rather than waiting most of a cycle for it.
        document.getElementById('sun-path-speed').addEventListener('input', function () {
            sunPathState.speed = sunPathSpeedFrom(+this.value);
            updateSunPath();
        });
        document.getElementById('sun-path-figure').addEventListener('change', function () {
            sunPathState.figure = this.value;
            // The dome's figure is fixed furniture, so it has to be swapped out by hand; the
            // space pane's is rebuilt every update anyway.
            rebuildSunPathDomeFigure();
            updateSunPath();
        });
        SUNPATH_PANES.forEach(v => {
            const box = document.getElementById('sp-pane-' + v.key);
            if (box) box.addEventListener('change', function () {
                sunPathState.panes[v.key] = this.checked;
                // Never all four off: an empty stage is not a view of anything, and the way back
                // from it is to tick a box you can no longer see the point of.
                if (!SUNPATH_PANES.some(o => sunPathState.panes[o.key] !== false)) {
                    sunPathState.panes[v.key] = true;
                    this.checked = true;
                }
                syncSunPathPanes();
            });
        });
        const flag = (id, key, after) => {
            const el = document.getElementById(id);
            if (el) el.addEventListener('change', function () {
                sunPathState[key] = this.checked;
                if (after) after();
                updateSunPath();
            });
        };
        flag('sp-track-sun', 'trackSun', () => {
            // Handing over where it is rather than snapping: turning tracking off leaves the
            // camera exactly where tracking had it, so the switch reads as "stop following"
            // rather than as a jump to somewhere else.
            if (!sunPathState.trackSun) {
                const n = sunPathNow();
                sunPathState.groundAz = n.az;
                sunPathState.groundEl = n.alt;
            }
            applySunPathDomeCamera();
        });
        flag('sp-show-moon', 'showMoon');
        flag('sp-satellite', 'satellite', () => {
            refreshSunPathEarthTexture(true);
            refreshSunPathDomeGround(true);
        });
        flag('sp-tropics', 'tropics');
        flag('sp-daylen', 'dayLengths');
        flag('sp-zones', 'zones');
        document.getElementById('sun-path-play-day').addEventListener('click', () => toggleSunPathPlay('day'));
        document.getElementById('sun-path-play-year').addEventListener('click', () => toggleSunPathPlay('year'));
        document.getElementById('sun-path-here').addEventListener('click', () => {
            const st = document.getElementById('sun-path-status');
            if (!navigator.geolocation) { st.textContent = 'No location support here.'; return; }
            st.textContent = 'Asking for your location…';
            navigator.geolocation.getCurrentPosition(
                p => { if (!sunPathState) return;
                       sunPathState.lat = p.coords.latitude;
                       sunPathState.lon = p.coords.longitude;
                       st.textContent = ''; updateSunPath(); },
                e => { st.textContent = 'Location unavailable (' + e.message + ').'; },
                { timeout: 10000, maximumAge: 600000 });
        });
        const stops = document.getElementById('sun-path-stops');
        SUNPATH_STOPS.forEach(s => {
            const b = document.createElement('button');
            b.className = 'btn secondary';
            b.textContent = s.short || s.label;
            b.dataset.stopDay = String(s.day);
            b.title = s.label;
            b.addEventListener('click', () => { sunPathState.day = s.day; updateSunPath(); });
            stops.appendChild(b);
        });
    }
    panel.style.display = '';
}

// ONE clock for all four panes: 'day' spins the hour, 'year' walks the date. Both write the
// same state object and call the same update, so nothing can drift out of step.
function toggleSunPathPlay(mode) {
    if (!sunPathState) return;
    const already = sunPathState.playing && sunPathState.mode === mode;
    if (sunPathState.raf) { cancelAnimationFrame(sunPathState.raf); sunPathState.raf = null; }
    sunPathState.playing = !already;
    sunPathState.mode = mode;
    const dayBtn = document.getElementById('sun-path-play-day');
    const yearBtn = document.getElementById('sun-path-play-year');
    // Set the highlight here rather than waiting for updateSunPath: pressing stop ends the RAF
    // loop, so there would be no next frame to clear it on.
    if (dayBtn) {
        dayBtn.textContent = (sunPathState.playing && mode === 'day') ? '■ Day' : '▶ Day';
        dayBtn.classList.toggle('active', sunPathState.playing && mode === 'day');
    }
    if (yearBtn) {
        yearBtn.textContent = (sunPathState.playing && mode === 'year') ? '■ Year' : '▶ Year';
        yearBtn.classList.toggle('active', sunPathState.playing && mode === 'year');
    }
    if (sunPathState.playing) {
        // Start armed if the sun is currently up, so the first evening's sunset counts.
        const n = sunPathNow();
        sunPathState.armed = n.alt >= 0;
        sunPathState.sawSunset = false;
        sunPathState.last = performance.now();
        sunPathState.raf = requestAnimationFrame(stepSunPath);
    }
}

// Slider position (-20..20) to a rate multiplier: 2^(v/5). The midpoint is exactly 1x, the ends
// are 1/16x and 16x. An exponent rather than a linear rate because the useful range spans two
// orders of magnitude — creeping through a sunset, and skimming a whole year — and a linear
// slider would spend most of its travel in the fast half.
function sunPathSpeedFrom(v) {
    return Math.pow(2, (+v || 0) / 5);
}

function stepSunPath(now) {
    if (!sunPathState || !sunPathState.playing) return;
    const dt = Math.min(0.1, (now - sunPathState.last) / 1000);
    sunPathState.last = now;
    const k = sunPathState.speed == null ? 1 : sunPathState.speed;
    if (sunPathState.mode === 'year') {
        // A year as a series of DAYS, not a smooth slide of the date: run the day through at the
        // ordinary rate and step a week forward each time the sun sets. Sliding the date
        // continuously moved the track and the sun at once, so nothing could be read against
        // anything — this way each day is a still frame you can actually watch, and the change
        // between them lands in one visible jump.
        const before = sunAltitude(sunPathState.lat, declinationForDay(sunPathState.day),
                                   (sunPathState.hour - 12) * 15);
        sunPathState.hour += dt * 4 * k;
        let wrapped = false;
        if (sunPathState.hour >= 24) { sunPathState.hour -= 24; wrapped = true; }
        const after = sunAltitude(sunPathState.lat, declinationForDay(sunPathState.day),
                                  (sunPathState.hour - 12) * 15);
        // Sunset = the altitude crossing zero downward. Inside the polar day or night there is
        // no crossing at all, so midnight is the FALLBACK tick — otherwise the year would stall
        // completely above the Arctic Circle. It has to be a fallback and not simply an extra
        // trigger: an ordinary day has both a sunset and a midnight, and firing on each would
        // walk the calendar two weeks per day.
        // ARMED is what stops a jump from re-triggering itself. Moving the date a week at the
        // instant of sunset also moves the declination, and while the days are lengthening the
        // sun on the new date is still up at that clock time — so it sets again a few minutes
        // later and fires again. Measured before this latch: twelve jumps in five days at 51°N,
        // while the southern hemisphere in a shortening season looked perfectly fine. A sunset
        // only counts while armed; only a sunrise (or midnight) re-arms it.
        if (before < 0 && after >= 0) sunPathState.armed = true;
        const sunset = !wrapped && sunPathState.armed && before >= 0 && after < 0;
        if (sunset) { sunPathState.armed = false; sunPathState.sawSunset = true; }
        const advance = sunset || (wrapped && !sunPathState.sawSunset);
        if (wrapped) { sunPathState.sawSunset = false; sunPathState.armed = true; }
        if (advance) {
            // Snap onto an equinox or solstice rather than stepping over it. A blind +7 walks
            // straight past the four dates the whole mode exists to show — over a year the
            // 52-week grid lands on one of them only by luck.
            const from = sunPathState.day;
            let to = from + 7;
            const hit = SUNPATH_STOPS.map(s => s.day)
                .filter(d => d > from + 0.5 && d <= to + 0.5)
                .sort((a, b) => a - b)[0];
            sunPathState.day = hit != null ? hit : to;
            if (sunPathState.day > 365) sunPathState.day -= 365;
        }
    } else {
        sunPathState.hour = (sunPathState.hour + dt * 4 * k) % 24;   // ~6 s per day at 1x
    }
    updateSunPath();
    sunPathState.raf = requestAnimationFrame(stepSunPath);
}

function removeSunPathMode() {
    if (!sunPathState) return;
    if (sunPathState.raf) cancelAnimationFrame(sunPathState.raf);
    if (sunPathState.ro) { try { sunPathState.ro.disconnect(); } catch (_) { /* best effort */ } }
    const th = sunPathState.three;
    if (th) {
        [th.dome, th.globe].forEach(v => {
            try { v.renderer.dispose(); } catch (_) { /* best effort */ }
            if (v.canvas && v.canvas.parentNode) v.canvas.parentNode.removeChild(v.canvas);
        });
    }
    const stage = document.getElementById('sun-path-stage');
    if (stage) stage.remove();
    const panel = document.getElementById('sun-path-panel');
    if (panel) panel.remove();
    const svgEl = document.getElementById('globe');
    if (svgEl) svgEl.style.display = '';
    document.body.classList.remove('sun-path-active');
    sunPathMap = null;
    sunPathState = null;
}

// ==================== COASTLINE MODEL ====================
// Every orbital spot sits somewhere on the world's coastline. The old picker threw darts at
// the globe and kept the ones that happened to have a shore nearby — up to 300 tries, six
// point-in-polygon tests each — which made the whole coast reachable only in the sense that
// a dartboard is (and made the sandbox's 400-dot cloud a multi-second stall).
//
// Instead the coast is modelled ONCE as a discontinuous polyline: topojson.mesh with an
// `a === b` filter keeps only the arcs that no two countries share, which is exactly the
// world's coastline and nothing else. A spot is then a distance along that line — which is
// what the seed hash stores — and the sub-point, facing and roll fall out of it.

const COAST_TOPO_URL = 'https://cdn.jsdelivr.net/npm/world-atlas@2/countries-110m.json';
const COAST_MIN_RING_KM = 300;                  // drop specks — an island you couldn't place from orbit
// The world-atlas closes Antarctica's polygon along the bottom of the map rather than at a
// real shore, so that edge is an artefact, not coastline. Everything above it stays: Greenland
// and the Antarctic coast proper are both fair game.
const COAST_ANTARCTIC_EDGE = -84;
const LAND_RASTER_W = 1024;                     // 0.35° cells (~39 km): the resolution this whole model works at
const ORBIT_VIEW_ASPECT = 16 / 9;               // nominal frame shape for footprint/land-fraction maths

const COAST_LAKES_URL = 'data/lakes.geo.json';   // Natural Earth 110m major lakes — shoreline too
let coastLakes = null;         // lake features once fetched (null until then)

let coastRaw = null;           // [{line, weights, effWeights, km}] every kept ring with its VW hierarchy
let coastWeightsSorted = null; // every finite EFFECTIVE weight, sorted — maps strength to a threshold
let coastSegs = null;          // [{a, b, km, cum}] flattened over every kept ring, at the current strength
let coastRings = null;         // the KEPT segments stitched back into runs — drawn as the reachable set,
                               // so what the sandbox shows is exactly what the picker can choose
let coastTotalKm = 0;
let landRaster = null;         // coarse equirectangular land mask, so "is this land?" is an array lookup

// ---- The four tunables ----
// Each is a 0..35 code (one base36 character) because all four decide WHERE SPOTS CAN LAND,
// not merely what is drawn, so all four have to travel in the seed hash for a shared quiz to
// replay identically. Codes rather than raw values keeps the header fixed-width.
const TUNE_MAX = 35;
const COAST_SIMPLIFY_MAX = TUNE_MAX;
let coastSimplifyStrength = 28;  // fraction of shoreline points cut: code/35 → 80%
let coastSizeBiasCode = 5;       // how much longer rings simplify before shorter ones: ×0.5
let spotStripCode = 19;          // half-width of the band spots may sit in: (code+1) × 25 → 500 km
let spotMinLandCode = 20;        // the X in "between X and 100−X % land in frame" → 20–80%

function coastCutFrac() { return Math.min(0.98, coastSimplifyStrength / TUNE_MAX); } // 0..98%
function coastSizeBias() { return coastSizeBiasCode / 10; }             // exponent, 0..3.5
function spotStripKm() { return (spotStripCode + 1) * 25; }             // 25..900 km
function spotMinLand() { return spotMinLandCode / 100; }                // 0..0.35

// Tunables from a seed link that arrived before the coastline existed; applied the moment it
// does. routeFromUrl runs long before the 110m topology lands.
let pendingCoastTune = null;

function coastTuneCodes() {
    return [coastSimplifyStrength, coastSizeBiasCode, spotStripCode, spotMinLandCode];
}

// Apply a decoded header. Returns true if the coastline itself has to be re-cut.
function applyCoastTuneCodes(codes) {
    if (!codes) return false;
    const clamp = v => Math.max(0, Math.min(TUNE_MAX, Math.round(v || 0)));
    const [s, b, st, ml] = codes.map(clamp);
    const reshape = (s !== coastSimplifyStrength || b !== coastSizeBiasCode);
    coastSimplifyStrength = s; coastSizeBiasCode = b;
    spotStripCode = st; spotMinLandCode = ml;
    return reshape;
}

// Rasterise the world's land once. Choosing a facing tests thousands of points; walking every
// country's rings for each of them is what made the old sampler slow.
function ensureLandRaster() {
    if (landRaster) return landRaster;
    const w = LAND_RASTER_W, h = w / 2;
    const bits = new Uint8Array(w * h);
    const topo = worldTopoCache[COAST_TOPO_URL];
    const feats = topo ? topojson.feature(topo, topo.objects.countries).features
                       : (gameState.countries || []);
    try {
        const cv = document.createElement('canvas');
        cv.width = w; cv.height = h;
        const ctx = cv.getContext('2d', { willReadFrequently: true });
        const proj = d3.geoEquirectangular().scale(w / (2 * Math.PI)).translate([w / 2, h / 2]).precision(0);
        const draw = d3.geoPath(proj, ctx);
        ctx.beginPath();
        draw({ type: 'FeatureCollection', features: feats });
        ctx.fill();
        // Punch the big lakes back out. The country polygons cover them, so without this a
        // lake shore's water side reads as land and both the offshore probe and the
        // land-fraction sweep get it backwards on every lake in the world.
        if (coastLakes && coastLakes.length) {
            ctx.globalCompositeOperation = 'destination-out';
            ctx.beginPath();
            draw({ type: 'FeatureCollection', features: coastLakes });
            ctx.fill();
            ctx.globalCompositeOperation = 'source-over';
        }
        const data = ctx.getImageData(0, 0, w, h).data;
        for (let i = 0; i < w * h; i++) bits[i] = data[i * 4 + 3] > 40 ? 1 : 0;
    } catch (_) { /* no canvas: everything reads as water and the facing sweep just gives up */ }
    landRaster = { w, h, bits };
    return landRaster;
}

function isLandFast(lon, lat) {
    const r = ensureLandRaster();
    const y = Math.floor((90 - lat) / 180 * r.h);
    if (y < 0 || y >= r.h) return false;
    let x = Math.floor((lon + 180) / 360 * r.w) % r.w;
    if (x < 0) x += r.w;
    return !!r.bits[y * r.w + x];
}

function kmBetween(a, b) { return d3.geoDistance(a, b) * EARTH_R_KM; }

// Great-circle destination from p on `bearing` (radians from north) after `km`.
function destPoint(p, bearing, km) {
    const d = km / EARTH_R_KM;
    const lat1 = p[1] * Math.PI / 180, lon1 = p[0] * Math.PI / 180;
    const sinLat2 = Math.sin(lat1) * Math.cos(d) + Math.cos(lat1) * Math.sin(d) * Math.cos(bearing);
    const lat2 = Math.asin(Math.max(-1, Math.min(1, sinLat2)));
    const lon2 = lon1 + Math.atan2(Math.sin(bearing) * Math.sin(d) * Math.cos(lat1),
                                   Math.cos(d) - Math.sin(lat1) * sinLat2);
    return [((lon2 * 180 / Math.PI + 540) % 360) - 180, lat2 * 180 / Math.PI];
}

// Initial great-circle bearing (radians from north) from a to b.
function bearingBetween(a, b) {
    const f1 = a[1] * Math.PI / 180, f2 = b[1] * Math.PI / 180, dl = (b[0] - a[0]) * Math.PI / 180;
    return Math.atan2(Math.sin(dl) * Math.cos(f2),
                      Math.cos(f1) * Math.sin(f2) - Math.sin(f1) * Math.cos(f2) * Math.cos(dl));
}

// ---- Visvalingam–Whyatt, with self-intersections avoided ----
// Classic VW: repeatedly drop the point whose triangle with its two neighbours is smallest,
// and record that area as the point's weight, so a single pass yields a whole hierarchy and
// the strength slider is then just a threshold. Two departures from the textbook version:
//   * weights are forced monotonically increasing, so every threshold gives a NESTED subset
//     (without it, a point can carry a smaller weight than one already removed and the line
//     flickers as you drag the slider);
//   * a removal that would make the line cross itself is refused outright — the point is
//     blocked and keeps its infinite weight — which is what stops a simplified fjord or
//     peninsula from folding through its own coast (cf. jasondavies.com/simplify).
// The crossing test only looks at nearby segments: a self-intersection introduced by deleting
// one point is always local, and an all-pairs test would be quadratic on top of quadratic.
const VW_CROSS_WINDOW = 40;   // alive neighbours each way to test the new segment against

function segCross(p1, p2, p3, p4) {
    const d = (p2[0] - p1[0]) * (p4[1] - p3[1]) - (p2[1] - p1[1]) * (p4[0] - p3[0]);
    if (!d) return false;
    const t = ((p3[0] - p1[0]) * (p4[1] - p3[1]) - (p3[1] - p1[1]) * (p4[0] - p3[0])) / d;
    const u = ((p3[0] - p1[0]) * (p2[1] - p1[1]) - (p3[1] - p1[1]) * (p2[0] - p1[0])) / d;
    return t > 0 && t < 1 && u > 0 && u < 1;
}

// Triangle area in km², with longitudes scaled by cos(lat) so a degree means the same thing
// at every latitude — otherwise the poles would look absurdly "important".
function triAreaKm2(a, b, c) {
    const k = 111.32, cosLat = Math.cos((a[1] + b[1] + c[1]) / 3 * Math.PI / 180);
    const ax = a[0] * cosLat * k, ay = a[1] * k;
    const bx = b[0] * cosLat * k, by = b[1] * k;
    const cx = c[0] * cosLat * k, cy = c[1] * k;
    return Math.abs((bx - ax) * (cy - ay) - (cx - ax) * (by - ay)) / 2;
}

// Lazily-deleted binary min-heap of [area, index]. A linear scan for the smallest triangle
// makes the whole pass quadratic — measured at 3.5 s over the world's coastline, which is
// exactly the kind of entry stall this rewrite exists to remove.
function vwHeap() {
    const a = [];
    const less = (i, j) => a[i][0] < a[j][0];
    const swap = (i, j) => { const t = a[i]; a[i] = a[j]; a[j] = t; };
    return {
        size: () => a.length,
        push(area, i) {
            a.push([area, i]);
            let c = a.length - 1;
            while (c > 0) { const p = (c - 1) >> 1; if (!less(c, p)) break; swap(c, p); c = p; }
        },
        pop() {
            if (!a.length) return null;
            const top = a[0], last = a.pop();
            if (a.length) {
                a[0] = last;
                let p = 0;
                for (;;) {
                    const l = p * 2 + 1, r = l + 1;
                    let m = p;
                    if (l < a.length && less(l, m)) m = l;
                    if (r < a.length && less(r, m)) m = r;
                    if (m === p) break;
                    swap(p, m); p = m;
                }
            }
            return top;
        }
    };
}

function vwWeights(line) {
    const n = line.length;
    const w = new Float64Array(n).fill(Infinity);   // endpoints are never dropped
    if (n < 3) return w;
    const prev = new Int32Array(n), next = new Int32Array(n);
    const alive = new Uint8Array(n).fill(1);
    const area = new Float64Array(n).fill(Infinity);
    for (let i = 0; i < n; i++) { prev[i] = i - 1; next[i] = i + 1; }
    next[n - 1] = -1;
    const heap = vwHeap();
    for (let i = 1; i < n - 1; i++) {
        area[i] = triAreaKm2(line[prev[i]], line[i], line[next[i]]);
        heap.push(area[i], i);
    }

    // Would joining prev(i)→next(i) cut through the line nearby?
    const crosses = (i) => {
        const a = line[prev[i]], b = line[next[i]];
        let node = prev[i];
        for (let s = 0; s < VW_CROSS_WINDOW && prev[node] >= 0; s++) node = prev[node];
        for (let s = 0, cur = node; cur >= 0 && next[cur] >= 0 && s < VW_CROSS_WINDOW * 2; s++, cur = next[cur]) {
            if (cur === prev[i] || cur === i || next[cur] === i) continue;   // shares an endpoint
            if (segCross(a, b, line[cur], line[next[cur]])) return true;
        }
        return false;
    };

    let last = 0;
    for (;;) {
        const top = heap.pop();
        if (!top) break;
        const [a0, best] = top;
        if (!alive[best] || a0 !== area[best]) continue;   // stale entry, superseded
        // Refused: leave it in the line with its infinite weight. It comes back up for
        // consideration if a neighbour is later removed (that re-pushes it).
        if (crosses(best)) continue;
        last = Math.max(last, a0);
        w[best] = last;
        alive[best] = 0;
        const p = prev[best], q = next[best];
        next[p] = q; prev[q] = p;
        [p, q].forEach(i => {
            if (i <= 0 || i >= n - 1 || !alive[i]) return;
            area[i] = triAreaKm2(line[prev[i]], line[i], line[next[i]]);
            heap.push(area[i], i);
        });
    }
    return w;
}

// Every shoreline ring worth keeping, each with its VW weights. Computed once; the sliders
// only re-weight and re-filter it.
function ensureCoastRaw() {
    if (coastRaw) return coastRaw;
    const topo = worldTopoCache[COAST_TOPO_URL];
    if (!topo || !topojson.mesh || !topo.objects || !topo.objects.countries) return null;
    // a === b keeps arcs belonging to a single polygon: coastline, not shared land borders.
    const mesh = topojson.mesh(topo, topo.objects.countries, (a, b) => a === b);
    const out = [];
    const addLine = line => {
        if (!line || line.length < 2) return;
        let km = 0;
        for (let i = 1; i < line.length; i++) km += kmBetween(line[i - 1], line[i]);
        if (km < COAST_MIN_RING_KM) return;
        out.push({ line, km, weights: vwWeights(line) });
    };
    (mesh.coordinates || []).forEach(addLine);
    // Lake shores are coastline too — the Great Lakes, Victoria, Baikal and the Caspian are
    // as recognisable from orbit as any sea coast. Their rings come from the polygons rather
    // than a mesh, since a lake borders nothing.
    (coastLakes || []).forEach(f => {
        const g = f && f.geometry;
        if (!g) return;
        if (g.type === 'Polygon') g.coordinates.forEach(addLine);
        else if (g.type === 'MultiPolygon') g.coordinates.forEach(poly => poly.forEach(addLine));
    });
    if (!out.length) return null;
    coastRaw = out;
    applyCoastBias();
    // A seed link's tunables may have been waiting for exactly this moment.
    if (pendingCoastTune) { applyCoastTuneCodes(pendingCoastTune); pendingCoastTune = null; applyCoastBias(); }
    return coastRaw;
}

// Re-weight every point for the current size bias, then re-sort the global list the strength
// threshold indexes into. Bias > 0 makes a point on a LONG ring look less important than the
// same triangle on a short one, so continents lose their wiggles before small islands lose
// their shape — at bias 0 it is plain Visvalingam–Whyatt, one global ranking by area.
function applyCoastBias() {
    if (!coastRaw) return;
    const bias = coastSizeBias();
    const lens = coastRaw.map(r => r.km).sort((a, b) => a - b);
    const refKm = lens[Math.floor(lens.length / 2)] || 1;   // median ring, so bias re-ranks rather than rescales
    const all = [];
    coastRaw.forEach(r => {
        const f = bias ? Math.pow(refKm / r.km, bias) : 1;
        r.effWeights = r.weights.map(v => (isFinite(v) ? v * f : v));
        r.effWeights.forEach(v => { if (isFinite(v)) all.push(v); });
    });
    all.sort((a, b) => a - b);
    coastWeightsSorted = all;
}

// Threshold for the current strength. 0 keeps every point; 35 drops 98% of them.
function coastSimplifyThreshold() {
    if (!coastSimplifyStrength || !coastWeightsSorted || !coastWeightsSorted.length) return 0;
    return coastWeightsSorted[Math.floor(coastCutFrac() * (coastWeightsSorted.length - 1))];
}

// Build the coastline polyline + its cumulative-length index at the current strength. Null
// until the 110m topology is in hand (the sandbox and the orbital view both load that file).
function ensureCoastModel() {
    if (coastSegs) return coastSegs;
    const raw = ensureCoastRaw();
    if (!raw) return null;
    const thr = coastSimplifyThreshold();
    const rings = [], segs = [];
    let cum = 0;
    raw.forEach(({ line, effWeights }) => {
        const kept = line.filter((p, i) => effWeights[i] >= thr);
        if (kept.length < 2) return;
        let run = null;   // the current unbroken stretch of kept segments, for drawing
        for (let i = 1; i < kept.length; i++) {
            const a = kept[i - 1], b = kept[i];
            const km = kmBetween(a, b);
            // Skip the antimeridian seam, Antarctica's artificial bottom edge, and repeats.
            if (Math.abs(a[0] - b[0]) > 180 || !(km > 0) ||
                (a[1] <= COAST_ANTARCTIC_EDGE && b[1] <= COAST_ANTARCTIC_EDGE)) { run = null; continue; }
            segs.push({ a, b, km, cum });
            cum += km;
            if (run) run.push(b);
            else { run = [a, b]; rings.push(run); }
        }
    });
    if (!segs.length) return null;
    coastRings = rings; coastSegs = segs; coastTotalKm = cum;
    return coastSegs;
}

// Re-cut the coastline after a strength or bias change. Spot positions are fractions of the
// total length, so they follow the line they were placed on.
function recutCoastline() {
    coastSegs = null; coastRings = null; coastTotalKm = 0;
    ensureCoastModel();
}

function setCoastSimplify(strength) {
    const s = Math.max(0, Math.min(COAST_SIMPLIFY_MAX, Math.round(strength)));
    if (s === coastSimplifyStrength && coastSegs) return;
    coastSimplifyStrength = s;
    recutCoastline();
}

function setCoastSizeBias(code) {
    const c = Math.max(0, Math.min(TUNE_MAX, Math.round(code)));
    if (c === coastSizeBiasCode && coastSegs) return;
    coastSizeBiasCode = c;
    applyCoastBias();
    recutCoastline();
}

// Run cb once the coast model can be built, fetching whatever is missing. Lakes are part of
// the shoreline, so they have to be in hand BEFORE the rings are cut and the land raster is
// punched — hence one combined wait rather than two independent ones.
function whenCoastReady(cb) {
    if (coastLakes && ensureCoastModel()) { cb(); return; }
    Promise.all([
        fetchWorldTopo(COAST_TOPO_URL),
        coastLakes ? Promise.resolve(coastLakes)
                   : d3.json(COAST_LAKES_URL).then(d => (d && d.features) || [], () => [])
    ]).then(([, lakes]) => {
        if (!coastLakes) {
            // Anything built before the lakes landed was built from the wrong shoreline —
            // a different ring set means a different total length, and every spot is a
            // fraction of that length, so a seed would resolve somewhere else entirely.
            coastLakes = lakes || [];
            landRaster = null; coastRaw = null; coastWeightsSorted = null;
            coastSegs = null; coastRings = null; coastTotalKm = 0;
        }
        if (ensureCoastModel()) cb();
    }).catch(err => console.warn('coastline model unavailable:', err));
}

// Nearest point on the whole shoreline to [lon, lat]: which position along it, and how far
// off (km, unsigned). Brute force over the segment list — a few thousand at most, and only
// while a pin is actually being dragged. Distances are planar in degrees scaled by cos(lat),
// which is accurate enough at the scale a strip is measured in.
function nearestCoast(pt) {
    const segs = ensureCoastModel();
    if (!segs) return null;
    const cosLat = Math.max(0.02, Math.cos(pt[1] * Math.PI / 180));
    const dlon = v => ((v + 540) % 360) - 180;
    let best = null;
    for (let i = 0; i < segs.length; i++) {
        const s = segs[i];
        const ax = dlon(s.a[0] - pt[0]) * cosLat, ay = s.a[1] - pt[1];
        const bx = dlon(s.b[0] - pt[0]) * cosLat, by = s.b[1] - pt[1];
        const vx = bx - ax, vy = by - ay;
        const len2 = vx * vx + vy * vy;
        let t = len2 > 0 ? -(ax * vx + ay * vy) / len2 : 0;
        t = Math.max(0, Math.min(1, t));
        const px = ax + vx * t, py = ay + vy * t;
        const d2 = px * px + py * py;
        if (!best || d2 < best.d2) best = { d2, t, seg: s };
    }
    if (!best) return null;
    const km = Math.sqrt(best.d2) * 111.32;
    return {
        pos: Math.round((best.seg.cum + best.t * best.seg.km) / coastTotalKm * SPOT_POS_MAX) % SPOT_POS_MAX,
        km
    };
}

// Point + local tangent bearing at `km` along the whole coastline.
function coastPointAt(km) {
    const segs = ensureCoastModel();
    if (!segs) return null;
    const t = ((km % coastTotalKm) + coastTotalKm) % coastTotalKm;
    let lo = 0, hi = segs.length - 1;
    while (lo < hi) { const mid = (lo + hi + 1) >> 1; if (segs[mid].cum <= t) lo = mid; else hi = mid - 1; }
    const s = segs[lo];
    const f = Math.max(0, Math.min(1, (t - s.cum) / s.km));
    return {
        pt: [s.a[0] + (s.b[0] - s.a[0]) * f, s.a[1] + (s.b[1] - s.a[1]) * f],
        bearing: bearingBetween(s.a, s.b)
    };
}

// ---- What the orbital camera can actually see ----
// The same basis as applyOrbitalCamera, in plain arrays so the maths works before (or
// without) three.js — the sandbox needs footprints whether or not WebGL ever comes up.
function v3cross(a, b) { return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]; }
function v3dot(a, b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; }
function v3scale(a, k) { return [a[0]*k, a[1]*k, a[2]*k]; }
function v3add(a, b) { return [a[0]+b[0], a[1]+b[1], a[2]+b[2]]; }
function v3norm(a) { const l = Math.hypot(a[0], a[1], a[2]) || 1; return v3scale(a, 1 / l); }
// Rodrigues: rotate v about unit axis k by ang.
function v3rot(v, k, ang) {
    const c = Math.cos(ang), s = Math.sin(ang);
    return v3add(v3add(v3scale(v, c), v3scale(v3cross(k, v), s)), v3scale(k, v3dot(k, v) * (1 - c)));
}

// Unit vector for a lat/lon in the same frame as surfaceNormal (three's sphere UV convention).
function unitFromLatLon(lat, lon) {
    const phi = (lon + 180) * Math.PI / 180, th = (90 - lat) * Math.PI / 180;
    return [-Math.cos(phi) * Math.sin(th), Math.cos(th), Math.sin(phi) * Math.sin(th)];
}
function latLonFromUnit(v) {
    const u = v3norm(v);
    const lat = 90 - Math.acos(Math.max(-1, Math.min(1, u[1]))) * 180 / Math.PI;
    let lon = Math.atan2(u[2], -u[0]) * 180 / Math.PI - 180;
    lon = ((lon + 540) % 360) - 180;
    return [lon, lat];
}

// Camera position + axes for a spot (mirrors applyOrbitalCamera exactly).
function orbitalFrame(spot) {
    const n = unitFromLatLon(spot.lat, spot.lon);
    const east = v3norm(v3cross([0, 1, 0], n));
    const north = v3norm(v3cross(n, east));
    const tau = (spot.tilt != null ? spot.tilt : defaultOrbitTilt()) * Math.PI / 180;
    const psi = spot.heading || 0;
    const horiz = v3add(v3scale(north, Math.cos(psi)), v3scale(east, Math.sin(psi)));
    const fwd = v3norm(v3add(v3scale(n, -Math.cos(tau)), v3scale(horiz, Math.sin(tau))));
    let up = spot.roll ? v3rot(n, fwd, spot.roll * Math.PI / 180) : n;
    const right = v3norm(v3cross(fwd, up));
    return { pos: v3scale(n, orbitDistance()), fwd, right, up: v3norm(v3cross(right, fwd)) };
}

// Where the ray through image point (u,v) in [-1,1]² lands. Rays that clear the limb are
// clamped to their closest approach — a point ON the horizon circle — which is what makes a
// footprint's far edge follow the horizon instead of running off to infinity.
function orbitalGroundPoint(frame, u, v, fovDeg) {
    const ty = Math.tan(fovDeg * Math.PI / 360), tx = ty * ORBIT_VIEW_ASPECT;
    const dir = v3norm(v3add(frame.fwd,
        v3add(v3scale(frame.right, u * tx), v3scale(frame.up, v * ty))));
    const b = v3dot(frame.pos, dir);
    const disc = b * b - (v3dot(frame.pos, frame.pos) - 1);
    const sky = disc < 0;
    const p = sky ? v3norm(v3add(frame.pos, v3scale(dir, -b)))
                  : v3add(frame.pos, v3scale(dir, -b - Math.sqrt(disc)));
    const ll = latLonFromUnit(p);
    return { lon: ll[0], lat: ll[1], sky };
}

// Fraction of the visible GROUND (sky above the limb excluded) that is land.
function viewLandFraction(spot) {
    const frame = orbitalFrame(spot);
    const fov = spot.fov || SPACESHIP_FOV;
    let land = 0, ground = 0;
    for (let iv = 0; iv <= 6; iv++) {
        for (let iu = 0; iu <= 8; iu++) {
            const g = orbitalGroundPoint(frame, -1 + iu / 4, -1 + iv / 3, fov);
            if (g.sky) continue;
            ground++;
            if (isLandFast(g.lon, g.lat)) land++;
        }
    }
    return ground ? land / ground : 0;
}

// The ground footprint as a ring of [lon,lat] — the wedge the sandbox draws over the map.
// Walks the frame's edge: near edge, up the right, back along the horizon, down the left.
function viewFootprint(spot, steps = 14) {
    const frame = orbitalFrame(spot);
    const fov = spot.fov || SPACESHIP_FOV;
    const ring = [];
    const at = (u, v) => { const g = orbitalGroundPoint(frame, u, v, fov); ring.push([g.lon, g.lat]); };
    for (let i = 0; i <= steps; i++) at(-1 + 2 * i / steps, -1);
    for (let i = 1; i <= steps; i++) at(1, -1 + 2 * i / steps);
    for (let i = 1; i <= steps; i++) at(1 - 2 * i / steps, 1);
    for (let i = 1; i < steps; i++) at(-1, 1 - 2 * i / steps);
    return ring;
}

// ---- From hash to spot ----
// Deterministic PRNG, so a given (position, variation) pair always yields the same view.
function mulberry32(seed) {
    let a = seed >>> 0;
    return function () {
        a = (a + 0x6D2B79F5) >>> 0;
        let t = Math.imul(a ^ (a >>> 15), 1 | a);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

// The reachable set is a STRIP, not the line itself: a spot may sit anywhere within
// spotStripKm of a shore, on either side of it. Signed offsets, with the positive direction
// being the water side, so half the strip is out to sea and half is inland.
//
// The 2-char `var` code therefore splits in two: the low base-36 digit is WHERE IN THE STRIP
// (36 steps across ±strip — at 500 km that is 29 km a step, well under half a pixel at the
// sandbox's scale), and the high digit seeds everything still random (the roll, and the
// tie-break when both sides of a shore read the same). Splitting it this way is what lets a
// pin be dragged: a drop point resolves to a position along the shore plus a step across the
// strip, and both are expressible in the hash.
const SPOT_OFF_STEPS = 36;
function spotVarParts(v) {
    const n = (((v | 0) % SPOT_VAR_MAX) + SPOT_VAR_MAX) % SPOT_VAR_MAX;
    return { off: n % SPOT_OFF_STEPS, seed: Math.floor(n / SPOT_OFF_STEPS) };
}
function spotVarFrom(off, seed) {
    const o = Math.max(0, Math.min(SPOT_OFF_STEPS - 1, Math.round(off)));
    return (Math.abs(seed | 0) % SPOT_OFF_STEPS) * SPOT_OFF_STEPS + o;
}
// Signed km across the strip ⇄ its step index.
function spotOffsetKm(off) { return (off / (SPOT_OFF_STEPS - 1) * 2 - 1) * spotStripKm(); }
function spotOffsetStep(km) {
    return Math.round((Math.max(-1, Math.min(1, km / spotStripKm())) + 1) / 2 * (SPOT_OFF_STEPS - 1));
}
// Tried in order, degrees off the shore-facing bearing. Nearby first, so the view keeps
// looking at the coast it was seeded on unless that frame is too lopsided to be guessable.
const SPOT_HEADING_SWEEP = [0, 20, -20, 40, -40, 60, -60, 90, -90, 120, -120, 150, -150, 180];

// Turn a {pos, var} pair into a full spot. Everything past the coast position is derived, so
// the hash stays short and the derivation is reproducible on any machine.
function resolveSpaceshipSpot(spot) {
    if (!spot) return null;
    if (spot.lat != null && spot.pos == null) return spot;   // a literal s1 spot — nothing to derive
    const c = ensureCoastModel() ? coastPointAt((spot.pos / SPOT_POS_MAX) * coastTotalKm) : null;
    if (!c) {
        // No coastline yet (offline, or topojson.mesh unavailable): fall back to the old
        // rejection sampler so a round can still be played.
        const t = pickCoastalTarget();
        return { lon: t[0], lat: t[1], roll: 0, pos: spot.pos || 0, var: spot.var || 0,
                 tilt: defaultOrbitTilt(), fov: SPACESHIP_FOV };
    }
    // Seeded from the variation's HIGH digit alone, deliberately: sliding a spot along the
    // coast then keeps its framing — same side, same roll — and only the place changes, which
    // is what makes the slider (and pin-dragging) usable for authoring. The low digit is the
    // position across the strip, so dragging a pin off the shore only moves it.
    const parts = spotVarParts(spot.var || 0);
    const rnd = mulberry32(parts.seed * 2654435761 + 17);

    // Which way is the water? Step off the coast either side and look.
    const left = destPoint(c.pt, c.bearing - Math.PI / 2, 45);
    const right = destPoint(c.pt, c.bearing + Math.PI / 2, 45);
    const leftLand = isLandFast(left[0], left[1]), rightLand = isLandFast(right[0], right[1]);
    let outBearing = c.bearing - Math.PI / 2;
    if (leftLand && !rightLand) outBearing = c.bearing + Math.PI / 2;
    else if (leftLand === rightLand && rnd() < 0.5) outBearing = c.bearing + Math.PI / 2;

    // Anywhere in the strip: signed, so a spot can sit inland as easily as offshore.
    const offsetKm = spotOffsetKm(parts.off);
    const sub = destPoint(c.pt, outBearing, offsetKm);
    // Face the shore — from inland that means looking back out over the water, which the
    // land-fraction sweep below sorts out either way.
    const base = bearingBetween(sub, c.pt) + (rnd() * 2 - 1) * 20 * Math.PI / 180;
    const out = {
        lon: sub[0], lat: sub[1],
        roll: Math.round((rnd() * 2 - 1) * 5 * 10) / 10,
        pos: spot.pos || 0, var: spot.var || 0,
        coast: c.pt, offsetKm,
        tilt: defaultOrbitTilt(), fov: SPACESHIP_FOV,
        heading: base
    };
    // A hand-spun facing (from the sandbox, or an edited hash) wins outright — the point of
    // authoring a spot is that the auto-sweep stops second-guessing you.
    if (spot.hdg != null) {
        out.heading = codeToHdg(spot.hdg);
        out.hdg = spot.hdg;
        out.landFrac = viewLandFraction(out);
        return out;
    }
    // Otherwise sweep the facing until the frame holds a real mix of land and sea: an
    // all-ocean (or all-land) view is unguessable, which is the whole reason for aiming at a
    // coast at all.
    let best = null;
    for (const step of SPOT_HEADING_SWEEP) {
        out.heading = base + step * Math.PI / 180;
        const frac = viewLandFraction(out);
        // The chosen facing is stamped back as a code, so re-resolving a spot that has
        // already been resolved (the sandbox hands its live objects straight to the mode)
        // replays the same view instead of sweeping again from scratch.
        const minLand = spotMinLand();
        if (frac >= minLand && frac <= 1 - minLand) {
            out.landFrac = frac; out.hdg = hdgToCode(out.heading); return out;
        }
        if (!best || Math.abs(frac - 0.5) < Math.abs(best.frac - 0.5)) best = { heading: out.heading, frac };
    }
    out.heading = best.heading; out.landFrac = best.frac; out.hdg = hdgToCode(out.heading);
    return out;
}

// ==================== SPACESHIP SANDBOX ====================
// The orbital view drops you over a random coastal sub-point with a heading aimed at the
// shore. Which points that can pick, and which way you end up facing, is otherwise invisible
// — the sandbox plots the whole reachable range, lets you inspect any single spot's
// orientation, and freezes a set of 10 into a hash so two players can run the same 10 rounds.
//
// A "spot" is [lon, lat] plus the roll. Heading and tilt are DERIVED (computeCoastHeading /
// defaultOrbitTilt), so they never need encoding — but roll is random per round, so it does,
// or the two players would see the same ground at slightly different angles.

// A queue of spots handed over by the sandbox (or a ?spots= link); consumed one per
// round so both players get the identical 10. Null means 'pick at random', as before.
let pendingSpaceshipSeed = null;

const SEED_SPOTS = 10;

// Fixed-width base36 so the hash is a flat string with no separators to escape.
function b36(n, digits) {
    let s = Math.max(0, Math.round(n)).toString(36);
    while (s.length < digits) s = '0' + s;
    return s.slice(-digits);
}

// ---- The seed ----
// s3 (current): one leading char for the coastline simplification strength — it decides where
// spots can land, so it has to travel — then 8 chars per spot: 4 for a DISTANCE ALONG THE
// WORLD COASTLINE, 2 for a variation index, 2 for the facing. The rest (which side of the
// shore is water, how far offshore, the roll) is derived, so every character means something:
// edit the first four to slide a spot along the coast, the last two to spin the camera.
// 83 chars for a 10-round quiz, and the quiz can be any length.
// s2: as above minus the strength char and the facing (heading was always the derived one).
// s1: 8 chars per spot holding lon/lat/roll outright. Both still decode, so old links work.
const SEED_VERSION = 's4';
const SEED_TUNE_CHARS = 4;   // simplify strength, size bias, strip width, min land
const SPOT_POS_DIGITS = 4;
const SPOT_VAR_DIGITS = 2;
const SPOT_HDG_DIGITS = 2;
const SPOT_POS_MAX = Math.pow(36, SPOT_POS_DIGITS);   // ~1.68M steps around ~300,000 km of coast
const SPOT_VAR_MAX = Math.pow(36, SPOT_VAR_DIGITS);
const SPOT_HDG_MAX = Math.pow(36, SPOT_HDG_DIGITS);   // 1296 steps = 0.28° of facing
const SEED_SPOT_LEN = SPOT_POS_DIGITS + SPOT_VAR_DIGITS + SPOT_HDG_DIGITS;
const SEED_SPOT_LEN_V2 = SPOT_POS_DIGITS + SPOT_VAR_DIGITS;

// Heading (radians) ↔ its 2-char code.
function hdgToCode(rad) {
    const deg = ((rad * 180 / Math.PI) % 360 + 360) % 360;
    return Math.round(deg / 360 * SPOT_HDG_MAX) % SPOT_HDG_MAX;
}
function codeToHdg(code) {
    return (code % SPOT_HDG_MAX) / SPOT_HDG_MAX * 2 * Math.PI;
}

function encodeSpaceshipSeed(spots) {
    return SEED_VERSION + coastTuneCodes().map(c => b36(c, 1)).join('') + spots.map(s =>
        b36(s.pos || 0, SPOT_POS_DIGITS) + b36(s.var || 0, SPOT_VAR_DIGITS) +
        b36(s.heading != null ? hdgToCode(s.heading) : 0, SPOT_HDG_DIGITS)
    ).join('');
}

function decodeSpaceshipSeed(str) {
    const s = (str || '').trim();
    let body = s.slice(2);
    const ver = s.slice(0, 2);
    if (ver === 's4' || ver === 's3') {
        // s3 carried the simplification strength alone; s4 carries all four tunables.
        const nTune = ver === 's4' ? SEED_TUNE_CHARS : 1;
        const tune = [];
        for (let i = 0; i < nTune; i++) {
            const v = parseInt(body.slice(i, i + 1), 36);
            if (!isFinite(v)) return null;
            tune.push(v);
        }
        body = body.slice(nTune);
        if (!body.length || body.length % SEED_SPOT_LEN !== 0) return null;
        const out = [];
        for (let i = 0; i < body.length; i += SEED_SPOT_LEN) {
            const pos = parseInt(body.slice(i, i + SPOT_POS_DIGITS), 36);
            const vr = parseInt(body.slice(i + SPOT_POS_DIGITS, i + SPOT_POS_DIGITS + SPOT_VAR_DIGITS), 36);
            const hd = parseInt(body.slice(i + SPOT_POS_DIGITS + SPOT_VAR_DIGITS, i + SEED_SPOT_LEN), 36);
            if (!isFinite(pos) || !isFinite(vr) || !isFinite(hd)) return null;
            out.push({ pos, var: vr, hdg: hd });
        }
        // Anything the older format didn't carry keeps whatever is currently set.
        out.tune = ver === 's4' ? tune
                                : [tune[0], coastSizeBiasCode, spotStripCode, spotMinLandCode];
        return out;
    }
    if (s.slice(0, 2) === 's2') {
        if (!body.length || body.length % SEED_SPOT_LEN_V2 !== 0) return null;
        const out = [];
        for (let i = 0; i < body.length; i += SEED_SPOT_LEN_V2) {
            const pos = parseInt(body.slice(i, i + SPOT_POS_DIGITS), 36);
            const vr = parseInt(body.slice(i + SPOT_POS_DIGITS, i + SEED_SPOT_LEN_V2), 36);
            if (!isFinite(pos) || !isFinite(vr)) return null;
            out.push({ pos, var: vr });
        }
        return out;
    }
    if (s.slice(0, 2) === 's1') {
        if (!body.length || body.length % 8 !== 0) return null;
        const out = [];
        for (let i = 0; i < body.length; i += 8) {
            const lon = parseInt(body.slice(i, i + 3), 36) / 100 - 180;
            const lat = parseInt(body.slice(i + 3, i + 6), 36) / 100 - 90;
            const roll = parseInt(body.slice(i + 6, i + 8), 36) / 10 - 5;
            if (!isFinite(lon) || !isFinite(lat) || !isFinite(roll)) return null;
            out.push({ lon, lat, roll });
        }
        return out;
    }
    return null;
}

function randomSpaceshipSpot() {
    return resolveSpaceshipSpot({
        pos: Math.floor(Math.random() * SPOT_POS_MAX),
        var: Math.floor(Math.random() * SPOT_VAR_MAX)
    });
}

// ---- The sandbox screen ----
let sandboxState = null;

function renderSpaceshipSandbox() {
    gameState.questionType = 'spaceship-sandbox';
    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('next-btn').style.display = 'none';
    document.getElementById('give-up-btn').style.display = 'none';
    const restart = document.getElementById('restart-btn');
    restart.style.display = 'inline-block';
    restart.textContent = 'Exit';
    restart.onclick = goHome;

    sandboxState = { spots: [], selected: null };
    document.getElementById('question-text').innerHTML =
        '<strong>Spaceship sandbox</strong> — the highlighted coastline is every spot the game can pick; ' +
        'the hash names a distance along it. Click a pin to preview what that spot looks like from orbit.';

    buildSandboxPanel();
    // The coast model needs the 110m topology; the mode has just loaded it, so this is
    // normally synchronous — but the sandbox is also reachable from a cold URL.
    whenCoastReady(() => {
        if (!sandboxState) return;   // left the sandbox while the topology was in flight
        const fromUrl = decodeSpaceshipSeed(new URLSearchParams(location.search).get('spots') || '');
        if (fromUrl && fromUrl.length) {
            // The tunables are part of the seed: re-shape the coastline before resolving onto it.
            if (applyCoastTuneCodes(fromUrl.tune)) { applyCoastBias(); recutCoastline(); }
            sandboxState.spots = lockSpotCount(fromUrl.map(resolveSpaceshipSpot));
        } else {
            sandboxState.spots = Array.from({ length: SEED_SPOTS }, randomSpaceshipSpot);
        }
        sandboxState.selected = 0;
        drawSandbox();
        syncSandboxHash();
    });
}

function rollSandboxSpots(redraw = true) {
    sandboxState.spots = Array.from({ length: SEED_SPOTS }, randomSpaceshipSpot);
    sandboxState.selected = 0;
    if (redraw) { drawSandbox(); syncSandboxHash(); }
}

// Project a ring of [lon,lat] into one SVG path string. Done by hand rather than through
// geoPath because a footprint is a spherical polygon whose winding decides whether d3 fills
// the wedge or everything BUT the wedge; in screen space there is no such ambiguity. A ring
// straddling the antimeridian is kept contiguous (and runs off the map edge) instead of
// smearing a band across the whole world.
function projectedRingPath(ring) {
    let d = '', prevX = null;
    for (const p of ring) {
        const q = projection(p);
        if (!q || isNaN(q[0])) return null;
        let x = q[0];
        if (prevX != null) {
            while (x - prevX > width / 2) x -= width;
            while (prevX - x > width / 2) x += width;
        }
        d += (d ? 'L' : 'M') + x.toFixed(1) + ',' + q[1].toFixed(1);
        prevX = x;
    }
    return d ? d + 'Z' : null;
}

// The layer splits in two: the shoreline and its strip (thousands of segments, rebuilt only
// when the model changes) and the spots themselves (rebuilt on every pointermove of a drag).
function drawSandbox() {
    if (!countriesGroup || !sandboxState) return;
    // Attached to the MAP group, not countriesGroup: the dot markers for tiny countries and
    // the lake overlay are siblings that come after countriesGroup, so a layer inside it
    // would be painted over by both. Here the shoreline stays on top of the dots.
    g.selectAll('.sandbox-layer').remove();
    const layer = g.append('g').attr('class', 'sandbox-layer');
    layer.on('pointerdown', startSandboxDrag);

    // The reachable set is a STRIP around the shoreline, so draw the band as well as the line.
    // Mercator inflates with latitude, so a fixed pixel width would be far too narrow near the
    // poles: the segments are bucketed into latitude bands and each band is stroked at its own
    // width, which tracks the real km within a few percent inside each band.
    if (coastSegs && coastSegs.length) {
        const bands = new Map();
        coastSegs.forEach(s => {
            const mid = (s.a[1] + s.b[1]) / 2;
            const key = Math.floor(mid / STRIP_BAND_DEG);
            if (!bands.has(key)) bands.set(key, []);
            bands.get(key).push([s.a, s.b]);
        });
        const strip = layer.append('g').attr('class', 'sandbox-strip-layer');
        bands.forEach((segs, key) => {
            const midLat = (key + 0.5) * STRIP_BAND_DEG;
            const px = stripPixelWidth(midLat);
            if (!(px > 0.5)) return;
            strip.append('path').attr('class', 'sandbox-strip')
                .attr('stroke-width', Math.min(px, 400).toFixed(2))
                .attr('d', path({ type: 'MultiLineString', coordinates: segs.map(([a, b]) => [a, b]) }));
        });
    }
    if (coastRings) {
        layer.append('path').attr('class', 'sandbox-coast')
            .attr('d', path({ type: 'MultiLineString', coordinates: coastRings }));
    }

    layer.append('g').attr('class', 'sandbox-spots-layer');
    drawSandboxSpots();
    layer.raise();   // stay above the dots and lakes however they were (re)drawn
}

// Just the footprint and the pins — cheap enough to run on every pointermove.
function drawSandboxSpots() {
    if (!sandboxState) return;
    const host = g.select('.sandbox-spots-layer');
    if (host.empty()) return;
    host.selectAll('*').remove();

    // The selected spot's ground footprint — the slice of world in frame from up there.
    const sel = sandboxState.spots[sandboxState.selected];
    if (sel) {
        const d = projectedRingPath(viewFootprint(sel));
        if (d) host.append('path').attr('class', 'sandbox-view-cone').attr('d', d);
    }

    // Each spot: a pin to drag it along the shore, and a handle on the spoke to spin the view.
    const SPOKE = 22;
    sandboxState.spots.forEach((s, i) => {
        const p = projection([s.lon, s.lat]);
        if (!p || isNaN(p[0])) return;
        const heading = spotHeading(s);   // radians, 0 = north
        // Screen-space: north is -y, east is +x.
        const x2 = p[0] + Math.sin(heading) * SPOKE;
        const y2 = p[1] - Math.cos(heading) * SPOKE;
        const isSel = sandboxState.selected === i;
        const spot = host.append('g')
            .attr('class', 'sandbox-spot' + (isSel ? ' selected' : ''))
            .attr('data-spot', i);
        spot.append('line').attr('class', 'sandbox-heading')
            .attr('x1', p[0]).attr('y1', p[1]).attr('x2', x2).attr('y2', y2);
        spot.append('circle').attr('class', 'sandbox-rotor')
            .attr('cx', x2).attr('cy', y2).attr('r', 5);
        spot.append('circle').attr('class', 'sandbox-pin')
            .attr('cx', p[0]).attr('cy', p[1]).attr('r', isSel ? 6 : 4.5);
        spot.append('text').attr('class', 'sandbox-num')
            .attr('x', p[0]).attr('y', p[1] - 9).attr('text-anchor', 'middle').text(i + 1);
    });
    renderSandboxReadout();
    drawSandboxPreview();
}

// ---- Dragging a spot on the map ----
// The pin slides the spot to the nearest shoreline position and across the strip; the handle
// on the end of the spoke spins the camera. Both write straight into the hash, so the map is
// a full editor rather than a readout of the sliders.
let sandboxDrag = null;

function startSandboxDrag(event) {
    if (event.button > 0 || !sandboxState) return;
    const el = event.target.closest ? event.target.closest('.sandbox-pin, .sandbox-rotor') : null;
    if (!el) return;
    const holder = el.closest('.sandbox-spot');
    const i = holder ? +holder.getAttribute('data-spot') : -1;
    if (!(i >= 0) || !sandboxState.spots[i]) return;
    event.preventDefault();
    sandboxState.selected = i;
    sandboxDrag = { i, kind: el.classList.contains('sandbox-rotor') ? 'spin' : 'move', moved: false,
                    pointerId: event.pointerId };
    window.addEventListener('pointermove', onSandboxDragMove);
    window.addEventListener('pointerup', endSandboxDrag);
    window.addEventListener('pointercancel', endSandboxDrag);
    try { el.setPointerCapture(event.pointerId); } catch (_) { /* best effort */ }
    drawSandboxSpots();
}

function onSandboxDragMove(event) {
    if (!sandboxDrag || !sandboxState) return;
    const s = sandboxState.spots[sandboxDrag.i];
    if (!s) return;
    const p = d3.pointer(event, svg.node());
    if (!p || isNaN(p[0])) return;
    sandboxDrag.moved = true;

    if (sandboxDrag.kind === 'spin') {
        const pin = projection([s.lon, s.lat]);
        if (!pin) return;
        // Screen y grows downward, so north is -y: this is the bearing of the cursor from the pin.
        const heading = Math.atan2(p[0] - pin[0], pin[1] - p[1]);
        sandboxState.spots[sandboxDrag.i] = resolveSpaceshipSpot({ pos: s.pos, var: s.var, hdg: hdgToCode(heading) });
    } else {
        const geo = projection.invert ? projection.invert(p) : null;
        if (!geo || isNaN(geo[0])) return;
        const hit = nearestCoast(geo);
        if (!hit) return;
        // Which side of the shore the drop is on decides the sign of the strip offset: try
        // both steps and keep whichever lands nearer the cursor. Cheaper and more robust than
        // re-deriving the water-side normal, and it always agrees with what the player sees.
        const seed = spotVarParts(s.var).seed;
        const step = spotOffsetStep(hit.km);
        const mirror = SPOT_OFF_STEPS - 1 - step;
        const keepHdg = s.hdg != null ? s.hdg : hdgToCode(spotHeading(s));
        const cands = [step, mirror].map(off =>
            resolveSpaceshipSpot({ pos: hit.pos, var: spotVarFrom(off, seed), hdg: keepHdg }));
        const best = cands.reduce((a, b) =>
            (!a || kmBetween([b.lon, b.lat], geo) < kmBetween([a.lon, a.lat], geo)) ? b : a, null);
        sandboxState.spots[sandboxDrag.i] = best;
    }
    drawSandboxSpots();
}

function endSandboxDrag() {
    if (!sandboxDrag) return;
    window.removeEventListener('pointermove', onSandboxDragMove);
    window.removeEventListener('pointerup', endSandboxDrag);
    window.removeEventListener('pointercancel', endSandboxDrag);
    sandboxDrag = null;
    syncSandboxHash();
    drawSandboxSpots();
}

// Board-unit width of the full strip (both sides) at a latitude. Mercator's scale is
// s/cos(lat) user units per radian, so a km width is 2·strip/R · scale / cos(lat).
const STRIP_BAND_DEG = 10;
function stripPixelWidth(midLat) {
    const lat = Math.max(-85, Math.min(85, midLat));
    const rad = 2 * spotStripKm() / EARTH_R_KM;      // full width in radians of great circle
    return rad * projection.scale() / Math.cos(lat * Math.PI / 180);
}

// Legacy (s1) spots carry no facing of their own, so they still derive one from the coast.
function spotHeading(s) {
    return s.heading != null ? s.heading : computeCoastHeading([s.lon, s.lat]);
}

function renderSandboxReadout() {
    const el = document.getElementById('sandbox-readout');
    if (!el || !sandboxState) return;
    const i = sandboxState.selected;
    const s = sandboxState.spots[i];
    if (i == null || !s) {
        el.innerHTML = '<em>No spot selected.</em>';
        return;
    }
    const headingDeg = (spotHeading(s) * 180 / Math.PI + 360) % 360;
    const compass = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'][
        Math.round(headingDeg / 22.5) % 16];
    const land = s.landFrac != null ? s.landFrac : viewLandFraction(s);
    el.innerHTML =
        `<strong>Spot ${i + 1}/${sandboxState.spots.length}</strong> &nbsp;<code>` +
        `${b36(s.pos || 0, SPOT_POS_DIGITS)}${b36(s.var || 0, SPOT_VAR_DIGITS)}` +
        `${b36(hdgToCode(spotHeading(s)), SPOT_HDG_DIGITS)}</code><br>` +
        `lat ${s.lat.toFixed(2)}°, lon ${s.lon.toFixed(2)}°<br>` +
        `heading ${headingDeg.toFixed(0)}° (${compass}) · ${Math.round(land * 100)}% land in frame<br>` +
        `tilt ${(s.tilt != null ? s.tilt : defaultOrbitTilt()).toFixed(1)}° · roll ${(s.roll || 0).toFixed(1)}°` +
        (s.offsetKm != null ? ` · ${Math.round(s.offsetKm)} km offshore` : '') + '<br>' +
        `<span class="sandbox-note">tilt follows the Orbit-height slider (${orbitAltitudeKm} km)</span>`;
}

// ---- Low-res preview ----
// Deliberately the cheapest possible render of the real thing: the 2048px Blue Marble base
// sphere and nothing else — no cap tiles, no atmosphere, no outlines. It answers "what would
// I be looking at here?" without the multi-hundred-megabyte texture machinery of the mode
// proper, so clicking through ten spots costs nothing.
let sandboxPreview = null;

function ensureSandboxPreview() {
    const T = window.THREE;
    const host = document.getElementById('sandbox-preview');
    if (!T || !host) return null;
    if (sandboxPreview) return sandboxPreview;
    const canvas = document.createElement('canvas');
    host.appendChild(canvas);
    const renderer = new T.WebGLRenderer({ canvas, antialias: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    renderer.outputColorSpace = T.SRGBColorSpace;
    const scene = new T.Scene();
    scene.background = new T.Color(0x05070d);
    const camera = new T.PerspectiveCamera(SPACESHIP_FOV, ORBIT_VIEW_ASPECT, 0.001, 100);
    loadEarthTextures();
    const earth = new T.Mesh(new T.SphereGeometry(1, 96, 96),
        new T.MeshBasicMaterial({ map: orbitalTexLow }));
    scene.add(earth);
    sandboxPreview = { renderer, scene, camera, earth, canvas, host };
    return sandboxPreview;
}

function drawSandboxPreview() {
    if (!sandboxState) return;
    const spot = sandboxState.spots[sandboxState.selected];
    if (!spot) return;
    withThree(() => {
        const p = ensureSandboxPreview();
        if (!p || !sandboxState) return;
        // The base texture loads asynchronously; an unloaded map renders as a black ball.
        if (!orbitalTexLow || !orbitalTexLow.image) { setTimeout(drawSandboxPreview, 250); return; }
        if (p.earth.material.map !== orbitalTexLow) {
            p.earth.material.map = orbitalTexLow;
            p.earth.material.needsUpdate = true;
        }
        const w = Math.max(1, Math.round(p.host.clientWidth));
        const h = Math.max(1, Math.round(w / ORBIT_VIEW_ASPECT));
        p.renderer.setSize(w, h, true);
        p.camera.aspect = w / h;
        aimOrbitalCamera(p.camera, {
            lat: spot.lat, lon: spot.lon, heading: spotHeading(spot),
            tilt: spot.tilt != null ? spot.tilt : defaultOrbitTilt(),
            roll: spot.roll || 0, fov: spot.fov || SPACESHIP_FOV
        });
        p.renderer.render(p.scene, p.camera);
    });
}

function disposeSandboxPreview() {
    if (!sandboxPreview) return;
    try {
        sandboxPreview.earth.geometry.dispose();
        sandboxPreview.earth.material.dispose();
        sandboxPreview.renderer.dispose();
    } catch (e) { /* best-effort cleanup */ }
    if (sandboxPreview.canvas.parentNode) sandboxPreview.canvas.parentNode.removeChild(sandboxPreview.canvas);
    sandboxPreview = null;
}

function buildSandboxPanel() {
    let panel = document.getElementById('sandbox-panel');
    if (!panel) {
        panel = document.createElement('div');
        panel.id = 'sandbox-panel';
        panel.className = 'sandbox-panel';
        panel.innerHTML = `
            <div class="sandbox-title">Quiz seed</div>
            <div class="sandbox-preview" id="sandbox-preview"></div>
            <div class="sandbox-readout" id="sandbox-readout"></div>
            <div class="sandbox-edit">
                <label class="sandbox-slider" title="Slide the spot along the world coastline.">
                    <span>Slide</span>
                    <input type="range" id="sandbox-slide" min="0" max="${SPOT_POS_MAX - 1}" step="1" value="0">
                </label>
                <div class="sandbox-nudge">
                    <button class="btn secondary" data-nudge="-100" title="100 km back">«</button>
                    <button class="btn secondary" data-nudge="-10" title="10 km back">‹</button>
                    <button class="btn secondary" data-nudge="10" title="10 km on">›</button>
                    <button class="btn secondary" data-nudge="100" title="100 km on">»</button>
                </div>
                <label class="sandbox-slider" title="Spin the camera about the sub-point.">
                    <span>Spin</span>
                    <input type="range" id="sandbox-spin" min="0" max="359" step="1" value="0">
                </label>
            </div>
            <div class="sandbox-edit sandbox-tune">
                <label class="sandbox-slider" title="Visvalingam–Whyatt simplification of the shoreline the spots live on.">
                    <span>Coast</span>
                    <input type="range" id="sandbox-simplify" min="0" max="${TUNE_MAX}" step="1" value="${coastSimplifyStrength}">
                    <span class="sandbox-note" id="sandbox-simplify-val">80% cut</span>
                </label>
                <label class="sandbox-slider" title="Simplify points on long shorelines before those on short ones, so continents lose their wiggles before small islands lose their shape.">
                    <span>Bias</span>
                    <input type="range" id="sandbox-bias" min="0" max="${TUNE_MAX}" step="1" value="${coastSizeBiasCode}">
                    <span class="sandbox-note" id="sandbox-bias-val">×0.5</span>
                </label>
                <label class="sandbox-slider" title="Spots may sit anywhere within this distance of a shore, on either side of it.">
                    <span>Strip</span>
                    <input type="range" id="sandbox-strip" min="0" max="${TUNE_MAX}" step="1" value="${spotStripCode}">
                    <span class="sandbox-note" id="sandbox-strip-val">±500 km</span>
                </label>
                <label class="sandbox-slider" title="A spot's facing is swept until the frame is between this much and this much less than all land.">
                    <span>Land</span>
                    <input type="range" id="sandbox-land" min="0" max="${TUNE_MAX}" step="1" value="${spotMinLandCode}">
                    <span class="sandbox-note" id="sandbox-land-val">20–80%</span>
                </label>
                <div class="sandbox-note">All four travel in the hash — they decide where spots can land.</div>
            </div>
            <label class="sandbox-label" for="sandbox-hash">Seed hash</label>
            <textarea id="sandbox-hash" class="sandbox-hash" rows="3" spellcheck="false"></textarea>
            <div class="sandbox-actions">
                <button class="btn secondary" id="sandbox-roll">Roll 10 new</button>
                <button class="btn secondary" id="sandbox-copy">Copy link</button>
                <button class="btn" id="sandbox-play">Play these 10</button>
            </div>
            <div class="sandbox-status" id="sandbox-status" role="status"></div>`;
        (document.getElementById('globe-side-panel') || document.body).appendChild(panel);

        document.getElementById('sandbox-roll').addEventListener('click', () => rollSandboxSpots());
        document.getElementById('sandbox-copy').addEventListener('click', copySandboxLink);
        document.getElementById('sandbox-play').addEventListener('click', playSandboxSeed);

        // Slide along the coast / spin the camera: both edit the selected spot in place, so
        // the map, the footprint and the preview all follow the slider live.
        document.getElementById('sandbox-slide').addEventListener('input', function () {
            editSelectedSpot({ pos: +this.value });
        });
        document.getElementById('sandbox-spin').addEventListener('input', function () {
            editSelectedSpot({ hdg: Math.round(+this.value / 360 * SPOT_HDG_MAX) });
        });
        panel.querySelectorAll('[data-nudge]').forEach(b => b.addEventListener('click', () => {
            nudgeSelectedSpot(+b.dataset.nudge);
        }));
        // The four tunables. The first two re-shape the shoreline itself, the last two only
        // change how spots are drawn from it — either way every spot is then re-resolved.
        document.getElementById('sandbox-simplify').addEventListener('input', function () {
            setCoastSimplify(+this.value); reresolveSandboxSpots();
        });
        document.getElementById('sandbox-bias').addEventListener('input', function () {
            setCoastSizeBias(+this.value); reresolveSandboxSpots();
        });
        document.getElementById('sandbox-strip').addEventListener('input', function () {
            spotStripCode = +this.value; reresolveSandboxSpots();
        });
        document.getElementById('sandbox-land').addEventListener('input', function () {
            spotMinLandCode = +this.value; reresolveSandboxSpots();
        });
        // Pasting a hash re-plots it, so a shared seed can be inspected before playing.
        document.getElementById('sandbox-hash').addEventListener('input', function () {
            const parsed = decodeSpaceshipSeed(this.value.trim());
            const status = document.getElementById('sandbox-status');
            if (parsed && parsed.length) {
                if (applyCoastTuneCodes(parsed.tune)) { applyCoastBias(); recutCoastline(); }
                sandboxState.spots = lockSpotCount(parsed.map(resolveSpaceshipSpot));
                sandboxState.selected = 0;
                drawSandbox();
                syncSandboxControls();
                status.textContent = `Loaded ${parsed.length} spot${parsed.length === 1 ? '' : 's'}.`;
            } else if (this.value.trim()) {
                status.textContent = 'Not a valid seed.';
            }
        });
    }
    panel.style.display = '';
}

function syncSandboxHash() {
    const box = document.getElementById('sandbox-hash');
    if (box && sandboxState) box.value = encodeSpaceshipSeed(sandboxState.spots);
    syncSandboxControls();
}

// Point the edit controls at whichever spot is selected (and disable them when none is).
function syncSandboxControls() {
    const slide = document.getElementById('sandbox-slide');
    const spin = document.getElementById('sandbox-spin');
    if (!slide || !sandboxState) return;
    const s = sandboxState.spots[sandboxState.selected];
    slide.disabled = spin.disabled = !s;
    if (s) {
        slide.value = String(s.pos || 0);
        spin.value = String(Math.round(((spotHeading(s) * 180 / Math.PI) % 360 + 360) % 360));
    }
    const set = (id, value, label) => {
        const el = document.getElementById('sandbox-' + id);
        const lab = document.getElementById('sandbox-' + id + '-val');
        if (el) el.value = String(value);
        if (lab) lab.textContent = label;
    };
    set('simplify', coastSimplifyStrength, coastSimplifyStrength === 0
        ? 'full' : Math.round(coastCutFrac() * 100) + '% cut');
    set('bias', coastSizeBiasCode, coastSizeBiasCode === 0 ? 'none' : '×' + coastSizeBias().toFixed(1));
    set('strip', spotStripCode, '±' + spotStripKm() + ' km');
    set('land', spotMinLandCode, spotMinLandCode + '–' + (100 - spotMinLandCode) + '%');
}

// Re-derive the selected spot from an edited field. `pos` re-runs the facing sweep (a new
// stretch of coast deserves a fresh look); `hdg` pins the facing the player chose.
function editSelectedSpot(patch) {
    if (!sandboxState) return;
    const i = sandboxState.selected;
    const cur = sandboxState.spots[i];
    if (!cur) return;
    const next = {
        pos: patch.pos != null ? ((patch.pos % SPOT_POS_MAX) + SPOT_POS_MAX) % SPOT_POS_MAX : cur.pos,
        var: patch.var != null ? patch.var : cur.var,
        hdg: patch.hdg != null ? patch.hdg : (patch.pos != null ? null : hdgToCode(spotHeading(cur)))
    };
    if (next.hdg == null) delete next.hdg;
    sandboxState.spots[i] = resolveSpaceshipSpot(next);
    drawSandbox();
    syncSandboxHash();
}

// Slide the selected spot a fixed number of km along the coastline.
function nudgeSelectedSpot(km) {
    const s = sandboxState && sandboxState.spots[sandboxState.selected];
    if (!s || !coastTotalKm) return;
    const step = Math.round(km / coastTotalKm * SPOT_POS_MAX);
    editSelectedSpot({ pos: (s.pos || 0) + step });
}

// The quiz is always exactly SEED_SPOTS long: a decoded seed is trimmed or topped up, so a
// hand-edited hash can't produce a 3-round or 40-round game.
function lockSpotCount(spots) {
    const out = (spots || []).slice(0, SEED_SPOTS);
    while (out.length < SEED_SPOTS) out.push(randomSpaceshipSpot());
    return out;
}

// Re-resolve every spot against the current tunables. Positions are fractions of the total
// shoreline length, so spots follow the line rather than jumping to stale coordinates; the
// facing is kept, since a slider nudge shouldn't silently re-aim a shot the player framed.
function reresolveSandboxSpots() {
    if (!sandboxState) return;
    sandboxState.spots = sandboxState.spots.map(s =>
        resolveSpaceshipSpot({ pos: s.pos, var: s.var, hdg: s.hdg != null ? s.hdg : hdgToCode(spotHeading(s)) }));
    drawSandbox();
    syncSandboxHash();
}

function sandboxSeedUrl() {
    const p = new URLSearchParams();
    p.set('mode', 'spaceship');
    p.set('spots', encodeSpaceshipSeed(sandboxState.spots));
    return location.origin + location.pathname + '?' + p.toString();
}

function copySandboxLink() {
    copyShareLink(sandboxSeedUrl(), 'sandbox-status');
}

// Hand the current 10 straight to the orbital view.
function playSandboxSeed() {
    const seed = encodeSpaceshipSeed(sandboxState.spots);
    history.replaceState(null, '', location.origin + location.pathname + '?mode=spaceship&spots=' + seed);
    startSpaceshipWithSeed(sandboxState.spots.slice());
}

// `tune` is the four-tunable header the seed was authored at. It has to be applied BEFORE the
// spots resolve — they are distances along a line those tunables shape, so a different header
// lands them somewhere else. (Array.slice drops the property off the decoded list, which is
// why it is passed separately rather than read back off `spots`.)
function startSpaceshipWithSeed(spots, tune) {
    if (tune) {
        pendingCoastTune = tune;
        if (coastRaw) {                              // model already built — re-cut it now
            if (applyCoastTuneCodes(tune)) { applyCoastBias(); recutCoastline(); }
            pendingCoastTune = null;
        }
    }
    pendingSpaceshipSeed = spots && spots.length ? spots.slice() : null;
    startGameWithMode('spaceship');
}

function removeSandboxPanel() {
    disposeSandboxPreview();   // its own WebGL context — release it with the panel
    const p = document.getElementById('sandbox-panel');
    if (p) p.remove();
    sandboxState = null;
}

// ==================== FLAG MATCH ====================
// A world map ringed by every flag; drag each one onto its country. A correct drop fills
// that country's shape with the flag via fillCountryWithFlag, so the map paints itself in
// as you go. Reuses the puzzle's pointer-drag conventions (listeners attached before
// setPointerCapture, a fixed-position ghost on <body>) but drops by HIT-TESTING the map
// rather than by distance: the target is a country you can see, not a remembered position.
let flagDrag = null;

function renderFlagPlaceMode() {
    gameState.questionType = 'flag-place';
    gameState.flagPlaced = new Set();
    gameState.flagMisses = 0;
    cancelFlagDrag();

    document.getElementById('flag-display').style.display = 'none';
    document.getElementById('multiple-choice-container').classList.add('hidden');
    document.getElementById('next-btn').style.display = 'none';
    const giveUp = document.getElementById('give-up-btn');
    giveUp.style.display = 'inline-block';
    giveUp.textContent = 'Give Up';
    document.getElementById('restart-btn').style.display = 'inline-block';

    // Only countries that are BOTH on the map and have a flag code are playable.
    const drawn = new Set((gameState.countries || []).map(f => normalizeName(f.properties.name)));
    gameState.flagPool = (gameState.currentQuizList || []).filter(n => {
        const d = gameState.currentDataObj[n];
        return d && d.code && drawn.has(normalizeName(n));
    });
    gameState.flagTotal = gameState.flagPool.length;
    gameState.totalQuestions = gameState.flagTotal;
    gameState.currentQuestion = 0;
    const totalEl = document.getElementById('total-questions');
    if (totalEl) totalEl.textContent = String(gameState.flagTotal);

    document.getElementById('question-text').innerHTML =
        `Drag each flag onto its country — <span id="flag-placed-count">0</span>/${gameState.flagTotal} placed` +
        ` &nbsp;|&nbsp; wrong drops: <span id="flag-misses">0</span>`;
    const feedback = document.getElementById('feedback');
    feedback.textContent = ''; feedback.className = 'feedback';

    buildFlagTray();
    refreshFlagTray();
}

function buildFlagTray() {
    let tray = document.getElementById('flag-tray');
    if (!tray) {
        tray = document.createElement('div');
        tray.id = 'flag-tray';
        tray.className = 'puzzle-tray flag-tray';
        tray.innerHTML = `
            <div class="puzzle-tray-head">
                <span class="puzzle-tray-title">Flags left: <span id="flag-remaining">0</span></span>
                <span class="puzzle-tray-hint">Drag a flag onto the right country.</span>
            </div>
            <div class="flag-chips" id="flag-chips"></div>`;
        (document.getElementById('globe-side-panel') || document.body).appendChild(tray);
        // Delegated, since the strip is rewritten as flags are placed.
        document.getElementById('flag-chips').addEventListener('pointerdown', startFlagDrag);
    }
    tray.style.display = '';
}

function refreshFlagTray() {
    const host = document.getElementById('flag-chips');
    if (!host) return;
    if (!gameState.flagOrder) gameState.flagOrder = shuffleArray(gameState.flagPool);
    const left = gameState.flagOrder.filter(n => !gameState.flagPlaced.has(n));
    // No name anywhere on the chip — the flag IS the question.
    host.innerHTML = left.map(n => {
        const d = gameState.currentDataObj[n];
        return `<button type="button" class="flag-chip" data-country="${escAttr(n)}">` +
            `<img src="https://flagcdn.com/${d.code}.svg" alt="" draggable="false"></button>`;
    }).join('');
    const rem = document.getElementById('flag-remaining');
    if (rem) rem.textContent = String(left.length);
}

function startFlagDrag(event) {
    if (event.button > 0 || flagDrag) return;
    const chip = event.target.closest('.flag-chip');
    if (!chip) return;
    const name = chip.dataset.country;
    if (!name || gameState.flagPlaced.has(name)) return;
    event.preventDefault();

    const img = chip.querySelector('img');
    const r = img.getBoundingClientRect();
    const ghost = document.createElement('div');
    ghost.className = 'flag-ghost';
    ghost.innerHTML = `<img src="${img.src}" alt="">`;
    ghost.style.width = r.width + 'px';
    ghost.style.height = r.height + 'px';
    document.body.appendChild(ghost);

    flagDrag = { name, chip, ghost, pointerId: event.pointerId,
                 offX: event.clientX - r.left, offY: event.clientY - r.top };
    chip.classList.add('in-hand');
    moveFlagGhost(event);

    window.addEventListener('pointermove', onFlagDragMove);
    window.addEventListener('pointerup', onFlagDragEnd);
    window.addEventListener('pointercancel', onFlagDragEnd);
    try { chip.setPointerCapture(event.pointerId); } catch (_) { /* best effort */ }
}

function moveFlagGhost(event) {
    if (!flagDrag) return;
    flagDrag.ghost.style.left = (event.clientX - flagDrag.offX) + 'px';
    flagDrag.ghost.style.top = (event.clientY - flagDrag.offY) + 'px';
}

// Which country is under the cursor? The ghost is pointer-events:none, so elementFromPoint
// sees straight through it to the map.
function countryUnderPointer(event) {
    const el = document.elementFromPoint(event.clientX, event.clientY);
    if (!el || !el.closest) return null;
    const pathEl = el.closest('path.country, circle.island-marker');
    if (!pathEl) return null;
    const d = d3.select(pathEl).datum();
    if (!d || !d.properties) return null;
    // A drop on an overseas territory counts as its sovereign parent, as clicks do.
    return d.properties.parent || d.properties.name;
}

function onFlagDragMove(event) {
    if (!flagDrag) return;
    moveFlagGhost(event);
    const over = countryUnderPointer(event);
    flagDrag.ghost.classList.toggle('over-country', !!over);
}

function onFlagDragEnd(event) {
    if (!flagDrag) return;
    const { name } = flagDrag;
    const dropped = countryUnderPointer(event);
    cancelFlagDrag();
    if (!dropped) return;   // dropped on the ocean or off-map: no penalty, just put it back

    const feedback = document.getElementById('feedback');
    if (namesMatch(dropped, name)) {
        gameState.flagPlaced.add(name);
        fillCountryWithFlag(name);
        gameState.score++;
        gameState.currentQuestion = gameState.flagPlaced.size;
        document.getElementById('score').textContent = gameState.score;
        syncScoreDisplay();
        playPuzzleClick();
        feedback.textContent = `${name} — correct!`;
        feedback.className = 'feedback correct';
        refreshFlagTray();
        updateFlagStatus();
        if (gameState.flagPlaced.size >= gameState.flagTotal) finishFlagPlace();
    } else {
        gameState.flagMisses = (gameState.flagMisses || 0) + 1;
        feedback.textContent = `That flag isn't ${dropped}.`;
        feedback.className = 'feedback incorrect';
        const back = document.querySelector(`.flag-chip[data-country="${escAttr(name)}"]`);
        if (back) { back.classList.remove('bounced'); void back.offsetWidth; back.classList.add('bounced'); }
        updateFlagStatus();
    }
}

function cancelFlagDrag() {
    if (!flagDrag) return;
    window.removeEventListener('pointermove', onFlagDragMove);
    window.removeEventListener('pointerup', onFlagDragEnd);
    window.removeEventListener('pointercancel', onFlagDragEnd);
    try { flagDrag.chip.releasePointerCapture(flagDrag.pointerId); } catch (_) { /* best effort */ }
    flagDrag.chip.classList.remove('in-hand');
    flagDrag.ghost.remove();
    flagDrag = null;
}

function updateFlagStatus() {
    const p = document.getElementById('flag-placed-count');
    if (p) p.textContent = String(gameState.flagPlaced ? gameState.flagPlaced.size : 0);
    const m = document.getElementById('flag-misses');
    if (m) m.textContent = String(gameState.flagMisses || 0);
}

function finishFlagPlace() {
    const tray = document.getElementById('flag-tray');
    if (tray) tray.style.display = 'none';
    endGame();
}

function removeFlagTray() {
    cancelFlagDrag();
    const tray = document.getElementById('flag-tray');
    if (tray) tray.remove();
}

// ==================== FLAGS CATEGORY ====================
// Mystery Flag (see a flag, find the country) and Flag Match (drag every flag onto its
// country) are both "flag → place", so they share one tile and picker.
const FLAG_SUBMODES = [
    { key: 'mystery-flag', icon: 'flag',        label: 'Mystery Flag',
      desc: 'See the flag, find the country on the globe' },
    { key: 'flag-place',   icon: 'emoji_flags', label: 'Flag Match',
      desc: 'Drag every flag onto its country to fill the map' },
    // Promoted out of the quick quizzes: it is a question about flags before it is anything else,
    // and somebody looking for one looks here.
    { key: 'sb-fake-flag', icon: 'gpp_maybe',   label: 'False Flag',
      desc: 'Four flags, one invented — which country does not exist?' },
    { key: 'flag-workshop', icon: 'palette',    label: 'Flag Workshop',
      desc: 'Build a flag out of other flags, and save it into False Flag' }
];

// EXPLORE. Two ways of looking at the world with nothing being asked of you: roam the globe and
// click things, or put the same world through a dozen projections. They belong together because
// they are the same activity at two removes, and the View toggle carries you between them.
